/*
    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓

    ▓              🌟  KuKo Day 169  🌟              
    ▓
    ▓  TBT. Last day of the work retreat X_X 

    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓
*/
#define T iTime

// Constants
const float GRID_SIZE   = 5.0;
const float SHAPE_SPEED = 0.2;
const float SDF_SPEED   = 0.05;
const float DEL_SPEED   = 0.04;
const float RADIUS      = 0.2;

// Color palette
const vec3 BLUE   = vec3(0.1, 0.3, 0.5);
const vec3 GREY   = vec3(0.145, 0.141, 0.122);
const vec3 ORANGE = vec3(0.649, 0.431, 0.008);
const vec3 GREEN  = vec3(0.094, 0.212, 0.204);
const vec3 PINK   = vec3(0.69, 0.435, 0.459);

mat2 rotate2D(float angle) { return mat2(cos(angle), -sin(angle),  sin(angle), cos(angle));}

float sdfCircle(vec2 cell, float radius) {
    float d2 = abs(cell.x);
    //return 0.15 / (d2 + 0.001);
    //Alternative implementation (commented out)
    float d1 = length(cell) - radius;
    float w = 1.0 / iResolution.y;
    return 1.2992 / (smoothstep(w, w, d1) + 0.01);
}

struct AnimationPattern {
    vec2 direction;
    vec3 color;
};

AnimationPattern getAnimationPattern(float id) 
{
    float idx = mod(id, 8.0);

    if (idx == 0.0) return AnimationPattern(vec2(0.0, SDF_SPEED), BLUE);
    if (idx == 1.0) return AnimationPattern(vec2(-SDF_SPEED, 0.0), ORANGE);
    if (idx == 2.0) return AnimationPattern(vec2(SDF_SPEED, 0.0), GREY);
    if (idx == 3.0) return AnimationPattern(vec2(0.0, SDF_SPEED), BLUE);
    if (idx == 4.0) return AnimationPattern(vec2(-SDF_SPEED, 0.0), PINK);
    if (idx == 5.0) return AnimationPattern(vec2(SDF_SPEED, 0.0), GREEN);
    if (idx == 6.0) return AnimationPattern(vec2(0.0, SDF_SPEED), BLUE);
    if (idx == 7.0) return AnimationPattern(vec2(-SDF_SPEED, 0.0), PINK);

    return AnimationPattern(vec2(0.0), GREY);
}

void mainImage(out vec4 O, in vec2 I) 
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    uv = rotate2D(T * DEL_SPEED) * uv;

    uv.x += sin(uv.x * 2.7 + T * SHAPE_SPEED) * 0.3 
          + sin(uv.x * 8.1 - T * SHAPE_SPEED) * 0.1 
          + cos(uv.y * 5.3 + T * SHAPE_SPEED) * 0.25 
          + cos(uv.y * 3.2 - T * SHAPE_SPEED) * 0.2 
          + 0.15;

    uv.x += T * 0.1;

    float id = floor(uv.x * GRID_SIZE);
    AnimationPattern pattern = getAnimationPattern(id);
    vec2 animatedUV = uv + pattern.direction * T;

    vec2 cell = fract(animatedUV * GRID_SIZE) - 0.5;

    float dist = sdfCircle(cell, RADIUS);
    vec3 shape = mix(vec3(0.0),pattern.color, dist);

    O = vec4(shape, 1.0);
}

/*
    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓

    ▓              🌟  KuKo Day 94  🌟                

    ▓  Learning Flow field simulation

    ▓  Great tutorial on:
    ▓  https://wyattflanders.com/MeAndMyNeighborhood.pdf

    ▓  Added Simplex Noise
    ▓  https://www.shadertoy.com/view/W3VGW3

    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓
*/

#define LOOKUP(COORD) texture(iChannel0, COORD/iResolution.xy)

void mainImage( out vec4 O, in vec2 I )
{
    vec4 field = LOOKUP(I * 1.);
    O = vec4(field.y * 0.5 + 0.0, field.x*0.5+0.2, field.x *0.5+0.3, 1.0);

     // Add noise to the force field
    vec3 n = noise(I * SCALE_P + iTime * NOISE_T); // slow time evolution
    vec3 an = abs(n);
    vec4 s = vec4(
        dot(n, vec3(1.)),
        dot(an, vec3(1.)),
        length(n),
        max(max(an.x, an.y), an.z)
    );

    // Apply noise as additional force
    O += 0.025*( s.y*-abs(s.x) );



}

#define V_FIELD(COORD) texture(iChannel0, COORD/iResolution.xy)
#define T iTime

const float SPEED_D1 = 0.5;
// 1: All my energy translate with my order energey
vec4 Field(vec2 p)
{
    vec2 vf = V_FIELD(p).xy;
    //   └── fetch v(p) from R﻿G channels
    vec2 p0 = p - vf;
    //   └── back‑trace: p₀ = p - Δt·v(p)
    return V_FIELD(p0);
    //   └── sample the old field at that p₀
}

void mainImage( out vec4 O, in vec2 I )
{
    vec2 R = iResolution.xy;
    // check if resolution changed
    if(iFrame < 1 )
    {
        O = vec4(0.1,0.0,0.0,0.0);
        return;
    }
    O = Field(I);
    // neighborhood
    vec4 px = Field(I + vec2(1,0));
    vec4 py = Field(I + vec2(0,1));
    vec4 nx = Field(I - vec2(1,0));
    vec4 ny = Field(I - vec2(0,1));

    // 2: disorder energy diffuses completely 
    O.b = (px.b + py.b + nx.b + ny.b) / 4.0;

    // 3: order in the disorder energy creates order 
    vec2 Force;
    Force.x = (py.b - ny.b);
    Force.y = (nx.b - px.b);


    // Add noise to the force field
    vec3 n = noise(I * SCALE_P + vec2(T * NOISE_T)); // slow time evolution
    vec3 an = abs(n);
    vec4 s = vec4(
        dot(n, vec3(1.)),
        dot(an, vec3(1.)),
        length(n),
        max(max(an.x, an.y), an.z)
    );

    // Apply noise as additional force
    //Force += 0.25*( s.y * -abs(s.x));
    float strength = 0.9;
    Force.x += n.y * strength;  // perpendicular to gradient
    Force.y += -n.x * strength;

    //O.xy += (Force) * 0.0045;

    // 4: disorder in the order energy creates disorder
    O.b += (nx.x - px.x + ny.y - py.y) / 4.0;

    // gravity offset
    O.y -= O.w / 300.0;

    // mass concervation 
    O.w += (nx.x * nx.w - px.x * px.w + ny.y * ny.w - py.y * py.w)/4.0;


    O.xy += (Force) * (sin(T * 1.0) * 0.01 + 0.025 * cos(T * 2.0) * 0.5 + 0.025);

    //boundery conditions
    if(I.x < 10. || I.y < 10. || R.x - I.x < 10. || R.y - I.y < 10.)
    {
        O.xy *= 0.0;
    }
}

#define ss(t, b, g) smoothstep(t-b, t+b, g)
#define screen(a, b) a+b-a*b
#define SCALE_P 0.516
#define NOISE_T 0.0

vec2 hash( vec2 p ) // modified from iq's too
{
	p = vec2( dot(p,vec2(127.1,311.7)), dot(p,vec2(269.5,183.3)) );
	p = -1.0 + 2.0*fract(sin(p)*43758.5453123);
    return p;
    //return normalize(p); // more uniform (thanks Fabrice)
}

// slightly modified version of iq's simplex noise shader: https://www.shadertoy.com/view/Msf3WH
vec3 noise( in vec2 p )
{
    const float K1 = 0.366025404; // (sqrt(3)-1)/2;
    const float K2 = 0.211324865; // (3-sqrt(3))/6;

	vec2  i = floor( p + (p.x+p.y)*K1 );
    vec2  a = p - i + (i.x+i.y)*K2;
    float m = step(a.y,a.x); 
    vec2  o = vec2(m,1.0-m);
    vec2  b = a - o + K2;
	vec2  c = a - 1.0 + 2.0*K2;
    vec3  h = max( 0.5-vec3(dot(a,a), dot(b,b), dot(c,c) ), 0.0 );
	vec3  n = h*h*h*h*vec3( dot(a,hash(i+0.0)), dot(b,hash(i+o)), dot(c,hash(i+1.0)));
    return 1e2*n; //return full vector
}

/*
    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓


    ▓              🌟  KuKo Day 110  🌟                

    ▓  AA practice. Every time there's repetition,  
    ▓  I get aliasing problems.


    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓
*/

#define T iTime

float sdfCapsule(vec3 p)
{
    vec3 a = vec3(0.0, -50.0, 0.0);
    vec3 b = vec3(0.0, 50.0, 0.0);
    vec3 pa = p - a, ab = b - a;

    float h = clamp( dot(pa, ab) / dot(ab, ab), 0.0,1.0);

    return length(pa - ab * h) - 0.1;
}

float map(vec3 p)
{

    vec2 cell = vec2(2.0);
    p.z -= T * 0.9;
    p.xz = mod(p.xz + 0.0, cell) - 0.5*cell;

    return sdfCapsule(p);
}

float rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.0;

    for(int i=0; i<80; i++)
    {
        vec3 p = ro + rd * dt;
        float d = map(p);
        dt += d;
        if(d < 0.01 || dt > 20.0) break;
    }
    return dt;
}


vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
        map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
        map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
    ));
}

void mainImage( out vec4 O, in vec2 I )
{
    vec2 uv = (2.0 * I - iResolution.xy)/iResolution.y;
    vec3 col = vec3(0.0);

    vec3 ro = vec3(0.0,0.0,3.0);
    vec3 rd = normalize(vec3(uv, -1.0)); 

    float dt = rayMarch(ro, rd);

    if(dt < 10.0)
    {
        vec3 p = ro + rd * dt;

        vec3 norm = calcNormal(p);
        vec3 lightDir = normalize(vec3(3.0,3.0,9.0));
        float diff = max(dot(norm, lightDir), 0.0);

        float ambient = 0.1;
        vec3 albedo = vec3(0.0, 0.5, 0.5);

        col = norm;
        //col = albedo * (ambient + diff);
        //col = (ambient + diff) * vec3(0.0,0.5,0.5);
    }


    col = pow(col * 2.1, vec3(1.1 / 2.2));

    O = vec4(col,1.0);
}

/*
    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓


    ▓              🌟  KuKo Day 112  🌟                

    ▓  AA practice. in case I can't use iq AA supersampling

    ▓  Weyl Supersample 
    ▓  https://www.shadertoy.com/view/WXjXRt


    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓
*/

#define T iTime

float sdfCapsule(vec3 p)
{
    p.x += sin(p.y * 7.5 - T) * 0.06;

    vec3 a = vec3(0.0, -50.0, 0.0);
    vec3 b = vec3(0.0, 50.0, 0.0);
    vec3 pa = p - a, ab = b - a;

    float h = clamp( dot(pa, ab) / dot(ab, ab), 0.0,1.0);

    return length(pa - ab * h) - 0.2;
}

float map(vec3 p)
{

    vec2 cell = vec2(2.0);
    //p.z -= T * 0.9;
    p.xz = mod(p.xz + 0.0, cell) - 0.5*cell;

    return sdfCapsule(p);
}


float rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.0;

    for(int i=0; i<80; i++)
    {
        vec3 p = ro + rd * dt;
        float d = map(p);
        dt += d;
        if(d < 0.01 || dt > 20.0) break;
    }
    return dt;
}


vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
        map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
        map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
    ));
}


const vec2 R2 = vec2(0.754877669, 0.569840296);
vec2 jitter(int i) {
    return (fract((float(i)+0.5) * R2) - 0.5) / iResolution.xy; // in pixels
}

vec3 renderLinear(vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy)/iResolution.y;
    vec3 ro = vec3(0.0,0.0,3.0);
    vec3 rd = normalize(vec3(uv, -1.0)); 

    vec3 col = vec3(0.0);
    float dt = rayMarch(ro, rd);
    if (dt < 20.0) {
        vec3 p = ro + rd * dt;
        vec3 norm = calcNormal(p);
        col = norm;                         // normals-only as you had
    }
    return col;                              // linear space
}

#ifndef SPP
#define SPP 4        // try 4; bump to 8 if you need more smoothing
#endif


void mainImage( out vec4 O, in vec2 I )
{
    vec3 sum = vec3(0.0);

    // slight per-frame rotate of the sequence (optional; good for animation)
    vec2 r = mat2(cos(0.23*T), -sin(0.23*T), sin(0.23*T), cos(0.23*T)) * R2;

    for (int s = 0; s < SPP; ++s) {
        vec2 j = (fract((float(s)+0.5) * r) - 0.5) / iResolution.xy;
        sum += renderLinear(I + j);
    }

    vec3 col = sum / float(SPP);             // average in linear space
    col = pow(col * 2.1, vec3(1.1 / 2.2));   // your tone curve once

    O = vec4(col, 1.0);
}

/*
    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓


    ▓              🌟  KuKo Day 113  🌟                

    ▓  AA practice. using iqs AA method 

    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓
*/

// Copyright Inigo Quilez, 2014 - https://iquilezles.org/
