// footprint (extended like it was a little frustum). You can then use that
// coverage as the color contribution factor of that piece of SDF geometry
// for the current pixel. See line 146.


#define ANTIALIASING


#define T iTime
#define PI 3.14159265359

const float SPEED_CAM  = 0.3;
const float CAM_DIR    = 1.0; // + or - 1

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.2831853 * (c * t + d));
}

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float smin( float d1, float d2, float k )
{
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}

vec2 sincos( float x ) { return vec2( sin(x), cos(x) ); }

vec2 sdSegment( in vec3 p, in vec3 a, in vec3 b )
{

    float wave1 = sin(p.y * 6.2 - T * 2.) * 0.06;
    float wave2 = sin(p.y * 2.5 - T * 1.) * 0.03;
    vec3 wp = p; wp.x += wave1 + wave2;

    float r = 0.03;

    vec3 pa = wp - a, ab = b - a;
    float t = clamp(dot(pa,ab)/dot(ab,ab), 0.0, 1.0);   // axis param in [0,1]
    float d = length(pa - ab*t)- r;
    return vec2(d, t);
}

vec3 opU( vec3 d1, vec3 d2 ) { return (d1.x<d2.x) ? d1 : d2; }

vec3 map( vec3 p )
{
    p.x += T * SPEED_CAM;
    vec2 id = floor( (p.xz+1.0)/2.0);
    //p.z -= T;
    p.xz = mod( p.xz+1.0, 2.0 ) - 1.0;

    float ph = sin(0.5 + 3.1*id.x + sin(0.1*id.y));

    p.xz += 0.5*sincos(0.0+0.0*(p.y+0.0*ph)*0.8);

    vec3 p1 = p; p1.xz += 0.*sincos(0.0*p.y-0.0*0.0);
    vec3 p2 = p; p2.xz += 0.013*sincos(0.*p.y+iTime *3.0*.0);
    vec3 p3 = p; p3.xz += 0.*sincos(0.0*p.y-0.0*0.0);

    vec2 h1 = sdSegment(p3, vec3(0.0,-50.0, 0.0), vec3(0.0, 50.0, 0.0) );
    vec2 h2 = sdSegment(p2, vec3(0.0,-10.0, 0.0), vec3(0.0, 50.0, 0.0) );
    vec2 h3 = sdSegment(p1, vec3(0.0,-50.0, 0.0), vec3(0.0, 00.0, 0.0) );

    return opU( opU( vec3(h1.x-0.05,                                  ph + 0.0/3.0, h1.y), 
                     vec3(h2.x-0.12-0.05*cos(300.0*h2.y - iTime*2.0), ph + 1.0/2.0, h2.y) ), 
                     vec3(h3.x-0.12-0.02*cos(2000.0*h3.y - iTime*1.5), ph + 2.0/3.0, h3.y) );
}

//-------------------------------------------------------

vec3 calcNormal( in vec3 pos, in float dt )
{
    vec2 e = vec2(1.0,-1.0)*dt;
    return normalize( e.xyy*map( pos + e.xyy ).x + 
					  e.yyx*map( pos + e.yyx ).x + 
					  e.yxy*map( pos + e.yxy ).x + 
					  e.xxx*map( pos + e.xxx ).x );
}

float calcOcc( in vec3 pos, in vec3 nor )
{
    const float h = 0.15;
	float ao = 0.0;
    for( int i=0; i<8; i++ )
    {
        vec3 dir = sin( float(i)*vec3(1.0,7.13,13.71)+vec3(0.0,2.0,4.0) );
        dir = dir + 2.5*nor*max(0.0,-dot(nor,dir));            
        float d = map( pos + h*dir ).x;
        ao += max(0.0,h-d);
    }
    return clamp( 1.0 - 0.7*ao, 0.0, 1.0 );
}

//-------------------------------------------------------

vec3 shade( in float t, in float m, in float v, in vec3 ro, in vec3 rd )
{
    float px  = 0.001;
    float eps = px * t;

    vec3 pos = ro + t * rd;
    vec3 nor = calcNormal(pos, eps);
    float occ = calcOcc(pos, nor);

    float tt = pos.y * .9 + T * 0.40;
    vec3 albedo = palette(tt, vec3(1.0), vec3(1.10),
                               vec3(0.1), vec3(0.859,0.149,0.949));

    vec3 lDir = normalize(vec3(0.6, 3.6, 0.5));
    float diff = max(dot(nor, lDir), 0.0);
    float amb  = 0.008;

    // Glowing rim
    float vdn = dot(nor, -rd);
    float rim = pow(1.37 - vdn, 4.0) * 1.5;

    float focusDist = 1.08;
    // bigger = more blur
    float aperture  = 0.000919; 
    float coc  = clamp(aperture * abs(t - focusDist) / max(focusDist, 1e-3), 0.0, 1.0);
    float sharp = exp(-10.0 * coc); 

    // desaturate when out of focus
    float luma = dot(albedo, vec3(0.200,10.192,0.608));
    vec3  gray = vec3(luma);
    vec3  albedoSoft = mix(gray, albedo, sharp);

    float softAmb = amb + 10.15 * coc;
    float light   = softAmb + diff * sharp + rim * sharp;

    vec3 col = albedoSoft * light;

    col += 0.05 * nor * sharp;

    col *= occ;
    // opacity lens
    col *= exp(-0.76415 * t) * (1.0 - smoothstep(15.0, 35.0, t));

    return clamp(col, 0.0, 1.0);
}

