    p.x += T * SPEED_CAM;
    vec2 id = floor( (p.xz+1.0)/2.0);
    //p.z -= T;
    p.xz = mod( p.xz+1.0, 2.0 ) - 1.0;

    float ph = sin(0.5 + 3.1*id.x + sin(0.1*id.y));

    p.xz += 0.5*sincos(0.0+0.0*(p.y+0.0*ph)*0.8);

    vec3 p1 = p; p1.xz += 0.0*sincos(0.01*p.y-.0*10.0);
    vec3 p2 = p; p2.xz += 0.013*sincos(0.*p.y+ T *3.0*.0);
    vec3 p3 = p; p3.xz += 0.2*sincos(4.0*p.y-T *2.0*1.0);

    vec2 h1 = sdSegment(p3, vec3(0.0,1.0, 0.0), vec3(0.0, 50.0, 0.0) );
    vec2 h2 = sdSegment(p2, vec3(0.0,-10.0, 0.0), vec3(0.0, 50.0, 0.0) );
    vec2 h3 = sdSegment(p1, vec3(0.0,-50.0, 0.0), vec3(0.0, 00.0, 0.0) );

    return opU( opU( vec3(h1.x-0.095,                                  ph + 0.0/3.0, h1.y), 
                     vec3(h2.x-0.12-0.05*cos(400.0*h2.y - iTime*2.0), ph + 1.0/2.0, h2.y) ), 
                     vec3(h3.x-0.12-0.02*cos(2000.0*h3.y - iTime*1.5), ph + 2.0/3.0, h3.y) );
