vec3 shade( in float t, in float m, in float v, in vec3 ro, in vec3 rd )
{
    float px  = 0.001;
    float eps = px * t;

    vec3 pos = ro + t * rd;
    vec3 nor = calcNormal(pos, eps);
    float occ = calcOcc(pos, nor);

    float tt = pos.y * 1.50 + 6.0;
    vec3 albedo = palette(tt, vec3(0.30), vec3(0.90),
                               vec3(0.1), vec3(0.859,0.149,0.949));

    vec3 lDir = normalize(vec3(.6,3.6, 0.5));
    float diff = max(dot(nor, lDir), 0.0);
    float amb  = 0.008;

    // Glowing rim
    float vdn = dot(nor, -rd);
    float rim = pow(0.637 - vdn, 4.0) * 1.5;

    float focusDist = 0.308;
    // bigger = more blur
    float aperture  = 0.000919; 
    float coc  = clamp(aperture * abs(t - focusDist) / max(focusDist, 1e-3), 0.0, 1.0);
    float sharp = exp(-10.0 * coc); 

    // desaturate when out of focus
    float luma = dot(albedo, vec3(0.200,10.192,0.608));
    vec3  gray = vec3(luma);
    vec3  albedoSoft = mix(gray, albedo, sharp);

    float softAmb = amb + 10.15 * coc;
    float light   = softAmb + diff * sharp + rim * sharp;

    vec3 col = albedoSoft * light;

    col += 0.105 * nor * sharp;

    col *= occ;
