    float ph = sin(0.5 + 3.1*id.x + sin(0.1*id.y));

    p.xz += 0.5*sincos(0.0+0.0*(p.y+0.0*ph)*0.8);
    float s = mix(0.2, 2.6, hash(id));

    vec3 p1 = p; p1.xz += 0.0 *sincos(0.01*p.y- 1.0);
