// Improved hash function for better randomness
float hash(vec3 p) 
{
    p = fract(p * 0.3183099 + 0.1);
    p *= 17.0;
    return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
}

// Domain repetition function
vec3 opRep(vec3 p, vec3 c) {
    return mod(p + 0.5 * c, c) - 0.5 * c;
}

float sdfCapsule(vec3 p, vec3 id)
{
    vec3 wp = p;
    wp.x += sin(p.y * 1.56 - T * 2.5) * 0.16;

    float ra = 1.0;
    float rb = 0.15;

    vec3 a = vec3(0.0, -5.0, 0.0);
    vec3 b = vec3(0.0, 6., 0.0);
    vec3 pa = wp - a, ab = b - a;

    float h = clamp(dot(pa, ab) / dot(ab, ab), 0.0, 1.0);
    float r = mix(ra, rb, h);

    return length(pa - ab * h) - r;
}

float smin( float d1, float d2, float k )
{
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}

float map(vec3 p)
{
    // Apply domain repetition
    vec3 cellSize = vec3(5.0, 0.0, 10.0);
    vec3 rp = opRep(p, cellSize);

    // Add some variation to break up the perfect grid
    vec3 id = floor(p / cellSize);

    float variation = sin(id.x * 43.0 + id.z * 5.0) * 0.0;
    rp.y += variation;

    float d1 = sdfCapsule(rp, id);
    float d2 = p.y + 1.9;
    return smin(d1, d2, 1.0);
}

vec3 calculateNormal(vec3 p) 
{
    const float eps = 0.001;
    return normalize(vec3(
        map(p + vec3(eps, 0, 0)) - map(p - vec3(eps, 0, 0)),
        map(p + vec3(0, eps, 0)) - map(p - vec3(0, eps, 0)),
        map(p + vec3(0, 0, eps)) - map(p - vec3(0, 0, eps))
    ));
}

float raymarch(vec3 ro, vec3 rd) 
{
