    vec3 ld = normalize(vec3(3.0, 3.0, 1.0));

    // Background gradient
    float bgGrad = sqrt(I.y / R.y);
    vec4 bgColor = mix(vec4(0.169,0.020,0.200,1.0), vec4(0.239,0.012,0.271,1.0), bgGrad);
    O = bgColor;

    // Raymarch to find intersection
    float t = raymarch(ro, rd);

    if (t > 0.0) 
    {
        // Ray hits capsule
        vec3 hitPoint = ro + t * rd;
        vec3 norm = calculateNormal(hitPoint);

        // Lighting calculations
        float diffuse = max(0.0, dot(norm, ld));
        float facingAmount = max(0.0, dot(norm, -rd));

        // Capsule color with palette variation based on world position
        float tt = hitPoint.y * 0.053 + hitPoint.x * 0.01 + 3.0;
        vec3 albedo = palette(tt, vec3(1.0), vec3(1.0),
                                   vec3(.23), vec3(3.859,4.149,6.949)); 

        vec4 sdfColor = vec4(albedo, 1.0) * (0.32 + diffuse);

        // Silhouette effect
        float silhouetteMask = pow(1.0 - facingAmount, 3.0);

        O =  sdfColor + silhouetteMask;
    } else {
        // Ray misses capsule - calculate glow effect
        float minDist = 1000.0;
        vec3 closestPoint;

        // Enhanced glow sampling with more steps for repeated geometry
        for (float rayT = 0.0; rayT < 80.0; rayT += 0.3) {
            vec3 samplePoint = ro + rayT * rd;
            float dist = map(samplePoint);
            if (dist < minDist) {
                minDist = dist;
                closestPoint = samplePoint;
            }
        }

        float distToShapeEdge = minDist;

        // Enhanced glow with color variation based on position
        float glowIntensity = pow(max(0.0, 1.0 - distToShapeEdge * 1.2), 8.0);

        // Add color variation to the glow based on closest point
        float colorT = closestPoint.y * 0.02 + closestPoint.x * 0.01 + 2.0;
        vec3 glowAlbedo = palette(colorT, vec3(0.5), vec3(0.5),
                                       vec3(.23), vec3(3.859,10.149,0.949));

        vec4 glowColor = vec4(glowAlbedo * glowIntensity, glowIntensity);
        O += glowColor;
    }

    // Convert to sRGB color space
    O = pow(O * 0.7, vec4(1.1 / 2.2));
}

