*/

#define T iTime
#define FX sin(T * 0.3) * 0.5 + 0.4

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float smin( float d1, float d2, float k )
{
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}

/*
    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓


    ▓              💊  SDF, MAP  💊                


    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓
*/

float sdfCapsule(vec3 p, float id)
{
    p.x += sin(p.y * 4.5 - T) * .06;
    vec3 a = vec3(0.0, -10.0, 0.0);
    vec3 b = vec3(0.0, (0.3 * id) - FX, 0.0);
    vec3 pa = p - a, ab = b - a;

    float h = clamp( dot(pa, ab) / dot(ab, ab), 0.0,1.0);

    return length(pa - ab * h) - 0.15;
}

float map(vec3 p)
{
    vec2 cell = vec2(1.4, 1.0);
    p.z -= T * 0.4;
    vec2 id = floor(p.xz / cell);
    p.xz = mod(p.xz + 0.0, cell) - 0.5*cell;

    float s = mix(-1.1, 1.1, hash(id));  

    float d1 = sdfCapsule(p, s);
    float d2 = p.y + 3.0;
    return smin(d1, d2, 0.2);
}

/*
    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓


    ▓          💡  COLOR, RAYMARCH, NORMALS  💡                


    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓
*/

float rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.0;

    for(int i=0; i<80; i++)
    {
        float d = map(ro + rd * dt);
        dt += d;
        if(d < 0.01 || dt > 10.0) break;
    }
    return dt;
}

vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
        map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
        map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
    ));
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

vec3 renderScene(vec2 uv, out float dtOut) 
{
    float cam_up = sin(T * 0.2) * 0.7 - 0.54; 
    float cam_x = cos(T * 0.3) * 0.3;
    vec3 ro = vec3(0.0,cam_up,2.5);
    vec3 rd = normalize(vec3(uv, -1.0));

    float dt = rayMarch(ro, rd);
    dtOut = dt;

    vec3 col = mix(vec3(0.1),vec3(0.0,0.4,0.8),vec3(uv.y + 0.1));
    if (dt < 10.0) 
    {
        vec3 p     = ro + rd * dt;
        vec3 norm  = calcNormal(p);
        vec3 ld    = normalize(vec3(0.3,5.0,2.0));
        float diff = max(dot(norm, ld), 0.0);

        float vdn  = dot(norm, -rd);
        float wRim = max(fwidth(vdn),0.9);
        float rim  = pow(smoothstep(0.0,wRim, 1.0 - vdn), 2.0);

        float t     = exp((p.y - 0.3 + FX) * 1.9) * 0.1 + 0.75;
        vec3 albedo = palette(t, vec3(0.55), vec3(0.5), vec3(1.0), vec3(0.5, 0.6, 0.065));

        float focDist  = 1.0;
        float aperture = 0.03719;
        float bright   = 0.3;
        float ambient  = 0.3;

        float coc   = clamp(aperture * abs(dt - focDist) / max(focDist, 1e-3), 0.0, 1.0);
        float sharp = exp(-10.0 * coc);
        vec3 grey   = vec3(dot(albedo, vec3(0)));

        vec3 albedoSoft = mix(grey, albedo, sharp);
        float softAmb   = bright + 0.15 * coc;

        float d0  = map(p);
        float wCov = max(fwidth(d0), 1e-1);
        float alpha = 1.0 - smoothstep(0.0, wCov, d0);

        float spe = pow(max(dot(reflect(-ld,norm), -rd), 0.0), 2.0);

        float light = softAmb + (diff + 2.6 * rim) * sharp;

        col = albedoSoft * (0.5*spe + light) * alpha;
        //col = norm; 
    }
    col = pow(col * 1.1, vec3(1.1/2.2));
    return col;
}

/*
    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓


    ▓          💡  SMAA, Antialiasing  💡                


    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓
*/

float luma(vec3 c){ return dot(c, vec3(0.2126, 0.7152, 0.0722)); }

// SMAA-lite (single pass, no area/search textures)
vec3 smaaResolve(vec2 uv, vec3 C, float LC) 
{
    vec2 texel = 1.0 / iResolution.xy;

    // 1) Neighbor samples
    float d; // dummy
    vec3 Cr = renderScene(uv + vec2(texel.x, 0.0), d);
    vec3 Cl = renderScene(uv - vec2(texel.x, 0.0), d);
    vec3 Cu = renderScene(uv + vec2(0.0, texel.y), d);
    vec3 Cd = renderScene(uv - vec2(0.0, texel.y), d);

    float LR = luma(Cr), LL = luma(Cl), LU = luma(Cu), LD = luma(Cd);

    // 2) Edge detection (local contrast + threshold)
    float th = 0.05; // tune
    float horEdge = max(abs(LU - LC), abs(LD - LC));
    float verEdge = max(abs(LR - LC), abs(LL - LC));
    float edgeStrength = max(horEdge, verEdge);

    if (edgeStrength < th) return C; // no edge, keep original

    // Dominant orientation
    bool horizontal = (horEdge > verEdge);

    // 3) Short “search” along edge to estimate span (cheap stand-in for SMAA search tex)
    int maxSteps = 12; // tune: quality vs cost
    float spanNeg = 0.0, spanPos = 0.0;
    float Lref = LC;
    // adaptive threshold using local contrast
    float ath = th * (1.0 + 3.0*edgeStrength);

    // Horizontal edge => blend vertically (search up/down).
    if (horizontal) {
        // up
        for (int i=1; i<=maxSteps; ++i) {
            vec3 c = renderScene(uv + vec2(0.0, float(i)*texel.y), d);
            if (abs(luma(c) - Lref) < ath) { spanPos = float(i); break; }
            if (i==maxSteps) spanPos = float(i);
        }
        // down
        for (int i=1; i<=maxSteps; ++i) {
            vec3 c = renderScene(uv - vec2(0.0, float(i)*texel.y), d);
            if (abs(luma(c) - Lref) < ath) { spanNeg = float(i); break; }
            if (i==maxSteps) spanNeg = float(i);
        }

        // 4) Blend weight from span + edge strength (proxy for area tex)
        float span = spanNeg + spanPos;
        float w = clamp(edgeStrength * 4.0 * (span / float(maxSteps*2)), 0.0, 1.0);

        // sample across the edge normal (vertical)
        vec3 Cpos = renderScene(uv + vec2(0.0, 0.5*spanPos*texel.y), d);
        vec3 Cneg = renderScene(uv - vec2(0.0, 0.5*spanNeg*texel.y), d);
        vec3 Cavg = 0.5*(Cpos + Cneg);
        return mix(C, Cavg, w);
    }
    else {
        // Vertical edge => blend horizontally (search left/right).
        for (int i=1; i<=maxSteps; ++i) {
            vec3 c = renderScene(uv + vec2(float(i)*texel.x, 0.0), d);
            if (abs(luma(c) - Lref) < ath) { spanPos = float(i); break; }
            if (i==maxSteps) spanPos = float(i);
        }
        for (int i=1; i<=maxSteps; ++i) {
            vec3 c = renderScene(uv - vec2(float(i)*texel.x, 0.0), d);
            if (abs(luma(c) - Lref) < ath) { spanNeg = float(i); break; }
            if (i==maxSteps) spanNeg = float(i);
        }

        float span = spanNeg + spanPos;
        float w = clamp(edgeStrength * 4.0 * (span / float(maxSteps*2)), 0.0, 1.0);

        vec3 Cpos = renderScene(uv + vec2(0.5*spanPos*texel.x, 0.0), d);
        vec3 Cneg = renderScene(uv - vec2(0.5*spanNeg*texel.x, 0.0), d);
        vec3 Cavg = 0.5*(Cpos + Cneg);
        return mix(C, Cavg, w);
    }
}

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0*I - iResolution.xy)/iResolution.y;

    float dt;
    vec3 C = renderScene(uv, dt);
    float LC = luma(C);

    // SMAA-lite resolve
    vec3 outC = smaaResolve(uv, C, LC);

    O = vec4(outC, 1.0);
}

/*
    * Day 168 
    * Day 4 of work retreat, last day it was hard to do shaders on a work retreat 

    * AA practice using FXAA from a 2009 paper
    * https://developer.download.nvidia.com/assets/gamedev/files/sdk/11/FXAA_WhitePaper.pdf?
*/

float luma(vec3 c){ return dot(c, vec3(0.299, 0.587, 0.114)); }
// helper to avoid multiple luma calls
vec3 cN(vec3 x){return x;}

vec3 fxaa(sampler2D tex, vec2 uv, vec2 rcpFrame)
{
    // 3x3 neighborhood
    vec3 cM = texture(tex, uv).rgb;
    float lM = luma(cM);
    float lN = luma(texture(tex, uv + vec2(0.0, -rcpFrame.y)).rgb);
    float lS = luma(texture(tex, uv + vec2(0.0,  rcpFrame.y)).rgb);
    float lW = luma(texture(tex, uv + vec2(-rcpFrame.x, 0.0)).rgb);
    float lE = luma(texture(tex, uv + vec2( rcpFrame.x, 0.0)).rgb);

    // edge direction (FXAA uses luma gradient)
    float lH = (lW + lE) - 2.0*lM;
    float lV = (lN + lS) - 2.0*lM;

    // choose primary direction (bigger magnitude)
    bool horiz = abs(lH) >= abs(lV);
    float dirSign = horiz ? sign(lH) : sign(lV);
    vec2 dir = horiz ? vec2(dirSign, 0.0) : vec2(0.0, dirSign);

    // reduce step size on weak edges (similar to FXAA's reduce logic)
    float lMin = min(lM, min(min(lN,lS), min(lW,lE)));
    float lMax = max(lM, max(max(lN,lS), max(lW,lE)));
    float contrast = lMax - lMin;
    if(contrast < 0.031) return cM; // skip very low-contrast regions

    // sample along edge normal (per FXAA, filter is perpendicular to gradient)
    vec2 stepUV = dir.yx * rcpFrame; // rotate 90°
    // short & long taps (FXAA adapts; keep it tiny to avoid blur)
    vec3 c1 = texture(tex, uv + stepUV*0.5).rgb;
    vec3 c2 = texture(tex, uv - stepUV*0.5).rgb;
    vec3 c3 = texture(tex, uv + stepUV*1.5).rgb;
    vec3 c4 = texture(tex, uv - stepUV*1.5).rgb;

    vec3 blendNarrow = 0.5*(c1 + c2);
    vec3 blendWide   = 0.5*(c3 + c4);

    // pick narrow vs wide depending on how strong the edge is (very rough analog)
    float edgeStrength = clamp(contrast*8.0, 0.0, 1.0);
    vec3  result = mix(blendNarrow, blendWide, edgeStrength*0.5);

    // clamp to neighborhood to avoid overshoot (FXAA uses neighborhood bounds)
    result = clamp(result, min(min(cM, min(cN(c1), cN(c2))), min(c3, c4)),
                           max(max(cM, max(cN(c1), cN(c2))), max(c3, c4)));
    return result;
}


void mainImage(out vec4 O, vec2 I)
{
    vec2 R = iResolution.xy;
    vec2 uv  = I / R;
    vec2 rcp = 1.0 / R;

    vec3 colAA = fxaa(iChannel0, uv, rcp);
    O = vec4(colAA, 1.0);
}

#define T iTime
#define PI 3.14159265359

float hash11(float x){ return fract(sin(x*12.9898)*43758.5453123); }
vec2  hash21(float x){ return fract(sin(vec2(x, x+1.23)*vec2(12.9898,78.233))*43758.5453); }

mat2 R(float a){ float c=cos(a), s=sin(a); return mat2(c,-s,s,c); }

float sdSphere(vec3 p, float r){ return length(p)-r; }

float smin(float a, float b, float k){
    float h = clamp(0.5 + 0.5*(b-a)/k, 0.0, 1.0);
    return mix(b, a, h) - k*h*(1.0-h);
}

void basis(vec3 n, out vec3 t, out vec3 b)
{
    float s = sign(n.z==0.0 ? 1.0 : n.z);
    float a = -1.0/(s + n.z);
    float bb = n.x*n.y*a;
    t = vec3(1.0 + s*n.x*n.x*a, s*bb, -s*n.x);
    b = vec3(bb, s + n.y*n.y*a, -n.y);
}

float gEmit = 1e9;
float sdTentacle(vec3 p, vec3 o, vec3 n, float len, float r0, float r1, float seed)
{
    vec3 t, b; basis(n, t, b);
    float u = clamp(dot(p - o, n)/len, 0.0, 1.0);

    float wFreq = mix(1.5, 3.5, hash11(seed*3.1));
    float phase = T*mix(0.4, 0.9, hash11(seed*5.7)) + seed*6.28;
    float amp   = mix(0.03, 0.08, hash11(seed*2.3));
    vec2  sc    = vec2(sin(wFreq*u*6.283 + phase + T * 3.) * 0.3, cos(wFreq*u*6.283 + phase + T * 3.) * 0.2);
    vec3  side  = (t*sc.x + b*sc.y) * (amp*u);         

    vec3 c = o + n*(u*len) + side;
    float r = mix(r0, r1, u);

    vec3 tipC = o + n*len + (t*0.0 + b*0.0);
    gEmit = min(gEmit, length(p - tipC) - (r1*1.15));

    return length(p - c) - r;
}

vec3 hemiFibo(uint i, uint N)
{
    float phi = (sqrt(5.0)*0.5 + 0.5) * 2.0*PI;        // golden angle
    float k   = float(i) + 0.5;
    float y   = 1.0 - 2.0*k/float(N);                  // -1..1
    float r   = sqrt(max(0.0, 1.0 - y*y));
    float th  = phi*k;
    vec3 p    = vec3(cos(th)*r, y, sin(th)*r);
    if(p.y < 0.0) p.y = -p.y;                          // flip to upper hemi
    return normalize(p);
}

const uint NUM_TENT = 15u;       

float map(vec3 p)
{
    p.xz *= R(0.15 * (T*0.35));

    float baseR = .428;
    float d = sdSphere(p - vec3(0.0, -0.12, 0.0), baseR*0.9);

    for(uint i=0u; i<NUM_TENT; ++i){
        vec3 n = hemiFibo(i, NUM_TENT);                // outward normal
        vec3 o = vec3(0.0, -0.12, 0.0) + n*baseR;      // anchor on base surface

        float sd = sdTentacle(
            p, o, normalize(n + vec3(0.0,0.15,0.0)),   // push axis a bit upward
            /*len*/ mix(0.55, 0.95, hash11(float(i)*1.7)),
            /*r0 */ mix(0.055,0.075, hash11(float(i)*2.9)),
            /*r1 */ mix(0.018,0.028, hash11(float(i)*4.1)),
            /*seed*/ float(i)+13.0
        );
        d = smin(d, sd, 0.08);                         // soft union to keep “fleshy” look
    }
    return d;
}

vec3 calcNormal(vec3 p)
{
    float e = 1e-3;
    vec2 h = vec2(1,-1)*0.5773;
    return normalize( h.xyy*map(p+h.xyy*e) +
                      h.yyx*map(p+h.yyx*e) +
                      h.yxy*map(p+h.yxy*e) +
                      h.xxx*map(p+h.xxx*e) );
}

float march(vec3 ro, vec3 rd)
{
    float t = 0.0;
    for(int i=0;i<128;i++){
        vec3 p = ro + t*rd;
        float d = map(p);
        if(d<1e-4) return t;
        t += d;
        if(t>8.0) break;
    }
    return -1.0;
}

void mainImage(out vec4 O, vec2 I)
{
    vec2 p = (2.0*I - iResolution.xy)/iResolution.y;

    // Camera
    float ang = (T*1.2);
    vec3 ro = vec3(0,0,1.5);//vec3(2.5*sin(ang) + 1.0, 0.15, 2.5*cos(ang) + 1.0);
    vec3 ta = vec3(0.0,0.5,0);
    vec3 ww = normalize(ta - ro);
    vec3 uu = normalize(cross(vec3(0,1,0), ww));
    vec3 vv = cross(ww, uu);
    vec3 rd = normalize(p.x*uu + p.y*vv + 1.7*ww);

    // Raymarch
    gEmit = 1e9;
    vec3 col = vec3(0.0);
    float t = march(ro, rd);

    // Background
    col = mix(vec3(0.015,0.03,0.06), vec3(0.02,0.05,0.09), 0.5 + 0.5*p.y);

    if(t>0.0){
        vec3 pos = ro + t*rd;
        vec3 n = calcNormal(pos);
        vec3 l = normalize(vec3(0.7, 0.9, 0.4));
        vec3 h = normalize(l - rd);

        float diff = max(dot(n,l),0.0);
        float spe  = pow(max(dot(n,h),0.0), 32.0);

        vec3 baseCol = vec3(0.08,0.10,0.16);
        vec3 bodyCol = baseCol + vec3(0.0, 0.07, 0.03)*smoothstep(0.0, 0.8, diff);

        float glow = exp(-8.0*max(gEmit,0.0)) * 1.4;   // strong near tips
        vec3 tipCol = vec3(0.95, 0.98, 0.15) * glow;

        col = bodyCol + 0.9*diff + 0.25*spe + tipCol;

        col += 0.15*pow(max(dot(normalize(l+vec3(0,0.8,0)), n),0.0), 2.0);
    }

    col = pow(col, vec3(0.4545)); // gamma lift
    O = vec4(col,1.0);
}

