    ▓  Branching practice. I remember 14 years ago when I first 
    ▓  saw my first code in Processing - it was about someone 
    ▓  who created a tree with code and math. This got me hooked 
    ▓  on coding. Ever since that day, I wanted to learn how to 
    ▓  code. I didn't understand 99% of it. Now I'm happy to say
    ▓  that I understand 50% of it, haha. 

    ▓  This is very fun 😀

    ▓  Axiom: F
    ▓  Rule:  F -> [+F] F [-F] F     (classic bracketed tree)
    ▓  Turtle: F=draw forward, +=turn left, -=turn right, []=push/pop
    ▓  Based on @sillsm
    ▓  https://www.shadertoy.com/view/XtyGzh


    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓
*/

#define PI 3.14159265359
#define SPEED iTime * 0.2

const int   DEPTH   = 6;             // 3^6 = 729 paths
const float ANG     = radians(25.7);
const float LEN0    = 0.35;
const float SHRINK  = 0.66;          // per-level length shrink
const float WID     = 0.0021;        // branch radius
const int   BR      = 3;             // [+F], F, [-F]
const int   TOTAL   = 729;           // 3^6 (keep in sync with DEPTH)

mat3 Rot(float a){
    float c=cos(a), s=sin(a);
    return mat3(c, s, 0, -s,c,0, 0,0,1);
}
mat3 Disp(vec2 d){
    return mat3(1,0,0, 0,1,0, d,1);
}

// Capsule along +Y in local space; h.x=radius, h.y=half-length-center
float sdCappedCylinder(vec2 p, vec2 h)
{
    p -= vec2(0.0, h.y);
    vec2 d = abs(vec2(length(p.x), p.y)) - h;
    return min(max(d.x, d.y), 0.0) + length(max(d, 0.0));
}

vec2 treeOne(vec2 pt)
{
    // Tree location
    pt += vec2(0.0, 0.9);

    // Root trunk (for a solid base)
    float dBranch = sdCappedCylinder(pt, vec2(WID, LEN0));
    float dLeaf   = 1e5;

    int maxDepth = int(pow(float(BR) , float(DEPTH )));
    mat3 posR = Rot(+ANG);
    mat3 negR = Rot(-ANG);

    // c is the path counter in base-3.
    int c = 0;
    for (int iter = 0; iter < TOTAL && c < TOTAL; ++iter)
    {
        // Start each path from world sample 'pt'
        vec2 pLoc = pt;

        // off is current base-3 place value 
        int off = TOTAL;

        // Current segment length (shrink each level)
        float L = LEN0 * SHRINK;

        bool bailed = false;

        // L-SYSTEM APPLICATION (depth levels)
        // F -> [ + F ] F [ - F ] F   ==> 3 choices per level:
        // path==0 => [+F], path==1 => F, path==2 => [-F]
        for (int i = 1; i <= DEPTH; ++i)
        {
            off /= BR;
            int dec  = c / off;
            int path = dec - BR * (dec / BR); // dec % BR

            // Transform sample into this segment's local frame,
            // then move forward by current length.
            mat3 mx;
            if (path == 0) {
                mx = posR * Disp(vec2(0.0, -2.0*L));         // [+F]
            } else if (path == 1) {
                mat3 wind = Rot(.2*sin(SPEED + 6.2));
                mx = wind*negR*Disp(vec2(0.0, -2.0*L));      //  F
            } else {
                mat3 wind = Rot(.2*sin(SPEED + 1.0));
                mx = wind*negR * Disp(vec2(0.0, -2.0*L));    // [-F]
            }

            pLoc = (mx * vec3(pLoc, 1.0)).xy;

            // Draw this branch segment
            float y = sdCappedCylinder(pLoc, vec2(WID, L));
            dBranch = min(dBranch, y);

            // Early-out cull: if we're clearly outside a "noodle" around
            // this segment, skip the whole remaining subtree.
            if (y - 2.0*L > 0.0) { c += off - 1; bailed = true; break; }

            // uncomment to have the leaf At the last level, 
            // (small circle at the tip y=2L)
           // if (i == DEPTH) {
                float rLeaf = 0.0535 * L;
                float leaf  = length(pLoc - vec2(0.0, 2.*L)) - rLeaf;
                dLeaf = min(dLeaf, leaf);
            //}

            // Prepare next level length
            L *= SHRINK;
        }
        // Next path
        c++;
        if (c > maxDepth) break;
    }
    return vec2(dBranch, dLeaf);
}

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (I - 0.5*iResolution.xy) / iResolution.y;

    // Compute distances: x=branches, y=leaves
    vec2 d = treeOne(uv);

    // Pixel AA
    float px = 1.0 / iResolution.y;

    // Branch color
    float wB = 0.00140; // visual thickness
    float mB = smoothstep(wB + 2.0*px, wB - px, d.x);
    vec3 col = mix(vec3(0.0), vec3(0.80, 0.68, 0.74)*0.6, mB);

    // Leaf color 
    float wL = 0.001;
    float mL = smoothstep(wL + 10.0*px, wL - px, d.y);
    col = mix(col, vec3(0.522, 0.1172, 0.330), mL);

    O = vec4(col, 1.0);
}

