float smin( float d1, float d2, float k )
{
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}

float sdEllipsoid( vec3 p, vec3 r )
{
  float k0 = length(p/r);
  float k1 = length(p/(r*r));
  return k0*(k0-1.0)/k1;
}

float ufo(vec3 p)
{
    float fxX = sin(iTime) * 1.5 - 1.0;
    float fxY = cos(iTime) * 0.2 - 1.0;

    float d1 = sdEllipsoid(p + vec3(fxX,0.1 + fxY,-iTime), vec3(1.7,0.5,0.5));
    float d2 = length(p + vec3(fxX,-0.1 + fxY, -iTime)) - 0.7;

    return smin(d1, d2, 0.5);
}

vec2 map(vec3 p, float T)
{
    float fh = -1.9 + 0.08 * (sin(2.3 * p.x + iTime * 0.5) * sin(2.4 * p.z + iTime * 2.0));

    float d1 = ufo(p);

    float d2 = p.y - fh;

    float cell = 5.0;

    vec3 q    = vec3(mod(p.x + 0.0,cell) - 1.5, p.y, mod(p.z + 1.5, cell) - 1.5);
    vec2 id   = vec2(floor(abs(p.x) / cell), floor((p.z + 1.5) / cell ));
    float fid = id.x *511.1 + id.y * 131.7;
    float fy  = fract(fid * 1.312 + T * 0.1);
    float y   = -1.0 + 4.0 * fy;
    vec3 rad  = vec3(0.7, 2.0 + 0.5 * sin(fid *431.7), 0.7);

    rad -= 0.1 * (sin(p.x * 3.) + sin(p.y * 4.0) + sin(p.y * 5.));

    float d3 = sdEllipsoid(q - vec3(0.5, -2.5, 0) , rad);
    float fs = smoothstep(-0.3, 0.3, sin(5.0 * p.x) * sin(5.0 * p.z) * sin(5. * p.y));

    d3 -= fs * 0.02;

    float plane = smin(d2, d3, 0.4);

    //return min(d1, d2);
    return plane < d1 ? vec2(plane, 1.0) : vec2(d1, 2.0);
}

vec2 rayMarch(vec3 ro, vec3 rd, float T)
{
    float m = -1.0;
    float dt = 0.0;

    for(int i = 0; i < 100; i++)
    {
        vec2 d = map(ro + rd * dt, T);

        m = d.y; 
        dt += d.x;
        if(abs(d.x) < 0.0001 || dt > 20.) break;
    }

    if(dt > 20.0){
        m  = -1.0;
        dt = -1.0;
    }

    return vec2(dt, m);
}

float castShadow(vec3 ro, vec3 rd, float T)
{
    float res = 1.0;
    float dt  = 0.001;

    for(int i=0; i<100; i++)
    {
        float d = map(ro + rd * dt, T).x;
        res = min(res, 8.0 * d / dt);

        if(res < 0.001) break;
        dt += d;

        if(dt > 20.0) break;
    }
    return clamp(res, 0.0, 1.0);
}

vec3 calcNormal(vec3 p, float T)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0), T).x - map(p - vec3(e,0,0), T).x,
        map(p + vec3(0,e,0), T).x - map(p - vec3(0,e,0), T).x,
        map(p + vec3(0,0,e), T).x - map(p - vec3(0,0,e), T).x
    ));
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

void mainImage( out vec4 O, in vec2 I )
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;

    vec3 col = mix(vec3(0.2,0.5,0.8), vec3(0.0), uv.y + 0.0);

