vec4 map(vec3 p, float T)
{
    float matId = 0.0;

    float fh = -4.0 + 0.16 * (sin(1.5 * p.x + T * 0.0) * sin(0.9 * p.z + T * 0.0));

    // UFO
    vec3 u_p  = p;
    u_p.z += iTime * 1.4;
    u_p.x += 1.0;

    float u_cell = 3.0;
    u_p = vec3(mod((u_p.x) + 1.0, 6.0) - 1.5, u_p.y, mod(u_p.z + 1.0, 6.0) - 4.5);
    float d1  = ufo(u_p + vec3(0,1,0));

    vec3 u_p2  = p;
    u_p2.x += iTime * 0.5;
    float u_cell2 = 3.0;
    u_p = vec3(mod((u_p2.x) + 1.0, 7.0) - 1.5, u_p2.y, mod(u_p2.z + 1.0, 4.0) - 4.5);
    float d5  = ufo(u_p + vec3(0,-2.6,0));

    float ufo = min(d1, d5);

    // tubes
    vec3 ca = vec3(0, -0, 10);
    vec3 cb = vec3(0,  0,-10);
    vec3 cc = vec3(0,-40,-10);

    vec2 rXy = R2(3.1416/2.) * (cc - cb).xy;

    vec3 tube_p = vec3(-5,-1,1);
    // tube right
    vec2 res4 = sdfCapsule(p + tube_p, 0.1, ca, cb, cc, rXy);
    float d4  = res4.x;

    // tube rings
    vec3 c_p = p;
    c_p.y = sin(c_p.x * 0.564) * 4.6; 
    vec2 res5 = sdfCapsule(p + tube_p, 0.05, ca, cb, cc, rXy);
    float d6  = res5.x - 0.2 * cos(200.0 * res5.y - iTime * 0.5); 

    float tubeRight = smin(d4, d6, 0.1);

    // tube left
    vec3 ca2 = vec3(0, -0, 10);
    vec3 cb2 = vec3(0,  0,-10);
    vec3 cc2 = vec3(0,-40,-10);

    vec2 rXy2 = R2(-3.1416/2.) * (cc2 - cb2).xy;

    vec3 tube_p2 = vec3(6,-2.5,1);

    vec2 res6 = sdfCapsule(p + tube_p2, 0.15, ca2, cb2, cc2, rXy2);
    float d7  = res6.x;

    // tube rings left
    vec3 c_p2 = p;
    c_p2.y = sin(c_p2.x * 0.564) * 1.6; 
    vec2 res7 = sdfCapsule(p + tube_p2, 0.1, ca2, cb2, cc2, rXy2);
    float d8  = res7.x - 0.25 * cos(100.0 * res7.y - iTime * 1.0); 

    float tubeLeft = smin(d7, d8, 0.01);

    // tube up
    vec3 ca3 = vec3(0,-20,  0);
    vec3 cb3 = vec3(0, 10,  0);
    vec3 cc3 = vec3(0,  0,  0);

    vec2 rXy3 = R2(0.0) * (cc3 - cb3).xy;

    vec3 tube_p3 = vec3(2, 4.5,1.5);

    vec2 res9 = sdfCapsule(p + tube_p3, 0.15, ca3, cb3, cc3, rXy3);
    float d9  = res9.x;

    // tube rings up
    vec3 c_p3 = p;
    c_p3.y = sin(c_p3.x * 0.564) * 1.6; 
    vec2 res10 = sdfCapsule(p + tube_p3, 0.1, ca3, cb3, cc3, rXy3);
    float d10  = res10.x - 0.3 * cos(60.0 * res10.y + iTime * 1.0); 

    float tubeUp = smin(d9, d10, 0.21);

    //float tube = min(d4, d6);
    float tube = min(min(tubeRight,tubeLeft),tubeUp);

    // plane
    float d2 = p.y - fh;

    float cell = 5.0;
    // bubbles
    vec3 q    = vec3(mod((p.x) + 1.0,cell) - 1.5, p.y, mod(p.z + 1.5, cell) - 1.5);
    vec2 id   = vec2(floor(abs(p.x) / cell), floor((p.z + 1.5) / cell ));
    float fid = id.x * 411.1 + id.y * 431.7;
    float fy  = fract(fid * 0.33312 + 0.3 + T * 0.0);
    float y   = -1.3 + 3.0 * fy;
    float siz = 5.0*fy*(1.0-fy);
    vec3 rad  = vec3(0.7, 2.1 + 0.85 * sin(fid *331.7), 1.0);

    rad -= 0.1 * (sin(p.x * 1.5) + sin(p.y * 0.4) + sin(p.y * 2.5 + T * 0.5));

    float d3 = sdEllipsoid(q - vec3(1.0, y, 0.0) , siz * rad);
    float fs = smoothstep(-0.1, 0.1, sin(2.0 * p.x) * sin(4.0 * p.z) * sin(9. * p.y));

    d3 -= fs * 0.03;

    // Warm ring glow (used later as emissive + light hint)
    float ringGlow = 0.0;
    ringGlow = max(ringGlow, exp(-40.0*abs(d6)));   // right rings
    ringGlow = max(ringGlow, exp(-40.0*abs(d8)));   // left rings
    ringGlow = max(ringGlow, exp(-40.0*abs(d10)));  // vertical rings

    float bubbleMask = smoothstep(-0.0, 0.06, d2 - d3);

    float plane = smin(d2, d3, 0.7);

    float dist  = min(min(plane, ufo), tube);

    if(tube < plane && tube < ufo){
        matId = 3.0;
    } else if(plane < ufo){
        matId = 2.0;
    } else {
        matId = 1.0;
    }

    return vec4(dist, matId, ringGlow, bubbleMask);
}


// Approximate thickness through the SDF shape along a direction.
// Start slightly inside the surface and march until we exit (d>0).
float thicknessSDF(vec3 p, vec3 dir, float T){
    vec3 pos = p;
    float t = 0.0;
    for(int i=0;i<30;i++){
        float d = map(pos, T).x;
        if(d>0.0) break;                      // outside
        float step = clamp(-d*0.7, 0.02, 0.25); // stable inside steps
        pos += dir * step;
        t   += step;
        if(t>3.0) break;                      // safety
    }
    return t;
}

// Simple environment gradient for reflections/refractions
vec3 envColor(vec3 dir){
    float k = clamp(0.5 + 0.5*dir.y, 0.0, 1.0);
    vec3 ground = vec3(0.02,0.10,0.12);
    vec3 sky    = vec3(0.02,0.50,0.85);
    return mix(ground, sky, k);
}


vec4 rayMarch(vec3 ro, vec3 rd, float T)
{
    vec4 res = vec4(-1.0,-1.0,0.0,1.0);

    float tmin = 0.5;
    float tmax = 30.0;

	#if 1
    // raytrace bounding plane
    float tp = (5.4 - ro.y) / rd.y;
    if( tp > 0.0 ) tmax = min(tmax, tp );
	#endif    

    // raymarch scene
    float t = tmin;
    for( int i=0; i<456 && t<tmax; i++ )
    {
        vec4 h = map( ro+rd*t, T );
        if(abs(h.x) < (0.0001 * t))
        { 
            res = vec4(t, h.yzw); 
            break;
        }
        t += h.x;
    }

    return res;
}

float castShadow(vec3 ro, vec3 rd, float T)
{
    float res = 1.0;
    float dt  = 0.001;

    for(int i=0; i<120; i++)
    {
        float d = map(ro + rd * dt, T).x;
        res = min(res, 20.0 * max(d, 0.0) / dt);

        if((res) < 0.001) break;
        dt += clamp(d, 0.0001, 0.1);

        if(dt > 20.0) break;
    }
    return clamp(res, 0.0, 1.0);
}

vec3 calcNormal(vec3 p, float T)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0), T).x - map(p - vec3(e,0,0), T).x,
        map(p + vec3(0,e,0), T).x - map(p - vec3(0,e,0), T).x,
        map(p + vec3(0,0,e), T).x - map(p - vec3(0,0,e), T).x
    ));
}

float calcOcclusion( in vec3 pos, in vec3 nor, float T )
{
	float occ = 0.0;
    float sca = 1.0;

    for(int i = 0; i<5; i++)
    {
        float h = 0.01 + 0.411 * float(i) / 4.0;
        float d = map(pos + h * nor, T).x;
        occ += (h-d) * sca;
        sca *= 0.95;
    }
    return clamp( 1.0 - 2.0 * occ, 0.0, 1.0 );
}

// Small ray-march with custom tmin/tmax (used for the "through" pass)
vec4 rayMarchFrom(vec3 ro, vec3 rd, float T, float tmin, float tmax)
{
    vec4 res = vec4(-1.0,-1.0,0.0,1.0);
    float t = tmin;
    // lower cap than the main march to keep it cheap
    for (int i=0; i<96 && t<tmax; i++)
    {
        vec4 h = map(ro + rd*t, T);
        if (abs(h.x) < (0.0005 * t)) { res = vec4(t, h.yzw); break; }
        t += h.x;
    }
    return res;
}

float saturate(float x){ return clamp(x,0.,1.); }
float linstep(float a, float b, float x){ return saturate((x-a)/(b-a)); }

// --- GGX / Cook-Torrance ---
float D_GGX(float NdotH, float a){
    float a2 = a*a; 
    float d = NdotH*NdotH*(a2-1.0)+1.0; 
    return a2/(3.14159265*d*d);
}
float V_SmithGGXCorrelated(float NdotV, float NdotL, float a){
    float a2=a*a;
    float gv = NdotL*sqrt(a2 + (1.0-a2)*NdotV*NdotV);
    float gl = NdotV*sqrt(a2 + (1.0-a2)*NdotL*NdotL);
    return 0.5/(gv+gl+1e-5);
}
vec3  F_Schlick(vec3 F0, float cosTheta){
    return F0 + (1.0-F0)*pow(1.0-cosTheta,5.0);
}

// Softer, stable SDF shadow
float softShadowSDF(vec3 ro, vec3 rd, float k, float T){
    float res = 1.0, t = 0.05;
    for(int i=0;i<64;i++){
        float h = map(ro + rd*t, T).x;
        res = min(res, k*h/t);
        t += clamp(h, 0.03, 0.4);
        if(h<0.001 || t>25.0) break;
    }
    return clamp(res,0.0,1.0);
}

// ACES-ish tonemap
vec3 tonemapACES(vec3 x){
    const float a=2.51, b=0.03, c=2.43, d=0.59, e=0.14;
    return clamp((x*(a*x+b))/(x*(c*x+d)+e), 0.0, 1.0);
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

void mainImage( out vec4 O, in vec2 I )
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;

    //vec3 col = vec3(0.0,0.5,0.9);
    vec3 col = mix( vec3(0.2, 0.5, 0.9), vec3(0.1,0.3,0.6), uv.y - 0.1);
    float mAngles = 10.0 * iMouse.x / iResolution.x;
    vec3  control = vec3(1.5 * sin(mAngles), 1, 1.5 * cos(mAngles));

    float T = iTime;
    vec3 ro = vec3(-0, 0.0, 4.0 + T * 0.0) + control;
    vec3 rd = normalize(vec3(uv, -1.0));

    vec4 dt = rayMarch(ro, rd, T);

    col = mix(col, vec3(0.2,0.5,0.9), exp(-10.0 * rd.y));

    // ---------- LIQUID BUILDINGS (translucent, less bounce) ----------
    vec3 p     = ro + rd * dt.x;
    vec3 norm  = calcNormal(p, T);

    // ---------- CAPSULES: pure transparency (refract & re-march) ----------
    if (dt.y > 2.5) {                                    // matId == 3
        vec3 N  = norm;
        vec3 V  = rd;                                     // incident (toward scene)
        float IOR = 1.45;

        // Refract into the capsule
        vec3 Tdir = refract(V, N, 1.0/IOR);

        // If total internal reflection happens, fall back to environment (rare here)
        if (length(Tdir) < 0.5) {
            col = envColor(reflect(V, N));                // very faint fallback
        } else {
            // March to the exit point: start just *inside*, walk until we leave (d>0)
            float th = thicknessSDF(p - N*0.002, Tdir, T);
            vec3  ro2 = p + Tdir * (th + 0.006);          // just outside the far side

            // Re-march the scene behind the capsule along the refracted ray
            vec4 hit2 = rayMarchFrom(ro2, Tdir, T, 0.0, 10.0);

            // Very simple background shading (cheap): sky gradient + fog,
            // plus a tiny directional to reveal shapes if we actually hit something.
            vec3 bg = envColor(Tdir);                     // gradient base

            if (hit2.y > 0.0) {
                vec3 p2 = ro2 + Tdir * hit2.x;
                vec3 n2 = calcNormal(p2, T);
                vec3 L  = normalize(vec3(-0.25, 0.90, 0.35));
                float diff = max(dot(n2, L), 0.0);

                // coarse albedos per material so silhouettes read through the glass
                vec3 alb = (hit2.y > 2.5) ? vec3(0.3)              // other capsules
                         : (hit2.y > 1.5) ? mix(vec3(0.05,0.18,0.25), vec3(0.10,0.45,0.55), hit2.w) // ground/buildings
                                          : vec3(0.30,0.55,0.65);   // UFOs

                bg = alb * (1.2 + 0.8*diff);
                // fog on the behind surface
                bg = mix(bg, vec3(0.0,0.4,0.6), 1.0 - exp(-0.0001*hit2.x*hit2.x*hit2.x));
            }

            // Pure transparency: just use what we saw through the capsule
            col = bg;

            // Optional (keeps edges readable; extremely faint):
            //col = mix(col, envColor(reflect(V, N)), 0.03);
        }
    }


    // only when the union "plane" material is hit, but we're on a bubble
    else if(dt.y > 0.5 && dt.w > 0.0){
        vec3 V = normalize(-rd);
        vec3 L = normalize(vec3(-0.30, 0.85, 0.35));      // cyan key
        float NdotL = max(dot(norm, L), 0.0);
        float NdotV = max(dot(norm, V), 0.0);

        // --- Translucency / transmission ---
        vec3 pin = p - norm*0.02;                         // start just inside
        float thL = thicknessSDF(pin,  L,  T);            // thickness toward light
        float thV = thicknessSDF(pin, -V,  T);            // thickness toward camera

        // Beer–Lambert absorption (water-like: kill reds more)
        vec3 sigma = vec3(4.0, 2.2, 0.35);                // tweak = “liquid color”
        vec3 transL = exp(-sigma * thL);
        vec3 transV = exp(-sigma * thV);

        // Back-lit glow (light passing through)
        vec3 through = transL * vec3(0.8,2.1,1.4) * clamp(dot(-norm, L), 0.0, 1.0);

        // --- Very low diffuse bounce (liquids don’t look chalky) ---
        float sh = softShadowSDF(p + norm*0.02, L, 6.0, T);
        vec3 baseB = mix(vec3(0.06,0.18,0.25), vec3(0.05,0.65,0.80), linstep(-0.4,0.6,p.y));
        vec3 lambert = baseB * (0.12 * NdotL * sh);       // 0.12 = low bounce

        // --- Specular (GGX), small F0; liquids are mostly dielectric ---
        float a = 0.22*0.22;                              // roughness^2  (~0.22)
        vec3  H = normalize(L+V);
        float NdotH = max(dot(norm,H),0.0);
        float LdotH = max(dot(L,H),0.0);
        vec3  F0    = vec3(0.02);
        vec3  F     = F_Schlick(F0, LdotH);
        float  D    = D_GGX(NdotH, a);
        float  Vis  = V_SmithGGXCorrelated(NdotV, NdotL, a);
        vec3  spec  = (D*Vis)*F * (NdotL * sh) * vec3(0.9,1.1,1.2);

        // --- Fresnel mix to add a bit of environment reflection ---
        vec3 envRefl = envColor(reflect(-V, norm)) * F_Schlick(F0, NdotV) * 0.6;

        // --- Refracted tint toward the camera (very cheap) ---
        vec3 envRefr = envColor(refract(-V, norm, 1.0/1.33)); // ~water IOR
        vec3 refrCol = transV * mix(envRefr, baseB, 0.3) * 0.6;

        // Warm hint from ring emissive (already computed in dt.z)
        vec3 ringWarm = vec3(1.00, 0.50, 0.15) * dt.z * 0.25;

        // Put it together
        vec3 buildCol = lambert + spec + envRefl + through + refrCol + ringWarm;

        // Tone map & write only where we’re actually on the bubble
        buildCol = tonemapACES(buildCol);
        col = mix(col, buildCol, dt.w);
    }

    // ---------- FOG FLOOR (blended with buildings) ----------
    if (dt.y > 1.5 && dt.y < 2.5 && dt.w < 0.5) {                // plane hit AND not a bubble

        // Simple fog based on height and distance
        float fogHeight = clamp((p.y + 2.0) / 3.0, 0.0, 1.0);
        float fogDistance = clamp(dt.x / 15.0, 0.0, 1.0);

        // Fog density - thicker at bottom, thinner at top
        float density = (1.0 - fogHeight) * 0.8 + 0.2;

        // Fog color - soft blue/teal
        vec3 fogColor = vec3(0.2, 0.4, 0.6);

        // Mix with distance fog for depth
        fogColor = mix(fogColor, vec3(0.1, 0.2, 0.4), fogDistance);

        // Apply density
        col = tonemapACES(fogColor * density);
    }

    // ---------- BLEND FOG WITH BUILDINGS (smooth transition) ----------
    if (dt.y > 1.5 && dt.y < 2.5 && dt.w > 0.0) {                // we hit a building/bubble

        // Calculate fog parameters at this position
        float fogHeight = clamp((p.y + 2.0) / 3.0, 0.0, 1.0);
        float fogDistance = clamp(dt.x / 15.0, 0.0, 1.0);
        float fogDensity = (1.0 - fogHeight) * 1.8 + 0.2;

        vec3 fogColor = vec3(.2, 0.4, 0.6);
        fogColor = mix(fogColor, vec3(0.1, 0.2, 0.4), fogDistance);

        // Create smooth blend factor based on height and bubble mask
        // Lower buildings blend more with fog
        float blendFactor = smoothstep(0.2, 2.0, fogDensity) * smoothstep(0.3, 0.7, dt.w);

        // Mix the existing building color with fog
        col = mix(col, fogColor * fogDensity, blendFactor * 0.6);
                col = mix( col, vec3(0.,0.5,0.6), 1.0-exp( -0.00001*dt.x*dt.x*dt.x ) );
    }

    else if (dt.y > 0.5 && dt.y < 1.5) {   // was: dt.y < 1.0
        vec3 N  = norm;
        vec3 V  = normalize(-rd);
        vec3 L  = normalize(vec3(-0.25, 0.85, 0.25));

        float NdotL = max(dot(N, L), 0.0);
        float NdotV = max(dot(N, V), 0.0);

        vec3 base = vec3(0.08, 0.21, 0.36);
        vec3 body = base * (0.25 + 0.65 * NdotL);

        float underside = smoothstep(0.0, -0.6, N.y);
        float center    = smoothstep(-1.0, -0.25, N.y);
        vec3  belly     = vec3(0.05, 0.85, 1.25) * underside * center;

        float rim = pow(1.0 - NdotV, 5.0) * smoothstep(0.05, 0.6, N.y);
        vec3  warmRim = vec3(1.20, 0.35, 0.10) * rim;

        vec3  F0   = vec3(0.02);
        vec3  refl = envColor(reflect(-V, N)) * F_Schlick(F0, NdotV) * 0.25;

        col = tonemapACES(body + belly + warmRim + refl);
    }



    col = pow(col * 1.0, vec3(1.0 / 2.2));

    O = vec4(col,1.0);
}

