    vec2 sdf = d1 < d2 ? vec2(smin(d1, d2,0.1), 1.0) : vec2(smin(d2, d1, 0.1), 2.0);

    return vec4(sdf, 0.0, 1.0);
}

float circlePattern(vec3 p, float T)
