    newp = vec3(mod(newp.x + 3.0, 7.0) - 2.5, mod(newp.y + 0.0,5.0) - 2.5, mod(newp.z + 0.0,5.0) - 2.5);
    vec3 b  = vec3(1.0,1.0,1.0);
    float r = 0.05;

    float d1 = sdBoxFrame(p, b * 1.3, r) - 0.025;
    d1 = smoothstep(0.0,0.01,d1);
