/*
    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓

    ▓           🌟  Utility functions, SDFs 🌟                

    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓
*/

// Colors
#define BG_COLOR    vec3(0.01)
#define BORDER      vec3(0.9)
#define GRAY_DARK   vec3(0.318,0.325,0.373)
#define GRAY_LITE   vec3(0.718,0.757,0.855)
#define ORANGE_DARK vec3(0.757,0.545,0.2)
#define ORANGE_LITE vec3(0.914,0.757,0.38)

// borders
#define OUTLINE_THICKNESS 0.01
#define OUTLINE_THRESHOLD 0.7

// Utility function
float Smooth(float sdf) { 
    return 1. - smoothstep(-0.025, -0.01, sdf);
}

// Clean cat shader using structured approach
mat2 R2(float a){ return mat2(cos(a), -sin(a), sin(a), cos(a));}

float smin( float d1, float d2, float k )
{
    k *= 4.0;
    float h = max(k-abs(d1-d2),0.0);
    return min(d1, d2) - h*h*0.25/k;
}

float sdEllipse( in vec2 p, in vec2 ab )
{
    p = abs(p); if( p.x > p.y ) {p=p.yx;ab=ab.yx;}
    float l = ab.y*ab.y - ab.x*ab.x;
    float m = ab.x*p.x/l;      float m2 = m*m; 
    float n = ab.y*p.y/l;      float n2 = n*n; 
    float c = (m2+n2-1.0)/3.0; float c3 = c*c*c;
    float q = c3 + m2*n2*2.0;
    float d = c3 + m2*n2;
    float g = m + m*n2;
    float co;
    if( d<0.0 )
    {
        float h = acos(q/c3)/3.0;
        float s = cos(h);
        float t = sin(h)*sqrt(3.0);
        float rx = sqrt( -c*(s + t + 2.0) + m2 );
        float ry = sqrt( -c*(s - t + 2.0) + m2 );
        co = (ry+sign(l)*rx+abs(g)/(rx*ry)- m)/2.0;
    }
    else
    {
        float h = 2.0*m*n*sqrt( d );
        float s = sign(q+h)*pow(abs(q+h), 1.0/3.0);
        float u = sign(q-h)*pow(abs(q-h), 1.0/3.0);
        float rx = -s - u - c*4.0 + 2.0*m2;
        float ry = (s - u)*sqrt(3.0);
        float rm = sqrt( rx*rx + ry*ry );
        co = (ry/sqrt(rm-rx)+2.0*g/rm-m)/2.0;
    }
    vec2 r = ab * vec2(co, sqrt(1.0-co*co));
    return length(r-p) * sign(p.y-r.y);
}

float sdEgg( in vec2 p, in float ra, in float rb )
{
    const float k = sqrt(3.0);
    p.x = abs(p.x);
    float r = ra - rb;
    return ((p.y<0.0)       ? length(vec2(p.x,  p.y    )) - r :
            (k*(p.x+r)<p.y) ? length(vec2(p.x,  p.y-k*r)) :
                              length(vec2(p.x+r,p.y    )) - 2.0*r) - rb;
}

float sdCircle(vec2 p, float r)
{
    return length(p) - r;
}

float sdEquilateralTriangle(in vec2 p, in float r)
{
    const float k = sqrt(3.0);
    p.x = abs(p.x) - r;
    p.y = p.y + r/k;
    if( p.x+k*p.y>0.0 ) p = vec2(p.x-k*p.y,-k*p.x-p.y)/2.0;
    p.x -= clamp( p.x, -2.0*r, 0.0 );
    return -length(p)*sign(p.y);
}

vec3 DoOutline(float d, vec3 color, float thickness, vec3 outColor)
{
    if (d < 0.)
    {
        float t = -d / thickness;
        t = t * t;
        color = mix(outColor, color, step(OUTLINE_THRESHOLD, t));
    }
    return color;
}

vec2 mainSound( int samp, float time )
{
    float P = 4.0; // Period of each ghost wail
    float t = mod(time, P);

    // Base frequency - low and haunting (around 150Hz)
    float baseFreq = 150.0 + 50.0 * sin(0.3 * time); // Slow frequency wobble across cycles

    // Add tremolo (amplitude modulation) for that ghostly warble
    float tremolo = 0.5 + 0.5 * sin(8.0 * t + sin(2.3 * t));

    // Main oscillator - more of a triangle/saw wave for breathiness
    float osc1 = sin(6.2831 * baseFreq * t);
    float osc2 = sin(6.2831 * baseFreq * t * 0.5) * 0.3; // Sub-harmonic

    // Add lots of filtered noise for breathiness
    float noise1 = sin(t * 647.3) * sin(t * 923.1) * sin(t * 1234.7);
    float noise2 = sin(t * 641.2) * sin(t * 1456.8);
    float breath = (noise1 + noise2 * 1.15) * 0.94;

    // Low-pass filter the noise (simple approximation)
    breath = breath * exp(-t * 0.1) * (1.0 + sin(t * 0.7));

    // Combine oscillators and breath
    float sound = (osc1 + osc2) * tremolo + breath;

    // Ghost envelope: slow attack, sustain, then fade for each cycle
    float attack = smoothstep(0.0, .3, t);           // slow attack
    float sustain = 1.0 - smoothstep(2.0, P, t);      // fade out near end of cycle
    float envelope = attack * sustain;

    // Add some reverb-like echo effect
    float echo1 = sin(6.2831 * baseFreq * (t - 0.15)) * 0.2 * envelope;
    float echo2 = sin(6.2831 * baseFreq * (t - 0.3)) * 0.1 * envelope;

    sound += echo1 + echo2;

    // Soft compression/limiting
    sound = tanh(sound * 0.035) * 0.036;

    return vec2(sound * envelope);
}

