    vec2 u = uv;
    vec4 o = vec4(col, 1.0);
    o += vec4(1.0, 0.6, 0.2, 0.0) * 0.02; // Add some light color
    o += tanh(o /2. / dot(u+=vec2(1.3,-0.7), u));

    O = o;
