vec2 SDFGhost(vec3 pos)
{
    vec3 q = pos + vec3(0.0, sin(t * 5.0) * 0.1, 0.0);

    float body = sdCappedCylinder(q - vec3(0.0, -1.0, 0.0), 1.0, 1.0);
    float head = sdSphere(q, 1.);
    float baseGhost = min(body, head);

    float repeat = 6.5;
    float wave =
        (0.9 + 0.2 * sin(t * 1.0)) *
        sin(q.x * repeat + t * 5.0) *
        sin(q.z * repeat + t * 5.0) * 2.0;

    float wavePlane = sdPlane(q, 1.1 - 0.1 * wave) * 0.5;
    float ghostD = max(baseGhost, -wavePlane);

    vec2 res = vec2(ghostD, GHOST_BODY);

    vec3 e = vec3(abs(q.x), q.yz);
    float eyeD   = sdSphere(e - vec3(0.35, 0.20, 0.70), 0.30);
    float pupilD = sdSphere(e - vec3(0.37, 0.23, 0.82), 0.20);

    res = combineMin(res, vec2(eyeD,   GHOST_EYE));
    res = combineMin(res, vec2(pupilD, GHOST_PUPIL));

    return res;
}

float map(vec3 p)
{
    vec2 g = SDFGhost(p);
    return g.x;
}


float rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.0;

    for(int i=0; i<100; i++)
    {
        float d = map(ro + rd * dt);
        dt += d;
        if(abs(d) < 0.001 || dt > 20.0) break;
    }

    return dt;
}

vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
        map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
        map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
    ));
}

mat3 setCamera( in vec3 ro, in vec3 ta, float cr )
{
    vec3 cw = normalize(ta-ro);
    vec3 cp = vec3(sin(cr), cos(cr),0.0);
    vec3 cu = normalize( cross(cw,cp) );
    vec3 cv =          ( cross(cu,cw) );
    return mat3( cu, cv, cw );
}

void mainImage( out vec4 O, in vec2 I )
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    vec3 col = vec3(0);
    float T = iTime;

    vec3 ta = vec3(0);
    //vec3 ro = ta + vec3(4.0*cos(0.5*T), 2.0, 7.0*sin(0.5*T)); 
    //vec3 ro = ta + vec3(1.0*cos(1.5), 2.0, 7.0*sin(1.5)); 
    vec3 ro = ta + vec3(1.0, 2.0, 6.); 

    mat3 ca = setCamera(ro, ta, 0.5);

    vec3 rd = ca * normalize(vec3(uv, 3.0));

    float dt = rayMarch(ro, rd);

    if(dt < 20.0)
    {
        vec3 p = ro + rd * dt;
        vec3 norm = calcNormal(p);

        if(true)
        col = 0.5 + 0.5*norm.yxz;

        col = mix( col, vec3(0.0), 1.0-exp( -0.001*dt*dt*dt) );
    }

    O = vec4(col, 1.0);
}

