// Ghost / Theremin Wail — sine + glide + vibrato + light echoes
// Minimal noise for "air". Stereo uses slightly different echo taps.
const float PI2 = 6.28318530718;
const float P   = 3.6;  

float freqAt(float u)
{
    float fStart = 380.0;       // start ~A5
    float fEnd   = 220.0;       // end ~A3
    float glide  = exp(-u/1.15);// time constant controls descent
    float f      = mix(fEnd, fStart, clamp(glide, 0.0, 1.0));
    float vib    = 1.0 + 0.001 * sin(PI2 * 6.0 * u);
    return f * vib;
}

// Smooth amplitude envelope: slow attack, hold, then fade
float envAt(float u)
{
    float attack  = smoothstep(0.00, 0.25, u);
    float release = 1.0 - smoothstep(P - 0.70, P, u);
    return attack * release;
}

// Safe sine oscillator using current freq approximation
float osc(float u){ return sin(PI2 * freqAt(u) * u); }

// Tiny hiss (very low) for breathiness; per-sample white noise
float hiss(int s)
{
    float n = fract(sin(float(s) * 12.9898) * 43758.5453);
    return (n * 2.0 - 1.0) * 0.02; // very subtle
}

// Echo tap: delayed copy with its own env & freq
float echoTap(float u, float delay, float gain)
{
    float td = u - delay;
    if(td <= 0.0) return 0.0;
    return osc(td) * envAt(td) * gain;
}

vec2 mainSound( int samp, float time )
{
    // length of one "wail" cycle (seconds)
    float t = mod(time, P);

    // ---------- Dry signal ----------
    float trem   = 0.90 + 0.10 * sin(PI2 * 4.0 * t); // subtle tremolo
    float dry    = osc(t) * envAt(t) * trem;

    // ---------- Space (simple echoes, different per channel) ----------
    float eL = 0.0;
    eL += echoTap(t, 0.22, 0.30);
    eL += echoTap(t, 0.41, 0.18);

    float eR = 0.0;
    eR += echoTap(t, 0.28, 0.30);
    eR += echoTap(t, 0.49, 0.18);

    // ---------- Air (very light) ----------
    float air = hiss(samp) * envAt(t);

    // ---------- Mix & gentle soft clip ----------
    float left  = dry + eL + air;
    float right = dry + eR + air;

    float gain = 0.035;
    left  = tanh(left  * gain);
    right = tanh(right * gain);

    return vec2(left, right);
}

