#define MAX_STEPS 80
#define MAX_DIST 120.0
#define SURF_DIST 0.0005
#define PI 3.14159265359

mat2 rot2D(float a) {
    float c = cos(a), s = sin(a);
    return mat2(c, -s, s, c);
}

// Smooth mandelbrot iteration with better interpolation
float mandelbrotSmooth(vec2 c, int maxIter) {
    vec2 z = vec2(0.0);
    float iter = 0.0;

    for(int i = 0; i < 256; i++) {
        if(i >= maxIter) break;

        z = vec2(z.x * z.x - z.y * z.y, 3.0 * z.x * z.y) + c;

        float mag2 = dot(z, z);
        if(mag2 > 256.0) {
            // Smooth iteration count using continuous potential
            iter = float(i) + 1.0 - log2(log2(mag2) * 0.5);
            return iter;
        }
    }

    return float(maxIter);
}

// Smooth height function using potential method
float getHeight(vec2 c) {
    float escape = mandelbrotSmooth(c, 64);

    // Use smooth exponential decay for smoother terrain
    float t = escape / 64.0;
    t = smoothstep(0., 1.0, t);

    // Create layered height with smooth transitions
    float height = escape * 0.032;

    // Add subtle wave pattern for smoothness
    height += sin(escape * 0.5) * 0.01;

    return height;
}

// Distance function with smoother sampling
float sdMandelbrot(vec3 p) {
    vec2 c = p.xz;

    // Multi-sample for smoother normals
    float h = getHeight(c);

    return p.y - h * 0.6;
}

float map(vec3 p) {
    p.xz *= rot2D(iTime * 0.08);
    p *= 0.46;

    float d = sdMandelbrot(p);
    float ground = p.y + 2.5;

    return min(d, ground);
}

// Better normal calculation with larger epsilon
vec3 calcNormal(vec3 p) {
    vec2 e = vec2(0.002, 0.0);
    return normalize(vec3(
        map(p + e.xyy) - map(p - e.xyy),
        map(p + e.yxy) - map(p - e.yxy),
        map(p + e.yyx) - map(p - e.yyx)
    ));
}

float rayMarch(vec3 ro, vec3 rd) {
    float t = 0.0;

    for(int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + rd * t;
        float d = map(p);

        if(abs(d) < SURF_DIST || t > MAX_DIST) break;

        t += d * 1.0;
    }

    return t;
}

void mainImage(out vec4 O, in vec2 I) {
    vec2 uv = (I - 0.5 * iResolution.xy) / iResolution.y;

    vec3 ro = vec3(0.0, 2.5, -5.5);
    vec3 lookAt = vec3(0.0, 0.3, 0.0);

    float angle = iTime * 0.15;
    ro.xz = vec2(cos(angle), sin(angle)) * 5.5;

    vec3 forward = normalize(lookAt - ro);
    vec3 right = normalize(cross(vec3(0, 1, 0), forward));
    vec3 up = cross(forward, right);

    vec3 rd = normalize(forward + uv.x * right + uv.y * up);

    float t = rayMarch(ro, rd);

    vec3 col = vec3(0.05, 0.02, 0.1);

    if(t < MAX_DIST) {
        vec3 p = ro + rd * t;
        vec3 n = calcNormal(p);

        vec3 lightPos = vec3(4.0, 7.0, -4.0);
        vec3 lightDir = normalize(lightPos - p);
        float diff = max(dot(n, lightDir), 0.0);

        vec2 c = (p.xz * rot2D(-iTime * 0.08)) / 0.6;
        float escape = mandelbrotSmooth(c, 64);
        float t_col = escape / 64.0;

        vec3 col1 = vec3(0.1, 0.15, 0.3);
        vec3 col2 = vec3(0.9, 0.6, 0.2);
        vec3 col3 = vec3(0.7, 0.2, 0.4);

        vec3 baseCol = mix(col1, col2, smoothstep(0.0, 0.5, t_col));
        baseCol = mix(baseCol, col3, smoothstep(0.5, 1.0, t_col));

        float ambient = 0.25;
        float fresnel = pow(1.0 - max(dot(n, -rd), 0.0), 2.5);

        col = baseCol * (ambient + diff * 0.8) + fresnel * vec3(0.3, 0.2, 0.4);

        float fog = 1.0 - exp(-0.015 * t * t);
        col = mix(col, vec3(0.05, 0.02, 0.1), fog);
    }

    col = pow(col, vec3(0.4545));

    O = vec4(col, 1.0);
}

