vec2 map(vec3 p)
{
    float cell = 4.0;
    vec3 q    = vec3(mod((p.x) + 0.0,10.0) - 5., mod((p.y) + 0.0,7.0) - 3.5, mod((p.z) + 0.0,cell) - 1.5);
    vec2 id   = vec2(floor(abs(p.x) / cell), p.z);

    //q.xz *= R2(iTime * 0.5);

    vec2 d1 = vec2(sdRoundBox(q, vec3(2.0,1.,1), 0.1), 1.0);
    vec2 d2 = vec2(sdBoxFrame(q, FRAME_B, FRAME_E), 2.0);

    return combineMin(d1, d2);
}

vec2 rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.0;
    float id = 0.0;
    glow = vec3(0.0);

    for(int i=0; i<50; i++)
    {
        vec3 p = ro + rd * dt;
        float cell = 4.0;

        vec3 q    = vec3(mod((p.x) + 0.0,10.0) - 5., mod((p.y) + 0.0,7.0) - 3.5, mod((p.z),cell) - 1.5);

        vec2 d = map(p);
