vec3 _noisePos;
vec3 glow;
const vec3  FRAME_B = vec3(1.96, 4.5, 0.96);
const float FRAME_E = 0.01;

const vec3  GLOW_COLOR   = vec3(1); 
const float GLOW_STRENGTH= 0.014;                  
const float GLOW_FALLOFF = 20.0;                 

vec2 map(vec3 p)
{
    float cell = 4.0;

    vec3 q  = vec3(mod((p.x) + 0.0,10.0) - 5., mod((p.y) + 0.0,20.0) - 10., mod((p.z) + 0.0,cell) - 1.5);

    vec3 box = q;
    vec2 id   = vec2(floor(abs(p.x) / cell), p.z);

    q.y += iTime;
    // fx
    float wave = sin(box.z * 0.8 + iTime * 2.0) * sin(box.x * 1.5) * 0.3;
    //box.xy *= R2(box.z * .95 * 0.3);
    float pulse = 0.9 + 0.1 * sin(iTime * 0.1 + box.y * 3.95);

    // SDFs
    vec2 d1 = vec2(sdRoundBox(box, vec3(2.0,10.,1), 0.1), 1.0);
    vec2 d2 = vec2(sdBoxFrame(q, FRAME_B, FRAME_E), 2.0);
    //return d1;
    return combineMin(d1, d2);
}

vec2 rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.0;
    float id = 0.0;
    glow = vec3(0.0);

    for(int i=0; i<50; i++)
    {
        vec3 p = ro + rd * dt;
        float cell = 4.0;

        vec3 q    = vec3(mod((p.x) + 0.0,10.0) - 5., mod((p.y) + 0.0,20.0) - 10.5, mod((p.z),cell) - 1.5);
        vec3 pf   = vec3(mod((p.x) + 0.0,10.0) - 5., mod((p.y + iTime) + 0.0,5.0) - 0.5, mod((p.z),cell) - 1.5);

        vec2 d = map(p);
        _noisePos = q;
        //_noisePos.xy *= R2(_noisePos.z * 0.15 + iTime * 0.3);

        if(abs(d.x) < 0.001 )
        {
            id = d.y;
            break;
        }

        float dFrame = sdBoxFrame(pf, FRAME_B, FRAME_E);

        float stepLen = clamp(d.x, 0.1, 0.2);          
        float fall    = 1.0 / (1.0 + dFrame*dFrame*GLOW_FALLOFF);
        float mask    = smoothstep(0.25, 0.0, abs(dFrame));

        float fogAmount = exp(-0.0005*dt*dt*dt);
        float fx = sin(iTime * 5.) * 2.0;
        glow += GLOW_COLOR * (GLOW_STRENGTH * stepLen * fall * mask *  fx ) * fogAmount;

        dt += d.x;
        if( dt > FAR) break;
    }

    if(dt > FAR)
    {
       float dt = -1.0;
       float id = -1.0; 
    }

    return vec2(dt, id);
}

vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)).x - map(p - vec3(e,0,0)).x,
        map(p + vec3(0,e,0)).x - map(p - vec3(0,e,0)).x,
        map(p + vec3(0,0,e)).x - map(p - vec3(0,0,e)).x
    ));
}

vec3 rustCol(float noise01, float nl, vec3 l, vec3 col, vec2 dt)
{
    vec3 darkMet = vec3(0.000,0.000,0.000); // dark metal
    vec3 rustOra = vec3(0.055,0.153,0.047);      // rusty orange
    vec3 stains  = vec3(0.008,0.090,0.035);       // deeper stains
    vec3 darkPat = vec3(0.01, 0.0, 0.0);      // darker patches

    float rust  = smoothstep(0.466,   0.6458, noise01);
    float stain = smoothstep(0.55,   0.425, noise01);
    float stain2= smoothstep(0.275, 0.625,  noise01);

    vec3 albedo = mix(darkMet, rustOra, rust);
    albedo = mix(albedo, stains, stain);
    //albedo = mix(albedo, darkPat, stain2);
    col = albedo * vec3(max(0.2, nl));

    float spot = dot(l, vec3(0, 1, 0));
    col *= smoothstep(0.3, 0.75, spot);

    return col;
}

void mainImage( out vec4 O, in vec2 I )
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    vec3 col = vec3(0);//vec3(uv.y);

    vec3 ro = vec3(0.,-10. ,3.8 - iTime);
    vec3 rd = normalize(vec3(uv, -1));

    vec2 dt = rayMarch(ro, rd);

    if(dt.x < FAR)
    {
        vec3 p = ro + rd * dt.x;

        vec3 norm = calcNormal(p);

        vec3 l = normalize(vec3(-0.7,2,0));
        float nl = dot(norm, l);

        vec4 noise = noisedFBM(_noisePos * vec3(1, 0.75, 1) * 4.0, 10, 0.95);
        norm = normalize(norm + noise.yzw * 0.8);

        float noise01 = noise.x * 0.5 + 0.5;

        if(dt.y > 1.9)
        {
            col = vec3(0);
        } else {
            col = rustCol(noise01, nl, l, col, dt);

            vec3 view = normalize(ro - p);
            vec3 halfVec = normalize(l + view);
            float spec = pow(max(0.0, dot(norm, halfVec)), 24.0);
            col += vec3(0.6, 0.8, 1.0) * spec * 0.2;

            float backLight = max(0.0, dot(norm, -l)) * 0.054;
            col += vec3(0.302,0.796,0.788) * backLight;
        }

        // fog 
        col = mix( col, vec3(0.0), 1.0-exp( -0.0005*dt.x*dt.x*dt.x ) );
    }
    col += glow; 

    col *= 20.0;

    col = pow(col, vec3(1.1 / 2.2));

    O = vec4(col,1.0);
}

