vec2 map2( vec3 p ) 
{
    vec3 terrP = p;
    terrP.y += 1.2;

    int octaves = 4;
	float dMin = dMax;
	float d; 
	float mID = -1.0; 

	// terrain
	float h = terrain(terrP.xz, octaves);
	h += smoothstep(-0.3, 1.1, h);
	h *= smoothstep(-1.5, -0.3, h); 

    // ROCKY DETAIL
    float rockDetail = surfFunc(terrP) - 0.5;  
    h += rockDetail * 0.25; 

    // Calculate cell
    vec2 posxz = terrP.xz / pumSpace;
    vec2 cellId = floor(posxz);
    vec2 cellXZ = (fract(posxz) - vec2(0.5)) * pumSpace;
    vec3 cellPos = vec3(cellXZ.x, terrP.y, cellXZ.y);

	d = terrP.y - h;	

    if (d<dMin) { 
		dMin = d;
		mID = 1.0;
	}

    vec3 cellP = terrP;
    cellP.xz = mod(terrP.xz, pumSpace) - pumSpace * 0.5; // Fold space

    vec2 d3Dist = SDFSphereCell(cellP, cellId);

    return d3Dist;
}

vec2 rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.0;
    float id = 0.0;
    glow2 = vec3(0.0);

    for(int i=0; i<50; i++)
    {
        vec3 p = ro + rd * dt;

        vec2 d = map(p);

        _noisePos = p;
        _noisePosPumpk = p;

        if(abs(d.x) < 0.001 )
        {
            id = d.y;
            break;
        }

        if (dt < 20.0) {
            float dSphere = map2(p).x;  // Get distance to spheres
            float stepLen = clamp(d.x, 0.1, 0.125);          
            float fall = 1.0 / (1.0 + dSphere * dSphere * GLOW_FALLOFF2);  // FIXED: Proper falloff calculation
            float mask = smoothstep(0.1, 0.57, abs(dSphere));
            float fogAmount = exp(-0.0005*dt*dt*dt);
            float fx = sin(iTime * PULSE) * .5 + 1.;
            glow2 += GLOW_COLOR * (GLOW_STRENGTH2 * stepLen * fall * mask * fx) * fogAmount;
        }


        dt += d.x;
        if( dt > FAR) break;
        //if (glow2.x > 10.095) break;
    }

    if(dt > FAR)
    {
       float dt = -1.0;
       float id = -1.0; 
    }

    return vec2(dt, id);
}

vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)).x - map(p - vec3(e,0,0)).x,
        map(p + vec3(0,e,0)).x - map(p - vec3(0,e,0)).x,
        map(p + vec3(0,0,e)).x - map(p - vec3(0,0,e)).x
    ));
}

