mat3 setCamera( in vec3 ro, in vec3 ta, float cr, float tilt)
{
    vec3 cw = normalize(ta-ro);
    vec3 cp = vec3(sin(cr), cos(cr),0.0);
    vec3 cu = normalize( cross(cw,cp) );
    vec3 cv = ( cross(cu,cw) );
    // Apply tilt rotation around the x-axis (affects YZ)
    float st = sin(tilt);
    float ct = cos(tilt);
    mat3 tiltMat = mat3(
        1.0, 0.0, 0.0,
        0.0, ct, -st,
        0.0, st, ct
    );

    return mat3( cu, cv, cw ) * tiltMat;
}

void mainImage( out vec4 O, in vec2 I )
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    vec3 col = vec3(0);//vec3(uv.y);

    vec3 ta = vec3(-0.9 - iTime * 0.5,0,-4);
    vec3 ro = ta + vec3(4.0*cos(3.3514),  3.0*sin(3.14), 0.0 ); 

    //vec3 ro = vec3(-5,0,-0.9 - iTime * 0.5);
    ro.y = terrain( ro.xz, 4 ) + 1.5;

    mat3 ca = setCamera(ro, ta, 0.4, 1.14804);
    vec3 rd = ca * normalize(vec3(uv, -1));

    vec2 dt = rayMarch(ro, rd);

    if(dt.x < FAR)
    {
        vec3 p = ro + rd * dt.x;

        vec3 norm = calcNormal(p);
        norm = normalize(vec3(norm.yz, 1.0));  

        vec3 l = normalize(vec3(1.5,0.547,0.25));
        float nl = dot(norm, l);

        _noisePos.x += sin(_noisePos.y * 1.5) ;
        vec4 noise = noisedFBM(_noisePos * vec3(.0, 10.75, 0) * 2.0 + vec3(3,0,0), 4, 0.95);
        norm = normalize(norm + noise.yzw * 5.3);

        float noise01 = noise.x * 0.5 + 0.5;

        if(dt.y > 0.9)
        {
            col = rustCol2(noise01, nl, l, col, dt);

            vec3 view = normalize(ro - p);
            vec3 halfVec = normalize(l + view);
            float spec = pow(max(0.0, dot(norm, halfVec)), 24.0);

            col += vec3(0.035,0.255,0.604) * spec * 0.105; //vec3(0.388,0.31,0.067)           

            float backLight = max(0.0, dot(norm, -l)) * .2054;
            col += vec3(0.212,0.227,0.227) * backLight;
        } else {
            col = rustCol(noise01, nl, l, col, dt);

            vec3 view = normalize(ro - p);
            vec3 halfVec = normalize(l + view);
            float spec = pow(max(0.0, dot(norm, halfVec)), 24.0);

            col += vec3(0.024,0.416,0.518) * spec * 0.205; //vec3(0.388,0.31,0.067)           

            float backLight = max(0.0, dot(norm, -l)) * .2054;
            col += vec3(0.294,0.290,0.286) * backLight;
        }

        // fog 
        col = mix( col, vec3(0.0), 1.0-exp( -0.005*dt.x*dt.x*dt.x ) );
    }
    //col += glow; 

    col *= 20.0;

    col = pow(col, vec3(1.1 / 2.2));

    O = vec4(col,1.0);
}


