#define t iTime

float sdfGyroid(vec3 pos, float time) {

    // Rotation matrix (dual axis)
    mat2 rot = mat2(sin(time + vec4(0, 33, 11, 0)));

    // Apply rotations
    vec3 q = pos;
    q.xz *= rot;

    // Gyroid implicit surface
    float val = dot(sin(q), cos(q.yzx));
    float dst = abs(val) - 0.01;

    // Clamp to cube bounds
    vec3 absPos = abs(q);
    dst = max(dst, max(absPos.x, max(absPos.y, absPos.z)) - 10.0);

    // grid pattern
    vec3 grid = abs(fract(q) - 0.5);
    float gridSize = 0.4 + 0.04; //* sin(time * 1.);
    dst = max(dst, max(grid.x, max(grid.y, grid.z)) - gridSize);

    return dst;
}

void mainImage(out vec4 O, vec2 U) 
{
    vec3 res = iResolution;

    // Ray direction 
    vec3 dir = vec3(0.3 * (U + U - res.xy) / res.y, -1.0);

    // Starting position
    vec3 pos = 25.0 / res;

    // Initial distance
    float dst = t;
    float val = 0.0;

    O = vec4(0);

    for (O++; O.x > 0.0 && dst > 0.001; O -= 0.015) {

        // Evaluate distance field
        dst = sdfGyroid(pos, t * 0.1);

        // Store surface value for coloring
        vec3 q = pos;
        mat2 rot = mat2(sin(t * .1 + vec4(0, 33, 11, 0)));
        q.xz *= rot;

        val = dot(sin(q), cos(q.yzx));

        // March along ray
        pos += 0.5 * dst * dir;
    }

    vec3 col = val > 0.0 ? vec3(0, 0.8, 0.8) : vec3(0.8, 0.5, 1.0);
    O *= vec4(col, 1.0);
}

