#define t iTime

vec2 path(in float z)
{ 
    float a = sin(z * 0.0741);
    float b = cos(z * 0.0114);
    return vec2(a*4. - b*1.5, b*1.7 + a*1.5); 
}

float smaxP(float a, float b, float s){

    float h = clamp( 0.5 + 0.5*(a-b)/s, 0., 1.);
    return mix(b, a, h) + h*(1.0-h)*s;
}

float objID = 0.;

float sdfGyroid(vec3 p, float time) 
{    
    p.xy -= path(p.z);
    p += cos(p.zxy*1.257)*.2;

    // I grabbed the bio and dst from @shane

    // https://www.shadertoy.com/view/4lyGzR
    float offSet = 0.56;
    float d = dot(sin(p * offSet), cos(p.yzx * offSet)) + 0.75;
    // Tube thing
    float bio = d + .425 + dot(sin(p*3. + time*3.283 + sin(p.yzx*2.5)), vec3(.033));
    // Wall thing
    float dst = smaxP(3.125 - length(p.xy - vec2(2, 0)) + 1.5*cos(p.z*4.14159/32.), 1.3075-d, 3.) - abs(1.5-d)*.375;// - sf*.25;

    objID = step(bio, dst);

    return min(bio, dst);
}

