    vec3 R = iResolution;

    // Ray direction 
    vec3 dir = vec3(0.3 * (U + U - R.xy) / R.y, -1.0);

    // Starting position
    vec3 p =1.0 / R;
    p = vec3(0.9, 0.2, -t * 7.9);

    p.xy += path(p.z);

    // Initial distance
    float dst = t;

    O = vec4(0);

    for (O++; O.x > 0.0 && dst > 0.001; O -= 0.00815) // idk what this is Fabrice 
    {    
        // Evaluate distance field
        dst = sdfGyroid(p, t);

        // Store surface value for coloring
        vec3 q = p;
        q.xy -= path(q.z);

        // March along ray
        p += 0.8 * dst * dir;
    }

    vec3 col = objID > 0.0 ? vec3(0.635,0.192,0.004) : vec3(0.169,0.62,0.561);
    O *= vec4(col, 1.0);
}

