float map(vec3 p)
{
    vec3 d1 = voronoiDistSq(p.xy * 1.0, iTime);  

    float w   = 3.0;
    float edgeDist = sqrt(d1.y) - sqrt(d1.x);

    vec3 col1 = 4.0 * sqrt(d1);
    col1 -= vec3(col1.x);
    col1 += 8.0 * ( col1.y / (col1.y / col1.z + 1.0) - 0.5 ) - col1;

    p.xy -= camPath(p.z);
    float offset = 0.5;
    float d2 = dot(sin(p * offset), cos(p.yzx * offset)) + 0.8 - (col1.x * 0.011) ;

