        float noise01 = noise.x * 0.5 + 0.5;
        vec3 l = normalize(vec3(0.91,0.753,1.5));
        float nl = dot(norm, l);

        col = rustCol(noise01, nl, l, col);
        vec3 view = normalize(ro - p);
        vec3 halfVec = normalize(l + view);
        float spec = pow(max(0.0, dot(norm, halfVec)),12.0);

        col += vec3(0.02,0.42,0.463) * spec * 0.08; //vec3(0.388,0.31,0.067)           
        //vec3(0.596,0.176,0.035)
