float castShadow(vec3 ro, vec3 rd, float T)
{
    float res = 1.0;
    float dt  = 0.001;

    for(int i=0; i<120; i++)
    {
        float d = map(ro + rd * dt);
        res = min(res, 20.0 * max(d, 0.0) / dt);

        if((res) < 0.001) break;
        dt += clamp(d, 0.0001, 0.1);

        if(dt > 20.0) break;
    }
    return clamp(res, 0.0, 1.0);
}

float rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.0;
    for(int i=0; i<80; i++)
    {
        vec3 p = ro + rd * dt;
        float d = map(p);
        _noisePos = p;
        dt += d;
        if(abs(d) < 0.001 || dt > FAR) break;
    }
    return dt;
}

vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
        map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
        map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
    ));
}

vec3 rustCol(float noise01, float nl, vec3 l, vec3 col)
{
    vec3 darkMet = vec3(0.015, 0.019, 0.018); // dark metal
    vec3 rustOra = vec3(0.3, 0.03, 0.0);      // rusty orange
    vec3 stains  = vec3(0.3, 0.0, 0.0);       // deeper stains
    vec3 darkPat = vec3(0.01, 0.0, 0.0);      // darker patches

    float rust  = smoothstep(0.6,   0.48, noise01);
    float stain = smoothstep(0.5,   0.4, noise01);
    float stain2= smoothstep(0.575, 0.25,  noise01);

    vec3 albedo = mix(darkMet, rustOra, rust);
    albedo = mix(albedo, stains, stain);
    albedo = mix(albedo, darkPat, stain2);
    col = albedo * vec3(max(0., nl));

    float spot = dot(l, vec3(0, 1, 0));
    col *= smoothstep(0.3, 0.75, spot);

    return col;
}


vec3 render(vec3 ro, vec3 rd, float T)
{
    vec3 col = vec3(0);

    float dt = rayMarch(ro, rd);

    vec4 noise = noisedFBM(_noisePos * vec3(0.9, 1.75, 1.6) * 2.0 + vec3(3,0,0), 10, 0.95);


    if(dt < FAR)
    {
        vec3 p = ro + rd * dt;
        vec3 norm = calcNormal(p);
        norm = normalize(norm + noise.yzw * 2.3);

        float noise01 = noise.x * 0.5 + 0.5;
        vec3 l = normalize(vec3(.745,0.4,.679));
        float nl = clamp(dot(norm, l), 0.0, 1.0);
        float NoV  = clamp(dot(norm, -rd), 0.0, 1.0);    
        float rim  = pow(1.0 - NoV, 3.0);

        col = rustCol(noise01, nl, l, col);
        vec3 view = normalize(ro - p);
        vec3 halfVec = normalize(l + view);
        float spec = pow(max(0.0, dot(norm, halfVec)),24.0);

        col += vec3(0.941,0.957,0.957) * spec * 0.04528; //vec3(0.388,0.31,0.067)           
        //vec3(0.596,0.176,0.035)
        float backLight = max(0.0, dot(norm, -l)) * .01;
        col += vec3(0.047,0.035,0.035) * backLight;
        col += vec3(0.749,0.031,0.031) * rim * 0.064 ;

        col = mix( col, vec3(0.0), 1.0-exp( -0.000925*dt*dt*dt ) );
        //col = norm * 0.5 + 0.5;
    }
    col *= 20.0;

    col = pow(col, vec3(1.1 / 2.2));

    return col;
    //O = vec4(col,1.0);
}

void mainImage(out vec4 O, in vec2 I)
{
    float T = iTime * 0.3;

    vec3 ro = vec3(4,0,-iTime * 1.);
    ro.xy += camPath(ro.z);

    vec3 tot = vec3(0.0);

    for (int m = 0; m < AA; m++)
    for (int n = 0; n < AA; n++) {
        vec2 off = vec2(m, n) / float(AA) - 0.5;
        vec2 uv = (2.0 * (I + off) - iResolution.xy) / iResolution.y;

        float rotDel = iTime * 0.06;
        uv *= mat2(cos(rotDel), -sin(rotDel), sin(rotDel), cos(rotDel));

        vec3 rd = normalize(vec3(uv, -1));
        vec3 col = render(ro, rd, T); 

        tot += col;
    }

    tot /= float(AA * AA);

    O = vec4(tot, 1.0);
}

