// fabrice -> https://www.shadertoy.com/view/4dKSDV
vec3 voronoiDistSq(vec2 p, float dt)
{
    vec2 cellId, diff;
    float d;
    vec3 dists = vec3(9.0);       

    for (int k = 0; k < 9; ++k)
    {
        cellId = ceil(p) + vec2(k - (k/3)*3, k/3) - 2.0;
        // diff   = H(cellId) + cellId - p;
        diff = H(cellId) + cellId + .15 * cos(dt + 6.28 * H(cellId)) - p;

        d = dot(diff, diff);      

        d < dists.x ? (dists.yz = dists.xy, dists.x = d) :
        d < dists.y ? (dists.z  = dists.y , dists.y = d) :
        d < dists.z ?               dists.z = d        :
                       d;
    }
    return dists;
}

float hash(ivec3 p)
{
    int n = p.x*3 + p.y*113 + p.z*311;
	n = (n << 13) ^ n;
    n = n * (n * n * 15731 + 789221) + 1376312589;
    return -1.0+2.0*float( n & 0x0fffffff)/float(0x0fffffff);
}

// https://iquilezles.org/articles/morenoise/
vec4 noised(in vec3 x)
{
    ivec3 i = ivec3(floor(x));
    vec3 w = fract(x);
    vec3 u = w*w*(3.0-2.0*w);
    //vec3 u = w*w*w*(w*(w*6.0-10.0)+5.0);
    vec3 du = 6.0*w*(1.0-w); 
    float a = hash(i+ivec3(0,0,0));
    float b = hash(i+ivec3(1,0,0));
    float c = hash(i+ivec3(0,1,0));
    float d = hash(i+ivec3(1,1,0));
    float e = hash(i+ivec3(0,0,1));
	float f = hash(i+ivec3(1,0,1));
    float g = hash(i+ivec3(0,1,1));
    float h = hash(i+ivec3(1,1,1));
    float k0 =   a;
    float k1 =   b - a;
    float k2 =   c - a;
    float k3 =   e - a;
    float k4 =   a - b - c + d;
    float k5 =   a - c - e + g;
    float k6 =   a - b - e + f;
    float k7 = - a + b + c - d + e - f - g + h;
    return vec4( k0 + k1*u.x + k2*u.y + k3*u.z + k4*u.x*u.y + k5*u.y*u.z + k6*u.z*u.x + k7*u.x*u.y*u.z, 
                 du * vec3( k1 + k4*u.y + k6*u.z + k7*u.y*u.z,
                            k2 + k5*u.z + k4*u.x + k7*u.z*u.x,
                            k3 + k6*u.x + k5*u.y + k7*u.x*u.y ) );
}

// ▓ Noise rust from @fewer
// ▓ https://www.shadertoy.com/view/wXlcDX
vec4 noisedFBM(in vec3 x, int octaves, float gain)
{
    vec4 result = vec4(0.);
    float a = 1.0;
    float s = 0.0;
    for (int i = 0; i < octaves; i++)
    {
        result += noised(x * 0.1047 ) * a;
        s += a;
        x *= 2.0;
        a *= gain;
    }
    return result / s;
}


vec2 camPath(float t)
{
    float s = sin(t * 0.312);
    float c = cos(t * 0.424);
    return vec2(c*1.4 - s*1.4, c*1.7 + s*2.5);
}

float sdGyroid(vec3 p, float offset, float thickness)
{
    p += cos(3.*iTime+p.yzx*1.6)*.16;
   	return abs(dot(sin(p * offset), cos(p.yzx * offset)) - thickness);
}

// https://iquilezles.org/articles/smin
float smax( float a, float b, float k )
{
    float h = max(k-abs(a-b),0.0);
    return max(a, b) + h*h*0.25/k;
}


// https://iquilezles.org/articles/distfunctions
float sdEllipsoid( in vec3 p, in vec3 r )
{
    float k1 = length(p/r);
    return (k1-1.0)*min(min(r.x,r.y),r.z);
}

vec2 combineMin(vec2 a, vec2 b)
{
    return (a.x < b.x)? a : b;
}

mat2 R2(float a){ return mat2(cos(a), -sin(a), sin(a), cos(a)); }

float pumSpace = 7.0;  // Distance between pumpkins
float pumOffset = 2.0; // Random offset within cell

vec2 SDFPumpkin(vec3 pos, float scale, float idIndex, float rotXy)
{  
    pos += cos(3.*iTime+pos.yzx*1.6)*.06;
    pos.xz *= R2(iTime * 0.4);
    //pos.xy *= R2(rotXy);
    pos *= scale;

    float proxy = length(pos - vec3(0.0, 0.2, 0.0));

    if (proxy > 4.0)
    {
    	return vec2((proxy - 3.0) / scale, 0.0);
    }
    else   
    {   
        //float angle = atan(pos.x, pos.z);
        float angle = pos.x / (abs(pos.x) + abs(pos.z) + 0.001); 
        angle *= 1.57;

        float section = smax(0.05, abs(sin(angle * 4.0)), 0.05) * 0.1;

        float longLen = length(pos.xz);

        float pinch = S(1.4, -0.2, longLen);

        float pumpkin = sdEllipsoid(pos, vec3(1.7, 1.5, 1.7)) + pinch * 0.6;

        float pumpkinDisplace =  ((sin(angle * 25.0) + sin(angle * 43.0)) * 0.0015 - section) * S(0.2, 1.3, longLen);

        pumpkin +=   pumpkinDisplace;

        float stem = longLen - 0.29 + S(1.1, 1.5, pos.y) * 0.15 + sin(angle * 4.0) * 0.01;

        float stemDisplace = sin(angle * 10.0);

        stem += stemDisplace * 0.005;

        stem -= (pos.y - 1.2) * 0.1;

        stem *= 0.8;

        float stemCut =  pos.y - 1.6 + pos.x * 0.3;

        stem = smax(stem, stemCut, 0.05);

        stem = max(stem, 1.0 - pos.y);


        float pumpkinID = clamp(pumpkinDisplace * 4.0 + 0.5, 0.0, 0.999);//, PUMPKIN_INSIDE, S(0.03, -0.05, pumpkin));

	    float stemID = STEM + (0.5 + stemDisplace * 0.2) * S(0.1, -0.6, stemCut);


        pumpkin = abs(pumpkin) - 0.05;

        float face = length(pos.xy - vec2(0.0, 0.3)) - 1.1;
        face = max(face, -(length(pos.xy - vec2(0.0, 1.8)) - 2.0));

        float teeth = abs(pos.x - 0.4) - 0.16;
        teeth = smax(teeth, -0.45 - pos.y + pos.x * 0.1, 0.07);

        float teeth2 = abs(pos.x + 0.40) - 0.16;
        teeth2 = smax(teeth2, 0.5 + pos.y + pos.x * 0.05, 0.07);


        face = smax(face, -min(teeth, teeth2), 0.07);

        vec2 symPos = pos.xy;
        symPos.x = abs(symPos.x);

        float nose = -pos.y + 0.1;
        nose = max(nose, symPos.x - 0.25 + symPos.y* 0.5);

        float eyes = -pos.y + 0.48 - symPos.x * 0.17;
        eyes = max(eyes, symPos.x - 1.0 + symPos.y * 0.5);
        eyes = max(eyes, -symPos.x - 0.05 + symPos.y * 0.5);


        face = min(face, nose);
        face = min(face, eyes);

        face = max(face, pos.z);

        pumpkin = smax(pumpkin, -face, 0.03);

        vec2 res = vec2(pumpkin, pumpkinID + idIndex);
		res = combineMin(res, vec2(stem, stemID + idIndex));

        res.x /= scale;

        return res;
    }
}

vec4 hash42(vec2 t) {
    float n = mod(t.x * 458.0 + t.y * 127.3, 100.0);
	return fract(sin(n*vec4(123., 1024., 1456., 264.))*vec4(6547., 345., 8799., 1564.));
}

float smin( float d1, float d2, float k )
{
    k *= 4.0;
    float h = max(k-abs(d1-d2),0.0);
    return min(d1, d2) - h*h*0.25/k;
}

float gyroidHeight(vec2 xz, float offset, float thickness)
{
    // For a given (x,z), find y where gyroid ≈ 0
    // Approximate: sin(x)cos(y) + sin(y)cos(z) + sin(z)cos(x) = thickness

    float y = 0.0;
    float sinX = sin(xz.x * offset);
    float cosZ = cos(xz.y * offset);
    float sinZ = sin(xz.y * offset);
    float cosX = cos(xz.x * offset);

    // Solve for y iteratively 
    for(int i = 0; i < 3; i++)
    {
        float sinY = sin(y * offset);
        float cosY = cos(y * offset);

        float f = sinX * cosY + sinY * cosZ + sinZ * cosX - thickness;
        float df = -sinX * sinY * offset + cosY * cosZ * offset;

        y -= f / (df + 0.001); // Newton-Raphson step
    }

    return y;
}

vec2 SDFPumpkinCell(vec3 pos, vec2 cellId, float offset, float thickness) 
{
    vec4 rnd = hash42(cellId);

    vec2 offsetXZ = (rnd.xy - vec2(0.5)) * pumOffset;
    vec2 pumpkinCenter = (cellId + vec2(0.5)) * pumSpace + offsetXZ;

    float surfaceY = gyroidHeight(pumpkinCenter, offset, thickness);

    vec3 pumpkinPos = pos - vec3(offsetXZ.x, surfaceY, offsetXZ.y);
    vec3 pumpkinWorldPos = vec3(pumpkinCenter.x + offsetXZ.x, surfaceY, pumpkinCenter.y + offsetXZ.y);
    float scale = 1.4;

    vec2 toCamera = pos.xz - pumpkinWorldPos.xz;
    float faceAngle = atan(toCamera.x, toCamera.y);

    return SDFPumpkin(pumpkinPos, scale, 4.0, faceAngle);
}

float map(vec3 p)
{
    vec3 d1 = voronoiDistSq(p.xy * 1.30, iTime * 0.6);  

    float edgeDist = sqrt(d1.y) - sqrt(d1.x);

    vec3 col1 = 4.0 * sqrt(d1);
    col1 -= vec3(col1.x);
    col1 += 7.0 * ( col1.y / (col1.y / col1.z + 1.0) - 0.5 ) - col1;

    p.xy -= camPath(p.z);
    float offset = 0.231;
    float thickness = 0.149;
    float d2 = sdGyroid(p, offset, thickness) + (col1.x * 0.0142035);

    vec2 posxz = p.xz / pumSpace;
    vec2 cellId = floor(posxz);

    vec3 cellP = p;
    cellP.xz = mod(p.xz, pumSpace) - pumSpace * 0.5;

    vec2 pDist = SDFPumpkinCell(cellP, cellId, offset, thickness + 0.1);
    //vec2 d3 = SDFPumpkin(p, 0.9, 4.0,  3.28);

    Objid = step(d2,pDist.x);
    //return d2;
    return smin(d2, pDist.x, 0.105);
}

