// https://iquilezles.org/articles/morenoise/
vec4 noised(in vec3 x)
{
    ivec3 i = ivec3(floor(x));
    vec3 w = fract(x);
    vec3 u = w*w*(3.0-2.0*w);
    //vec3 u = w*w*w*(w*(w*6.0-10.0)+5.0);
    vec3 du = 6.0*w*(1.0-w); 
    float a = hash(i+ivec3(0,0,0));
    float b = hash(i+ivec3(1,0,0));
    float c = hash(i+ivec3(0,1,0));
    float d = hash(i+ivec3(1,1,0));
    float e = hash(i+ivec3(0,0,1));
	float f = hash(i+ivec3(1,0,1));
    float g = hash(i+ivec3(0,1,1));
    float h = hash(i+ivec3(1,1,1));
    float k0 =   a;
    float k1 =   b - a;
    float k2 =   c - a;
    float k3 =   e - a;
    float k4 =   a - b - c + d;
    float k5 =   a - c - e + g;
    float k6 =   a - b - e + f;
    float k7 = - a + b + c - d + e - f - g + h;
    return vec4( k0 + k1*u.x + k2*u.y + k3*u.z + k4*u.x*u.y + k5*u.y*u.z + k6*u.z*u.x + k7*u.x*u.y*u.z, 
                 du * vec3( k1 + k4*u.y + k6*u.z + k7*u.y*u.z,
                            k2 + k5*u.z + k4*u.x + k7*u.z*u.x,
                            k3 + k6*u.x + k5*u.y + k7*u.x*u.y ) );
}

//  Noise rust from @fewer
//  https://www.shadertoy.com/view/wXlcDX
vec4 noisedFBM(in vec3 x, int octaves, float gain)
{
    vec4 result = vec4(0.);
    float a = 1.0;
    float s = 0.0;
    for (int i = 0; i < octaves; i++)
    {
        result += noised(x * 0.047 ) * a;
        s += a;
        x *= 2.0;
        a *= gain;
    }
    return result / s;
}

vec2 camPath(float t)
{
    float s = sin(t * 0.312);
    float c = cos(t * 0.424);
    return vec2(c*1.4 - s*1.4, c*1.7 + s*2.5);
}

float sdGyroid(vec3 p, float offset, float thickness)
{
   	return abs(dot(sin(p * offset), cos(p.yzx * offset)) - thickness);
}

float gyroidHeight(vec2 p, float offset, float w )
{
    // donde esta y
    float y = 0.;
    float sx = sin(p.x * offset);
    float cz = cos(p.y * offset);
    float sz = sin(p.y * offset);
    float cx = cos(p.x * offset);

    for(int i=0; i<6; i++)
    {
        float sy = sin(y * offset);
        float cy = cos(y * offset);

        float f  = sx*cy + sy*cz + sz*cx - w;

        float df = -sx*sy*offset + cy*cz*offset;

        y -= f / (df + 0.001);
    }

    return y;
}

mat2 R2(float a){ return mat2(cos(a), -sin(a), sin(a), cos(a)); }

vec4 hash42(vec2 t) {
    float n = mod(t.x * 458.0 + t.y * 127.3, 100.0);
	return fract(sin(n*vec4(123., 1024., 1456., 264.))*vec4(6547., 345., 8799., 1564.));
}

float sdOctahedron( vec3 p, float s)
{
  p = abs(p);
  return (p.x+p.y+p.z-s)*0.57735027;
}

float sdfSphereCell(vec3 p, vec2 cellId, float offset, float w) 
{
    vec4 rnd = hash42(cellId);

    vec2 offsetXZ = (rnd.xy - vec2(0.5)) * pOffset;
    vec2 pCenter = (cellId + vec2(0.5)) * pSpace + offsetXZ;

    float surfaceY = gyroidHeight(pCenter, offset, w);

    vec3 pUv = p - vec3(offsetXZ.x, surfaceY, offsetXZ.y);
    float r = 0.98;

    //pUv.z += sin(pUv.x + iTime * 0.3) * 0.3;
    pUv.xy *= R2(iTime * 0.2);
    return sdOctahedron(pUv, 1.);//length(pUv) - r;
}

float map(vec3 p)
{
    vec3 d1 = voronoiDistSq(p.xy * 1.2949095, iTime * 0.26);  

    float edgeDist = sqrt(d1.y) - sqrt(d1.x);

    vec3 col1 = 4.0 * sqrt(d1);
    col1 -= vec3(col1.x);
    col1 += 7.0 * ( col1.y / (col1.y / col1.z + 1.0) - 0.5 ) - col1;

    p.xy -= camPath(p.z);
    float offset = 0.35;
    float w = 0.249;
    float d2 = sdGyroid(p, offset, w) + (col1.x * 0.0142035) ;

    //p.xz += iTime;
    vec2 pxz = p.xz / pSpace;
    vec2 cellId = floor(pxz);

    vec3 cellP = p;
    cellP.xz = mod(p.xz, pSpace) - pSpace * 0.5;

    float pDist = sdfSphereCell(cellP, cellId, offset, w);

    objId = step(d2, pDist);

    return smin(d2, pDist, 0.1);
}

float castShadow(vec3 ro, vec3 rd, float T)
{
    float res = 1.0;
    float dt  = 0.001;

    for(int i=0; i<120; i++)
    {
        float d = map(ro + rd * dt);
        res = min(res, 20.0 * max(d, 0.0) / dt);

        if((res) < 0.001) break;
        dt += clamp(d, 0.0001, 0.1);

        if(dt > 20.0) break;
    }
    return clamp(res, 0.0, 1.0);
}

float rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.0;
    for(int i=0; i<80; i++)
    {
        vec3 p = ro + rd * dt;
        float d = map(p);
        _noisePos = p;
        dt += d;
        if(abs(d) < 0.001 || dt > FAR) break;
    }
    return dt;
}

vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
        map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
        map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
    ));
}

vec3 rustCol(float noise01, float nl, vec3 l, vec3 col)
{
    vec3 darkMet = vec3(0.015, 0.019, 0.018); // dark metal
    vec3 rustOra = vec3(0.0, 0.2, 0.2);      // rusty orange
    vec3 stains  = vec3(0.0, 0.2, 0.3);       // deeper stains
    vec3 darkPat = vec3(0.01, 0.0, 0.0);      // darker patches

    float rust  = smoothstep(0.6,   0.48, noise01);
    float stain = smoothstep(0.5,   0.4, noise01);
    float stain2= smoothstep(0.575, 0.25,  noise01);

    vec3 albedo = mix(darkMet, rustOra, rust);
    albedo = mix(albedo, stains, stain);
    albedo = mix(albedo, darkPat, stain2);
    col = albedo * vec3(max(0., nl));

    float spot = dot(l, vec3(0, 1, 0));
    col *= smoothstep(0.3, 0.75, spot);

    return col;
}

