vec3 render(vec3 ro, vec3 rd, float T)
{
    vec3 col = vec3(0);

    float dt = rayMarch(ro, rd);

    vec4 noise = noisedFBM(_noisePos * vec3(0.9, 1.75, 1.6) * 2.0 + vec3(3,0,0), 10, 0.95);


    if(dt < FAR)
    {
        vec3 p = ro + rd * dt;
        vec3 norm = calcNormal(p);
        vec3 l = normalize(vec3(.3745,0.4,.679));

        vec3 norm2 = normalize(norm + noise.yzw * 2.3);
        vec3 norm3 = normalize(norm + noise.yzw * 1.3);

        if(objId > 0.0)
        {
            float noise01 = noise.x * 0.5 + 0.5;
            float nl = clamp(dot(norm2, l), 0.0, 1.0);
            float NoV  = clamp(dot(norm2, -rd), 0.0, 1.0);    
            float rim  = pow(1.0 - NoV, 3.0);

            col = rustCol(noise01, nl, l, col);

            vec3 view = normalize(ro - p);
            vec3 halfVec = normalize(l + view);
            float spec = pow(max(0.0, dot(norm2, halfVec)),24.0);

            col += vec3(0.941,0.957,0.957) * spec * 0.04528; //vec3(0.388,0.31,0.067)           
            //vec3(0.596,0.176,0.035)
            float backLight = max(0.0, dot(norm2, -l)) * .01;
            col += vec3(0.047,0.035,0.035) * backLight;
            col += vec3(0.031,0.573,0.710) * rim * 0.0164 ;
        } else {
            float noise01 = noise.x * 0.5 + 0.5;
            float nl = clamp(dot(norm3, l), 0.0, 1.0);
            float NoV  = clamp(dot(norm3, -rd), 0.0, 1.0);    
            float rim  = pow(1.0 - NoV, 3.0);

            col = rustCol2(noise01, nl, l, col);

            vec3 view = normalize(ro - p);
            vec3 halfVec = normalize(l + view);
            float spec = pow(max(0.0, dot(norm3, halfVec)),24.0);

            col += vec3(0.941,0.957,0.957) * spec * 0.04528;         

            float backLight = max(0.0, dot(norm3, -l)) * .01;
            col += vec3(0.047,0.035,0.035) * backLight;
            float fx = sin(iTime * 5.) * 0.45 + 0.45;
            col += vec3(0.710,0.031,0.686) * rim * fx;//0.1064 ;
        }

        col = mix( col, vec3(0.0), 1.0-exp( -0.000925*dt*dt*dt ) );
        //col = norm * 0.5 + 0.5;
    }
    col *= 20.0;

    col = pow(col, vec3(1.1 / 2.2));

    return col;
    //O = vec4(col,1.0);
}

void mainImage(out vec4 O, in vec2 I)
{
    float T = iTime * 0.3;

    vec3 ro = vec3(4,0,-iTime * 1.);
    ro.xy += camPath(ro.z);

    vec3 tot = vec3(0.0);

    for (int m = 0; m < AA; m++)
    for (int n = 0; n < AA; n++) {
        vec2 off = vec2(m, n) / float(AA) - 0.5;
        vec2 uv = (2.0 * (I + off) - iResolution.xy) / iResolution.y;

        float rotDel = iTime * 0.06;
        uv *= mat2(cos(rotDel), -sin(rotDel), sin(rotDel), cos(rotDel));

        vec3 rd = normalize(vec3(uv, -1));
        vec3 col = render(ro, rd, T); 

        tot += col;
    }

    tot /= float(AA * AA);

    O = vec4(tot, 1.0);
}

