vec4 noisedFBM(in vec3 x, int octaves, float gain)
{
    vec4 result = vec4(0.);
    float a = 1.0;
    float s = 0.0;
    for (int i = 0; i < octaves; i++)
    {
        result += noised(x * 0.047 ) * a;
        s += a;
        x *= 2.0;
        a *= gain;
    }
    return result / s;
}

vec2 camPath(float t)
{
