    vec4 noise = noisedFBM(_noisePos * vec3(0.2, 0.45, 0.6) * 2.0 + vec3(3,0,0), 10, 0.95);

    if(dt.y < FAR)
    {
        vec3 p = ro + rd * dt.x;
        vec3 norm = calcNormal(p);
        vec3 l = normalize(vec3(.3745,0.4,.679));

        vec3 norm2 = normalize(norm + noise.yzw * 0.6);
        vec3 norm3 = normalize(norm + noise.yzw * 2.3);

        if(objId > 0.0)
        {
            float noise01 = noise.x * 0.5 + 0.5;
            float nl = clamp(dot(norm2, l), 0.0, 1.0);
            float NoV  = clamp(dot(norm2, -rd), 0.0, 1.0);    
            float rim  = pow(1.0 - NoV, 3.0);

            // kind of like it without the noise color 
            //col = rustCol(noise01, nl, l, col);

            vec3 view = normalize(ro - p);
            vec3 halfVec = normalize(l + view);
            float spec = pow(max(0.0, dot(norm2, halfVec)),24.0);

            col += vec3(0.941,0.957,0.957) * spec * 0.02; //vec3(0.388,0.31,0.067)           
            //vec3(0.596,0.176,0.035)
            float backLight = max(0.0, dot(norm2, -l)) * .01;
            col += vec3(0.047,0.035,0.035) * backLight;
            col += vec3(0.710,0.133,0.031) * rim * 0.32;

            vec3 d1 = voronoiDistSq(p.xy * 0.6, iTime * 0.5);  

            float edgeDist = sqrt(d1.y) - sqrt(d1.x);

            vec3 col1 = 4.0 * sqrt(d1);
            col1 -= vec3(col1.x);
            col1 += 7.0 * ( col1.y / (col1.y / col1.z + 1.0) - 0.5 ) - col1;

            // 2nd gyroid  
            float gyroid2 = sdGyroid(p, 0.01,  0.3)  + (col1.x * 0.44);

            float crackWidth = -.01+smoothstep(0.,-0.2,norm2.y)* .24;
            float cracks = smoothstep(crackWidth,-10.0,gyroid2);

            float gyroid3 = sdGyroid(p+(iTime*.5), 0.3, 0.3);
            cracks *= gyroid3*2.+.2*smoothstep(0.2,.0,norm2.y);

            col+=cracks*vec3(1,.1,.1)*1.;//multiply by color. then multiply for intensity

        }

        col = mix( col, vec3(0.0), 1.0-exp( -0.000525*dt.x*dt.x*dt.x ) );
        //col = norm * 0.5 + 0.5;
    }
    col *= 20.0;

    col = pow(col, vec3(1.1 / 2.2));

    return col;
    //O = vec4(col,1.0);
}

void mainImage(out vec4 O, in vec2 I)
{   
    vec3 ro = vec3(4,0, -iTime * 3.5);
    ro.xy += camPath(ro.z);

    vec3 tot = vec3(0.0);

    for (int m = 0; m < AA; m++)
    for (int n = 0; n < AA; n++) {
