#define H(n)  fract( 1e4 * sin( n.x+n.y/.7 +vec2(1,12.34)  ) )
#define FAR 30.0

// change to 2 for better AA 
// if you don't have a GPU make it 1 
#define AA 2

vec3 _noisePos;
float pSpace = 3.;
float pOffset = 0.0;
float objId = 0.0;

// fabrice -> https://www.shadertoy.com/view/4dKSDV
vec3 voronoiDistSq(vec2 p, float dt)
{
    vec2 cellId, diff;
    float d;
    vec3 dists = vec3(9.0);       

    for (int k = 0; k < 9; ++k)
    {
        cellId = ceil(p) + vec2(k - (k/3)*3, k/3) - 2.0;
        // diff   = H(cellId) + cellId - p;
        diff = H(cellId) + cellId + .15 * cos(dt + 6.28 * H(cellId)) - p;

        d = dot(diff, diff);      

        d < dists.x ? (dists.yz = dists.xy, dists.x = d) :
        d < dists.y ? (dists.z  = dists.y , dists.y = d) :
        d < dists.z ?               dists.z = d        :
                       d;
    }
    return dists;
}

float hash(ivec3 p)
{
    int n = p.x*3 + p.y*113 + p.z*311;
	n = (n << 13) ^ n;
    n = n * (n * n * 15731 + 789221) + 1376312589;
    return -1.0+2.0*float( n & 0x0fffffff)/float(0x0fffffff);
}

// https://iquilezles.org/articles/
float smin( float d1, float d2, float k )
{
    k *= 4.0;
    float h = max(k-abs(d1-d2),0.0);
    return min(d1, d2) - h*h*0.25/k;
}

// https://iquilezles.org/articles/morenoise/
vec4 noised(in vec3 x)
{
    ivec3 i = ivec3(floor(x));
    vec3 w = fract(x);
    vec3 u = w*w*(3.0-2.0*w);
    //vec3 u = w*w*w*(w*(w*6.0-10.0)+5.0);
    vec3 du = 6.0*w*(1.0-w); 
    float a = hash(i+ivec3(0,0,0));
    float b = hash(i+ivec3(1,0,0));
    float c = hash(i+ivec3(0,1,0));
    float d = hash(i+ivec3(1,1,0));
    float e = hash(i+ivec3(0,0,1));
	float f = hash(i+ivec3(1,0,1));
    float g = hash(i+ivec3(0,1,1));
    float h = hash(i+ivec3(1,1,1));
    float k0 =   a;
    float k1 =   b - a;
    float k2 =   c - a;
    float k3 =   e - a;
    float k4 =   a - b - c + d;
    float k5 =   a - c - e + g;
    float k6 =   a - b - e + f;
    float k7 = - a + b + c - d + e - f - g + h;
    return vec4( k0 + k1*u.x + k2*u.y + k3*u.z + k4*u.x*u.y + k5*u.y*u.z + k6*u.z*u.x + k7*u.x*u.y*u.z, 
                 du * vec3( k1 + k4*u.y + k6*u.z + k7*u.y*u.z,
                            k2 + k5*u.z + k4*u.x + k7*u.z*u.x,
                            k3 + k6*u.x + k5*u.y + k7*u.x*u.y ) );
}

//  Noise rust from @fewer
//  https://www.shadertoy.com/view/wXlcDX
vec4 noisedFBM(in vec3 x, int octaves, float gain)
{
    vec4 result = vec4(0.);
    float a = 1.0;
    float s = 0.0;
    for (int i = 0; i < octaves; i++)
    {
        result += noised(x * 0.035 ) * a;
        s += a;
        x *= 2.0;
        a *= gain;
    }
    return result / s;
}

vec2 camPath(float t)
{
    float x = sin(t * 0.5 ) * 1.25;
    float y = cos(t * 0.3 ) * 1.25;

    x += sin(t * 0.131) * 0.3;
    y += cos(t * 0.112) * 0.3;

    return vec2(x, y);
}


mat2 R2(float a){ return mat2(cos(a), -sin(a), sin(a), cos(a)); }

float sdGyroid(vec3 p, float offset, float thickness)
{
    return abs(dot(sin(p * offset), cos(p.yzx * offset)) - thickness);
}

vec2 map(vec3 p)
{
    vec3 d1 = voronoiDistSq(p.xy * 0.6, iTime * 0.5);  
    float edgeDist = sqrt(d1.y) - sqrt(d1.x);

    vec3 col1 = 4.0 * sqrt(d1);
    col1 -= vec3(col1.x);
    col1 += 7.0 * (col1.y / (col1.y / col1.z + 1.0) - 0.5) - col1;

    p.xy -= camPath(p.z);

    // REFLECTION
    float mirrorSide = p.y + 0.1;
    p.y = abs(mirrorSide);

    // Apply distortions 
    vec3 p_distorted = p;
    p_distorted.y -= 0.11;  

    // warping
    p_distorted.x += sin(p.z * 0.5) * 0.5;
    p_distorted.y += cos(p.z * 0.3) * 0.5;

    // Distort and Mirror from mrange
    // https://www.shadertoy.com/view/WfcGWj
    float twist = -0.2 * p.z;
    p_distorted.xy *= mat2(cos(twist), -sin(twist), sin(twist), cos(twist));

    float offset = 0.301;
    float w = -2.0;
    vec2 d2 = vec2(sdGyroid(p_distorted, offset, w) + (col1.x * 0.08), mirrorSide);

    // 2nd gyroid 
    float offset2 = 0.3;
    float w2 = -1.2;
    vec2 d4 = vec2(sdGyroid(p_distorted, offset2, w2), mirrorSide);

    objId = 1.0;

    vec2 minDist = vec2(smin(d2.x, d4.x, 0.17), mirrorSide);
    return minDist;
}

vec2 rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.0;
    float id = 0.0;
    for(int i=0; i<80; i++)
    {
        vec3 p = ro + rd * dt;
        vec2 d = map(p);
        _noisePos = p;
        id = d.y;
        dt += d.x;
        if(abs(d.x) < 0.002 || dt > FAR) break;
    }
    return vec2(dt, id);
}

vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)).x - map(p - vec3(e,0,0)).x,
        map(p + vec3(0,e,0)).x - map(p - vec3(0,e,0)).x,
        map(p + vec3(0,0,e)).x - map(p - vec3(0,0,e)).x
    ));
}


vec3 render(vec3 ro, vec3 rd)
{
    vec3 col = vec3(0);

    vec2 dt = rayMarch(ro, rd);

    vec4 noise = noisedFBM(_noisePos * vec3(0.2, 0.45, 0.6) * 2.0 + vec3(3,0,0), 10, 0.95);

