        {
            float noise01 = noise.x * 0.5 + 0.5;
            float nl = clamp(dot(norm2, l), 0.0, 1.0);
            float NoV  = clamp(dot(norm2, -rd), 0.0, 1.0);    
            float rim  = pow(1.0 - NoV, 3.0);

            vec3 view = normalize(ro - p);
            vec3 halfVec = normalize(l + view);
            float spec = pow(max(0.0, dot(norm2, halfVec)),24.0);

            col += vec3(0.941,0.957,0.957) * spec * 0.04;
            col += vec3(0.710,0.133,0.031) * rim * 0.32;

            vec3 d1 = voronoiDistSq(p.xy * 0.6, iTime * 0.5);  

            float edgeDist = sqrt(d1.y) - sqrt(d1.x);

            vec3 col1 = 4.0 * sqrt(d1);
            col1 -= vec3(col1.x);
            col1 += 7.0 * ( col1.y / (col1.y / col1.z + 1.0) - 0.5 ) - col1;

            // 2nd gyroid  
            float gyroid2 = sdGyroid(p, 0.01,  0.3)  + (col1.x * 0.44);

            float crackWidth = -.01+smoothstep(0.,-0.2,norm2.y)* 0.24;
            float cracks = smoothstep(crackWidth,-20.0,gyroid2);

            float gyroid3 = sdGyroid(p+(iTime*.5), 0.5, 0.3);
            cracks *= gyroid3*2.+.2*smoothstep(0.2,.0,norm2.y);

            col+=cracks*vec3(1,.1,.1)*1.;
        }

        // Distort and Mirror from mrange
        // https://www.shadertoy.com/view/WfcGWj
        if(mirrorSide < 0.0)
        {
            col *= 1.0;
        }

        col = mix( col, vec3(0.0), 1.0-exp( -0.000525*dt.x*dt.x*dt.x ) );
    }
    col *= 20.0;

    col = pow(col, vec3(1.1 / 2.2));

    return col;
}

void mainImage(out vec4 O, in vec2 I)
{   
    vec3 ro = vec3(0,0, -14. -iTime * 1.);
