vec3 camLeft(float z, float s)
{
    float warpX = 1.5 * sin(0.5 * z);
    float warpY = 1.5 * cos(0.3 * z);

    // left side of the mirror (y < 5)
    float y = 3.0 - (1.1 + warpY) - s;

    float x = -warpX - s;

    return vec3(x, y, z);
}

vec3 makeRay(vec3 ro, vec2 uv)
{
    float z = ro.z;
    float warpX = 1.5 * sin(0.5 * z);
    float warpY = 1.5 * cos(0.3 * z);
    vec3 target = vec3(-warpX, 5.0 - (1.1 + warpY), z - 2.0); 
    vec3 f = normalize(target - ro);
    vec3 r = normalize(cross(vec3(0,1,0), f));
    vec3 u = cross(f, r);
    return normalize(f + uv.x*r + uv.y*u);
}

