float hash21( in vec2 p )
{
    p = 2.0*fract( p*0.3183099 + vec2(0.71,0.113));
    return fract( p.x*p.y*(p.x+p.y) );
}

vec2 hash22( in vec2 p )
{
    return vec2(hash21(p.xy+vec2(0.0,0.0)),
                hash21(p.yx+vec2(0.7,0.5)));
}

float noise( in vec2 x )
{
    vec2 i = floor(x);
    vec2 f = fract(x);
    f = f*f*(3.0-2.0*f);
    float a = hash21(i+vec2(0,0));
	float b = hash21(i+vec2(1,0));
	float c = hash21(i+vec2(0,1));
	float d = hash21(i+vec2(1,1));
    return -1.0+2.0*mix(mix(a,b,f.x),mix(c,d,f.x),f.y);
}

float voronoi2D( in vec2 p )
{
	vec2 i = floor(p);
	vec2 f = fract(p);
	float d = 10.0; 
	for( int n=-1; n<=1; n++ )
    for( int m=-1; m<=1; m++ )
    {
        vec2 b = vec2(m, n);
        vec2 r = b - f + hash22(i+b);
        d = min(d,dot(r,r));
    }
	return d;
}

// @iq
// https://www.shadertoy.com/view/3XlfWH
// https://iquilezles.org/articles/warp/
float fbmNoise( in vec2 p, in int oct )
{
    const mat2 m = mat2( 0.80, 0.60, -0.60, 0.80 );
    float f = 0.0;
    float s = 0.5;
    float t = 0.0;
    for( int i=0; i<oct; i++ )
    {
        f += s*noise( p );
        t += s;
        p = m*p*2.01;
        s *= .45;
    }
    return f/t;
}

float fbmVoronoi( in vec2 p )
{
    float f = 1.0;
    float s = 1.0;
    for( int i=0; i<8; i++ )
    {
        float v = voronoi2D(p);
        f = min(f,v*s);
        p *= 2.0;
        s *= 2.4;
    }
    return 10.0*f;
}

vec2 fbm2Noise( in vec2 p, in int o )
{
    return vec2(fbmNoise(p.xy+vec2(0.0,0.0),o), 
                fbmNoise(p.yx+vec2(0.7,1.3),o));
}

// Domain distortion
vec2 dis( in vec2 p, in float t )
{
    t *= 0.2;
    t += 0.1*sin(t);
    p.x -= 0.4*t;

    const float a = 0.7;
    p += a*0.5000*sin(p.yx*1.4+0.0+t);
    p += a*0.2500*sin(p.yx*2.3+1.0+t);
    p += a*0.1250*sin(p.yx*4.2+2.0+t);
    p += a*0.0625*sin(p.yx*8.1+3.0+t);

    p += 0.4*fbm2Noise( 0.5*p-t*vec2(0.9,0.18), 2 );
    return p;
}

// fabrice -> https://www.shadertoy.com/view/4dKSDV
vec3 voronoiDistSq(vec2 p, float dt)
{
    vec2 cellId, diff;
    float d;
    vec3 dists = vec3(9.0);       

    for (int k = 0; k < 9; ++k)
    {
        cellId = ceil(p) + vec2(k - (k/3)*3, k/3) - 2.0;
        // diff   = H(cellId) + cellId - p;
        diff = H(cellId) + cellId + .15 * cos(dt + 6.28 * H(cellId)) - p;

        d = dot(diff, diff);      

        d < dists.x ? (dists.yz = dists.xy, dists.x = d) :
        d < dists.y ? (dists.z  = dists.y , dists.y = d) :
        d < dists.z ?               dists.z = d        :
                       d;
    }
    return dists;
}

// https://iquilezles.org/articles/
float smin( float d1, float d2, float k )
{
    k *= 4.0;
    float h = max(k-abs(d1-d2),0.0);
    return min(d1, d2) - h*h*0.25/k;
}


vec2 camPath(float t)
{
    float x = sin(t * 0.5 ) * 1.25;
    float y = cos(t * 0.3 ) * 1.25;

    x += sin(t * 0.131) * 0.3;
    y += cos(t * 0.112) * 0.3;

    return vec2(x, y);
}


mat2 R2(float a){ return mat2(cos(a), -sin(a), sin(a), cos(a)); }

float sdGyroid(vec3 p, float offset, float thickness)
{
    return abs(dot(sin(p * offset), cos(p.yzx * offset)) - thickness);
}

vec2 map(vec3 p)
{
    vec3 d1 = voronoiDistSq(p.xy * 0.6, iTime * 0.5);  
    float edgeDist = sqrt(d1.y) - sqrt(d1.x);

    vec3 col1 = 4.0 * sqrt(d1);
    col1 -= vec3(col1.x);
    col1 += 7.0 * (col1.y / (col1.y / col1.z + 1.0) - 0.5) - col1;

    p.xy -= camPath(p.z);

    // REFLECTION
    float mirrorSide = p.y + 0.;
    p.y = abs(mirrorSide);

    // Apply distortions 
    vec3 p_distorted = p;
    p_distorted.y -= 5.31;  

    // warping
    p_distorted.x += sin(p.z * 2.5 + iTime * 1.0) * 0.5;
    p_distorted.y += cos(p.z * 2.3 + iTime * 1.) * 0.5;

    // Distort and Mirror from mrange
    // https://www.shadertoy.com/view/WfcGWj
    float twist = -0.2 * p.z;
    p_distorted.xy *= mat2(cos(twist), -sin(twist), sin(twist), cos(twist));

    // 2nd gyroid 
    float offset2 = 0.2;
    float w2 = -1.3;
    vec2 d4 = vec2(sdGyroid(p_distorted, offset2, w2), mirrorSide);

    objId = 1.0;

    return d4;
}

vec2 rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.0;
    float id = 0.0;
    for(int i=0; i<80; i++)
    {
        vec3 p = ro + rd * dt;
        vec2 d = map(p);
        _noisePos = p;
        id = d.y;
        dt += d.x;
        if(abs(d.x) < 0.002 || dt > FAR) break;
    }
    return vec2(dt, id);
}

vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)).x - map(p - vec3(e,0,0)).x,
        map(p + vec3(0,e,0)).x - map(p - vec3(0,e,0)).x,
        map(p + vec3(0,0,e)).x - map(p - vec3(0,0,e)).x
    ));
}


vec3 render(vec3 ro, vec3 rd)
{
    vec3 col = vec3(0);

    vec2 dt = rayMarch(ro, rd);

    if(dt.y < FAR)
    {
        vec3 p = ro + rd * dt.x;
        float mirrorSide = dt.y;

        // ===== TEXTURE CALCULATION =====
        // Use 3D position projected to 2D for texture coordinates
        vec2 texCoord = p.xy * 0.5;

        const float deltaTime = 2.3;
        vec2 q = dis(texCoord, iTime * 1.04);
        vec2 oq = dis(texCoord, iTime - deltaTime);
        float vel = length(q - oq) / deltaTime;

        // Wave pattern
        float f = q.y - 0.2*sin(0.57*q.x);

        // Add velocity-based cellular detail
        f -= 0.5*vel*vel*(1.1 - fbmVoronoi(q));

        // Final texture detail - THIS IS YOUR TEXTURE VALUE
        float texNoise = 0.5 + 1.5*fbmNoise(vec2(2.5*f, 0.0), 10);
        // ===== END TEXTURE CALCULATION =====

        vec3 norm = calcNormal(p);
        vec3 l = normalize(vec3(.3745,0.4,.679));

        //vec3 norm2 = norm; // Keep original normal since we removed derivatives
        vec3 norm2 = normalize(norm + oq.x * 0.01);
        if(objId > 0.0)
        {
            // Normalize texture to 0-1 range
            float noise01 = clamp(texNoise, 0.0, 1.0);

            float nl = clamp(dot(norm2, l), 0.0, 1.0);
            float NoV  = clamp(dot(norm2, -rd), 0.0, 1.0);    
            float rim  = pow(1.0 - NoV, 3.0);

            vec3 view = normalize(ro - p);
            vec3 halfVec = normalize(l + view);
            float spec = pow(max(0.0, dot(norm2, halfVec)),24.0);

            col += vec3(0.941,0.957,0.957) * spec * .04;
            col += vec3(0.031,0.710,0.573) * rim * 0.92;

            vec3 d1 = voronoiDistSq(p.xy * 0.5, iTime * 0.5);  
            float edgeDist = sqrt(d1.y) - sqrt(d1.x);

            vec3 col1 = 4.0 * sqrt(d1);
            col1 -= vec3(col1.x);
            col1 += 7.0 * ( col1.y / (col1.y / col1.z + 1.0) - 0.5 ) - col1;

            // 2nd gyroid  
            float gyroid2 = sdGyroid(p, 0.01, .3) + (col1.x * 1.44);

            float crackWidth = -.01+smoothstep(0.,-0.2,norm2.y)* 0.24;
            float cracks = smoothstep(crackWidth,-20.0,gyroid2);

            float gyroid3 = sdGyroid(p+(iTime*.5), 0.5, 0.3);
            cracks *= gyroid3*2.+.2*smoothstep(0.2,.0,norm2.y);

            // APPLY THE TEXTURE HERE - multiply or add the texture pattern
            col += cracks * vec3(0.314,0.098,0.008) * 1.;

            // ADD TEXTURE AS MODULATION
            col *= mix(vec3(0.0,0.25,0.6), vec3(0), noise01); // Modulate brightness based on texture

            // OR as additive detail:
            //col += vec3(noise01) * 0.3;
        }

        if(mirrorSide < 0.0)
        {
            col *= 0.02;
        }

        col = mix( col, vec3(0.0), 1.0-exp( -0.00015*dt.x*dt.x*dt.x ) );
    }
    col *= 20.0;

    col = pow(col, vec3(1.1 / 2.2));

    return col;
}
void mainImage(out vec4 O, in vec2 I)
{   
    vec3 ro = vec3(0,0, -1. -iTime * 1.);
    ro.xy += camPath(ro.z);

    vec3 tot = vec3(0.0);

    for (int m = 0; m < AA; m++)
    for (int n = 0; n < AA; n++) {
        vec2 off = vec2(m, n) / float(AA) - 0.5;
        vec2 uv = (2.0 * (I + off) - iResolution.xy) / iResolution.y;

        float rotDel = -1.56;//iTime * 0.05;
        //uv *= mat2(cos(rotDel), -sin(rotDel), sin(rotDel), cos(rotDel));

        vec3 rd = normalize(vec3(uv, -1));
        vec3 col = render(ro, rd); 

        tot += col;
    }

    tot /= float(AA * AA);

    O = vec4(tot, 1.0);
}

