        diff = H(cellId) + cellId + .15 * cos(dt + 6.28 * H(cellId)) - p;

        d = dot(diff, diff);      

        d < dists.x ? (dists.yz = dists.xy, dists.x = d) :
        d < dists.y ? (dists.z  = dists.y , dists.y = d) :
        d < dists.z ?               dists.z = d        :
                       d;
    }
    return dists;
}

// https://iquilezles.org/articles/
float smin( float d1, float d2, float k )
{
    k *= 4.0;
    float h = max(k-abs(d1-d2),0.0);
    return min(d1, d2) - h*h*0.25/k;
}

vec2 camPath(float t)
{
    float x = sin(t * 0.5 ) * 1.25;
    float y = cos(t * 0.3 ) * 1.25;

    x += sin(t * 0.131) * 0.3;
    y += cos(t * 0.112) * 0.3;

    return vec2(x, y);
}


mat2 R2(float a){ return mat2(cos(a), -sin(a), sin(a), cos(a)); }

float sdGyroid(vec3 p, float offset, float thickness)
{
    return abs(dot(sin(p * offset), cos(p.yzx * offset)) - thickness);
}

vec2 map(vec3 p)
{
    vec3 d1 = voronoiDistSq(p.xy * 0.6, iTime * 0.5);  
    float edgeDist = sqrt(d1.y) - sqrt(d1.x);

    vec3 col1 = 4.0 * sqrt(d1);
    col1 -= vec3(col1.x);
    col1 += 7.0 * (col1.y / (col1.y / col1.z + 1.0) - 0.5) - col1;

    p.xy -= camPath(p.z);

    // REFLECTION
    float mirrorSide = p.y + 2.;
    //p.y = abs(mirrorSide);

    // Apply distortions 
    vec3 p_distorted = p;
    p_distorted.y -= 4.9;  

    // warping
    p_distorted.x += sin(p.z * 1.5 + iTime * 0.5) * 0.5;
    p_distorted.y += cos(p.z * 1.3 + iTime * 0.5) * 0.5;

    // Distort and Mirror from mrange
    // https://www.shadertoy.com/view/WfcGWj
    float twist = -0.2 * p.z;
    p_distorted.xy *= mat2(cos(twist), -sin(twist), sin(twist), cos(twist));

    // 2nd gyroid 
    float offset2 = 0.1922;
    float w2 = -1.3;
    vec2 d4 = vec2(sdGyroid(p_distorted, offset2, w2), mirrorSide);

    objId = 1.0;

    return d4;
}

vec2 rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.0;
    float id = 0.0;
    for(int i=0; i<80; i++)
    {
        vec3 p = ro + rd * dt;
        vec2 d = map(p);
        _noisePos = p;
        id = d.y;
        dt += d.x;
        if(abs(d.x) < 0.002 || dt > FAR) break;
    }
    return vec2(dt, id);
}

vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)).x - map(p - vec3(e,0,0)).x,
        map(p + vec3(0,e,0)).x - map(p - vec3(0,e,0)).x,
        map(p + vec3(0,0,e)).x - map(p - vec3(0,0,e)).x
    ));
}


vec3 render(vec3 ro, vec3 rd)
{
    vec3 col = vec3(0);

    vec2 dt = rayMarch(ro, rd);

    if(dt.y < FAR)
    {
        vec3 p = ro + rd * dt.x;
        float mirrorSide = dt.y;


        vec3 norm = calcNormal(p);
        vec3 l = normalize(vec3(.3745,0.4,.679));

        if(objId > 0.0)
        {   
            float nl = clamp(dot(norm, l), 0.0, 1.0);
            float NoV  = clamp(dot(norm, -rd), 0.0, 1.0);    
            float rim  = pow(1.0 - NoV, 3.0);

            vec3 view = normalize(ro - p);
            vec3 halfVec = normalize(l + view);
            float spec = pow(max(0.0, dot(norm, halfVec)),24.0);

            col += vec3(0.941,0.957,0.957) * spec * .04;
            col += vec3(0.031,0.710,0.573) * rim * 0.92;

            vec3 d1 = voronoiDistSq(p.xy * 0.7, iTime * 1.);  
            float edgeDist = sqrt(d1.y) - sqrt(d1.x);

            vec3 col1 = 4.0 * sqrt(d1);
            col1 -= vec3(col1.x);
            col1 += 5.7 * ( col1.y / (col1.y / col1.z + 1.0) - 0.5 ) - col1;

            // 2nd gyroid  
            float gyroid2 = sdGyroid(p, 1.4, 2.3) + (col1.x * 1.444);

            float crackWidth = -.01+smoothstep(0.,-2.2,norm.y)* 1.24;
            float cracks = smoothstep(crackWidth,-20.0,gyroid2);

            float gyroid3 = sdGyroid(p+(iTime*.5), 0.5, 0.3);
            cracks *= gyroid3*2.+.2*smoothstep(0.2,.0,norm.y);

            col += cracks * vec3(0.078,0.839,0.941) * 1.;
        }

        if( mirrorSide < 0.0)
            col *= 0.01;

        col = mix( col, vec3(0.0), 1.0-exp( -0.00013*dt.x*dt.x*dt.x ) );
    }
    col *= 20.0;

    col = pow(col, vec3(1.1 / 2.2));

    return col;
}
