    return vec2(x, y);
}

// Quaternion multiplication
vec4 qmul(vec4 q1, vec4 q2) {
    return vec4(
        q1.w * q2.xyz + q2.w * q1.xyz + cross(q1.xyz, q2.xyz),
        q1.w * q2.w - dot(q1.xyz, q2.xyz)
    );
}

// Rotate a 3D point by a quaternion
vec3 qrot(vec3 p, vec4 q) {
    // q = (xyz, w) where xyz is the axis*sin(angle/2), w is cos(angle/2)
    vec3 t = 2.0 * cross(q.xyz, p);
    return p + q.w * t + cross(q.xyz, t);
}

// Create a quaternion from axis-angle
vec4 axisAngleToQuat(vec3 axis, float angle) {
    float halfAngle = angle * 0.5;
    return vec4(axis * sin(halfAngle), cos(halfAngle));
}

