        float fre  = clamp(1.3 + dot(norm, rd), 0., 1.);
        vec3  hal  = normalize(L - rd); // * sin(T) * 0.5 + 0.5;
        float spec = saturate(dot(norm, hal));
        float NoV  = clamp(dot(norm, -rd), 0.0, 1.0);    
