vec2 camPath(float t)
{
    float s = sin(t * 0.112);
    float c = cos(t * 0.024);
    return vec2(c*1.4 - s*1.4, c*1.7 + s*2.5);
}

float sdGyroid(vec3 p)
{
    float offset = 0.35;
    return dot(sin(p * offset), cos(p.yzx * offset)) - 0.25;
}

// Organic texture from 
// @jairoandre 
// https://www.shadertoy.com/view/clXXDl
float textOrganic(vec3 p)
{
    // Organic texture 
    vec2 n = vec2(0);
    vec2 q = vec2(0);
    vec2 uv = p.xy * 0.36; 
    float d = dot(uv, uv);
    float S = 4.;
    float a = 0.0;
    float t = iTime * 0.1052;
    mat2 m = R2(5.);

    for (float j = 0.; j < 5.; j++) { 
        uv *= m;
        n *= m;
        q = uv * S + t * 2. + sin(t * 2. - d * 3.) * .6 + j + n;
        a += dot(cos(q)/S, vec2(.215));
        n -= sin(q);
        S *= 1.52;
    }

    return a * 0.8;
}

float map(vec3 p)
{
    //p.z += iTime * 1.6;

    p.xy -= camPath(p.z);
    vec2 cellId = vec2(
        floor(p.x / 3.0),
        floor(p.z / 7.0)
    );


    float d1 = sdGyroid(p) - textOrganic(p) * 1.;

    float offset = (hash(cellId) - 0.5) * 6.0;//-3.1 + hash(cellId + 1.0) * 6.0;

    p.z += iTime * 4.;

    vec3 u_p = vec3(p.x - 4., p.y + 0.,  mod(p.z,13.0) - 0.5);
    //u_p.xy *= R2(iTime * 0.1);
    float sphere = length(u_p) - (1.2 + sin(iTime * 2.5) * 0.1);
    float n1 = fbm(u_p.xy * 0.7);
    float n2 = fbm(u_p.yz * 0.5 );
    float n = (n1 + n2) * .04;

    // Use smax to smoothly carve the sphere
    float d2 = smax(sphere, -n, 0.2);

    objId = step(d1, d2);
    return min(d1,d2);
}


