#define AA 1  // <----- make it 2 for AA
float objId = 0.0;

float psrdnoise(vec2 x, vec2 period, float alpha, out vec2 gradient) {
    vec2 uv = vec2(x.x + x.y * 0.5, x.y);
    vec2 i0 = floor(uv), f0 = fract(uv);

    float cmp = step(f0.y, f0.x);
    vec2 o1 = vec2(cmp, 1.0 - cmp);
    vec2 i1 = i0 + o1, i2 = i0 + 1.0;

    vec2 v0 = vec2(i0.x - i0.y * 0.5, i0.y);
    vec2 v1 = vec2(v0.x + o1.x - o1.y * 0.5, v0.y + o1.y);
    vec2 v2 = vec2(v0.x + 0.5, v0.y + 1.0);

    vec2 x0 = x - v0, x1 = x - v1, x2 = x - v2;

    vec3 iu, iv;
    if(any(greaterThan(period, vec2(0.0)))) {
        vec3 xw = vec3(v0.x, v1.x, v2.x);
        vec3 yw = vec3(v0.y, v1.y, v2.y);
        if(period.x > 0.0) xw = mod(xw, period.x);
        if(period.y > 0.0) yw = mod(yw, period.y);
        iu = floor(xw + 0.5 * yw + 0.5);
        iv = floor(yw + 0.5);
    } else {
        iu = vec3(i0.x, i1.x, i2.x);
        iv = vec3(i0.y, i1.y, i2.y);
    }

    vec3 hash = mod(iu, 289.0);
    hash = mod((hash * 51.0 + 2.0) * hash + iv, 289.0);
    hash = mod((hash * 34.0 + 10.0) * hash, 289.0);

    vec3 psi = hash * 0.07482 + alpha;
    vec3 gx = cos(psi); vec3 gy = sin(psi);
    vec2 g0 = vec2(gx.x, gy.x);
    vec2 g1 = vec2(gx.y, gy.y);
    vec2 g2 = vec2(gx.z, gy.z);

    vec3 w = 0.8 - vec3(dot(x0, x0), dot(x1, x1), dot(x2, x2));
    w = max(w, 0.0); vec3 w2 = w * w; vec3 w4 = w2 * w2;

    vec3 gdotx = vec3(dot(g0, x0), dot(g1, x1), dot(g2, x2));
    float n = dot(w4, gdotx);

    vec3 w3 = w2 * w; vec3 dw = -8.0 * w3 * gdotx;
    vec2 dn0 = w4.x * g0 + dw.x * x0;
    vec2 dn1 = w4.y * g1 + dw.y * x1;
    vec2 dn2 = w4.z * g2 + dw.z * x2;
    gradient = 10.9 * (dn0 + dn1 + dn2);

    return 10.9 * n;
}

// https://iquilezles.org/articles/smin
float smax( float a, float b, float k )
{
    float h = max(k-abs(a-b),0.0);
    return max(a, b) + h*h*0.25/k;
}

float smin( float d1, float d2, float k )
{
    k *= 4.0;
    float h = max(k-abs(d1-d2),0.0);
    return min(d1, d2) - h*h*0.25/k;
}

float fbm( in vec2 x)
{    
    float f = 5.9;
    float a = 1.;
    float t = 0.0;
    float fx = sin(iTime * 0.1) * 0.5 + 1.6;

    //x += iTime * 0.01;
    for( int i=0; i<4; i++ )
    {
        vec2 grad;
        t += a* (psrdnoise(f*x + iTime * 0.05,vec2(0,0), 1.0, grad));
        f *= 1.4;
        a *= 0.5;
    }
    return t;
}

mat2 R2(float a){
    float s = sin(a);
    float c = cos(a);
    return mat2(c,-s,s,c);
}

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

vec2 camPath(float t)
{
    float s = sin(t * 0.112);
    float c = cos(t * 0.024);
    return vec2(c*1.4 - s*1.4, c*1.7 + s*2.5);
}

float sdGyroid(vec3 p)
{
    float offset = 0.35;
    return dot(sin(p * offset), cos(p.yzx * offset)) - 0.25;
}

// Organic texture from 
// @jairoandre 
// https://www.shadertoy.com/view/clXXDl
float textOrganic(vec3 p)
{
    // Organic texture 
    vec2 n = vec2(0);
    vec2 q = vec2(0);
    vec2 uv = p.xy * 0.36; 
    float d = dot(uv, uv);
    float S = 4.;
    float a = 0.0;
    float t = iTime * 0.5;
    mat2 m = R2(5.);

    for (float j = 0.; j < 5.; j++) { 
        uv *= m;
        n *= m;
        q = uv * S + t * 1. + sin(t * 0.3 - d * 3.) * .6 + j + n;
        a += dot(cos(q)/S, vec2(.215));
        n -= sin(q);
        S *= 1.52;
    }

    return a * 0.8;
}

vec4 hash42(vec2 t) {
    float n = mod(t.x * 458.0 + t.y * 127.3, 100.0);
	return fract(sin(n*vec4(123., 1024., 1456., 264.))*vec4(6547., 345., 8799., 1564.));
}

float gyroidHeight(vec2 p, float offset, float w )
{
    // donde esta y
    float y = 0.;
    float sx = sin(p.x * offset);
    float cz = cos(p.y * offset);
    float sz = sin(p.y * offset);
    float cx = cos(p.x * offset);

    for(int i=0; i<6; i++)
    {
        float sy = sin(y * offset);
        float cy = cos(y * offset);

        float f  = sx*cy + sy*cz + sz*cx - w;

        float df = -sx*sy*offset + cy*cz*offset;

        y -= f / (df + 0.001);
    }

    return y;
}


float map(vec3 p)
{
    p.xy -= camPath(p.z);
    vec3 pulse = tanh(p); // make p chill so we can use it in calcs (make smol)
    // add pulse wave
    p +=  .1*(cos(1.5*iTime+dot(cos(1.5*iTime+p+cos(pulse)), pulse) ));;

    float d1 = sdGyroid(p) - textOrganic(p) * 1.;

    // Grid-based sphere placement (like the original)
    float pSpace = 3.0;
    vec2 pxz = p.xz / pSpace;
    vec2 cellId = floor(pxz);

    // Get cell center position
    vec2 cellCenter = (cellId + vec2(0.5)) * pSpace;

    // Get gyroid surface height at cell center
    float offset = 0.35;
    float w = 0.425;
    float surfaceY = gyroidHeight(cellCenter, offset, w);

    // Transform point to cell-local space
    vec3 cellP = p;
    cellP.xz = mod(p.xz, pSpace) - pSpace * 0.5;
    cellP.y -= surfaceY;

    // Create sphere with noise carving
    float sphere = length(cellP) - (1.3 + sin(iTime * 2.0) * 0.1);
    float n1 = fbm(cellP.xy * 0.25);
    float n2 = fbm(cellP.yz * 0.15);
    float n = (n2 + n1) * .03;

    float d2 = smax(sphere, -n, .5);

    objId = step(d1, d2);
    return smin(d1, d2, 0.1);
}

float rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.0;
    for(int i = 0; i < 80; i++)
    {   
        float d = map(ro + rd * dt);
        dt += d;

        if(abs(d) < 0.001 || dt > 30.0) break;
    }

    return dt;
}

vec3 calcNormal2(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
        map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
        map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
    ));
}

vec3 calcNormalBump(vec3 p)
{
    vec2 e = vec2(0.001, 0.0);

    float d = map(p);
    float dx = map(p + e.xyy) - map(p - e.xyy);
    float dy = map(p + e.yxy) - map(p - e.yxy);
    float dz = map(p + e.yyx) - map(p - e.yyx);

    vec3 norm = normalize(vec3(dx, dy, dz));

    // bump using fbm noise
    float bump = fbm(p.xy *2.0) * 0.5;

    // Calculate bump gradient
    float bx = fbm((p + e.xyy).xy * 1.0) - fbm((p - e.xyy).xy * 1.0);
    float by = fbm((p + e.yxy).xy * 1.0) - fbm((p - e.yxy).xy * 1.0);

    float bumpStrength = 0.0073;
    norm = normalize(norm + vec3(bx, by, 0) * bumpStrength / e.x);

    return norm;
}

float saturate(float x){ return clamp(x, 0.0, 1.0); }

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

vec3 render(vec3 ro, vec3 rd)
{
    vec3 col = vec3(0);

    float dt = rayMarch(ro,rd);

    if(dt < 30.)
    {
        vec3 p = ro + rd * dt;
        vec3 norm = calcNormalBump(p);

        float ambient = 0.8;
        vec3  L    = normalize(vec3(2, 2, 1));
        float diff = saturate(dot(norm, L));
        float fre  = clamp(1.3 + dot(norm, rd), 0., 1.);
        vec3  hal  = normalize(L - rd); // * sin(T) * 0.5 + 0.5;
        float spec = saturate(dot(norm, hal));
        float NoV  = clamp(dot(norm, -rd), 0.0, 1.0);    
        float rim  = pow(1.0 - NoV, 3.0);


        if(false)
            col += 0.5 + 0.5*norm.yxz;

        float t = 0.0;
        vec3 albedo = vec3(0);

        //if(objId > 0.0) 
        {
            t = (sdGyroid(p) - 0.) * 1.0 + iTime * 0.1; 
            albedo = palette(t, vec3(0.5), vec3(0.5), vec3(1.0), vec3(0.1, 0.4, 0.5));
            col = ambient * albedo; 
            col += diff * diff * spec * 0.6;
            col += vec3(0.922,0.925,0.937) * rim * .747;
        } 

        col = mix( col, vec3(0.0), 1.0-exp( -0.0003*dt*dt*dt) );
    }


    return col;
}

