// Simple Bio Texture Example - Foundation Shader
// Demonstrates cellular/organic texturing on a box
// Based on Shane's Biomine cellular tiling technique

// https://www.shadertoy.com/view/4lyGzR

// The cellular tile function - creates organic voronoi-like patterns
// This is the CORE of the bio texture effect
float drawSphere(in vec3 p)
{
    p = fract(p) - 0.5;    
    return dot(p, p);
}

float cellTile(in vec3 p)
{
    // Draw four overlapping spheres at different positions in a tile
    // The positions wrap around edges, making it tileable
    vec4 d;

    d.x = drawSphere(p - vec3(0.81, 0.62, 0.53));

    // Rotate coordinates and place second sphere
    p.xy = vec2(p.y - p.x, p.y + p.x) * 0.7071;
    d.y = drawSphere(p - vec3(0.39, 0.2, 0.11));

    // Rotate YZ and place third sphere
    p.yz = vec2(p.z - p.y, p.z + p.y) * 0.7071;
    d.z = drawSphere(p - vec3(0.62, 0.24, 0.06));

    // Rotate XZ and place fourth sphere
    p.xz = vec2(p.z - p.x, p.z + p.x) * 0.7071;
    d.w = drawSphere(p - vec3(0.2, 0.82, 0.64));

    // Find first and second closest distances
    vec4 v;
    v.xy = min(d.xz, d.yw);
    v.z = min(max(d.x, d.y), max(d.z, d.w));
    v.w = max(v.x, v.y);

    // Subtract second from first for beveled voronoi look
    float result = min(v.z, v.w) - min(v.x, v.y);

    return result * 2.66; // Normalize roughly to [0,1]
}

// Simple 3D noise for additional detail
float hash(float n) { return fract(sin(n) * 43758.5453); }

float noise3D(in vec3 p)
{
    const vec3 s = vec3(7, 157, 113);
    vec3 ip = floor(p);
    p -= ip; 
    vec4 h = vec4(0.0, s.yz, s.y + s.z) + dot(ip, s);
    p = p * p * (3.0 - 2.0 * p);
    h = mix(fract(sin(h) * 43758.5453), fract(sin(h + s.x) * 43758.5453), p.x);
    h.xy = mix(h.xz, h.yw, p.y);
    return mix(h.x, h.y, p.z);
}

// Rotation matrix
mat2 R2(float a) { return mat2(cos(a), -sin(a), sin(a), cos(a)); }

// Rounded box SDF
float sdRoundBox(vec3 p, vec3 b, float r)
{
    vec3 q = abs(p) - b + r;
    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0) - r;
}

// Simple scene - just a rotating box
vec3 _hitPos;
vec3 _rotatedPos;
float map(vec3 p)
{
    p.xz *= R2(iTime * 0.4);
    p.zy *= R2(iTime * 0.4);
    _rotatedPos = p;
    float d = sdRoundBox(p, vec3(1.0), 0.1);
    return d;
}

// Basic raymarcher
float rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.0;
    for(int i = 0; i < 80; i++)
    {
        vec3 p = ro + rd * dt;
        float d = map(p);
        _hitPos = p;
        dt += d;
        if(abs(d) < 0.001 || dt > 30.0) break;
    }
    return dt;
}

// Calculate surface normal
vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e, 0, 0)) - map(p - vec3(e, 0, 0)),
        map(p + vec3(0, e, 0)) - map(p - vec3(0, e, 0)),
        map(p + vec3(0, 0, e)) - map(p - vec3(0, 0, e))
    ));
}

// Bio texture bump function - this creates the organic surface detail
float bumpSurf(in vec3 p)
{
    // Scale the position for texture detail
    p /= 3.0;

    // Two layers of cellular texture at different frequencies
    // This gives it depth and variation
    float ct1 = cellTile(p * 2.0 + sin(p * 12.0) * 0.5) * 0.66;
    float ct2 = cellTile(p * 6.0 + sin(p * 36.0) * 0.5) * 0.34;
    float ct = ct1 + ct2;

    // Smoothstep creates the characteristic bio-vein look
    // Values outside the range create the raised "veins"
    float bioPattern = (1.0 - smoothstep(-0.2, 0.25, ct)) * 0.9;

    // Add a tiny bit of noise for micro-detail
    float noi = noise3D(p * 66.0) * 0.1;

    return bioPattern + noi;
}

// Bump mapping - perturbs the normal based on texture
vec3 doBumpMap(in vec3 p, in vec3 nor, float bumpfactor)
{
    const vec2 e = vec2(0.001, 0);
    float ref = bumpSurf(p);

    // Calculate gradient of bump function
    vec3 grad = (vec3(
        bumpSurf(p - e.xyy),
        bumpSurf(p - e.yxy),
        bumpSurf(p - e.yyx)
    ) - ref) / e.x;

    // Remove normal component from gradient
    grad -= nor * dot(nor, grad);

    return normalize(nor + grad * bumpfactor);
}

void mainImage(out vec4 O, in vec2 I)
{
    // Screen coordinates
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    vec3 col = vec3(0);

    // Camera setup
    vec3 ro = vec3(0, 0, 2.4);
    vec3 rd = normalize(vec3(uv, -1));

    // Ray march the scene
    float dt = rayMarch(ro, rd);

    if(dt < 30.0)
    {
        vec3 p = ro + rd * dt;
        vec3 norm = calcNormal(p);

        // Apply bump mapping for organic surface detail
        norm = doBumpMap(_rotatedPos, norm, 0.3);

        col = norm; ///texCol * (diff + amb);
    }

    O = vec4(col, 1.0);
}

