float map(vec3 p)
{
    p.xy -= camPath(p.z); 
    _rotatedPos = p;
    float d = sdGyroid(p);
    return d +  dot(sin(p*1. + iTime*3.283 + sin(p.yzx*.5)), vec3(.033));
