// Basic raymarcher
float rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.0;
    for(int i = 0; i < 80; i++)
    {
        vec3 p = ro + rd * dt;
        float d = map(p);
        _hitPos = p;
        dt += step(d, 1.0) * d * 0.2 + d * 0.5;
        //dt += d;
        if(abs(d) < 0.002 * (dt * 0.125 + 1.0) || dt > 30.0) break;
        //if(abs(d) < 0.001 || dt > 30.0) break;
    }
    return dt;
}

// Calculate surface normal
vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e, 0, 0)) - map(p - vec3(e, 0, 0)),
        map(p + vec3(0, e, 0)) - map(p - vec3(0, e, 0)),
        map(p + vec3(0, 0, e)) - map(p - vec3(0, 0, e))
    ));
}

// Bio texture bump function - this creates the organic surface detail
float bumpSurf(in vec3 p)
{
    // Scale the position for texture detail
    p /= 7.0;

    // Two layers of cellular texture at different frequencies
    // This gives it depth and variation
    float ct1 = cellTile(p * 2.0 + sin(p * 12.0) * 0.5) * 0.66;
    float ct2 = cellTile(p * 6.0 + sin(p * 36.0) * 0.5) * 0.34;
    float ct = ct1 + ct2;

    // Smoothstep creates the characteristic bio-vein look
    // Values outside the range create the raised "veins"
    float bioPattern = (1.0 - smoothstep(-0.2, 0.25, ct)) * 0.9;

    // Add a tiny bit of noise for micro-detail
    float noi = noise3D(p * 66.0) * 0.1;

    return bioPattern + noi;
}

// Bump mapping - perturbs the normal based on texture
vec3 doBumpMap(in vec3 p, in vec3 nor, float bumpfactor)
{
    const vec2 e = vec2(0.02, 0);
    float ref = bumpSurf(p);

    // Calculate gradient of bump function
    vec3 grad = (vec3(
        bumpSurf(p - e.xyy),
        bumpSurf(p - e.yxy),
        bumpSurf(p - e.yyx)
    ) - ref) / e.x;

    // Remove normal component from gradient
    grad -= nor * dot(nor, grad);

    return normalize(nor + grad * bumpfactor);
}

float calculateAO( in vec3 p, in vec3 n )
{
	float ao = 0.0, l;
    const float maxDist = 4.;
	const float nbIte = 6.0;
    for( float i=1.; i< nbIte+.5; i++ )
    {
        l = (i + hash(i))*.5/nbIte*maxDist;

        ao += (l - map( p + n*l ))/(1.+ l);
    }

    return clamp(1.- ao/nbIte, 0., 1.);
}

float saturate(float x){ return clamp(x, 0.0, 1.0); }

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    vec3 col = vec3(0);

    vec3 ro = vec3(4, 0, 2.4 - iTime * 4.);
    ro.xy += camPath(ro.z);
    vec3 rd = normalize(vec3(uv, -1));

    float dt = rayMarch(ro, rd);

    if(dt < 30.0)
    {
        vec3 p = ro + rd * dt;
        vec3 norm = calcNormal(p);


        norm = doBumpMap(p, norm, 0.02); 

        float ao = calculateAO(p, norm);

        // Create bio texture color
        vec3 sps = _hitPos / 7.0;
        float ct1 = cellTile(sps * 2.0 + sin(sps * 12.0) * 0.5) * 0.66;
        float ct2 = cellTile(sps * 6.0 + sin(sps * 36.0) * 0.5) * 0.34;
        float ct = ct1 + ct2;

        // Color the veins
        vec3 baseColor = vec3(0.114,0.620,0.788);
        vec3 veinColor = vec3(0.231,0.016,0.404);//vec3(0.275,0.204,0.749);
        float veinMask = 1.0 - smoothstep(-0.1, 0.25, ct);
        vec3 texCol = baseColor * veinMask + veinColor;

        // Light position in world space
        vec3 lightPos = ro + vec3(0, 0.5, 5);

        // Light direction vector
        vec3 L = lightPos - p;

        // Get distance BEFORE normalizing
        float distlpsp = max(length(L), 0.001);

        // normalize the light direction
        L /= distlpsp;

        // Light attenuation based on distance
        float atten = 1.0 / (1.0 + distlpsp * 0.25);

        // Lighting terms 
        float ambience = .5; 
        float diff = max(dot(norm, L), 0.0);

        // Specular
        float spec = pow(max(dot(reflect(-L, norm), -rd), 0.0), 32.0);

        float shading = 1.0; 

        // Base texture + separate specular with blue tint
        col = texCol * (diff + ambience) + vec3(0.7, 0.9, 1.0) * spec;

        // Apply attenuation, shading, AND ambient occlusion
        col *= atten * shading * ao; 

        // Fog
        col = mix(col, vec3(0), 1.0 - exp(-0.00021 * dt * dt * dt));
    }

    col *= 4.0;
    col = pow(col, vec3(1.1 / 2.2));

    O = vec4(col, 1.0);
}

