float drawSphere(in vec3 p)
{
    p = fract(p) - 0.5;    
    return dot(p, p);
}

float cellTile(in vec3 p)
{
    // Draw four overlapping spheres at different positions in a tile
    // The positions wrap around edges, making it tileable
    vec4 d;

    d.x = drawSphere(p - vec3(0.81, 0.62, 0.53));

    // Rotate coordinates and place second sphere
    p.xy = vec2(p.y - p.x, p.y + p.x) * 0.7071;
    d.y = drawSphere(p - vec3(0.39, 0.2, 0.11));

    // Rotate YZ and place third sphere
    p.yz = vec2(p.z - p.y, p.z + p.y) * 0.7071;
    d.z = drawSphere(p - vec3(0.62, 0.24, 0.06));

    // Rotate XZ and place fourth sphere
    p.xz = vec2(p.z - p.x, p.z + p.x) * 0.7071;
    d.w = drawSphere(p - vec3(0.2, 0.82, 0.64));

    // Find first and second closest distances
    vec4 v;
    v.xy = min(d.xz, d.yw);
    v.z = min(max(d.x, d.y), max(d.z, d.w));
    v.w = max(v.x, v.y);

    // Subtract second from first for beveled voronoi look
    float result = min(v.z, v.w) - min(v.x, v.y);

    return result * 2.66; // Normalize roughly to [0,1]
}

