vec3 render(vec3 ro, vec3 rd)
{
    vec3 col = vec3(0);

    float dt = rayMarch(ro, rd);

    if(dt < 30.0)
    {
        vec3 p = ro + rd * dt;
        vec3 norm = calcNormal(p);

        vec3 baseColor = vec3(0.180,0.180,0.180);
        float t = 0.0;
        vec3 veinColor = vec3(0);

        if(objId == 0.0) 
        {

            float d1 = sdGyroid(p, 1.5 , 1.719);
            float d2 = sdGyroid(p, 25.,  -5.2);
            float blob = d1 + dot(sin(p.y*1.2 - iTime*0.3 + sin(p.yzx*2.5)), vec3(.15033));
            blob -= d2 * .3749;
            t = blob * .02 + .1;
            veinColor = palette(t, vec3(0.5), vec3(0.5), vec3(1.0), vec3(0.41, 0.694, 0.5));
        } else {
            t = sdGyroid(p, 1.2, 1.1) * .1 + 0.3183;
            veinColor = palette(t, vec3(0.5), vec3(0.5), vec3(1.0), vec3(0.1, 0.4, 0.5));
        }
