#define AA 1  // <----- make it 2 for AA

// Simple 3D noise for additional detail
float hash(float n) { return fract(sin(n) * 43758.5453); }

float noise3D(in vec3 p)
{
    const vec3 s = vec3(7, 157, 113);
    vec3 ip = floor(p);
    p -= ip; 
    vec4 h = vec4(0.0, s.yz, s.y + s.z) + dot(ip, s);
    p = p * p * (3.0 - 2.0 * p);
    h = mix(fract(sin(h) * 43758.5453), fract(sin(h + s.x) * 43758.5453), p.x);
    h.xy = mix(h.xz, h.yw, p.y);
    return mix(h.x, h.y, p.z);
}

mat2 R2(float a) { return mat2(cos(a), -sin(a), sin(a), cos(a)); }

vec2 camPath(float t)
{
    float s = sin(t * 0.212);
    float c = cos(t * 0.124);
    return vec2(c*1.4 - s*1.4, c*1.7 + s*2.5);
}

// https://iquilezles.org/articles/
float smin( float d1, float d2, float k )
{
    k *= 4.0;
    float h = max(k-abs(d1-d2),0.0);
    return min(d1, d2) - h*h*0.25/k;
}

float sdGyroid2(vec3 p, float scale, float thickness)
{
    p *= scale;
    float offset = 0.35;
    float d = dot(sin(p * offset), cos(p.yzx * offset)) + thickness;
    return d / scale;
}

float sdGyroid(vec3 p, float scale, float thickness)
{
    p *= scale;
    float offset = 0.35;
    float d = 0.5 * (sin(2.*p.x*offset)*cos(p.y*offset)*sin(p.z*offset)
                   + sin(p.x*offset)*sin(2.*p.y*offset)*cos(p.z*offset)
                   + cos(p.x*offset)*sin(p.y*offset)*sin(2.*p.z*offset))
            - 0.5 * (cos(2.*p.x*offset)*cos(2.*p.y*offset)
                   + cos(2.*p.y*offset)*cos(2.*p.z*offset)
                   + cos(2.*p.z*offset)*cos(2.*p.x*offset)) + thickness;
    return d / scale;
}

float smaxP(float a, float b, float s){

    float h = clamp( 0.5 + 0.5*(a-b)/s, 0., 1.);
    return mix(b, a, h) + h*(1.0-h)*s;
}


