float map(vec3 p)
{
    p.xy -= camPath(p.z);
    _rotatedPos = p;

    float d1 = sdGyroid(p, 1.5, 1.719);
    float d2 = sdGyroid(p, 25., -3.2);
    float d3 = sdGyroid(p, 1., 2.09);
    float d5 = sdGyroid(p, 2.13, 1.4); // New scale for interference

    // Multiplicative combination - creates interesting moiré interference
    float interference = d1 * d5 * 1.18;

    float d4 = smaxP(1.125 - length(p.xy - vec2(2, 0)) + 2.5*cos(p.z*4.14159/32.),
                1.23075-interference, 7.) - abs(3.5-d3)*.14375;

    float blob = d1 + dot(sin(p.z*1.2 + iTime*0.53 + sin(p.yzx*5.5)), vec3(.15033));
    blob -= d2 * .259;

    float finalDist = smin(blob, min(d3, d4), 0.25);

    objId = 0.0;
    if (d3 < blob && d3 <= d4) objId = 1.0;
    else if (d4 < blob && d4 < d3) objId = 2.0;

    return finalDist;
}

// Basic raymarcher
float rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.0;
    for(int i = 0; i < 100; i++)
    {
        vec3 p = ro + rd * dt;
        float d = map(p);
        _hitPos = p;
        dt += step(d, 1.0) * d * 0.2 + d * 0.5;
        //dt += d;
        if(abs(d) < 0.002 * (dt * 0.125 + 1.0) || dt > 30.0) break;
        //if(abs(d) < 0.001 || dt > 30.0) break;
    }
    return dt;
}

// Calculate surface normal
vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e, 0, 0)) - map(p - vec3(e, 0, 0)),
        map(p + vec3(0, e, 0)) - map(p - vec3(0, e, 0)),
        map(p + vec3(0, 0, e)) - map(p - vec3(0, 0, e))
    ));
}

float coral(vec3 p)
{
    float result = 0.0;
    float amp = 1.0;

    // First pass: create main branches
    for(int i = 0; i < 3; i++)
    {
        float scale = pow(2.3, float(i));
        vec3 q = p * scale;

        // Ridged noise (abs creates ridges)
        float layer = abs(dot(sin(q), cos(q.zxy)));
        layer = 1.0 - layer; // Invert so ridges are high
        layer = layer * layer; // Sharpen ridges

        result += layer * amp;
        amp *= 0.5;
    }

    // Second pass: add fine detail that follows the structure
    vec3 q = p * 8.0;
    float detail = abs(dot(sin(q + result), cos(q.yzx + result)));

    // Enhance the branches
    result = pow(result, 0.8) + detail * 0.2;

    return result * 1.5;
}

// Bio texture bump function - this creates the organic surface detail
float bumpSurf(in vec3 p)
{
    // Scale the position for texture detail
    p /= 7.0;

    // Two layers of cellular texture at different frequencies
    // This gives it depth and variation
    float ct1 = coral(p * 2.0 + sin(p * 12.0) * 0.5) * .066;
    float ct2 = coral(p * 1.0 + sin(p * 36.0) * 0.5) * 0.2234;
    float ct = ct1 + ct2;

    // Smoothstep creates the characteristic bio-vein look
    // Values outside the range create the raised "veins"
    float bioPattern = (1.0 - smoothstep(-0.2, 0.25, ct)) * 0.9;

    // Add a tiny bit of noise for micro-detail
    float noi = noise3D(p * 36.0) * 0.1;

    return bioPattern + noi;
}

// Bump mapping - perturbs the normal based on texture
vec3 doBumpMap(in vec3 p, in vec3 nor, float bumpfactor)
{
    const vec2 e = vec2(0.02, 0);
    float ref = bumpSurf(p);

    // Calculate gradient of bump function
    vec3 grad = (vec3(
        bumpSurf(p - e.xyy),
        bumpSurf(p - e.yxy),
        bumpSurf(p - e.yyx)
    ) - ref) / e.x;

    // Remove normal component from gradient
    grad -= nor * dot(nor, grad);

    return normalize(nor + grad * bumpfactor);
}

float calculateAO( in vec3 p, in vec3 n )
{
	float ao = 0.0, l;
    const float maxDist = 4.;
	const float nbIte = 6.0;
    for( float i=1.; i< nbIte+.5; i++ )
    {
        l = (i + hash(i))*.5/nbIte*maxDist;

        ao += (l - map( p + n*l ))/(1.+ l);
    }

    return clamp(1.- ao/nbIte, 0., 1.);
}

float saturate(float x){ return clamp(x, 0.0, 1.0); }

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

vec3 render(vec3 ro, vec3 rd)
{
    vec3 col = vec3(0);

    float dt = rayMarch(ro, rd);

    if(dt < 30.0)
    {
        vec3 p = ro + rd * dt;
        vec3 norm = calcNormal(p);

        vec3 baseColor = vec3(0.180,0.180,0.180);
        float t = 0.0;
        vec3 veinColor = vec3(0);

        if(objId == 0.0) 
        {

            float d1 = sdGyroid(p, 1.5, 1.719);
            float d2 = sdGyroid(p, 25., -3.2);

            float blob = d1 + dot(sin(p.z*1.2 - iTime*.53 + sin(p.yzx*5.5)), vec3(.15033));
            blob -= d2 * .259;

            t = blob * .0 + .78;
            veinColor = palette(t, vec3(0.5), vec3(0.5), vec3(1.0), vec3(0.43, 0.74, 0.55));
        } else {
            t = sdGyroid(p, 1.2, 1.1) * .15 + 0.7;
            veinColor = palette(t, vec3(0.5), vec3(0.5), vec3(1.0), vec3(0.661, 0.54, 0.5));
        }
        norm = doBumpMap(p, norm, 0.25); 

        float ao = calculateAO(p, norm);
        float NoV = clamp(dot(norm, -rd), 0.0, 1.0);    
        float rim = pow(1.0 - NoV, 3.0);

        vec3 sps = _hitPos / 7.0;
        float scale1 = (objId > 0.0) ? 2.0 : 1.0;
        float scale2 = (objId > 0.0) ? 6.0 : 10.0;
        float sineScale2 = (objId > 0.0) ? 36.0 : 6.0;


        float ct1 = coral(p * 2.0 + sin(p * 12.0) * 0.5) * .066;
        float ct2 = coral(p * 1.0 + sin(p * 36.0) * 0.5) * 0.2234;
        float ct = ct1 + ct2;

        // Color the veins
        float veinMask = 1.0 - smoothstep(-0.1, 0.25, ct);
        vec3 texCol = baseColor * veinMask + veinColor;

        // Light position in world space
        vec3 lightPos = ro + vec3(0, 0.5, 5);
        vec3 L = lightPos - p;
        float distlpsp = max(length(L), 0.001);
        L /= distlpsp;

        // Light attenuation based on distance
        float atten = 1.0 / (1.0 + distlpsp * .25);

        // Lighting terms 
        float ambience = .5; 
        float diff = max(dot(norm, L), .0);

        // Specular with different colors based on objId
        vec3 specColor = (objId > .0) ? vec3(0.871) : vec3(0.7, 0.9, 1.0);
        float spec = pow(max(dot(reflect(-L, norm), -rd), 0.0), 32.0);

        // Base texture + separate specular
        col = texCol * (diff + ambience) + specColor * spec;

        // Apply attenuation, shading, AND ambient occlusion
        col *= atten * ao; 

        float hi = abs(mod(dt/0.665 - iTime*.003, 10.) - 5.) * 2.15;
        vec3 chargeCol = vec3(0.6) * col * 0.1 / (.01061 + hi * hi * .02);
        col += mix(chargeCol.yxz, chargeCol, noise3D(p * 1.0));

        // Fog
        col = mix(col, vec3(0), 1.0 - exp(-0.00019 * dt * dt * dt));
    }

    col *= 4.0;
    col = pow(col, vec3(1.1 / 2.2));

    return col;
}

void mainImage(out vec4 O, in vec2 I)
{
    vec3 ro = vec3(2, 0, -iTime * 2.5);
