        float NoV = clamp(dot(norm, -rd), 0.0, 1.0);    
        float rim = pow(1.0 - NoV, 3.0);

        vec3 sps = _hitPos / 7.0;
        float scale1 = (objId > 0.0) ? 2.0 : 1.0;
        float scale2 = (objId > 0.0) ? 6.0 : 10.0;
        float sineScale2 = (objId > 0.0) ? 36.0 : 6.0;


        float ct1 = coral(p * 2.0 + sin(p * 12.0) * 0.5) * .066;
        float ct2 = coral(p * 1.0 + sin(p * 36.0) * 0.5) * 0.2234;
        float ct = ct1 + ct2;

        // Color the veins
        float veinMask = 1.0 - smoothstep(-0.1, 0.25, ct);
        vec3 texCol = baseColor * veinMask + veinColor;

        // Light position in world space
        vec3 lightPos = ro + vec3(0, 0.5, 5);
        vec3 L = lightPos - p;
        float distlpsp = max(length(L), 0.001);
        L /= distlpsp;

        // Light attenuation based on distance
        float atten = 1.0 / (1.0 + distlpsp * .25);

        // Lighting terms 
        float ambience = .5; 
        float diff = max(dot(norm, L), .0);

        // Specular with different colors based on objId
        vec3 specColor = (objId > .0) ? vec3(0.871) : vec3(0.7, 0.9, 1.0);
        float spec = pow(max(dot(reflect(-L, norm), -rd), 0.0), 32.0);

        // Base texture + separate specular
        col = texCol * (diff + ambience) + specColor * spec;

        // Apply attenuation, shading, AND ambient occlusion
        col *= atten * ao; 

        float hi = abs(mod(dt/0.665 - iTime*.003, 10.) - 5.) * 2.15;
        vec3 chargeCol = vec3(0.6) * col * 0.1 / (.01061 + hi * hi * .02);
        col += mix(chargeCol.yxz, chargeCol, noise3D(p * 1.0));

        // Fog
        col = mix(col, vec3(0), 1.0 - exp(-0.00019 * dt * dt * dt));
    }

    col *= 4.0;
    col = pow(col, vec3(1.1 / 2.2));

    return col;
}

void mainImage(out vec4 O, in vec2 I)
{
    vec3 ro = vec3(2, 0, -iTime * 2.5);
    ro.xy += camPath(ro.z);
    vec3 tot = vec3(0.0);

    for (int m = 0; m < AA; m++)
    for (int n = 0; n < AA; n++) {
        vec2 off = vec2(m, n) / float(AA) - 0.5;
        vec2 uv = (2.0 * (I + off) - iResolution.xy) / iResolution.y;
        vec3 rd = normalize(vec3(uv * 0.5, -1));
        vec3 col = render(ro, rd); 

        tot += col;
    }

    tot /= float(AA * AA);

    O = vec4(tot, 1.0);
}

