void mainImage(out vec4 O, vec2 I)
{
    vec2 uv = I / iResolution.xy;
    vec2 center = vec2(0.5);

    vec3 col = vec3(0);
    float depth = 3.;

    float T = iTime;

    for(float i = 0.; i < depth; i++)
    {
        float z = fract(T * .125 + i / depth); 

        float scale = 1. + z * .8; 

        vec2 zoomUV = center + (uv - center) / scale;

        // Lateral parallax
        float parallax = (.5 - i / depth) * 0.02;
        vec2 offset = vec2(sin(T * 0.3), cos(iTime * 0.3)) * parallax;

        vec3 sam = texture(iChannel0, zoomUV + offset).rgb;

        // Fade in/out based on Z position
        // Smooth transition as patterns cycle through
        float fade = smoothstep(0., 0.5, z) * smoothstep(1., 0.59, z);
        float att = fade * (.3 - i / depth);

        col += sam * att;
    }
    col *= 4.;
    col /= depth * 1.5;
    col = pow(col, vec3(.8));

    O = vec4(col, 1.0);
}

