*/

#define T (iTime/3e2)
#define H(a) (cos(radians(vec3(180, 90, 0))+(a)*.82832)*0.5 + 0.5)

void mainImage(out vec4 O, vec2 I) {
    vec2 uv = I / iResolution.xy;
    vec4 buf = texture(iChannel0, uv);
    vec3 col = buf.rgb;
    float energy = buf.a;

    if (length(col) < 0.001 && energy < 0.001) {
        O = vec4(0.0);
        return;
    }

    float t = T;
    vec3 color = vec3(0.0);

    vec2 uvSize = 1.0 / iResolution.xy;

    float center = length(col);

    float right = length(texture(iChannel0, uv + vec2(uvSize.x, 0)).rgb);
    float left  = length(texture(iChannel0, uv - vec2(uvSize.x, 0)).rgb);
    float up    = length(texture(iChannel0, uv + vec2(0, uvSize.y)).rgb);
    float down  = length(texture(iChannel0, uv - vec2(0, uvSize.y)).rgb);

    vec2 gradient = vec2(right - left, up - down);
    float gradientStrength = length(gradient);

    float highlight = max(0.0, right - center);  // Bright edges
    float shadow = max(0.0, center - left);      // Dark edges

    // Flow-based hue
    float flowA = atan(gradient.y, gradient.x) / 3.1416;
    float hueInput = flowA + t * .046 + length(col);
    vec3 flowColor = H(hueInput);

    float colBright = smoothstep(0.0, .52, center);


    color = vec3(.0, 2.9, 1.7) * highlight * highlight * 2.0;  // Bright highlights
    color -= vec3(0.106,0.110,0.114) * shadow * shadow * 2.0;   // Subtle shadows
    color += mix(col, flowColor, .576) * colBright * 0.595;

    // Energy glow
    //vec3 energyGlow = vec3(0.9, 0.5, 0.7) * energy * .0555;
    //color += energyGlow;

    // Color mixing
    vec3 bgCol = color * .015 + color.brg * .236 + color * color;

    bgCol = max(bgCol, vec3(0.0));
    bgCol = pow(bgCol, vec3(.83));

    O = vec4(bgCol, 1.0);
}

