void mainImage(out vec4 O, vec2 I)
{
    vec2 uv = I / iResolution.xy;
    T = iTime;

    vec4 prev = texture(iChannel0, uv);

    vec2 worldPos = (2.0 * I - iResolution.xy) / iResolution.y;
    worldPos.x += T * .001;

    float scale = .5;
    vec2 accGrad = vec2(0.0);
    float totalWeight = 0.0;

    for(int i = 0; i < 6; i++)
    {
        float weight = 1.0 / scale;  
        vec2 grad = gradNoise(worldPos * scale * 6.0 + vec2(T * .05, 0)).yz;
        accGrad += grad * weight;
        totalWeight += weight;
        scale *= 2.0;
    }

    accGrad /= totalWeight; 

    float flowS = length(accGrad);

    vec2 eps = 1.0 / iResolution.xy;
    vec2 gradR = gradNoise((worldPos + vec2(eps.x, 0)) * 5.0).yz;
    vec2 gradL = gradNoise((worldPos - vec2(eps.x, 0)) * 5.0).yz;
    vec2 gradU = gradNoise((worldPos + vec2(0, eps.y)) * 5.0).yz;
    vec2 gradD = gradNoise((worldPos - vec2(0, eps.y)) * 5.0).yz;

    float div = (gradR.x - gradL.x + gradU.y - gradD.y) * .5;

    // Combine for energy field
    flowS = flowS * 2. + abs(div) * .5;

    // Exponential mapping
    flowS = 1. - exp(-flowS * 1.);

    O = vec4(prev.rgb, flowS);
}

