// Light by @Shane
void mainImage(out vec4 fragColor, in vec2 fragCoord){


    // The screen coordinates.
    vec2 uv = fragCoord/iResolution.xy;

    // Read in the blurred pixel value. There's no rule that says you can't read in the
    // value in the "X" channel, but blurred stuff is easier to bump, that's all.
    float c = 1. - texture(iChannel0, uv).y; 
    // Reading in the same at a slightly offsetted position. The difference between
    // "c2" and "c" is used to provide the highlighting.
    float c2 = 1. - texture(iChannel0, uv + .5/iResolution.xy).y;


    // Color the pixel by mixing two colors in a sinusoidal kind of pattern.
    float pattern = -cos(uv.x*1.75*3.14159 - .9)*cos(uv.y*1.5*3.14159 - .75)*.5 + .5;

    // Blue and gold, for an abstract sky over a... wheat field look. Very artsy. :)
    vec3 col = pow(vec3(1.5, 1, 1)*c, vec3(1, 4, 12));
    col = mix(col, col.zyx, clamp(pattern - .2, 0., 1.) );

    // Extra color variations.
    //vec3 col = mix(vec3(c*1.2, pow(c, 8.), pow(c, 2.)), vec3(c*1.3, pow(c, 2.), pow(c, 10.)), pattern );
	//vec3 col = mix(vec3(c*1.3, c*c, pow(c, 10.)), vec3(c*c*c, c*sqrt(c), c), pattern );

    // Adding the highlighting. Not as nice as proper bump mapping, but still pretty effective.
    col += vec3(.036, 1.073, 0.56)*max(c2*c2 - c*c, 0.)*10.;

    // Apply a vignette and increase the brightness for that fake spotlight effect.
    col *= pow( 18.0*uv.x*uv.y*(1. - uv.x)*(1. - uv.y) ,1.125)*.615;

    // Fade in for the first few seconds.
    col *= smoothstep(0., 1., iTime/5.);

    // Rough gamma correction.
    fragColor = vec4(sqrt(min(col, 1.)), 1); 


}

// noise
vec3 hash33(in vec2 p){ 
    float n = sin(dot(p, vec2(41, 289)));    
    return fract(vec3(2097152, 262144, 32768)*n); 
}
// utility function
vec4 tx(in vec2 p) { return texture(iChannel0, p);}

vec2 laplacian(in vec2 uv, vec2 px)
{   
    vec2 c = tx(uv).xy;

    vec2 r = tx(uv + vec2(px.x, 0)).xy;
    vec2 l = tx(uv - vec2(px.x, 0)).xy;
    vec2 u = tx(uv + vec2(0, px.y)).xy;
    vec2 d = tx(uv - vec2(0, px.y)).xy;

    // Standard discrete laplacian: ∇²u ≈ (neighbors - 4*center)
    vec2 res = (r + l + u + d - 4.0 * c);

    return res;
}

void mainImage( out vec4 O, in vec2 I )
{
    vec2 uv = I / iResolution.xy;
    vec2 px = 1. / iResolution.xy;

    // Get current chemical concentrations
    float u = tx(uv).x;  // Chemical A
    float v = tx(uv).y;  // Chemical B

    // Calculate laplacian for both channels
    vec2 lap = laplacian(uv, px);

    // Gray-Scott Reaction-Diffusion Parameters
    // These create different patterns - experiment with them!
    float Du = 0.2097;      // Diffusion rate for U (faster)
    float Dv = 0.075;       // Diffusion rate for V (slower)
    float feed = 0.0637;     // Feed rate (adds U)
    float kill = 0.065;     // Kill rate (removes V)

    // The Gray-Scott equations:
    // ∂u/∂t = Du∇²u - uv² + f(1-u)
    // ∂v/∂t = Dv∇²v + uv² - (k+f)v

    float uvv = u * v * v;  // Reaction term

    // Update U (chemical A)
    float newU = u + Du * lap.x           // Diffusion
                   - uvv                   // Consumption by reaction
                   + feed * (1.0 - u);     // Feed (replenishment)

    // Update V (chemical B)
    float newV = v + Dv * lap.y           // Diffusion (slower)
                   + uvv                   // Production by reaction
                   - (kill + feed) * v;    // Removal

    // Add tiny noise for pattern nucleation
    vec3 noise = hash33(uv + vec2(53, 43)*iTime);
    newU += (noise.x - 0.5) * 0.0001;
    newV += (noise.y - 0.5) * 0.0001;

    if(iFrame > 9)
    {
        O.xy = clamp(vec2(newU, newV), 0., 1.); 
    } else {
        // Initialize with some circles 
        // you can add any shape to start here
        vec2 center = uv - 0.5;

        float size = 2.0;
        vec2 cell  = fract(center * size) - 0.5;
        vec2 id    = floor(center * size) - 0.5;

        float rnd = fract(sin(dot(id, vec2(12.9898, 78.233))) * 43758.5453);
        float phi = fract(iTime * 0.15 + rnd);
        float fx = step(0.9, phi);

        // circle
        float dist  = smoothstep(0.43, 0.3, length(cell) - 0.0);

        //float dist = fract(length(center) * 4.) - 0.5;
        float spot = smoothstep(0.15, 0.1, dist);

        O.x = 1.0; // U starts at 1
        O.y = spot * 0.5 + noise.z * 0.05; // V starts with small spots
    }
}

