    float uvv = u * v * v;  // Reaction term

    // Update U (chemical A)
    float newU = u + Du * lap.x           // Diffusion
                   - uvv                   // Consumption by reaction
                   + feed * (1.0 - u);     // Feed (replenishment)

    // Update V (chemical B)
    float newV = v + Dv * lap.y           // Diffusion (slower)
