// A simple fireworks demo. This was written a few years back, so I do not
// recall some of the finer implementation details... But the basic idea was
// to reduce the number of particles that needs to be tested by dividing each
// firework (big particle) into angles/sectors for the explosion (smaller
// particles). Using a very simple accumulation buffer style of temporal
// accumulation (without history clamping) also gives the nice light trails :)
//
// Author: Fredrik Nysjö (2018?)

#define NUM_SUBPARTICLES 45.
#define BLAST_RADIUS 0.63
#define PARTICLE_RADIUS 0.005
#define SUBPARTICLE_RADIUS 0.003
#define USE_TEMPORAL_ACCUMULATION 1
#define USE_JITTER 1
#define boxstep(a, b, x) clamp(((x)-(a))/((b)-(a)),0.0,1.0)

// Laplacian approximation - measures how much the center differs from its neighbors.
// Used for diffusion: high values flow toward low values, giving us those smooth smoke trails.
// The "- 4*c" balances out the 4 neighbor samples (standard 5-point stencil).
vec3 laplacian(vec2 uv, vec2 px, sampler2D ch)
{
    vec3 c = texture(ch, uv).rgb;
    vec3 r = texture(ch, uv + vec2( px.x, 0.0)).rgb;
    vec3 l = texture(ch, uv + vec2(-px.x, 0.0)).rgb;
    vec3 u = texture(ch, uv + vec2(0.0,  px.y)).rgb;
    vec3 d = texture(ch, uv + vec2(0.0, -px.y)).rgb;

    return r + l + u + d - 4.0*c;
}

// Simple sky gradient. Dark blue at the bottom fading to black at the top.
vec3 sky(vec2 uv)
{
    return mix(vec3(0.0, 0.002, 0.004), vec3(0.0), smoothstep(0.0, 1.0, uv.y));
}

// Individual explosion particle. The firework is divided into angular sectors, and this function
// handles each radial streak. By quantizing the angle and adding some randomized delay per sector.
float subparticle(vec2 xy, vec2 uv, float t, float r)
{
    // Position relative to firework center, normalized by radius.
    vec2 p = (xy - uv) / r;

    // Quantize the angle into discrete sectors.
    // angular bins, which gives us those distinct radial streaks instead of a uniform explosion.
    float s  = NUM_SUBPARTICLES / 360.0;
    float a  = round((degrees(atan(p.y, p.x) + 3.141592)) * s) / s;

    // Delta vector for this angular sector. The particle moves outward along its angle, with
    // gravity pulling it down over time
    vec2 del    = vec2(cos(radians(a)), sin(radians(a)));

    // Random delay per sector, sampled from noise. This staggers the particle emissions slightly,
    // so they don't all shoot out at exactly the same moment. Gives a more organic feel.
    float delay = texture(iChannel0, vec2(fract(a / 24.0), 1.0) + 0.5).a * 0.5 + 0.5;

    // Subparticle radius grows slightly over time.
    float sub_r = SUBPARTICLE_RADIUS * (1.0 + t);

    // Check if the current pixel is within this subparticle's radius. If so, light it up.
    float fade  = (length((xy + del * (r * 0.9) * delay) - uv) < sub_r) ? 4.0 : 0.0;

    return fade;
}

// Main firework particle. Handles the launch trajectory and explosion timing.
vec3 particle(vec2 uv, float aspect, vec2 jitter)
{
    vec2 xy    = vec2(aspect * 0.5, 0.6);               // Starting position - centered horizontally
    vec2 del   = vec2(0.2, 0.15);                       // Directional trajectory 
    vec3 color = vec3(0.890,0.110,0.227);                  
    color *= bool(USE_TEMPORAL_ACCUMULATION) ? 2.0 : 1.0; // Boost brightness if using temporal accumulation.

    // Normalized time for the firework's lifecycle. Loops continuously based on frame count.
    float t = mod((float(iFrame) / 60.0) * del.y, xy.y) / xy.y;

    // Radius expands from PARTICLE_RADIUS to BLAST_RADIUS as the firework explodes
    float r = boxstep(0.3, 1.0, t) * BLAST_RADIUS + PARTICLE_RADIUS;

    // Fade out as the firework ages. Bright during ascent and explosion, then dims.
    float fade = boxstep(1.0, 0.2, t);

    // Update position based on trajectory. The particle rises with a parabolic arc
    xy.x += t * del.x;
    xy.y = 0.8 * pow(t * xy.y, 1.0 / 3.0);
    xy   += bool(USE_JITTER) ? jitter : vec2(10.0); // Slight jitter for anti-aliasing.

    // Once the radius exceeds PARTICLE_RADIUS, switch to the explosion phase
    // Otherwise, just render the ascending particle.
    fade = (r > PARTICLE_RADIUS) ? subparticle(xy, uv, t, r) * fade : 2.0;

    // Return color if within radius, black otherwise.
    return (length(xy - uv) < r) ? fade * color : vec3(0.0);
}

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv  = I / iResolution.xy;
    float as = iResolution.x / iResolution.y;
    vec2 px  = 1.0 / iResolution.xy;

    // Random noise for dithering and jitter. Helps with banding and gives a subtle film grain look.
    vec3 rnd = texture(iChannel0, mod(I, 64.0) / 64.0).rgb;

    // Temporal jitter for anti-aliasing. Shifts the sample position slightly each frame using
    // the golden ratio for good distribution over time.
    vec2 jitter = (fract(rnd.rg + 1.61803 * float(iFrame % 64)) - 0.5) * 0.0025;

    // Start with the sky gradient and add some noise to break up color banding.
    vec3 colSky = sky(uv); 
    colSky += (rnd - 0.5) / 255.0;

    // Current fireworks light
    vec3 fw = particle(vec2(uv.x * as, uv.y), as, jitter);

    // Previous "smoke/light" field
    vec3 prev = texture(iChannel1, uv).rgb;

    // Simple diffusion + decay PDE on the buffer
    vec3 lap = laplacian(uv, px, iChannel1);

    float D      = .49;     // diffusion strength
    float decay  = 1.;      // how fast trails disappear
    float inject = 2.5;     // coupling from fireworks into smoke

    vec3 smoke = prev + D * lap - decay * prev + inject * fw;

    // Clamp to keep things sane
    smoke = clamp(smoke, 0.0, 9.0);

    vec3 col = colSky + fw + smoke * .49;

    O = vec4(col, 1.0);
}

