// testing every tiny particle individually -- instead, each firework divides its
// explosion into angular sectors, which cuts down the workload significantly.
// 
// Also using a super basic temporal accumulation buffer (no fancy history clamping)
// which gives us those nice light trails for free. Sometimes the simple approach
// just works. :)
//
// Author: Fredrik Nysjö (2018?)

#define NUM_SUBPARTICLES 32.
#define BLAST_RADIUS 0.63
#define PARTICLE_RADIUS 0.005
#define SUBPARTICLE_RADIUS 0.0103
#define USE_TEMPORAL_ACCUMULATION 1
#define USE_JITTER 1
#define boxstep(a, b, x) clamp(((x)-(a))/((b)-(a)),0.0,1.0)

// Standard 5-point Laplacian stencil. Basically measures how much the center 
// pixel differs from its neighbors. High values flow toward low values, which
// gives us the smooth diffusion effect for the smoke trails. The "- 4*c" part
// just balances out the four neighbor samples.
vec3 laplacian(vec2 uv, vec2 px, sampler2D ch)
{
    vec3 c = texture(ch, uv).rgb;
    vec3 r = texture(ch, uv + vec2( px.x, 0.0)).rgb;
    vec3 l = texture(ch, uv + vec2(-px.x, 0.0)).rgb;
    vec3 u = texture(ch, uv + vec2(0.0,  px.y)).rgb;
    vec3 d = texture(ch, uv + vec2(0.0, -px.y)).rgb;

    return r + l + u + d - 4.0*c;
}

// Simple sky gradient -- dark blue at bottom, black at top.
vec3 sky(vec2 uv)
{
    return mix(vec3(0.0, 0.002, 0.004), vec3(0.0), smoothstep(0.0, 1.0, uv.y));
}

// Individual explosion particle. Each firework gets divided into angular sectors,
// and this handles one radial streak. Quantizing the angle gives us those distinct
// rays instead of just a uniform circular explosion.
float subparticle(vec2 xy, vec2 uv, float t, float r, int i)
{
    // Position relative to the firework center, normalized by radius.
    vec2 p = (xy - uv) / r;

    // Quantize angle into discrete sectors. This is what creates the distinct
    // radial streaks -- without it you'd just get a boring spherical explosion.
    float s  = NUM_SUBPARTICLES / 360.0;
    float a  = round((degrees(atan(p.y, p.x) + 3.141592)) * s) / s;

    // Direction vector for this sector. Particles shoot outward along their angle,
    // with gravity pulling them down over time.
    vec2 del = vec2(cos(radians(a)), sin(radians(a)));

    // Random delay per sector from noise. Staggers the emissions slightly so they
    // don't all blast out at exactly the same moment -- makes it feel more organic.
    float delay = texture(iChannel0, vec2(fract(a / 24.0 + float(i) * 1.618), 1.0) + 0.5).a * .5 + .5;

    // Subparticle grows a bit over time.
    float sub_r = SUBPARTICLE_RADIUS * (1.0 + t);

    // Light up if we're within the subparticle radius.
    // Square particles using max distance
    // Here you can add different shapes to the particle explosion 
    vec2 particlePos = (xy + del * (r * 0.9) * delay) - uv;
    float fade = (max(abs(particlePos.x), abs(particlePos.y)) < sub_r) ? 4.0 : 0.0;

    // dymond
    //fade = (abs(particlePos.x) + abs(particlePos.y) < sub_r) ? 4.0 : 0.0;

    return fade;
}

// Main firework particle -- handles launch trajectory and explosion timing.
vec3 particle(vec2 uv, float aspect, vec2 jitter, int i)
{
    // Each firework needs unique properties, so we use `i` to sample different
    // regions of the noise texture. Converting to 2D coordinates for a 64x64 layout.
    ivec2 txtPos = ivec2(i & 63, i >> 6);

    // Starting position -- scaled to cover screen width/height.
    vec2 xy = texture(iChannel0, vec2(txtPos) / 64. + 0.4).rg * vec2(aspect, 0.5) + vec2(0,0.5);             

    // Trajectory velocity -- sampling different channels for horizontal/vertical.
    vec2 del = texture(iChannel0, vec2(txtPos) / 64. + 0.5).ba * vec2(0.4, 0.05) + vec2(-0.2, 0.1);                     

    // Color variation per firework. Offsetting the texture lookup gives each one
    // a different hue.
    vec3 color = texture(iChannel0, vec2(txtPos.x, txtPos.y + 3) / 64. + 0.5).rgb * .5 + 0.05;
    color *= color;
    color *= bool(USE_TEMPORAL_ACCUMULATION) ? 4.0 : 1.0; // Brightness boost if using accumulation.

    // Normalized time for this firework's lifecycle -- loops continuously.
    float t = mod((float(iFrame) / 60.0) * del.y, xy.y) / xy.y;

    // Radius expands as it explodes.
    float r = boxstep(0.5, 1.0, t) * BLAST_RADIUS + PARTICLE_RADIUS;

    // Fade out over time -- bright during ascent and explosion, then dims.
    float fade = boxstep(1.0, 0.2, t);

    // Update position with parabolic arc trajectory.
    xy.x += t * del.x;
    xy.y = 0.8 * pow(t * xy.y, 1.0 / 3.0);
    xy.y -= t * t * 0.23; 
    xy += bool(USE_JITTER) ? jitter : vec2(10.0); // Jitter for anti-aliasing.

    // Once radius exceeds PARTICLE_RADIUS, we're in explosion mode.
    // Otherwise just render the ascending particle.
    fade = (r > PARTICLE_RADIUS) ? subparticle(xy, uv, t, r, i) * fade : 2.0;

    // Return color if we're within radius, black otherwise.
    return (length(xy - uv) < r) ? fade * color : vec3(0.0);
}

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv  = I / iResolution.xy;
    float as = iResolution.x / iResolution.y;
    vec2 px  = 1.0 / iResolution.xy;

    // Random noise for dithering -- helps with banding and adds subtle film grain.
    vec3 rnd = texture(iChannel0, mod(I, 64.0) / 64.0).rgb;

    // Temporal jitter using golden ratio for good distribution across frames.
    // Cheap anti-aliasing basically.
    vec2 jitter = (fract(rnd.rg + 1.61803 * float(iFrame % 64)) - 0.5) * 0.0025;

    // Sky gradient with a bit of noise to break up banding.
    vec3 colSky = sky(uv); 
    colSky += (rnd - 0.5) / 255.0;

    // Accumulate current frame's fireworks.
    vec3 fw = vec3(0);

    // Render multiple fireworks. The "min(0, iFrame)" trick forces the loop
    // to unroll properly on some drivers -- bit of a hack, but it works.
    for(int i = 0; i < 10 + min(0, iFrame); i++)
    {
        fw += particle(vec2(uv.x * as, uv.y), as, jitter, i);
    }

    // Previous frame's "smoke/light" field.
    vec3 prev = texture(iChannel1, uv).rgb;

    // Simple reaction-diffusion PDE on the buffer.
    vec3 lap = laplacian(uv, px, iChannel1);

    float D      = .45;     // Diffusion strength.
    float decay  = 1.;      // How fast trails disappear.
    float inject = 2.5;     // How much firework light feeds into the smoke.

    vec3 smoke = prev + D * lap - decay * prev + inject * fw;

    // Clamp to keep things reasonable.
    smoke = clamp(smoke, 0.0, 9.0);

    vec3 col = colSky + fw + smoke * .49;

    O = vec4(col, 1.0);
}

