// explosion into angular sectors, which cuts down the workload significantly.
// 
// Also using a super basic temporal accumulation buffer (no fancy history clamping)
// which gives us those nice light trails for free. Sometimes the simple approach
// just works. :)
//
// Author: Fredrik Nysjö (2018?)

#define NUM_SUBPARTICLES 32.
#define BLAST_RADIUS 0.63
#define PARTICLE_RADIUS 0.005
#define SUBPARTICLE_RADIUS 0.0103
#define USE_TEMPORAL_ACCUMULATION 1
#define USE_JITTER 1
#define boxstep(a, b, x) clamp(((x)-(a))/((b)-(a)),0.0,1.0)

const int WORD[5] = int[5](110, 140, 179, 177, 133); 

// Standard 5-point Laplacian stencil. Basically measures how much the center 
// pixel differs from its neighbors. High values flow toward low values, which
// gives us the smooth diffusion effect for the smoke trails. The "- 4*c" part
// just balances out the four neighbor samples.
vec3 laplacian(vec2 uv, vec2 px, sampler2D ch)
{
