    vec3 r = texture(ch, uv + vec2( px.x, 0.0)).rgb;
    vec3 l = texture(ch, uv + vec2(-px.x, 0.0)).rgb;
    vec3 u = texture(ch, uv + vec2(0.0,  px.y)).rgb;
    vec3 d = texture(ch, uv + vec2(0.0, -px.y)).rgb;

    return r + l + u + d - 4.0*c;
}

