// and this handles one radial streak. Quantizing the angle gives us those distinct
// rays instead of just a uniform circular explosion.
float subparticle(vec2 xy, vec2 uv, float t, float r, int i)
{
    // Position relative to the firework center, normalized by radius.
    vec2 p = (xy - uv) / r;

    // Quantize angle into discrete sectors. This is what creates the distinct
    // radial streaks -- without it you'd just get a boring spherical explosion.
    float s  = NUM_SUBPARTICLES / 360.0;
    float a  = round((degrees(atan(p.y, p.x) + 3.141592)) * s) / s;

    // Direction vector for this sector. Particles shoot outward along their angle,
    // with gravity pulling them down over time.
    vec2 del = vec2(cos(radians(a)), sin(radians(a)));

    // Random delay per sector from noise. Staggers the emissions slightly so they
    // don't all blast out at exactly the same moment -- makes it feel more organic.
    float delay = texture(iChannel0, vec2(fract(a / 24.0 + float(i) * 1.618), 1.0) + 0.5).a * .5 + .5;

    // Subparticle grows a bit over time.
    float sub_r = SUBPARTICLE_RADIUS * (1.0 + t);

    // Position relative to this particle.
    vec2 particlePos = (xy + del * (r * 0.9) * delay) - uv;

    // Make the character billboard a bit bigger than the particle.
    float charSize = sub_r * 1.5;

    // Convert world space to 0-1 UV coordinates for the character.
    vec2 charUV = (particlePos / charSize) * 0.5 + 0.5;

    // Outside the character box? Bail early.
    if(charUV.x < 0.0 || charUV.x > 1. || charUV.y < 0.0 || charUV.y > 1.0) {
        return 0.0;
    }

    // Pick which letter based on which radial sector we're in.
    int letterIdx = int(mod(a / (360.0 / float(NUM_SUBPARTICLES)), 5.0));
    int ascii = WORD[letterIdx];

    // Font texture is a 16x16 grid. Convert ASCII to grid position.
    vec2 charCell = vec2(mod(float(ascii), 16.0), floor(float(ascii) / 16.0)) / 16.0;

    // Scale our UVs to one grid cell and offset to the right character.
    vec2 fontUV = charUV / 16.0 + charCell;

    // Sample and brighten.
    float charAlpha = texture(iChannel2, fontUV).r;

    return charAlpha * 4.0;
}

