// Distance from point p to line segment ab
float sdSegment(vec2 p, vec2 a, vec2 b)
{
    vec2 pa = p - a;
    vec2 ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}

// Letter K: vertical stem + two diagonals meeting at center
float sdK(vec2 p, float scale)
{
    float h = 0.5 * scale;
    float w = 0.5 * scale;

    vec2 stemTop = vec2(0.0, h);
    vec2 stemBot = vec2(0.0, -h);
    vec2 diagTopEnd = vec2(-w, h);
    vec2 diagBotEnd = vec2(-w, -h);
    vec2 center = vec2(0.0, 0.0);

    float dStem = sdSegment(p, stemBot, stemTop);
    float dUpperDiag = sdSegment(p, center, diagTopEnd);
    float dLowerDiag = sdSegment(p, center, diagBotEnd);

    return min(dStem, min(dUpperDiag, dLowerDiag));
}

// Modified subparticle function using K-SDF
float subparticle(vec2 xy, vec2 uv, float t, float r, int i)
{
    // Position relative to firework center
    vec2 p = (xy - uv);

    // Scale the K based on explosion radius
    float kScale = r * 0.5;

    // Distance to K shape
    float distToK = sdK(p, kScale);

    // Thickness of the K lines
    float lineThickness = SUBPARTICLE_RADIUS * (1.0 + t * 0.5);

    // Light up if we're near the K shape
    float fade = (distToK < lineThickness) ? 4.0 : 0.0;

    return fade;
}

