/*
    Holographic Foil Dice
    ---------------------

    A raymarched dice with holographic foil effects. The shader creates a 3D
    dice with sparkles and chromatic aberration to simulate that shiny trading
    card foil appearance.

    The approach uses volumetric raymarching with chromatic dispersion - we
    render the scene three times with slight offsets (once per RGB channel)
    to create that rainbow shimmer effect characteristic of holographic foil.

    The dice geometry is created using SDFs, with
    an additional fractal pattern overlaid to create the sparkly foil texture.
    Random sparkle positions are determined per voxel using hash functions.
*/

// Two by two rotation matrix constructor.
mat2 rot2D(float a) {
    return mat2(cos(a), sin(a), -sin(a), cos(a));
}

// Hash function for random sparkle generation.
// Takes a 3D grid position and returns a pseudo-random value.
float hash(vec3 p) {
    return fract(sin(dot(p, vec3(127.1, 311.7, 74.7))) * 43758.5);
}

// Second hash for sparkle animation phase.
float hash2(vec3 p) {
    return fract(sin(dot(p, vec3(43.7, 78.2, 123.4))) * 127.1);
}

// Distance to dice using chamfered cube approximation.
float diceSDF(vec3 p) 
{
    // Combination of box and chamfered edges for dice shape.
    float box = max(max(abs(p.x), abs(p.y)), abs(p.z)) - 3.0;
    float chamfer = dot(abs(p), vec3(.577)) * .9 - 3.0;
    return max(box, chamfer);
}

float foilGyroid(vec3 p, float t) 
{
    float freq = 1.5;
    p *= freq;

    // Animated gyroid + time to phase-shift the surface
    float gyroid = dot(sin(p+t), cos(p.yzx));

    // Return absolute value to get distance-like field
    return abs(gyroid) * 1.5;
}


// Main raymarching function with chromatic offset.
// Returns the accumulated glow/color for one channel.
float raymarch(vec2 I, vec2 R, mat2 rotX, mat2 rotY, float chromaticOffset) 
{    
    float colorAccum = 0.0;
    float dt = 0.0;

    for(float i = 0.0; i < 80.0; i++) {

        // Ray position: start from camera, march along ray direction.
        // Scale controls the zoom - smaller values = zoomed out, larger = zoomed in
        vec3 p = vec3((I + I - R) / R.y * dt, dt - 5.0);

        // Early exit if ray goes too far off screen.
        if (abs(p.x) > 5.0) break;

        // Apply rotations for camera orientation.
        p.xz *= rotX;
        if (iMouse.z > 0.0) {
            p.yz *= rotY;
        } else {
            p.xy *= rotY;
        }

        // Voxel grid position for sparkle lookup.
        vec3 gridPos = floor(p * 6.0);
        vec3 localPos = fract(p * 6.0) - 0.5;

        // Determine if this voxel contains a sparkle.
        // Random threshold creates scattered sparkle distribution.
        float sparkleAmount = step(length(localPos), hash(gridPos) * 0.3 + 0.1);

        // Random phase offset for sparkle animation.
        float sparklePhase = hash2(gridPos) * 6.28;

        // Calculate foil pattern distance.
        float foilDist = foilGyroid(p, iTime * 0.5);

        // Calculate dice SDF.
        float cubeDist = diceSDF(p);

        // Add sine wave modulation for extra surface detail.
        float sineDist = length(sin(cubeDist)) - .13;

        // Combine distances: dice surface, foil pattern, and sine detail.
        // The chromatic offset creates RGB separation for holographic effect.
        float combinedDist = max(max(cubeDist, foilDist - 0.1), sineDist) 
                             + chromaticOffset * 0.02 - i / 130.0;

        // Adaptive step size - smaller steps near surfaces. interesting
        float stepSize = 0.01 + 0.15 * abs(combinedDist);
        dt += stepSize;

        // Smooth factor for glow intensity near surfaces.
        float stepFactor = smoothstep(0.02, 0.01, stepSize);

        // Accumulate volumetric glow with sparkle contribution.
        // Base glow + animated sparkles create the holographic shimmer.
        colorAccum += 2.3 / stepSize * 
            (0.5 + 0.5 * sin(i * 0.3 + chromaticOffset * 5.0) + 
             stepFactor * 4.0 * sparkleAmount * 
             sin(sparklePhase + i * 0.04 + chromaticOffset * 5.0));
    }

    return colorAccum;
}

void mainImage(out vec4 O, in vec2 I) 
{    
    vec3 R = iResolution;

    // Mouse control for rotation, or auto-rotate based on time.
    vec2 Ma = iMouse.z > 0.0 ? 
                      (iMouse.xy / R.xy - 0.5) * 6.28 : 
                      vec2(iTime / 6.0);

    // Rotation matrices for 3D camera orientation.
    mat2 rotX = rot2D(Ma.x);
    mat2 rotY = rot2D(Ma.y);

    // Raymarch three times with chromatic offset for RGB channels.
    // -1.0 = red shifted backward, 0.0 = green centered, 1.0 = blue shifted forward.
    O.r = raymarch(I, R.xy, rotX, rotY, -1.0);
    O.g = raymarch(I, R.xy, rotX, rotY,  0.0);
    O.b = raymarch(I, R.xy, rotX, rotY,  1.0);
    O.a = 1.0;

    // Tone mapping to compress the high dynamic range glow.
    O = tanh(O * O / 1e7);
}

