// inspired by @Jaenam's gem shaders
// e.g., https://www.shadertoy.com/view/t3SyzV
// Play with color here
#define PALETTE vec3(1,4,2)
#define FAR 55.0

// Domain distortion that creates the swirling crystalline effect
vec3 swirling(vec3 p, float t, float d1)
{
    // Rotation based on time and depth creates the swirling motion
    p.xy *= mat2(cos(t + p.z * 0.16 + vec4(0, 33, 11, 0)));

    // First distortion layer: dual sine waves
    p += cos(t + p.zxy) + cos(t + p.yzx * d1) / d1 / 4.0;

    // Second distortion: self-dot product creates complex folding
    p += 0.15 * cos(t + dot(cos(t + p), p) * p);

    return p;
}

vec3 raymarch(vec2 uv, vec2 offset, float T)
{
    vec3 ro = vec3(0, 0, -16.0);  // Ray origin
    vec3 rd = normalize(vec3(uv, 1)); // Ray direction

    float dt = 0.0;  // Distance traveled
    vec3 col = vec3(0.0);  // Accumulated color

    // Main raymarch loop
    for(float i = 0.0; i < FAR && dt < FAR; i++) 
    {
        // Current position along ray
        vec3 p = ro + rd * dt;

        // Store original position for band calculation
        vec3 q = p;

        // Sphere SDF 
        float d = length(p) - 11.0;

        // Apply swirling distortion
        p = swirling(p, T, d);

        // Radial bands centered at distance 
        float bandDist = 0.021 + 0.6 * abs(8.0 - length(q.xy));

        // Tileable box grid
        float boxDist = dot(abs(fract(p) - 0.5), vec3(0.054));
        float v = max(d, boxDist);

        // Step forward by minimum distance
        d = min(bandDist, v);
        dt += d;

        // Accumulate color from multiple sources
        col += (1.0 + cos(p.z + PALETTE)) / v          
             + dt * vec3(5, 2, 1) / bandDist / 10.0         
             + 7.0 * vec3(3, 4, 1) / length(offset);   
    }

    return col;
}

void mainImage(out vec4 O, vec2 I) 
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    float T = iTime * 0.12;

    // Create an offset vector for secondary glow effect
    // It looks like the sun is hitting it from the side
    vec2 offSet = uv - (uv.yx * .9 + .35 - vec2(-0.235, 0.215));    

    // Perform raymarch and get accumulated color
    vec3 c = raymarch(uv, offSet, T);

    // Vignette-style color rotation based on distance from center
    // Smoothly rotates RGB->GBR near edges
    c = mix(c, c.yzx, smoothstep(3.0, .1, length(uv) * 1.));

    // Final tonemap: square for saturation boost, massive scale down,
    // slight offset to prevent pure black, and radial brightness fallout
    O.rgb = tanh(c * c / 6e7 / length(uv - .43) + .02 * length(uv));
}

































