/*
    HELICAL GRID SPACE WARP 
    ----------------------------------------

    A nice helix twig from @TekF of a xmas shader
    https://www.shadertoy.com/view/wtd3D4

    This wraps 3D space into repeating cells that spiral around the Y axis.
    We're placing capsules (twigs) to show where each cell lives in the warped space.
*/

vec3 HelixGrid( out ivec2 grid, vec3 pos, int numSpokes, float yStepPerRotation, float yByOutStep )
{
    // Start by converting to polar coords - angle, height, radius
    vec3 p = vec3(atan(pos.x,pos.z), pos.y, length(pos.xz));

    // Tilt based on radial distance - this creates the spiral
    p.y -= yByOutStep*p.z;
    float l = sqrt(1.+yByOutStep*yByOutStep);

    // Set up our grid spacing
    vec2 scale = vec2(6.283185/float(numSpokes), yStepPerRotation);
    p.xy /= scale;

    // Rotate and skew to get that nice irrational period
    float sn = 1./float(numSpokes);
    p.xy += p.yx*vec2(-1,1)*sn;

    // Triangle-wave the horizontal axis so cells mirror and tile seamlessly
    grid = ivec2(floor(p.xy));
    vec2 pair = fract((p.xy + 1.)*.5)*2.-1.0;
    p.xy = (abs(pair)-.5);
    vec2 flip = step(0.,pair)*2.-1.;
    p.xy *= scale;

    // Undo the skew
    p.y += flip.y*yByOutStep*p.z;

    // Convert back to Cartesian
    p.xz = p.z*vec2(sin(p.x),cos(p.x));

    // Apply rotation to match the earlier skew
    p.yz = (p.yz + flip.yy*p.zy*vec2(-1,1)*yByOutStep)/l;

    return p;
}

// 2d rotation function
mat2 R2(float a){ return mat2(cos(a), -sin(a), sin(a), cos(a));}

float map(vec3 p)
{ 
    ivec2 grid;

    // rotate in a planet direction
    p.xz *= R2(iTime * 0.4);

    vec3 twig = HelixGrid(grid, p, 20, 0.3, 0.2);

    // INFINITE CYLINDER 
    float capsule = length(twig.xy) - 0.01;

    return capsule;
}


void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    vec3 color = vec3(0.0);

    // setup the ray origin and direction
    vec3 ro = vec3(0,0,1);
    vec3 rd = normalize(vec3(uv, -1));

    // distance travel
    float dt = 0.0;

    // Standard raymarching loop
    for(int i = 0; i < 50; i++)
    {
        vec3 p = ro + rd * dt;
        float d = map(p);
        dt += d;

        if(abs(d) < 0.001 || dt > 20.0) break;
    }

    // Simple depth-based shading 
    color = vec3(1.0 - dt * 1.1);

    O = vec4(color, 1.0);
}

