/*
    HELICAL GRID SPACE WARP 
    ----------------------------------------

    A nice helix twig from @TekF of a xmas shader
    https://www.shadertoy.com/view/wtd3D4

    This wraps 3D space into repeating cells that spiral around the Y axis.
    We're placing capsules (twigs) to show where each cell lives in the warped space.
*/

vec3 HelixGrid( out ivec2 grid, vec3 pos, int numSpokes, float yStepPerRotation, float yByOutStep )
{
    // Start by converting to polar coords - angle, height, radius
    vec3 p = vec3(atan(pos.x,pos.z), pos.y, length(pos.xz));

    // Tilt based on radial distance - this creates the spiral
    p.y -= yByOutStep*p.z;
    float l = sqrt(1.+yByOutStep*yByOutStep);

    // Set up our grid spacing
    vec2 scale = vec2(6.283185/float(numSpokes), yStepPerRotation);
    p.xy /= scale;

    // Rotate and skew to get that nice irrational period
    float sn = 1./float(numSpokes);
    p.xy += p.yx*vec2(-1,1)*sn;

    // CORRECTED TRIANGLE-WAVE REPETITION
    // The key insight: we need the cell to go from [0, 1] in normalized space
    grid = ivec2(floor(p.xy));

    // Get fractional part [0, 1]
    vec2 frac = fract(p.xy);

    // Determine which cells need mirroring
    // Even cells: use frac as-is [0, 1]
    // Odd cells: mirror to [1, 0] so they tile seamlessly
    vec2 flip = mod(vec2(grid), 2.0);  // 0 for even, 1 for odd
    frac = mix(frac, 1.0 - frac, flip);

    // Now frac is in [0, 1] and properly mirrored
    // Center it to [-0.5, 0.5] for symmetric geometry
    p.xy = (frac - 0.5) * scale;

    // Track flip direction for later transformations
    vec2 flipSign = sign(flip - 0.5);  // -1 or +1

    // Undo the skew
    p.y += flipSign.y * yByOutStep * p.z;

    // Convert back to Cartesian
    p.xz = p.z * vec2(sin(p.x), cos(p.x));

    // Apply rotation to match the earlier skew
    p.yz = (p.yz + flipSign.yy * p.zy * vec2(-1,1) * yByOutStep) / l;

    return p;
}

// 2d rotation function
mat2 R2(float a){ return mat2(cos(a), -sin(a), sin(a), cos(a));}

float map(vec3 p)
{ 
    ivec2 grid, twigGrid;

    // 1st level main branch of the helix grid
    vec3 branchP = p;
    branchP.xz *= R2(iTime * 0.053);
    vec3 branch = HelixGrid(grid, branchP, 10, 0.425, 0.135);

    // 2nd level: Twigs spiraling around each branch
    // Key: Use the .xzy swizzle to rotate the space so twigs don't spiral 
    // in the same direction as branches (looks more organic)
    vec3 twig = HelixGrid(twigGrid, branch.xzy, 10, 0.036, 0.15);

    // Twig capsule (smaller and shorter than branches)
    float clampTwig = max(0.0, abs(twig.z) - 0.13);
    float twigCapsule = length(vec2(length(twig.xy), clampTwig)) - 0.0058;

    // Combine branches and twigs - min gives us both
    return twigCapsule;
}

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    vec3 color = vec3(0.0);

    // setup the ray origin and direction
    vec3 ro = vec3(0,0,1);
    vec3 rd = normalize(vec3(uv, -1));

    // distance travel
    float dt = 0.0;

    // Standard raymarching loop
    for(int i = 0; i < 50; i++)
    {
        vec3 p = ro + rd * dt;
        float d = map(p);
        dt += d;

        if(abs(d) < 0.001 || dt > 20.0) break;
    }

    // Simple depth-based shading 
    color = vec3(1.0 - dt * 1.);

    O = vec4(color, 1.0);
}

