// cone mask for the tree
float sdCone(vec3 p)
{
    float r = length(p.xz);
    return max(
        dot(vec2(p.y, r), normalize(vec2(.3, 1))),  
        -p.y - 2.0 + r * .46                          
    );
}

vec3 HelixGrid( vec3 p, float n, float da, float s )
{
    // convert to polar coordinates
    p = vec3( atan(p.x,p.z), p.y, length(p.xz) );
    p.y -= s*p.z;

    // draw a grid of needles
    vec2 scale = vec2( 6.28/n, da );
    p.xy /= scale;

    // rotate and skew the grid to get a spiral with nice irrational period
    p.xy += p.yx*vec2(-1,1)/n; // so we step by an integer number of rows

    // make horizontal triangle-waved, so edges of cells match up no matter what's put inside them!
    vec2 pair = mod(p.xy + 1.,2.) - 1.;
    p.xy = abs(pair) - .5;
    p.xy *= scale;

    // unshear...
    float flip = sign(pair.y); // sign() - using actual sign here since mod guarantees non-zero
    p.y += flip*s*p.z;

    // reconstruct a non-bent space
    p.xz = p.z*vec2(sin(p.x),cos(p.x));
    // ...and apply rotation to match the shear (now we've sorted out the grid stuff)
    p.yz = ( p.yz + flip*p.zy*vec2(-1,1)*s ) / sqrt(1.+s*s); 

    return p;
}

// Bubble bounds - shell around the tree
float sdBubble(vec3 pos) {
    float bounds = sdCone(pos);
    return abs(bounds) - 0.3;  // Shell 0.3 units thick around cone
}

float XmasLight(vec3 p, uint seed, float s, float r) 
{
    // Early culling - only compute if near valid area
    float f = sdBubble(p);
    f -= r;

    float margin = 0.1;
    if (f > margin) return f;  // Skip if far away

    // Random offset per seed (different for each bauble set)
    vec3 offset = s * (hash3(coord1(seed)) - 0.5);
    p += offset;

    // Find which grid cell we're in
    vec3 c = floor(p / s);
    ivec3 ic = ivec3(c);
    c = (c + 0.5) * s;  // Center of grid cell

    // Jitter position within cell (deterministic per cell)
    c += (s * 0.5 - r) * (hash1(coord3(uvec3(ic + 63356)) ^ seed) * 2.0 - 1.0);

    // Cull if sphere center is outside valid zone
    if (sdBubble(c - offset) > 0.0) return margin;

    // Simple sphere SDF
    f = length(p - c) - r;

    return min(f, margin);  // Don't overshoot to next cell
}

// Multiple bauble sets with different spacing/sizes
float Baubles1(vec3 p) { return XmasLight(p, 0x1004U, 0.34, 0.05); }

float map(vec3 p)
{   
    // Cone centered where camera can see it
    float bounds = sdCone(p);

    // 1st level - main branches
    vec3 p1 = p;
    p1.xz *= R2(-iTime * 0.105);
    vec3 branch = HelixGrid(p1, 12., 0.5, 0.5);

    // Infinite cylinders 
    float d1 = length(branch.xy) - 0.005;

    // 2nd level - twigs
    vec3 branch2 = HelixGrid(branch.xzy, 7., 0.45, 1.);
    float d2 = length(branch2.xy) - 0.0005;

    // 3rd level - needles  
    vec3 branch3 = HelixGrid(branch2.xzy, 9., 0.04, 1.);
    float d3 = length(vec3(branch3.xy, max(0., branch3.z - 0.035))) - 0.0003;

    // Create repeating drop animation
    float dropTime = fract(iTime * .5); 

    // Radius grows as sphere drops: starts small (0.001), grows to big (0.01)
    float sphereR2 = mix(0.001, 0.01, dropTime);

    vec3 spherePos2 = vec3(0, 0.05 + dropTime * 0.12, 0.1);
    float sphere2 = length(branch2 - spherePos2) - sphereR2;

    // Sphere at the tip of each needle
    // Position sphere at z = needleLength (the tip)
    vec3 spherePos = vec3(0, 0.021, 0.025);
    float sphere = length(branch3 - spherePos) - 0.009;

    // Combine needle with sphere at tip
    d3 = min(d3, sphere);
    d2 = min(d2, sphere2);

    // Combine using bounds to clip
    // This makes them shorter as you go up the tree
    float tree = max(
        min(
            min(d2, d3),
            max(d1, bounds - .5)  
        ),
        length(vec3(branch.xy, max(0., bounds - 0.03))) - .35  // Rounded tip
    );

    // ornaments
    vec3 b1 = p;
    b1.xz *= R2(-iTime * 0.105);
    float ornaments = Baubles1(b1);

    // grab the id so we can color later 
    objId = step(tree * 0.7, ornaments); 

    return min(tree * 0.7, ornaments);
}

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    vec3 color = vec3(0.0);

    // setup the ray origin and direction
    vec3 ro = vec3(0,-0.8,1.5);
    vec3 rd = normalize(vec3(uv, -1));

    // distance travel
    float dt = 0.0;

    // Standard raymarching loop
    for(int i = 0; i < 325; i++)
    {
        vec3 p = ro + rd * dt;
        float d = map(p);
        dt += d;

        if(abs(d) < 0.0004 || dt > 20.0) break;
    }

    if(objId > 0.0)
    {
        // Simple depth-based shading 
        color = vec3(1.2 - dt * .47);
    } else {
        // Get the final position where the ray hit
        vec3 p = ro + rd * dt;

        // Generate a unique offset per sphere based on its position
        // Scale factor controls variation
        uint posHash = coord3(uvec3(floor(p * 10.0)));
        // Random phase shift
        float offset = hash1(posHash) * 6.28;  

        // Apply offset to the animation timing
        float fx = sin(iTime * 3.0 + offset) * 0.2 + 0.2;
        color = mix(vec3(1,0,0), vec3(0), 1.32 - dt * .6 + fx);
    }

    O = vec4(color, 1.0);
}

