float map(vec3 p)
{   
    // Cone centered where camera can see it
    float bounds = sdCone(p);

    // 1st level - main branches
    vec3 p1 = p;
    // rotate tree
    p1.xz *= R2(-iTime * 0.105);
    vec3 branch = HelixGrid(p1, 12., 0.5, 0.5);

    // Infinite cylinders 
    float d1 = length(branch.xy) - 0.005;

    // 2nd level - twigs
    vec3 branch2 = HelixGrid(branch.xzy, 7., 0.45, 1.);
    float d2 = length(branch2.xy) - 0.0005;

    // 3rd level - needles  
    vec3 branch3 = HelixGrid(branch2.xzy, 9., 0.04, 1.);
    float d3 = length(vec3(branch3.xy, max(0., branch3.z - 0.035))) - 0.0003;

    // Create repeating drop animation
    float dropTime = fract(iTime * .5); 

    // Radius grows as sphere drops: starts small (0.001), grows to big (0.01)
    float sphereR2 = mix(0.001, 0.01, dropTime);

    vec3 spherePos2 = vec3(0, 0.05 + dropTime * 0.12, 0.1);
    float sphere2 = length(branch2 - spherePos2) - sphereR2;

    // Sphere at the tip of each needle
    // Position sphere at z = needleLength (the tip)
    vec3 spherePos = vec3(0, 0.021, 0.025);
    float sphere = length(branch3 - spherePos) - 0.009;

    // Combine needle with sphere at tip
    d3 = min(d3, sphere);
    d2 = min(d2, sphere2);

    // Combine using bounds to clip
    // This makes them shorter as you go up the tree
    float tree = max(
        min(
            min(d2, d3),
            max(d1, bounds - .5)  
        ),
        length(vec3(branch.xy, max(0., bounds - 0.03))) - .35  // Rounded tip
    );

    // ornaments
    vec3 b1 = p;
    // rotate ornaments
    b1.xz *= R2(-iTime * 0.105);
    float ornaments = Baubles1(b1);

    // Todo: Create gift boxes
    // 1. Lets setup a sdBox 
    // 2. We'll need to create a lid with two boxes 
    //    a. The lid box 
    //    b. A bottom box so we can subtracted from the lid
    // 3. We'll smooth it so the lid with the box 
    float d4 = giftBox(p);
    // Then we'll wanna create some stripes on the boxes 
    // 1. Lets create some sort of grid 
    // 2. We can color it red later 

    // Then lets add some snow to the scene maybe 

    // We also need a star 

    // grab the id so we can color later 
    objId = step(tree * 0.7, ornaments); 

    float treeMain = min(tree * 0.7, ornaments);

    float shape = min(treeMain, d4);

    // Determine which object we hit
    if (shape == d4) {
        objId = 2.0;  // Gift box
    } else if (shape == ornaments) {
        objId = 1.0;  // Ornament
    } else {
        objId = 0.0;  // Tree
    }

    return shape;
}

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    vec3 color = vec3(0.0);

    // setup the ray origin and direction
    vec3 ro = vec3(0,-0.7,2.5);
    vec3 rd = normalize(vec3(uv, -1));

    // distance travel
    float dt = 0.0;

    // Standard raymarching loop
    for(int i = 0; i < 325; i++)
    {
        vec3 p = ro + rd * dt;
        float d = map(p);
        dt += d;

        if(abs(d) < 0.0004 || dt > 20.0) break;
    }

    // Only color if we hit something
    if(dt < 20.0)
    {
        if(objId > 1.5)  // Gift boxes (objId == 2.0)
        {
            // Extract gift ID from stripe variable
            float giftId = floor(stripe * 10.0);
            float isStripe = fract(stripe * 10.0) > 0.5 ? 1.0 : 0.0;

            if(isStripe > 0.5)
            {
                // Gold ribbon with shimmer
                float shimmer = sin(iTime * 2.0 + giftId) * 1.5 + 1.5;
                color = vec3(0.8, 0.6, 0.1) * (0.7 + 0.3 * shimmer);
            }
            else
            {
                // Festive box colors - red, blue, green variations
                vec3 giftColor;
                float colorSelect = mod(giftId, 3.0);

                if(colorSelect < 1.0)
                    giftColor = vec3(0.8, 0.2, 0.2) * 1.2;  // Red
                else if(colorSelect < 2.0)
                    giftColor = vec3(0.2, 0.4, 0.7) * 1.2;  // Blue
                else
                    giftColor = vec3(0.3, 0.7, 0.3) * 1.2;  // Green

                color = giftColor * (1.0 - dt * 0.1);  
            }
        }
        else if(objId > 0.5)  // Ornaments 
        {
            vec3 p = ro + rd * dt;

            // Generate a unique offset per sphere based on its position
            uint posHash = coord3(uvec3(floor(p * 10.0)));
            float offset = hash1(posHash) * 6.28;  

            // Apply offset to the animation timing
            float fx = sin(iTime * 3.0 + offset) * 0.2 + 0.2;
            float fx2 = sin(iTime * 3.0 + offset) * 0.5 + 0.5;
            color = mix(vec3(0,1,fx2), vec3(0), 1.32 - dt * .6 + fx);
        } 
        else  // Tree 
        {

            // Simple depth-based shading 
            color = vec3(1.2 - dt * .3);
        }
    }

    O = vec4(color, 1.0);
}

