                    giftColor = vec3(0.2, 0.4, 0.7) * 1.2;  // Blue
                else
                    giftColor = vec3(0.3, 0.7, 0.3) * 1.2;  // Green

                color = giftColor * (1.0 - dt * 0.1);  
            }
        }
        else if(objId > 0.5)  // Ornaments 
        {
            vec3 p = ro + rd * dt;

            // Generate a unique offset per sphere based on its position
            uint posHash = coord3(uvec3(floor(p * 10.0)));
            float offset = hash1(posHash) * 6.28;  

            // Apply offset to the animation timing
            float fx = sin(iTime * 3.0 + offset) * 0.2 + 0.2;
            float fx2 = sin(iTime * 3.0 + offset) * 0.5 + 0.5;
            color = mix(vec3(0,1,fx2), vec3(0), 1.32 - dt * .6 + fx);
        } 
        else  // Tree 
        {    
            color = vec3(1.2 - dt * .3);  // Tree color
        }
    }

    O = vec4(color, 1.0);
}

