*/

// 2d rotation function
mat2 R2(float a){ return mat2(cos(a), -sin(a), sin(a), cos(a));}
// Palette function for colors
#define Palette(t) (.5 + .5 * sin(6.111 * (t + vec3(0, 1, 2)*1.23)))

float map(vec3 p)
{ 
    // rotate in a planet direction
    p.xy *= R2(iTime * 0.14);

    // SQUARE TUNNEL using Minkowski distance
    vec2 s = vec2(.75, 1.0);
    float power = 7.0;

    float tunnel = dot(pow(abs(p.xy) * s, vec2(power)), vec2(1.0));
    tunnel = pow(tunnel, 1./power);
    tunnel = tunnel - 3.6;

    return tunnel;
}

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    vec3 col = vec3(0.0);

    // setup the ray origin and direction
    vec3 ro = vec3(0, 0, iTime * 2.0);
    vec3 rd = normalize(vec3(uv, -1));

    // distance travel
    float dt = 0.0;

    // Standard raymarching loop
    for(int i = 0; i < 50; i++)
    {
        vec3 p = ro + rd * dt;
        float d = map(p);
        dt += d;

        if(abs(d) < 0.001) break;
    }

    // Get hit position
    vec3 p = ro + rd * dt;

    // Rotate position to match tunnel rotation
    vec3 pRot = p;
    pRot.xy *= R2(iTime * 0.14);

    // Grid parameters and light size
    float grid = 0.5;     
    float lSize = .408;   

    // Calculate grid coordinates along the tunnel
    vec2 gridXY = fract(pRot.xy / grid) - 0.5;
    float gridZ = fract(pRot.z / grid) - 0.5;

    // Create lights on all four walls of the rectangular tunnel
    float lightP = 0.0;

    // Determine which wall we're closest to
    vec2 absXY = abs(pRot.xy);

    // Create grid pattern based on which wall
    if(absXY.x / 0.75 > absXY.y / 1.0) 
    {
        // Left or right wall - lights in Y-Z plane
        vec2 gridPos = vec2(gridXY.y, gridZ);
        float light = length(gridPos);
        lightP = smoothstep(lSize, lSize * 0.5, light);
    } else 
    {
        // Top or bottom wall - lights in X-Z plane
        vec2 gridPos = vec2(gridXY.x, gridZ);
        float light = length(gridPos);
        lightP = smoothstep(lSize, lSize * 0.5, light);
    }

    // Color based on position along the tunnel
    vec3 d1Col = Palette(pRot.z * .5 + atan(pRot.y, pRot.x));

    // Base tunnel color (darker)
    vec3 bgCol = d1Col * 0.2;

    // Light color (bright)
    vec3 lCol = d1Col * 2.0;

    // Combine base and lights
    col = mix(bgCol, lCol, lightP);

    // Add glow around lights
    float glow = lightP * .5;
    col += d1Col * glow * .3;

    // Simple distance-based attenuation (fog)
    float atten = min(1.0 / max(1.0 + dt * 0.25 + dt * dt * 0.05, 0.001), 1.0);
    col *= atten;

    O = vec4(col, 1.0);
}

