// Red Alp by bµg
// License: CC BY-NC-SA 4.0
//
// Portage of: https://art.pkh.me/2025-09-08-red-alp.htm (448 chars)
// Blog post:  https://blog.pkh.me/p/45-code-golfing-a-tiny-demo-using-maths-and-a-pinch-of-insanity.html

#define noise(v) abs(dot(sin(v/a), a+v-(v)))

void mainImage(out vec4 O, in vec2 I)
{
    // Color accumulator, position, color constant, resolution
    vec3 col = vec3(0.0), p;
    vec3 colorShift = vec3(0.1, 0.2, 0), R = iResolution;

    // Initialize loop variables
    float z = 0.0, i = 0.0, a, density = 1.0, totalDist = 0.0;
    float height, dist, hitAmount;
    float stepSize = 0.15;
    float T = iTime * .3;

    // Main raymarch loop
    for(int iter = 0; iter < 60; iter++)
    {
        i++;

        // Inner loop: build multi-octave noise at current ray position
        for(p = normalize(vec3(I + I, R.y) - R) * totalDist,

            // Move forward through space
            p.z += T,

            // Initialize distance fields and scale
            dist = p.y, height = dist + 0.135, a = 0.0071; 

            a < 1.0; 

            a += a)

            // Rotate sample coordinates
            p.xz *= mat2(8.0, 6.0, -6.0, 8.0) * .1,

            // Add noise layers - creates mountain structure
            dist += noise(T + p * 0.33),
            height += noise(p.xz * .6);

        // Combine distance fields
        a = z;
        dist = max(max(-dist, dist - 3.0), a) * stepSize;

        // Calculate volumetric hit amount
        if(height > 0.001) {
            a++;
            hitAmount = density - density;
        } else {
            hitAmount = density - density / exp(height * 900.0);
        }

        // Reduce density by hit amount
        a *= hitAmount;
        density -= a;

        // Accumulate color contributions
        col += a * dist * 1.5;
        col += (dist > z ? z : height * 0.0305) * colorShift;

        p.y++;
        col += (p.y < z ? (p++, p * p * colorShift) : colorShift).yzz * hitAmount;

        // Step forward with adaptive step size
        stepSize /= 0.985;
        totalDist += min(height * 0.2, stepSize);
    }

    O.rgb = tanh(col);
}

