// Portage of: https://art.pkh.me/2025-09-08-red-alp.htm (448 chars)
// Blog post:  https://blog.pkh.me/p/45-code-golfing-a-tiny-demo-using-maths-and-a-pinch-of-insanity.html

// Compact noise function - uses the scale variable 'a' that we pass in.
// Pretty clever trick with the dot product to get pseudo-random values.
#define noise(v) abs(dot(sin(v/a), a+v-(v)))

void mainImage(out vec4 O, in vec2 I)
{
    vec3 col = vec3(0.0), p;

    // Color mountain vibes - 
    vec3 colorShift = vec3(0, 0.3, 0.3); 

    vec3 R = iResolution;

    float z = 0.0, i = 0.0, a, density = 1.0, totalDist = 0.0;

    float height, dist, hitAmount;
    // Starting step - gets bigger as we go
    float stepSize = 0.15; 

    // Slow drift through the scene
    float T = iTime * 0.3; 

    // Main raymarch loop - 60 steps is usually enough to capture the detail
    for(int iter = 0; iter < 60; iter++)
    {
        i++;

        // Set up our ray position. Standard perspective projection stuff.
        p = normalize(vec3(I + I, R.y) - R) * totalDist;

        p.z += T; // Move the whole scene forward over time

        // Start with the basic ground plane height
        dist = p.y;
        height = dist + 0.35; // Offset to position the terrain

        // Multi-octave noise - this is where the magic happens. :)
        // We're layering different frequencies to build up complexity.
        a = 0.0071; // Start small (fine detail)
        while(a < 1.0)
        {
            // Rotate the sample coords - keeps the noise from looking too grid-aligned
            p.xz *= mat2(8.0, 6.0, -6.0, 8.0) * 0.1;

            // Add noise at this octave. Each layer adds more character.
            dist += noise(T + p * 0.33);
            height += noise(p.xz * .86);

            // Double the frequency for the next octave
            a += a;
        }

        // Reset our temp variable
        a = z;
        hitAmount = 0.0; // Initialize to zero - this was the culprit!

        // Figure out if we're hitting terrain or empty space
        if(height < 0.001)
        {
            // We're hitting the mountain!
            // The exp creates a nice sharp falloff as we get closer to the surface
            hitAmount = density - density / exp(height * 900.0);
        }

        // Track how much "stuff" we've hit
        a *= hitAmount;
        density -= a;

        // Build up the color. The ternary picks between sky and terrain contribution.
        col += (dist > z ? z : height * 0.1) * colorShift;

        // Add some depth-based color variation. We shift p.y up a bit, then check
        // if we're below the horizon. If so, square the position for brighter highlights.
        // The .yxx swizzle redistributes the color channels for a nice effect.
        p.y++;
        vec3 depthColor = (p.y < z) ? p * p * colorShift : colorShift;
        col += depthColor.yxx * hitAmount;

        // Adaptive step size - gets bigger as we march forward. Saves iterations
        // when we're far from detail, speeds things up nicely.
        stepSize /= 0.985;
        totalDist += min(height * 0.2, stepSize);
    }

    // tanh keeps everything in a nice range, prevents blown-out colors
    O.rgb = tanh(col);
}

