// 2D rotation matrix. Standard stuff.
mat2 R2(float a){ return mat2(cos(a), -sin(a), sin(a), cos(a));}

// Color palette function. Produces some nice cycling colors.
#define Palette(t) (.5 + .5 * sin(6.111 * (t + vec3(0, 1, 2)*1.23)))

// Hash function: Takes a vec2, spits out a float. Useful for randomness.
float hash21(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// Ray-plane intersection. Pretty straightforward - if the ray hits the plane,
// return the distance, otherwise return something huge so we know to ignore it.
float hitPlane(vec3 ro, vec3 rd, vec3 n, float dist) {
    float denom = dot(rd, n);
    if (denom < 0.0) {
        float t = (-dist - dot(ro, n)) / denom;
        if (t > 0.0) return t;
    }
    return 1e8;
}


void mainImage(out vec4 O, in vec2 I)
{
    // Aspect correct screen coordinates.
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    vec3 col = vec3(0.0);

    // Set up the ray origin and direction. Camera moves forward through time.
    vec3 ro = vec3(0, 0, iTime * .8);
    vec3 rd = normalize(vec3(uv, 1.0));

    // Alpha for blending each bounce. Starts at full opacity.
    float alpha = 1.0;

    // Store the first hit distance so we can apply some fog later.
    float fogDt = 1.0;

    // Three bounces through the tunnel.
    for(int i = 0; i < 2; i++) 
    {    
        // Check all four walls of the tunnel and find which one we hit first.
        vec4 planes;
        planes.x = hitPlane(ro, rd, vec3(0, 1, 0), 1.0);   // bottom
        planes.y = hitPlane(ro, rd, vec3(0, -1, 0), 1.0);  // top
        planes.z = hitPlane(ro, rd, vec3(1, 0, 0), 1.0);   // left
        planes.w = hitPlane(ro, rd, vec3(-1, 0, 0), 1.0);  // right

        // Minimum distance - that's our winner.
        float dt = min(min(planes.x, planes.y), min(planes.z, planes.w));

        // On the first bounce, save the distance for fog calculations.
        if (i == 0) fogDt = dt;

        // Where we hit the wall.
        vec3 p = ro + rd * dt;

        // Figure out which wall we hit, and set up the UVs and normal accordingly.
        vec2 tuv;
        vec3 n;

        if (planes.x < min(planes.y, min(planes.z, planes.w)))
        {
            tuv = p.xz;
            n = vec3(0, 1, 0);
        } else if (planes.y < min(planes.z, planes.w)) 
        {
            tuv = p.xz;
            n = vec3(0, -1, 0);
        } else if (planes.z < planes.w) 
        {
            tuv = p.yz;
            n = vec3(1, 0, 0);
        } else {
            tuv = p.yz;
            n = vec3(-1, 0, 0);
        }

        // Scale and tile the UVs for the reaction-diffusion pattern
        float gridScale = 1.7;
        tuv *= gridScale;

        // Normalize UVs to 0-1 for texture sampling
        vec2 sampleUV = fract(tuv);

        vec4 buf = texture(iChannel0, sampleUV);
        vec3 rdCol = buf.rgb;
        float energy = buf.a;

        // Calculate derivatives for lighting (same as Image tab)
        vec2 uvSize = 1.0 / iResolution.xy;

        float center = max(0.0, length(energy) - 0.1);

        float right = length(texture(iChannel0, sampleUV + vec2(uvSize.x, 0)).a);
        float left  = length(texture(iChannel0, sampleUV - vec2(uvSize.x, 0)).a);
        float up    = length(texture(iChannel0, sampleUV + vec2(0, uvSize.y)).a);
        float down  = length(texture(iChannel0, sampleUV - vec2(0, uvSize.y)).a);

        float dx = right - left;
        float dy = up - down;
        float n_x = max(0.0, dx);
        float m_x = max(0.0, -dx);
        float n_y = max(0.0, dy);
        float m_y = max(0.0, -dy);
        float n_val = (n_x + n_y) * 0.5;
        float m_val = (m_x + m_y) * 0.5;
        n_val *= n_val;
        m_val *= m_val;

        vec3 ambient = vec3(0.208, 0.208, 0.231);
        vec3 L = ambient + 5.0 * vec3(n_val, 0.28 * (n_val + n_val), 5.6 * m_val);
        vec3 layerCol = L * energy * vec3(0.424, 0.157, 0.016) * .257;

        // Add this layer's contribution to the final color
        col += layerCol * alpha * 15.0; // Boosted brightness

        // Reduce alpha for the next bounce
        alpha *= 0.37;

        // Reflect the ray off the wall for the next bounce.
        rd = reflect(rd, n);

        // Move the ray origin to the hit point
        ro = p + n * 0.001;
    }

    // Apply fog
    float fog = 2.35 / (1.0 + fogDt * fogDt * 3.105);
    col *= fog;

    O = vec4(col, 1.0);
}

float T = 0.;

vec2 hash(in vec2 x) 
{
    float t = T ,
          c = cos(t), 
          s = sin(t);
    const vec2 k = vec2(0.3183099, 0.3678794);
    x = x * k + k.yx;
    x = -1. + 2. * fract(16. * k * fract(x.x * x.y * (x.x + x.y)));
    return x * mat2(c, -s, s, c); // flownoise
    //return vec2(cos(t+3.1416*x.x), s = sin(t+3.1416*x.x)); // iq variant
}

vec3 gradNoise(in vec2 p)
{
    vec2 i = floor(p),
         f = fract(p);
#if 1 // quintic interpolation
    vec2 u = f * f * f * (f * (f * 6. - 15.) + 10.),
        du = 30. * f * f * (f * (f - 2.) + 1.);
#else // cubic interpolation
    vec2 u = f * f * (3. - 2. * f),
        du = 6. * f * (1. - f);
#endif    

    vec2 ga = hash(i + vec2(0, 0)),
         gb = hash(i + vec2(1, 0)),
         gc = hash(i + vec2(0, 1)),
         gd = hash(i + vec2(1, 1));

    float va = dot(ga, f - vec2(0, 0)),
          vb = dot(gb, f - vec2(1, 0)),
          vc = dot(gc, f - vec2(0, 1)),
          vd = dot(gd, f - vec2(1, 1));

    return vec3(va + u.x * (vb - va) + u.y * (vc - va) + u.x * u.y * (va - vb - vc + vd),   // value
                ga + u.x * (gb - ga) + u.y * (gc - ga) + u.x * u.y * (ga - gb - gc + gd) +  // derivatives
                du * (u.yx * (va - vb - vc + vd) + vec2(vb, vc) - va));
}

// normalize(grad(noise)) . div of it is nimitz pseudoLaplace noise
#define N(i,j) normalize(gradNoise(scale*(gridSize+.5*vec2(i,j))/64.).yz) // x:noise yz: gradient   

void mainImage(out vec4 O, vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;

    T = iTime;

    uv.x += T * .05;
    vec2 gridSize = uv * iResolution.y * 0.5;  
    float scale = .5; 
    vec3 col = vec3(0);
    vec3 tint = vec3(.2, .7, 1.) * 10.55; 

    for(int i = 0; i < 10; i++)
    {
        scale *= 2.;      
    }  

    col *= 2.;

    vec4 prev = texture(iChannel0, I / iResolution.xy);

    vec2 flow = normalize(gradNoise(uv * 5.0 + T * 0.1).yz) * .55;
    float flowS = length( gradNoise(uv * 5.0).yz + flow / scale );
    flowS += length( gradNoise(uv * 3.).yz + flow / (scale * 0.5) ) * 2.5; 

    O = vec4(col, flowS);
}

