float noise( in vec3 x )
{
    vec3 i = floor(x);
    vec3 f = fract(x);
    f = f*f*(3.0-2.0*f);
    vec2 uv = (i.xy+vec2(37.0,17.0)*i.z) + f.xy;
    vec2 rg = textureLod( iChannel0, (uv+0.5)/256.0, 0.0 ).yx;
    return mix( rg.x, rg.y, f.z );
}

float mapTerrain( vec3 p )
{
    p *= 0.1; 
    p.xz *= 0.6;

    float f;
    f  = 0.5000*noise( p*1.00 );
    f += 0.2500*noise( p*2.02 );
    f += 0.1250*noise( p*4.01 );
    return 25.0*f-10.0;
}

float map(in vec3 c) 
{
    vec3 p = c + 0.5;
    float f = mapTerrain( p ) + 0.25*p.y;
    return step( f, 0.5 );
}

float raycast( in vec3 ro, in vec3 rd, out vec3 oVos, out vec3 oDir )
{
    vec3 pos = floor(ro);
    vec3 ri = 1.0/rd;
    vec3 rs = sign(rd);
    vec3 dis = (pos-ro + 0.5 + rs*0.5) * ri;

    float res = -1.0;
    vec3 mm = vec3(0.0);

    for( int i=0; i<128; i++ ) 
    {
        if( map(pos)>0.5 ) { res=1.0; break; }

        // DDA step
        mm = step(dis.xyz, dis.yzx) * step(dis.xyz, dis.zxy);
        dis += mm * rs * ri;
        pos += mm * rs;
    }

    vec3 nor = -mm*rs;
    vec3 vos = pos;

    // intersect the cube
    vec3 mini = (pos-ro + 0.5 - 0.5*vec3(rs))*ri;
    float t = max( mini.x, max( mini.y, mini.z ) );

    oDir = mm;
    oVos = vos;

    return t*res;
}

void mainImage( out vec4 O, in vec2 I )
{
    vec2 p = (2.0*I-iResolution.xy)/iResolution.y;

    // simple camera
    vec3 ro = vec3(iTime+0.0, 10.0, 0);
    vec3 rd = normalize( vec3(p, -2.0) );

    vec3 vos, dir;
    float t = raycast( ro, rd, vos, dir );

    vec3 col = vec3(0.0);

    if( t > 0.0 )
    {
        vec3 pos = ro + rd*t;
        vec3 uvw = pos - vos;

        // grid lines on voxel faces
        vec3 grid = smoothstep( -1., 1., abs(fract(uvw)-.5)/fwidth(uvw) );
        float gridPattern = grid.x * grid.y * grid.z;

        col = vec3(0.5 + 0.5*gridPattern);
    }

    O = vec4( col, 1.0 );
}

