// iq https://iquilezles.org/articles/distfunctions/
float sdCapsule( vec3 p, vec3 a, vec3 b, float r )
{
  vec3 pa = p - a, ba = b - a;
  float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
  return length( pa - ba*h ) - r;
}

// iq https://iquilezles.org/articles/distfunctions/
float sdEllipsoid( vec3 p, vec3 r )
{
  float k0 = length(p/r);
  float k1 = length(p/(r*r));
  return k0*(k0-1.0)/k1;
}

float sdSphere(vec3 p, float r)
{
    return length(p) - r;
}

float shape(vec3 p0, float height, float rotate)
{
    // Rotate around the base of the capsule (at y = -1)
    vec3 p = p0;
    p.xz *= R2(rotate);
    // capsules 
    vec3 p1 = p;
    float d = sdCapsule(p1, vec3(0,-1,0), vec3(0,height,0), 0.1 );

    // ellipse 
    vec3 p2 = p + vec3(0,-0.8 - (height - 0.5),-0.3);
    float d1 = sdEllipsoid(p2 , vec3(0.5, 0.5, 0.4));

    // subtract the sphere with the ellipse
    vec3 p3 = p + vec3(0.1,-0.8 - (height - 0.5),-0.6);
    float d2 = sdSphere(p3, 0.3);

    return max(-d2, min(d,d1));
}

float map(vec3 p)
{ 
    // repetition for the capsules
    vec3 p0 = p;
    p0 = vec3(mod(p.x, 3.) - 3. * 0.5, p.y,
