// harmonics
float sdSphericalHarmonic(vec3 p, int m) {
    float d = length(p);
    vec3 n = p / max(d, 0.001);

    float theta = acos(clamp(n.y, -1.0, 1.0));
    float phi = atan(n.z, n.x);

    // Legendre polynomials
    float Y = cos(float(m) * phi) * pow(sin(theta), float(abs(m)));

    return d - abs(Y) * 1.5;
}

float sdSphericalHarmonic(vec3 p, int l, int m) {
    float d = length(p);
    vec3 n = p / max(d, 0.001);

    float theta = acos(clamp(n.y, -1.0, 1.0));
    float phi = atan(n.z, n.x);

    // Simplified spherical harmonic approximation
    float Y = cos(float(m) * phi) 
            * pow(sin(theta), float(abs(m)))
            * cos(float(l) * theta);

    return d - abs(Y) * 1.;
}

float map(vec3 p) {
