#define T iTime

mat2 R2(float a) { return mat2(cos(a), -sin(a), sin(a), cos(a));}

// https://iquilezles.org/articles/distfunctions/
float sdCapsule( vec3 p, vec3 a, vec3 b, float r )
{
  vec3 pa = p - a, ba = b - a;
  float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
  return length( pa - ba*h ) - r;
}

// https://iquilezles.org/articles/distfunctions/
float smin( float d1, float d2, float k )
{
    k *= 4.0;
    float h = max(k-abs(d1-d2),0.0);
    return min(d1, d2) - h*h*0.25/k;
}

// https://iquilezles.org/articles/distfunctions/
float sdEllipsoid( vec3 p, vec3 r )
{
  float k0 = length(p/r);
  float k1 = length(p/(r*r));
  return k0*(k0-1.0)/k1;
}

// ehh should have used ellipse this is the first one made
float sdEighthNote(vec3 p)
{
    p.xz *= R2(iTime);
    // Sphere left 
    vec3 a = vec3(0.6, 0,0);
    float r = 0.3;
    vec3 r2 = vec3(0.3,0.2,0.2);
    float d1 = sdEllipsoid(p + a, r2);
    // dot right
    float d2 = sdEllipsoid(p - a, r2);

    // left line
    vec3 a1 = vec3(0,0.6,0);
    float r1 = 0.1;
    vec3 b = vec3(a.x - r /1.7,-0.6,0);
    float d3 = sdCapsule(p + b, a1, -a1, r1);

    // right line
    vec3 a3 = vec3(0,0.4,0);
    vec3 b1 = vec3(-a.x - r /1.7,-0.55,0);
    float d6 = sdCapsule(p + b1, a1, -a3, r1);

    // top line
    vec3 a2 = vec3(0.5,0,0);
    vec3 b3 = vec3(0.2,1.2,0);
    float d5 = sdCapsule(p - b3, a2, -a2, r1);

    float shape = 1e10;

    shape = min(d1, d2);
    shape = smin(shape, d3, 0.01);
    shape = smin(shape, d6, 0.01);
    shape = smin(shape, d5, 0.03);

    return shape;
}

// 2nd one 

float sdSixteenNote(vec3 p)
{
    p.xz *= R2(iTime);
    // Sphere left 
    vec3 a = vec3(0.6, 0.6,0);
    vec3 a4 = vec3(a.x, -0.3,0);
    float r = 0.3;
    vec3 r2 = vec3(0.3,0.2,0.2);
    float d1 = sdEllipsoid(p + a + vec3(0.05,0,0), r2);
    // dot right
    float d2 = sdEllipsoid(p - a4, r2);

    // left line
    vec3 a1 = vec3(0,0.9,0);
    float r1 = 0.1;
    vec3 b = vec3(a.x - r /2.,-0.3,0);
    float d3 = sdCapsule(p + b, a1, -a1, r1);

    // right line
    vec3 a5 = vec3(0,0.9,0);
    vec3 b1 = vec3(-a.x - r /2.,-0.56,0);
    float d6 = sdCapsule(p + b1, a5, -a5, r1);

    // top line
    vec3 a2 = vec3(0.5,0.15,0);
    vec3 b3 = vec3(0.2,1.4,0);
    float d5 = sdCapsule(p - b3, a2, -a2, r1);

    // top middle line
    vec3 b4 = vec3(b3.x,1.,0);
    float d7 = sdCapsule(p - b4, a2, -a2, r1);

    // top bottom line
    vec3 b5 = vec3(b3.x,b4.y - .4,0);
    float d8 = sdCapsule(p - b5, a2, -a2, r1);

    float shape = 1e10;

    shape = min(d1, d2);
    shape = smin(shape, d3, 0.01);
    shape = smin(shape, d6, 0.01);
    shape = smin(shape, d5, 0.03);
    shape = smin(shape, d6, 0.01);
    shape = smin(shape, d7, 0.01);
    shape = smin(shape, d8, 0.01);

    return shape;
}

float map(vec3 p) 
{
    vec3 a = vec3(1.6,0,0);
    float d0 = sdEighthNote(p + a);
    float d1 = sdSixteenNote(p - a);
    return min(d0,d1);
}

