    float dt = rayMarch(ro, rd); 

    if(dt > 0.)
    {
        vec3 p = ro + rd * dt; 
        vec3 norm = calcNorm(p);

        col += norm * 0.5 + 0.5;

        // colors
        col += (1. + cos(1. + vec3(0,1,1))) / dt * vec3(0,0.3,0.3) * 1.;
    }

    // Dark background 'fog'
    col = mix(col, vec3(0), 1.0 - exp(-0.009 * dt * dt * dt));

    // vignette
    //col = mix(vec3(0), col, smoothstep(2.5, .1, length(uv * vec2(1.4,1) )));

    O = vec4(col, 1.0);
}

