*/
mat2 R2(float a) { return mat2(cos(a), -sin(a), sin(a), cos(a));}

// Hash for procedural detail
float hash(vec3 p) {
    p = fract(p * 0.3183099 + .1);
    p *= 17.0;
    return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
}

// noise for layering
float noise(vec3 p) {
    vec3 i = floor(p);
    vec3 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);

    return mix(mix(mix(hash(i + vec3(0,0,0)), hash(i + vec3(1,0,0)), f.x),
                   mix(hash(i + vec3(0,1,0)), hash(i + vec3(1,1,0)), f.x), f.y),
               mix(mix(hash(i + vec3(0,0,1)), hash(i + vec3(1,0,1)), f.x),
                   mix(hash(i + vec3(0,1,1)), hash(i + vec3(1,1,1)), f.x), f.y), f.z);
}

// Fractal Brownian Motion for detail layers
float fbm(vec3 p) {
    float value = 0.0;
    float amplitude = 0.5;
    float frequency = 1.0;

    for(int i = min(iFrame,0); i < 4; i++) {
        value += amplitude * noise(p * frequency);
        frequency *= 2.0;
        amplitude *= 0.5;
    }
    return value;
}

// Tri-planar with texture derivatives
vec3 tex3D(sampler2D tex, in vec3 p, in vec3 n) {
    n = max(n*n, 0.001);
    n /= (n.x + n.y + n.z);  

    return (texture(tex, p.yz)*n.x + 
            texture(tex, p.zx)*n.y + 
            texture(tex, p.xy)*n.z).xyz;
}

vec3 domainWarp(vec3 p, float time) {
    vec3 q = vec3(
        fbm(p + vec3(0.0, 0.0, time * 0.1)),
        fbm(p + vec3(5.2, 1.3, time * 0.1)),
        fbm(p + vec3(1.7, 9.2, time * 0.1))
    );

    vec3 r = vec3(
        fbm(p + 4.0 * q + vec3(1.7, 9.2, time * 0.15)),
        fbm(p + 4.0 * q + vec3(8.3, 2.8, time * 0.15)),
        fbm(p + 4.0 * q + vec3(3.1, 6.7, time * 0.15))
    );

    return p + r * 0.15;
}

float map(vec3 p) {
    vec3 n = vec3(0, 0, 1);

    // Multi-layer breathing distortion
    float breathe = sin(iTime * 0.5) * 0.5 + 0.5;
    p.xy += sin(p.xy * 3. + cos(p.yx * 13. + iTime)) * (0.031 + breathe * 0.02);

    // Apply domain warping
    vec3 warpedP = domainWarp(p, iTime);

    // Multi-scale displacement with texture
    float disp = tex3D(iChannel0, warpedP * 0.4, n).x;
    float detailDisp = tex3D(iChannel0, warpedP * 2.5, n).y * 0.3;


    return 1. - p.z - (disp * 0.15 + detailDisp * 0.05);
}

vec3 calcNorm(vec3 p) {
    vec2 e = vec2(0.001, 0);
    return normalize(vec3(
        map(p + e.xyy) - map(p - e.xyy),
        map(p + e.yxy) - map(p - e.yxy),
        map(p + e.yyx) - map(p - e.yyx)
    ));
}

float rayMarch(vec3 ro, vec3 rd) {
    float t = 0.;
    for(int i = 0; i < 2; i++) {
        float d = map(ro + rd * t);                    
        if(d < 0.001) break;
        t += d * 1.;
    }
    return t;
}

void mainImage(out vec4 O, in vec2 I) {
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    vec3 col = vec3(0);

    vec3 ro = vec3(iTime * 0.1, 0, 0);
    vec3 rd = normalize(vec3(uv, 1.5));

    float t = rayMarch(ro, rd); 

    if(t < 20.) {
        vec3 p = ro + rd * t; 
        vec3 norm = calcNorm(p);

        // Warp texture coordinates for more organic look
        vec3 warpedP = domainWarp(p, iTime);

        // Multi-scale texture sampling with chromatic offset
        vec3 texColor1 = tex3D(iChannel0, warpedP * 1.5 + iTime * 0.036, norm);
        vec3 texColor2 = tex3D(iChannel0, warpedP * 3.0 - iTime * 0.02, norm) * 0.5;

        // Chromatic aberration effect
        float r = tex3D(iChannel0, warpedP * 1.5 + vec3(0.01, 5, 0) + iTime * 0.036, norm).r;
        float g = tex3D(iChannel0, warpedP * 1.5 + iTime * 0.036, norm).g;
        float b = tex3D(iChannel0, warpedP * 1.5 + vec3(-0.01, 0.5, 0) + iTime * 0.036, norm).b;

        vec3 chromaticTex = vec3(r, g, b) * 3.5;

        // Procedural detail overlay
        float detail = fbm(p * 5.0 + iTime * 0.2);

        // Fresnel effect for edge highlighting
        float fresnel = pow(1.0 - max(dot(norm, -rd), 0.0), 12.0);

        // Combine layers
        vec3 baseColor = mix(texColor1, chromaticTex, 0.3) + texColor2;
        baseColor = mix(baseColor, vec3(detail), 0.15);

        // Enhanced lighting
        vec3 lightDir = normalize(vec3(0.5, 1, -1));
        float diffuse = max(dot(norm, lightDir), 0.0);
        float specular = pow(max(dot(reflect(lightDir, norm), rd), 0.0), 32.0);

        // Final color composition
        col = baseColor * (norm * 0.3 + 0.7) * (diffuse * 0.8 + 0.2);
        col += vec3(fresnel * 0.8);
        col += vec3(specular * 0.5);

        // Subtle color grading
        col = pow(col, vec3(0.9));
        col = mix(col, vec3(dot(col, vec3(0.299, 0.587, 0.114))), -0.1);
    }

    O = vec4(col, 1.0);
}

