void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    vec3 col = vec3(0);

    // Ray direction and origin
    vec3 ro = vec3(4, 3, -iTime * 0.5);
    vec3 rd = normalize(vec3(uv * 1., -1));
    float dt = rayMarch(ro, rd); 

   if(dt > 0.)
    {
        vec3 p = ro + rd * dt; 
        vec3 norm = calcNorm(p);

        float scale = 2.0;
        float texOffset = 0.01;

        // Sample texture and gradients using tex3D
        vec3 tex = tex3D(iChannel0, p * scale, norm);
        vec3 texX = tex3D(iChannel0, (p + vec3(texOffset, 0, 0)) * scale, norm);
        vec3 texY = tex3D(iChannel0, (p + vec3(0, texOffset, 0)) * scale, norm);

        // Compute texture gradient
        vec2 texGrad = vec2(texX.r - tex.r, texY.r - tex.r) / texOffset;

        // Perturb normal
        vec3 bump = normalize(norm + vec3(texGrad * 0.3, 0));

        // Light setup
        vec3 lightPos = vec3(sin(iTime) * 1.0, 5.0, -iTime * 0.5 + 2.0);
        vec3 L = normalize(lightPos - p);

        // Lighting terms
        float diff = max(dot(bump, L), 0.0);
        float fre  = pow(1.0 - abs(dot(bump, rd)), 3.0);
        vec3  hal  = normalize(L - rd);
        float spec = pow(max(dot(bump, hal), 0.0), 32.0);

        // Base color
        vec3 baseCol = (3. + cos(4. + vec3(0,4,4))) / dt * vec3(0,0.5,0.2);

        // Combine lighting
        col = baseCol * (diff * 0.7 + 0.3);  // diffuse with ambient
        col += vec3(0.4, 0.6, 1.0) * spec * 1.5;  // specular highlight
        col += vec3(0.2, 0.4, 0.6) * fre * 1.4;   // fresnel rim light
    }

    // Dark background 'fog'
    col = mix(col, vec3(0), 1.0 - exp(-0.0019 * dt * dt * dt));

    // vignette
    col = mix(vec3(0), col, smoothstep(3.9, .1, length(uv * vec2(1.4,1) )));

    O = vec4(col, 1.0);
}

