float cositas(vec3 p0, float height, float rotate, float r2)
{
    vec3 p = p0;
    p.xz *= R2(rotate);

    // ellipse 
    vec3 p2 = p + vec3(0,-0.8 - (height - 0.5),-0.3);
    float d1 = sdEllipsoid(p2 , vec3(0.44 - r2, 0.6 - r2, 0.5 - r2));

    // subtract the sphere with the ellipse
    vec3 p3 = p + vec3(0.1,-0.8 - (height - 0.5),-0.5);
    float d2 = sdSphere(p3, 0.3);

    return max(-d2,d1);
}

