        vec3 chargeCol = vec3(0.6) * col * 0.1 / (.01061 + hi * hi * .02);
        col += mix(chargeCol.yxz, chargeCol,  col);


        // colors
        col += (1. + cos(1. + vec3(0,3,3))) / dt * vec3(0,2.3,3.9) * 1.;
    }

    // Dark background 'fog'
    col = mix(col, vec3(0), 1.0 - exp(-0.00029 * dt * dt * dt));

    // vignette
    col = mix(vec3(0), col, smoothstep(4., .1, length(uv * vec2(1.4,1) )));

    O = vec4(col, 1.0);
}

