mat2 R2(float a) { return mat2(cos(a), -sin(a), sin(a), cos(a));}

// iq https://iquilezles.org/articles/distfunctions/
float sdEllipsoid( vec3 p, vec3 r )
{
  float k0 = length(p/r);
  float k1 = length(p/(r*r));
  return k0*(k0-1.0)/k1;
}

float smin( float d1, float d2, float k )
{
    k *= 4.0;
    float h = max(k-abs(d1-d2),0.0);
    return min(d1, d2) - h*h*0.25/k;
}

float sdSphere(vec3 p, float r)
{
    return length(p) - r;
}

float cositas(vec3 p0, float height, float rotate, float r2)
{
    vec3 p = p0;
    p.xz *= R2(rotate);

    // ellipse 
    vec3 p2 = p + vec3(0,-0.8 - (height - 0.5),-0.3);
    float d1 = sdEllipsoid(p2 , vec3(0.44 - r2, 0.6 - r2, 0.5 - r2));

    // subtract the sphere with the ellipse
    vec3 p3 = p + vec3(0.1,-0.8 - (height - 0.5),-0.5);
    float d2 = sdSphere(p3, 0.3);

    return max(-d2,d1);
}

float cositas2(vec3 p0, float height, float rotate, float r2, float fade)
{
    vec3 p = p0;
    p.xz *= R2(rotate);

    // ellipse 
    vec3 p2 = p + vec3(0,-0.8 - (height - 0.5),-0.3);
    float d1 = sdEllipsoid(p2 , vec3(0.44 - r2, 0.6 - r2, 0.5 - r2));

    // subtract the sphere with the ellipse
    vec3 p3 = p + vec3(0.1,-0.8 - (height - 0.5),-0.5);
    // bubble fx 
    float fx = sin(fade * 2.14159) * 0.15;
    float d2 = sdSphere(p3, fx);

    return d2;
    return max(-d2,d1);
}

float map(vec3 p)
{ 
    // repetition for the capsules
    vec3 p0 = p;
    p0 = vec3(mod(p.x, 4.) - 4. * 0.5, p.y,
        mod(p.z, 2.) - 1. * 0.5);

    // move the thing around
    p0.xz *= R2(iTime * .1);

    // plane
    float d3 = p.y + 1.0;

    float shape = 1e10;

    float d = cositas(p0, 0.4,0.3, 0.);

    float d1;

    float fx = mod(-iTime, 2.);
    for(int i=0; i<10; i++)
    {
        float f = float(i);
        d = cositas(p0, f * 0.5,1.1 * f, f * 0.06);
        d1 = cositas2(p0 + vec3(0,fx,0), f * 0.5,1.9 * f, f * 0.06, fx);

        shape = smin(shape, d, 0.113);
        // bubble layer
        shape = smin(shape, d1, 0.06);
    }

    return shape;
    return min(shape, d3);
}

// simple normal 
vec3 calcNorm(vec3 p)
{
    float e = 0.051;
    return normalize(vec3(
