// Basic raymarch
float rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.;
    for(int i=0; i< 70; i++)
    {
        vec3 p = ro + rd * dt; 
        float d = map(p);                    
        dt += d;                             
        if(abs(d) < 0.001 || dt > 20.0) break;
    }
    return dt;
}

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    vec3 col = vec3(0);
    //uv *= R2(iTime * 0.2);

    // Ray direction and origin
    vec3 ro = vec3(0, 3, -iTime * 0.2);

    vec3 rd = normalize(vec3(uv * 1., -1));
    float dt = rayMarch(ro, rd); 

    if(dt > 0.)
    {
        vec3 p = ro + rd * dt; 
        vec3 norm = calcNorm(p);

        //col += norm * 0.5 + 0.5;
         vec3 lp = vec3(ro.x, ro.y, ro.z - 2.); // Negated X, ahead in Z

        // Light direction from surface to light
        vec3 L = lp - p;
        float lDist = max(length(L), .0001);
        L /= lDist; // Normalize


        // we get the diffuse
        float diff = max(dot(norm, L), 0.0);
        diff = pow(diff, 4.)*0.66 + pow(diff, 8.)*0.34;

        float spec = pow(max(dot(reflect(rd, norm), L), 0.), 8.);

        float fre = pow(clamp(dot(rd, norm) + 1., 0., 1.), 4.);

       // float lDist = max(length(L), .0001);

        float atten = 1./(1. + lDist*.9125 + lDist*lDist*.025);

        // colors
        //col = (1. + cos(clamp(0.,3.,(p.z)) * clamp(0.,1.,(p.x * 1.)) * vec3(0,5,5) + 2.9)) / dt * vec3(3,2,6);
        vec3 bgCol = (1. + cos(4. + vec3(1,1,1))) / dt * vec3(0,1,2) * 2.3;

        col = bgCol * (diff * 3.1 + .3);
        col += vec3(0.886,0.267,0.933)*fre*5.;
        col *= atten;
        col += spec * 1.;        
        // colors
        //col += (1. + cos(4. + vec3(0,4,4))) / dt * vec3(1,1,1) * 2.;
    }

    // Dark background 'fog'
    col = mix(col, vec3(0), 1.0 - exp(-0.0019 * dt * dt * dt));

    // vignette
    col = mix(vec3(0), col, smoothstep(3., .1, length(uv * vec2(1.4,1) )));

    O = vec4(col, 1.0);
}

