    float l = 10.1;
    if (i == 0) return vec3(0, 0, 0);
    if (i == 1) return vec3(0, 0, l);
    if (i == 2) return vec3(l, 0, l);
    if (i == 3) return vec3(l, 0, 0);
    return vec3(0, 0, 0);
}

vec3 camPath(float t) {
    const int aNum = 4;
    t = fract(t / float(aNum)) * float(aNum);

    int seg = int(floor(t));
    float st = fract(t);

    // Wrap indices manually
    int i0 = seg == 0 ? 3 : seg - 1;
    int i1 = seg;
    int i2 = seg == 3 ? 0 : seg + 1;
    int i3 = (seg + 2) >= 4 ? (seg + 2 - 4) : seg + 2;

    return catmull(getPoint(i0), getPoint(i1), getPoint(i2), getPoint(i3), st);
}


