mat2 R2(float a) { return mat2(cos(a), -sin(a), sin(a), cos(a));}


float map(vec3 p)
{ 
    // I wanna flip it to see the rails looking thing
    p.xz *= R2(1.57); 
    p.y += 0.8;

    //p.xz *= anglePath(p);
    // Repete for the spheres on the choo choo thing inside 
    vec3 newP = p;
    newP.y += 0.2;
    newP = vec3( mod(newP.x + .0, 0.5) - 0.22, 
                 mod(newP.y + .4, 1.53) - 0.6,  
                 mod(newP.z + .2, 0.5) - .2);
    float d1 = length(newP) - .1;

    // 2nd circle grid for the choo choo looking things outside
    vec3 p4 = p;
    p4.y += 0.12;
    p4.z += 0.24;
    p4 = vec3( mod(p4.x + .0, 0.5) - 0.22, 
               mod(p4.y + .45, 1.68) - 0.5,  
               mod(p4.z + .2, 0.5) - .2);
    float d2 = length(p4) - .1;

    // 3nd circle grid for the choo choo looking things 
    vec3 p5 = p;
    p5.z -= 0.4;
    p5.x -= 0.3;
    p5 = vec3( mod(p5.x + .0, 0.5) - 0.22, 
               mod(p5.y + .45, 1.33) - 0.5,  
               mod(p5.z + .2, 2.3) - .2);
    float d4 = length(p5) - .2;

    // 4nd Lattice for subtraction and to play around with
    vec3 p6 = p;
    vec3 p3 = vec3( mod(p6.x + .0, 1.5) - 1.5 * 0.5,  
                    mod(p6.y + 1.03, 2.5) - 2.6 * 0.5,  
                    mod(p6.z + .50, 2.3) - 2.3 * 0.5);

    float d3 = min(
        length(p3.yz) - 0.28,  
        min(
            length(p3.xz) - 0.108, 
            length(p3.xy) - 0.08 
        )
    );

    // final sdf, I wanna keep adding into it seems to bring new shapes 
    // return d3;
    //return min(d4, d3);
    return max(max(max(-d1, -d2), -d4), d3);
}

vec3 calcNormal(vec3 p)
{
    float e = 0.1;
    return normalize(vec3(
        map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
        map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
        map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
    ));
}


float hash21(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec3 p) {
    vec3 i = floor(p);
    vec3 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);

    return mix(mix(hash21(i.xy), hash21(i.xy + vec2(1,0)), f.x),
               mix(hash21(i.xy + vec2(0,1)), hash21(i.xy + vec2(1,1)), f.x), f.y);
}


