▓  Camera from @Shane
▓  https://www.shadertoy.com/view/4s3SRN
*/


vec3 catmull(vec3 p0, vec3 p1, vec3 p2, vec3 p3, float t) {
    return 0.5 * ((2.0 * p1) + 
                  (-p0 + p2) * t +
                  (2.0*p0 - 5.0*p1 + 4.0*p2 - p3) * t*t +
                  (-p0 + 3.0*p1 - 3.0*p2 + p3) * t*t*t);
}

vec3 getPoint(int i) 
{
    // Define points inline instead of array
    float l = 10.5;
    float h = 5.;
    if (i == 0) return vec3(-0, -.3, -.1);
    if (i == 1) return vec3(0, l, l+.08);
    if (i == 2) return vec3(l, h-.1, l-.12);
    if (i == 3) return vec3(l, -h+.5, -.07);
    return vec3(0, 0, 0);
}


vec3 camPath(float t) {
    const int aNum = 4;
    t = fract(t / float(aNum)) * float(aNum);

    int seg = int(floor(t));
    float st = fract(t);

    // Wrap indices manually
    int i0 = seg == 0 ? 3 : seg - 1;
    int i1 = seg;
    int i2 = seg == 3 ? 0 : seg + 1;
    int i3 = (seg + 2) >= 4 ? (seg + 2 - 4) : seg + 2;

    return catmull(getPoint(i0), getPoint(i1), getPoint(i2), getPoint(i3), st);
}


void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    vec3 col = vec3(0);
    //uv *= R2(iTime * 0.2);
    //uv *= R2(1.57);

    float speed = iTime * 0.1;
    vec3 ro = camPath(speed);
    vec3 lookAt = camPath(speed + .3); // Look ahead

    vec3 fwd = normalize(lookAt - ro);
    vec3 rgt = normalize(cross(vec3(0, 1, 0), fwd));
    vec3 up = cross(fwd, rgt);

    vec3 rd = normalize(fwd + uv.x * rgt + uv.y * up);

    float dt = 0.0; 

    // Saving position to use it later
    vec3 p;
    // basic raymarch
    for(int i=0; i< 80; i++)
    {
        p = ro + rd * dt; 
        //p = camPath(p);
        float d = map(p);                    
        if(abs(d)<.001*(dt*.125 + 1.) || dt>20.) break;
        dt += d;                             
    }

    vec3 lp = vec3(ro.x, ro.y, ro.z + 1.);

    vec3 L = lp - p;
    float lDist = max(length(L), .0001);
    L /= lDist;
    vec3 norm = calcNormal(p);

    // Surface texture (Shane's tri-planar code)
    float tex = noise(p * 30.0) * 1.5 + noise(p * 10.0) * 0.25;
    tex = tex * .15 + .85; 

    float diff = max(dot(norm, L), 0.0);
    diff = pow(diff, 4.)*0.66 + pow(diff, 8.)*0.34;

    float spec = pow(max(dot(reflect(-L, norm), -rd), 0.), 16.); 

    float fre = pow(clamp(dot(rd, norm) + 1., 0., 1.), 4.);
    float atten = 1./(1. + lDist*.9125 + lDist*lDist*.025);

    vec3 bgCol = (1. + cos(0. + vec3(0.6))) / dt * vec3(0.9) * .6;

    col = bgCol * (diff * 2.1 + .3) * tex; 
    col += vec3(0.886,0.235,0.235)*fre*1.5;
    col *= atten;
    col += spec * 2.;
    // colors
    //col = (1. + cos(clamp(0.,4.,(p.z)) * clamp(0.,4.,(p.x * 1.)) * vec3(0,5,5) + iTime * 2.)) / dt * vec3(3,2,6);

    // Dark background 'fog'
    col = mix(col, vec3(0), 1.0 - exp(-0.019 * dt * dt * dt));

    // vignette
    col = mix(vec3(0), col, smoothstep(3.9, .1, length(uv * vec2(.2,1.) )));

    O = vec4(col, 1.0);
}

