mat2 R2(float a) { return mat2(cos(a), -sin(a), sin(a), cos(a));}

// Helix from @Fabrice
// https://www.shadertoy.com/view/4sdBW8
float sdHelix(vec3 p)
{
    float len = length(p.xy);
    float a = sin(atan(p.y, p.x) - p.z * .5); 

    // Double spring distance field
    return length(vec2(len - 2.5, a)) - .345;
}

// iq
float smin( float d1, float d2, float k )
{
    k *= 4.0;
    float h = max(k-abs(d1-d2),0.0);
    return min(d1, d2) - h*h*0.25/k;
}

// iq
float smax( float d1, float d2, float k )
{
    return -smin(d1,-d2,k);
}

// Helix path by @Fabrice
// https://www.shadertoy.com/view/XdtfW8
float sdHelixOfSpheres(vec3 p)
{
    p += vec3(-2.5,-2.5,1.6 + iTime * 0.0);
    float len   = length(p.xy);
    float angle = atan(p.y, p.x);  
    float dist  = angle - p.z * 0.5;

    float v = abs( mod(dist  ,6.28) -3.14);
    dist = v;//min(v, abs( mod(dist -A,6.28) -3.14));

    float n = 3.14;            // spheres per rotation
    float helixRadius = 2.5;  // radius of helix

    vec3 spherePos = vec3(
        len - helixRadius,           // radial offset to helix
        dist,                        // perpendicular to helix path
        fract(n * angle) - 0.5       // periodic spacing along helix
    );

    return length(spherePos) -0.1;  
}
float sdHelixOfSpheres2(vec3 p)
{
    p += vec3(-2.5,-2.5,1.6 + iTime * 0.0);
    float len   = length(p.xy);
    float angle = atan(p.y, p.x);  
    float dist  = angle - p.z * 0.5;

    float v = abs( mod(dist  ,6.28) -3.14);
    dist = v;//min(v, abs( mod(dist -A,6.28) -3.14));

    float n = 3.14;            // spheres per rotation
    float helixRadius = 2.5;  // radius of helix

    vec3 spherePos = vec3(
        len - helixRadius,           // radial offset to helix
        0.0,                        // perpendicular to helix path
        fract(n * angle) - 0.5       // periodic spacing along helix
    );

    return length(spherePos) -0.1;  
}

float map(vec3 p) 
{
    // now lets brin the spheres in a shape of a helix 
    // I did that on a pass shader

    vec3 p0 = vec3( mod( p.x, 7.) - 7. * 0.5, 
    mod( p.y, 7.) - 7. * 0.5, 
    p.z);

    p0.y += sin(p.x * 2.  + iTime * 2.0) * 0.1;
    p0.z += sin(p.x * 2.  + iTime * 2.5) * 0.1;

    // Helix math 
    float d = sdHelix(p0);

    // helix 2 
    vec3 p1 = p + vec3(1,1,0);
    p1 = vec3( mod( p1.x, 7.) - 7. * 0.5, 
    mod( p1.y, 7.) - 7. * 0.5, 
    p.z);

    p1.z += sin(p1.y * 3.  + iTime * 1.5) * 0.1;
    p1.z += sin(p1.x * 1.  + iTime * 2.5) * 0.2;

    float d1 = sdHelix(p1);

    vec3 p2 = p;

    p2.z += sin(p2.y * 1.  + iTime * 1.5) * 0.1;
    p2.z += sin(p2.x * 1.  + iTime * 2.5) * 0.2;


    vec3 p3 = p;

    p3.z += sin(p2.y * 2.  + iTime * 1.5) * .5;
    p3.z += sin(p2.x * 3.  + iTime * 2.5) * 0.5;

    p3.z += iTime * 2.;


    float d10 = sdHelixOfSpheres(p2 + vec3(-.8,-1.56,4.5));
    float d11 = sdHelixOfSpheres(p2 + vec3(-1.,-1.6,-1.6));

    float d3 = sdHelixOfSpheres(p2 + vec3(-1.6,-1,-1.5));
    float d4 = sdHelixOfSpheres(p2 + vec3(-1.6,-1,4.5));
    float d5 = sdHelixOfSpheres(p2 + vec3(-0.9,-1.,-2.3));

    float d6 = sdHelixOfSpheres(p3 + vec3(-1.4,0.1,-3.9));
    float d7 = sdHelixOfSpheres(p3 + vec3(-2.7,0.1,2.9));
    float d8 = sdHelixOfSpheres(p3 + vec3(0.6,0.1,0.9));
    float d9 = sdHelixOfSpheres(p3 + vec3(-.3,0.6,5.7));
    float d12 = sdHelixOfSpheres(p3 + vec3(-.5,0.1,-1.9));

    vec3 p4 = p + vec3(0.1,0.1, 0.6);
    p4 = vec3( mod(p4, 1.) - 1. * 0.5);


    float d13 = length(p4) - 0.33;

    vec3 p5 = p;
    p5.y += sin(p2.z * 2.  + iTime * .5) * 0.1;

    float d14 = sdHelixOfSpheres2(p5 + vec3(-0.9));

    //return d13;
    //return smin(d1, d, 0.1);  
    return smax(d13, smin(d14, smin(d3, smin(d4, smin(d5, smin(d7, smin(d8, smin(d10,
            smin(d11,d,0.1), 0.207), 0.3), 0.1507), 0.1509), 0.1508), 
            0.1409), 0.1), 0.05);  
}

