// Basic raymarch
float rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.;
    for(int i=0; i< 80; i++)
    {
        vec3 p = ro + rd * dt; 
        float d = map(p);
        dt += d;
        if(abs(d) < 0.001 || dt > 20.0) break;
    }
    return dt;
}

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    vec3 col = vec3(0);
    uv *= R2(iTime * 0.05);

    // Ray direction and origin
    vec3 ro = vec3(4, 3, -iTime * 1.7);

    vec3 rd = normalize(vec3(uv * 1., -1));
    float dt = rayMarch(ro, rd); 

    if(dt > 0.)
    {
        vec3 p = ro + rd * dt; 
        vec3 norm = calcNorm(p);

        vec3 lp = vec3(ro.x, ro.y, ro.z + 1.4); // Negated X, ahead in Z

        // light effects from @Shane

        // Light direction from surface to light
        vec3 L = lp - p;
        float lDist = max(length(L), .0001);
        L /= lDist; // Normalize

        float diff = max(dot(norm, L), 0.0);
        diff = pow(diff, 4.)*0.66 + pow(diff, 8.)*0.34;

        float spec = pow(max(dot(reflect(rd, norm), L), 0.), 8.);

        float fre = pow(clamp(dot(rd, norm) + 1., 0., 1.), 4.);

        float sss = pow(clamp(dot(rd, L), 0., 1.), 3.) * exp(-lDist * 0.02);
        // Cheap thickness estimate - sample map slightly inside surface
        float thickness = clamp(map(p - norm * 1.3) * 3.0, 0., 1.);
        sss *= (1.0 - thickness); 

        float NdotV = dot(norm, -rd);
        float iriAngle = acos(clamp(NdotV, 0., 1.));

        // Phase shift per channel = rainbow separation
        vec3 iridescence = 0.5 + 0.5 * cos(iriAngle * 4.5 + vec3(0., 2.1, 4.2) + p.z * 3.3);


        float atten = 1./(1. + lDist*.9125 + lDist*lDist*.025);

        // colors
        //col = (1. + cos(clamp(0.,3.,(p.z)) * clamp(0.,1.,(p.x * 1.)) * vec3(0,5,5) + 2.9)) / dt * vec3(3,2,6);
        vec3 bgCol = (1. + cos(4. + vec3(1,1,1))) / dt * vec3(0,2,0.3) * 1.3;

        col = bgCol * (diff * 3.1 +2.3);

        vec3 sssCol = vec3(0.1, 0.8, 10.7) * sss * 12.5;
        col += sssCol;

        col = mix(col, col * iridescence * 5.8, fre * .6);

       // col += vec3(0.020,0.020,0.020)*fre*5.;
        col *= atten;
        col += spec * 1.;

        // charge
        float hi = abs(mod(dt/0.2665 - iTime*1.3, 10.) - 5.) * 1.15;
        vec3 chargeCol = vec3(0.6) * col * 0.1 / (.01061 + hi * hi * .02);
        col += mix(chargeCol.yxz, chargeCol,  col);


        // colors
        //col += (1. + cos(1. + vec3(0,3,3))) / dt * vec3(0,2.3,3.9) * 1.;
    }

    // Dark background 'fog'
    col = mix(col, vec3(0), 1.0 - exp(-0.00029 * dt * dt * dt));

    // vignette
    col = mix(vec3(0), col, smoothstep(4., .1, length(uv * vec2(1.4,1) )));

    O = vec4(col, 1.0);
}

