mat2 R2(float a) { return mat2(cos(a), -sin(a), sin(a), cos(a));}

float almostIdentity( float x, float m, float n )
{
    if( x > m ) return x;
    float a = 2.0*n - m;
    float b = 2.0*m - 3.0*n;
    float t = x/m;
    return (a*t + b)*t*t + n;
}

float map(vec3 q)
{
    q.xz *= R2(iTime * 0.3);
    float r = 1.;
    q.y -= r;
    q *= 1. - 0.2*vec3(1.0,0.5,1.0);
    float x = abs(q.x);
    x = almostIdentity( x, 0.25, 0.1 );
    float y = q.y;
    float z = q.z;
    y = 1.5 + y*1.2 - x*sqrt(max((20.0-x)/15.0,0.0));
    z *= 2.0 - y/15.0;
    float d = sqrt(x*x+y*y+z*z) - r;
    return d / 3.0;
}

vec3 calcNorm(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
        map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
        map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
    ));
}

float rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.;
    for(int i = 0; i < 80; i++)
    {
        vec3 p = ro + rd * dt;
        float d = map(p);
        dt += d;
        if(abs(d) < 0.0001 || dt > 20.0) break;
    }
    return dt;
}

// Simple hash-based noise 
float hash(vec3 p)
{
    p = fract(p * 0.3183099 + 0.1);
    p *= 17.0;
    return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
}

float noise(vec3 p)
{
    vec3 i = floor(p);
    vec3 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(
        mix(mix(hash(i + vec3(0,0,0)), hash(i + vec3(1,0,0)), f.x),
            mix(hash(i + vec3(0,1,0)), hash(i + vec3(1,1,0)), f.x), f.y),
        mix(mix(hash(i + vec3(0,0,1)), hash(i + vec3(1,0,1)), f.x),
            mix(hash(i + vec3(0,1,1)), hash(i + vec3(1,1,1)), f.x), f.y),
        f.z);
}

float fbm(vec3 p)
{
    float v = 0.0, a = 0.5;
    for(int i = 0; i < 4; i++)
    {
        v += a * noise(p);
        p = p * 2.0 + 0.1;
        a *= 0.5;
    }
    return v;
}

// Interior volume color - the nebula/landscape inside the heart
vec3 interiorVolume(vec3 ro, vec3 rd, float tMax)
{
    vec3 col = vec3(0);
    float density = 0.0;

    // Step through the interior
    float dt = 0.05;
    for(float t = 0.0; t < tMax && density < 1.0; t += dt)
    {
        vec3 p = ro + rd * t;

        // Transform to heart-local space (match rotation)
        vec3 q = p;
        q.xz *= R2(iTime * 0.3);

        // Nebula noise field
        float n = fbm(q * 2.0 + vec3(0, iTime * 0.1, iTime * 0.05));

        // Create a landscape-like layer using y-position
        // Lower = more terrain, upper = more sky/clouds
        float yFade = smoothstep(-0.5, 0.8, q.y);

        // Terrain/mountain layer (lower portion)
        float terrain = fbm(q * 1.5 + vec3(iTime * 0.902, 0, 0));
        float terrainMask = smoothstep(0.1, -0.3, q.y - terrain * 0.5 + 0.2);

        // Cloud layer (upper)
        float clouds = fbm(q * 1.0 + vec3(0, 0, iTime * 0.08));
        float cloudMask = smoothstep(0.35, 0.6, clouds) * yFade;

        // Color palette inspired by reference image
        // Teal/cyan in lower-mid region
        vec3 teal = vec3(0.1, 0.8, 0.7);
        // Magenta/pink clouds
        vec3 pink = vec3(0.85, 0.2, 0.7);
        // Warm orange glow at terrain
        vec3 orange = vec3(1.0, 0.5, 0.1);
        // Deep purple for depth
        vec3 purple = vec3(0.3, 0.1, 0.5);

        // Mix colors by height and noise
        vec3 terrainCol = mix(orange, teal, smoothstep(-0.4, 0.1, q.y));
        terrainCol += orange * 0.5 * smoothstep(0.5, 0.7, terrain); // glowing peaks

        vec3 cloudCol = mix(teal, pink, smoothstep(0.4, 0.7, n));
        cloudCol = mix(cloudCol, purple, smoothstep(0.5, 1.0, q.y));

        // Sparkle/star points
        float sparkle = smoothstep(0.92, 0.95, hash(floor(q * 20.0)));
        vec3 sparkleCol = vec3(1.0, 0.9, 0.7) * sparkle * 2.0;

        // Combine layers
        float localDensity = terrainMask * 0.08 + cloudMask * 0.04;
        vec3 localCol = terrainCol * terrainMask + cloudCol * cloudMask + sparkleCol;

        // Accumulate
        col += localCol * localDensity * (1.0 - density);
        density += localDensity * (1.0 - density);

        dt = .05 + t * 0.02; // adaptive step
    }

    return col;
}

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    vec3 col = vec3(0);

    vec3 ro = vec3(0, 0, 2.4);
    vec3 rd = normalize(vec3(uv, -1.0));

    float dt = rayMarch(ro, rd);

    if(dt < 20.0)
    {
        vec3 p = ro + rd * dt;
        vec3 norm = calcNorm(p);

        // View direction
        vec3 V = -rd;

        // Fresnel - glass rim effect
        float fresnel = pow(1.0 - max(dot(norm, V), 0.0), 4.0);

        // Iridescent rim color (shifts with angle)
        float angle = dot(norm, V);
        vec3 iridescence = 0.5 + 0.5 * cos(6.28 * (angle * 2.0 + vec3(0.0, 0.33, 0.67)));

        // Glass rim
        vec3 rimCol = iridescence * fresnel *.5;

        // Environment reflection (simple fake)
        vec3 refl = reflect(-V, norm);
        float envLight = smoothstep(-0.2, 1.0, refl.y) * 0.15;
        rimCol += vec3(0.4, 0.6, 0.8) * envLight * fresnel;

        // Interior volume - march through the heart
        // Start from hit point, go inward
        vec3 interiorRo = p + rd * 0.01;
        float interiorDepth = 2.0; // max distance through interior
        vec3 interior = interiorVolume(interiorRo, rd, interiorDepth);

        // Combine: glass surface + interior seen through
        float transparency = 1.0 - fresnel * 0.6; // more transparent when looking straight on
        col = interior * transparency + rimCol;

        // Subtle specular highlight
        vec3 lightDir = normalize(vec3(0.5, 1.0, 0.5));
        float spec = pow(max(dot(reflect(-lightDir, norm), V), 0.0), 64.0);
        col += vec3(1.0) * spec * 0.4;

        // Secondary light for bottom rim
        vec3 lightDir2 = normalize(vec3(-0.3, -0.8, 0.2));
        float spec2 = pow(max(dot(reflect(-lightDir2, norm), V), 0.0), 32.0);
        col += vec3(0.3, 0.7, 1.0) * spec2 * 0.2;
    }

    // Fog to black
    //col = mix(col, vec3(0), 1.0 - exp(-0.004 * dt * dt * dt));

    // Vignette
    //col = mix(vec3(0), col, smoothstep(2.5, 0.1, length(uv * vec2(1.2, 1.0))));

    // Tone mapping & gamma
    col = col / (1.0 + col); // reinhard
    col = pow(col, vec3(0.85)); // slight gamma lift

    O = vec4(col, 1.0);
}

