float smin( float a, float b, float k )
{
    k *= 4.0;
    float h = max(k-abs(a-b),0.0);
    return min(a, b) - h*h*0.25/k;
}


// heart from @tachyonflux
// https://www.shadertoy.com/view/ll2fzt
float almostIdentity( float x, float m, float n )
{
    // For x > m: just return x (identity, no change)
    // For x < m: blend smoothly to a minimum value of n
    //            using a cubic hermite curve
    if( x > m ) return x;
    float a = 2.0*n - m;
    float b = 2.0*m - 3.0*n;
    float t = x/m;
    return (a*t + b)*t*t + n;
}

// iq https://www.shadertoy.com/view/4lK3Rc
float heart(vec3 q)
{
    //q.xz *= R2(iTime);
    float r = 1.0;
    q.y -= r;
    float ani = pow( 0.5+0.5*sin(6.28318*iTime), 4.0 );
    q *= 1.0 - 0.2*vec3(1.0,0.5,1.0);

    float x = abs(q.x);

    x = almostIdentity( x, 0.25, 0.1 ); // remove discontinuity (https://iquilezles.org/articles/functions)

    float y = q.y;
    float z = q.z;
    y = 2.0 + y*1.2 - x*sqrt(max((20.0-x)/15.0,0.0));
    z *= 2.0 - y/15.0;
    float d = sqrt(x*x+y*y+z*z) - r;
    d = d/3.0;

    return d;
}

float map(vec3 p)
{
    // cell ID before mod
    vec2 cellId = floor(vec2(p.x / 5.0, p.z / 5.0));

    // hash for this cell
    vec3 rr = hash3(cellId);

    // per-cell height offset
    float yOffset = 0.2 + 10.3 * rr.z;

    vec3 newP = p;
    //newP.y -= iTime;
    newP = vec3(
        mod(newP.x, 5.0) - 5. * 0.5,
        newP.y - 3.0,//mod(newP.y, 10.0) - 10. * 0.5,
        mod(newP.z, 5.0) - 5. * 0.5
    );

    newP.y -= yOffset;

    float d = heart(newP);

    //capsule 
    vec3 a = vec3(0,-1.5,0);
    vec3 b = vec3(0,-3.5,0);
    float r = 0.1;

    vec3 p1 = newP + vec3(0,0,-0.1);
    p1.x += sin(p1.y * 4.5 + iTime) * 0.07;
    float d1 = sdCapsule(p1, a, b, r);

    // floor
    float d3 = p.y - 1.6;

    float shape = -10e3;


    shape = smin(d,d1, 0.03);
    shape = smin(shape, d3, 0.1);

    return shape;
}
