void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    vec3 col = vec3(0);
    //uv *= R2(iTime * 0.2);

    vec2 mo = iMouse.xy / iResolution.xy;
    float time = 48.0; //+ iTime * .05;

    // camera
    vec3 ta = vec3(3, -6.0, 1.75 -iTime * .6);
    vec3 ro = ta + vec3(35.5 * cos(0.1 * time + 7.0 * mo.x), 7.2, 35.5 * sin(0.1 * time + 7.0 * mo.x));

    //ro.yz *= R2(-0.03);
    // camera-to-world transformation
    mat3 ca = setCamera(ro, ta, .0);

    // ray direction through the camera matrix
    vec3 rd = ca * normalize(vec3(uv, -1.0));

    float dt = rayMarch(ro, rd); 

    vec3 lp = ro + vec3(0, .75, 2);// Put it a bit in front of the camera.

    vec3 sky = sky(rd, lp);
    //col = sky;

    if(dt < 30.)
    {
        vec3 p = ro + rd * dt; 
        vec3 norm = calcNorm(p);

        //col += norm * 0.5 + 0.5;
        norm = texBump(iChannel0, p*0.5, norm, 0.01);

        if(objId < 1.)
        {
            col = vec3(.9);
        } else {
            col = vec3(.7,0.1,0.15);
        }

        // Obtaining the texel color. 
	    vec3 texCol = tex3D(iChannel0, p*0.5, norm);

    	// Light direction vectors.
	    vec3 ld = lp-p;

        // Distance from respective lights to the surface point.
	    float lDist = max(length(ld), 0.001);

    	// Normalize the light direction vectors.
	    ld /= lDist;

	    // Light attenuation, based on the distances above.
	    float atten = 1./(1. + lDist*lDist*0.025);

    	// Ambient light.
	    float ambience = .2;

    	// Diffuse lighting.
	    float diff = max( dot(norm, ld), 0.0);

    	// Specular lighting.
	    float spec = pow(max( dot( reflect(-ld, norm), -rd ), 0.0 ), 8.);

        // Combining the above terms to procude the final color.
        vec3 rCol = texCol * vec3(2.4,0.1,0.1); // red color here
        col += (rCol*(diff + ambience) + vec3(.8, .95, 1)*spec*1.5)*atten;

        col += sparkle(p.xy * .50) * vec3(0.8);
        // Counteract the blue fog desaturation by pushing saturation up.
        float luma = dot(col, vec3(.299, .587, .114));
        col = mix(vec3(luma), col, 1.4);
    }
    col = pow( col, vec3(0.4545) );

    // Dark background 'fog'
    col = mix(col, sky, 1.0 - exp(-0.00029 * dt * dt * dt));

    // vignette
    //col = mix(vec3(0), col, smoothstep(3., .1, length(uv * vec2(1.4,1.) )));

    O = vec4(col, 1.0);
}

