#define H(n)  fract( 1e4 * sin( n.x+n.y/.7 +vec2(1,12.34)  ) )
#define FAR 30.0

vec3 _noisePos;


// fabrice -> https://www.shadertoy.com/view/4dKSDV
vec3 voronoiDistSq(vec2 p, float dt)
{
    vec2 cellId, diff;
    float d;
    vec3 dists = vec3(9.0);       

    for (int k = 0; k < 9; ++k)
    {
        cellId = ceil(p) + vec2(k - (k/3)*3, k/3) - 2.0;
        // diff   = H(cellId) + cellId - p;
        diff = H(cellId) + cellId + .15 * cos(dt + 6.28 * H(cellId)) - p;

        d = dot(diff, diff);      

        d < dists.x ? (dists.yz = dists.xy, dists.x = d) :
        d < dists.y ? (dists.z  = dists.y , dists.y = d) :
        d < dists.z ?               dists.z = d        :
                       d;
    }
    return dists;
}


mat2 R2(float a) { return mat2(cos(a), -sin(a), sin(a), cos(a));}

// heart from @tachyonflux
// https://www.shadertoy.com/view/ll2fzt
float almostIdentity( float x, float m, float n )
{
    // For x > m: just return x (identity, no change)
    // For x < m: blend smoothly to a minimum value of n
    //            using a cubic hermite curve
    if( x > m ) return x;
    float a = 2.0*n - m;
    float b = 2.0*m - 3.0*n;
    float t = x/m;
    return (a*t + b)*t*t + n;
}

// iq https://www.shadertoy.com/view/4lK3Rc
float map(vec3 q)
{
    q.xz *= R2(iTime * 0.5);
    vec3 d1 = voronoiDistSq(q.xy * 8.095, iTime * 1.1);  

    float edgeDist = sqrt(d1.y) - sqrt(d1.x);

    vec3 col1 = 4.0 * sqrt(d1);
    col1 -= vec3(col1.x);
    col1 += 7.0 * ( col1.y / (col1.y / col1.z + 1.0) - 0.5 ) - col1;


    float r = 1.;
    q.y -= r;
    float ani = pow( 0.5+0.5*sin(6.28318*iTime), 4.0 );
    q *= 1.0 - 0.2*vec3(1.0,0.5,1.0);

    float x = abs(q.x);

    x = almostIdentity( x, 0.25, 0.1 ); // remove discontinuity (https://iquilezles.org/articles/functions)

    float y = q.y;
    float z = q.z;
    y = 2.0 + y*1.2 - x*sqrt(max((20.0-x)/15.0,0.0));
    z *= 2.0 - y/15.0;
    float d = sqrt(x*x+y*y+z*z) - r;
    d = d/3.0;

    return d - (col1.x * 0.002);
}


// simple normal 
vec3 calcNorm(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
        map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
        map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
    ));
}

// Basic raymarch
float rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.;
    for(int i=0; i< 80; i++)
    {
        vec3 p = ro + rd * dt; 
        float d = map(p);                    
        dt += d;                             
        if(abs(d) < 0.00001 || dt > 20.0) break;
    }
    return dt;
}

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    vec3 col = vec3(0);
    //uv *= R2(iTime * 0.2);

    // Ray direction and origin
    vec3 ro = vec3(0, 0,2.4);

    vec3 rd = normalize(vec3(uv * 1., -1));
    float dt = rayMarch(ro, rd); 

    if(dt > 0.)
    {
        vec3 p = ro + rd * dt; 
        vec3 norm = calcNorm(p);

        col += norm * 0.5 + 0.5;
    }

    // colors
    //col = (1. + cos(clamp(0.,3.,(p.z)) * clamp(0.,1.,(p.x * 1.)) * vec3(0,5,5) + 2.9)) / dt * vec3(3,2,6);
    //col += (1. + cos(4. + vec3(0,4,4))) / dt * vec3(0,1,1) * 2.;

    // Dark background 'fog'
    col = mix(col, vec3(0), 1.0 - exp(-0.0039 * dt * dt * dt));

    // vignette
    col = mix(vec3(0), col, smoothstep(3., .1, length(uv * vec2(1.4,1.) )));

    O = vec4(col, 1.0);
}

