// Simple noise algorithm contributed by Trisomie21 (Thanks!)
float snoise( vec2 p ) 
{
	vec2 f = fract(p);
	p = floor(p);
	float v = p.x+p.y*1000.0;
	vec4 r = vec4(v, v+1.0, v+1000.0, v+1001.0);
	r = fract(100000.0*sin(r*.001));
	f = f*f*(3.0-2.0*f);
	return 2.0*(mix(mix(r.x, r.y, f.x), mix(r.z, r.w, f.x), f.y))-1.0;
}

float terrain( vec2 p, int octaves ) 
{	
	float h = 0.0; // height
	float w = 0.6; // octave weight
	float m = 0.3; // octave multiplier
	for (int i=0; i<16; i++) {
		if (i<octaves) {
			h += w * snoise((p * m));
		}
		else break;
		w *= 0.2;
		m *= 1.0;
	}
	return h;
}

// iq 
float sdCapsule( vec3 p, vec3 a, vec3 b, float r )
{
  vec3 pa = p - a, ba = b - a;
  float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
  return length( pa - ba*h ) - r;
}

// iq 
float smin( float a, float b, float k )
{
    k *= 4.0;
    float h = max(k-abs(a-b),0.0);
    return min(a, b) - h*h*0.25/k;
}


// heart from @tachyonflux
// https://www.shadertoy.com/view/ll2fzt
float almostIdentity( float x, float m, float n )
{
    // For x > m: just return x (identity, no change)
    // For x < m: blend smoothly to a minimum value of n
    //            using a cubic hermite curve
    if( x > m ) return x;
    float a = 2.0*n - m;
    float b = 2.0*m - 3.0*n;
    float t = x/m;
    return (a*t + b)*t*t + n;
}

// iq https://www.shadertoy.com/view/4lK3Rc
float heart(vec3 q)
{
    //q.xz *= R2(iTime);
    vec3 d1 = voronoiDistSq(q.xy * 15.095, iTime * 1.1);  

    float edgeDist = sqrt(d1.y) - sqrt(d1.x);
    float bump = max(0.0, 0.4 - sqrt(d1.x));

    float r = 1.0;
    q.y -= r;
    float ani = pow( 0.3+0.4*sin(6.28318*iTime), 3.0 );
    q *= 1.0 - 0.2*vec3(1.0,0.5,1.0);

    float x = abs(q.x);

    x = almostIdentity( x, 0.25, 0.1 ); // remove discontinuity (https://iquilezles.org/articles/functions)

    float y = q.y;
    float z = q.z;
    y = 2.0 + y*1.2 - x*sqrt(max((20.0-x)/15.0,0.0));
    z *= 2.0 - y/15.0;
    float d = sqrt(x*x+y*y+z*z) - r;
    d = d/3.0;

    return d - (bump * 0.03);
}


vec2 terr( vec3 p ) 
{
    vec3 d1 = voronoiDistSq(p.zx * 8.095, iTime * 1.1);  

    float edgeDist = sqrt(d1.y) - sqrt(d1.x);
    float bump = max(0.0, 0.6 - sqrt(d1.x));

    int octaves = 4;
	float dMin = dMax; // nearest intersection
	float d; // depth
	float mID = -1.0; // material ID

	// terrain
	float h = terrain(p.xz, octaves);
	h += smoothstep(-0.3, 1.1, h); // exaggerate the higher terrain
	h *= smoothstep(-1.5, -0.3, h); // smooth out the lower terrain
    d = p.y - h;	
	if (d<dMin) { 
		dMin = d- (bump * .07);;
		mID = 0.0;
	}

	return vec2(dMin, 0.);
}

float objId;

vec2 map(vec3 p)
{
    float cellZ = 4.0;
    // cell ID before mod
    vec2 cellId = floor(vec2(p.x / 6.0, p.z / cellZ));

    // hash for this cell
    vec3 rr = hash3(cellId);

    // per-cell height offset
    float yOffset = 0.2 + 5.3 * rr.z;

    vec3 newP = p;
    //newP.y -= iTime;
    newP = vec3(
        mod(newP.x, 6.0) - 6. * 0.5,
        newP.y - 0.0,  //mod(newP.y, 10.0) - 10. * 0.5,
        mod(newP.z, cellZ) - cellZ * 0.5
    );

    newP.y -= yOffset;

    float d = heart(newP);

    //capsule 
    vec3 a = vec3(0,-1.,0);
    vec3 b = vec3(0,-30.5,0);
    float r = 0.02;

    vec3 p1 = newP + vec3(0,0,-0.);
    //p1.x += sin(p1.y * 3.0 + iTime) * 0.05;
    float d1 = sdCapsule(p1, a, b, r);

    // floor
    float d3 = terr(p + vec3(0,1.,0)).x;

    float heartCapsule = smin(d, d1, 0.03);
    float heartCapsuleId = d < d1 ? 1.0 : 2.0;  // 1.0 = heart, 2.0 = capsule

    // union with terrain
    if(d3 < heartCapsule)
        return vec2(d3, 0.0);           // 0.0 = terrain
    else
        return vec2(heartCapsule, heartCapsuleId);
}

// @Shane
// Tri-Planar blending function. Based on an old Nvidia tutorial.
vec3 tex3D( sampler2D tex, in vec3 p, in vec3 n ){

    //return cellTileColor(p);

    n = max((abs(n) - 0.2)*7., 0.001); // n = max(abs(n), 0.001), etc.
    n /= (n.x + n.y + n.z ); 
	return (texture(tex, p.yz)*n.x + texture(tex, p.zx)*n.y + texture(tex, p.xy)*n.z).xyz;
}

// Texture bump mapping. Four tri-planar lookups, or 12 texture lookups in total. I tried to 
// make it as concise as possible. Whether that translates to speed, or not, I couldn't say.
vec3 texBump( sampler2D tx, in vec3 p, in vec3 n, float bf)
{   
    const vec2 e = vec2(0.002, 0);

    // Three gradient vectors rolled into a matrix, constructed with offset greyscale texture values.    
    mat3 m = mat3( tex3D(tx, p - e.xyy, n), tex3D(tx, p - e.yxy, n), tex3D(tx, p - e.yyx, n));

    vec3 g = vec3(0.299, 0.587, 0.114)*m; // Converting to greyscale.
    g = (g - dot(tex3D(tx,  p , n), vec3(0.299, 0.587, 0.114)) )/e.x; g -= n*dot(n, g);

    return normalize( n + g*bf ); // Bumped normal. "bf" - bump factor.

}

vec3 rustCol(float noise01, float nl, vec3 l, vec3 col, vec2 dt)
{
    vec3 darkMet = vec3(0.973,0.969,0.969); // dark metal
    vec3 rustOra = vec3(0.933,0.890,0.906); // dark purple
    vec3 stains  = vec3(0.576,0.024,0.051); // deeper stains
    vec3 darkPat = vec3(0.06, 0.0, 0.0);      // darker patches

    float rust  = smoothstep(0.566, 0.6458, noise01);
    float stain = smoothstep(0.655, 0.425, noise01);
    float stain2= smoothstep(0.275, 0.5625,  noise01);

    vec3 albedo = mix(darkMet, rustOra, rust);
    albedo = mix(albedo, stains, stain);
    albedo = mix(albedo, darkPat, stain2);
    col = albedo * vec3(max(0.2, nl));

    float spot = dot(l, vec3(0, 1, 0));
    col *= smoothstep(0.3, 0.575, spot);

    return col;
}

