// Basic raymarch
vec2 rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.;
    float m = -1.0;
    for(int i=0; i< 80; i++)
    {
        vec3 p = ro + rd * dt; 
        vec2 d = map(p);
        m = d.y;
        dt += d.x;                             
        if(abs(d.x) < 0.001 || dt > 30.0) break;
    }
    if(dt > 30.0) m = -1.0;
    return vec2(dt, m);
}

mat3 setCamera(in vec3 ro, in vec3 ta, float cr)
{
    vec3 cw = normalize(ta - ro);
    vec3 cp = vec3(sin(cr), cos(cr), 0.0);
    vec3 cu = normalize(cross(cw, cp));
    vec3 cv = cross(cu, cw);
    return mat3(cu, cv, cw);
}

float castShadow(vec3 ro, vec3 rd)
{
    float res = 1.0;
    float dt  = 0.01;

    for(int i=0; i<100; i++)
    {
        float d = map(ro + rd * dt).x;
        res = min(res, 10.0 * d / dt);

        if((res) < 0.001) break;
        dt += d;

        if(dt > 15.0) break;
    }
    return clamp(res, 0.0, 1.0);
}

float calcAO(in vec3 p, in vec3 n){

	float sca = 2., occ = 0.;
    for( int i = 0; i<5; i++ ){

        float hr = float(i + 1)*.15/5.;        
        float d = map(p + n*hr).x;
        occ += (hr - d)*sca;
        sca *= .75;
    }

    return clamp(1. - occ, 0., 1.);  
}


