        vec3 p = ro + rd * dt.x; 
        vec3 norm = calcNorm(p);

        vec4 noise = noisedFBM(p * vec3(0.2, 2.75, 1) * 2.0 + vec3(3,0,0), 9, 0.95);

        //col += norm * 0.5 + 0.5;
        norm = texBump(iChannel0, p*.5, norm, 0.02);

        // Obtaining the texel color. 
	    vec3 texCol = tex3D(iChannel0, p*0.5, norm);

    	// Light direction vectors.
	    vec3 ld = lp-p;

        // Distance from respective lights to the surface point.
	    float lDist = max(length(ld), 0.001);

    	// Normalize the light direction vectors.
	    ld /= lDist;

        // shadow 
        float shadow = castShadow(p + norm* 0.001, ld);
        float ao = calcAO(lp, norm);

	    // Light attenuation, based on the distances above.
	    float atten = 1./(1. + lDist*lDist*0.025);

    	// Ambient light.
	    float ambience = .2;

    	// Diffuse lighting.
	    float diff = max( dot(norm, ld), 0.0);

    	// Specular lighting.
	    float spec = pow(max( dot( reflect(-ld, norm), -rd ), 0.0 ), 8.);

        // Combining the above terms to procude the final color.
        vec3 rCol = texCol * vec3(2.4,0.1,0.1); // red color here


        if(dt.y < 0.5)
        {
            // perturb normal with noise FIRST
            norm = normalize(norm + noise.yzw * .8);

            // recompute diffuse & spec with the bumped normal
            float nl = dot(norm, ld);
            float tDiff = max(nl, 0.0);
            float tSpec = pow(max(dot(reflect(-ld, norm), -rd), 0.0), 8.);

            float noise01 = noise.x * .135 + 0.5;
            col = rustCol(noise01, nl, ld, col, dt) * 20.;
            col += (col * (tDiff + ambience) + tSpec * 1.5) * atten;
        } else if(dt.y < 1.5) {
            col = vec3(.8, 0.1, 0.215);   // heart
            col += (rCol*(diff + ambience) + vec3(.8, .95, 1)*spec*1.5)*atten;
            col += sparkle(p.xy * .50) * vec3(0.8);
            // Counteract the blue fog desaturation by pushing saturation up.
            float luma = dot(col, vec3(.299, .587, .114));
            col = mix(vec3(luma), col, 1.4);
        } else if(dt.y < 2.5) {
            col = vec3(1);   // capsule/stem — give it its own color
            col += (vec3(0.6) * (diff + ambience) + vec3(.8, .95, 1) * spec * 1.5) * atten;
        }
        col *= mix(0.15, 1.0, shadow) * mix(0.3, 1.0, ao);

    }
    col = pow( col, vec3(0.4545) );

    // Dark background 'fog'
    col = mix(col, sky, 1.0 - exp(-0.00015 * dt.x * dt.x * dt.x));
    //col = mix(col, vec3(0), 1.0 - exp(-0.00015 * dt.x * dt.x * dt.x));

    // vignette
    col = mix(vec3(0), col, smoothstep(4.6, .1, length(uv * vec2(1.4,1.) )));

    O = vec4(col, 1.0);
}

