// https://www.shadertoy.com/view/XsXfRH
float hash(ivec3 p)
{
    int n = p.x*3 + p.y*113 + p.z*311;
	n = (n << 13) ^ n;
    n = n * (n * n * 15731 + 789221) + 1376312589;
    return -1.0+2.0*float( n & 0x0fffffff)/float(0x0fffffff);
}

// https://iquilezles.org/articles/morenoise/
vec4 noised(in vec3 x)
{
    ivec3 i = ivec3(floor(x));
    vec3 w = fract(x);
    vec3 u = w*w*(3.0-2.0*w);
    //vec3 u = w*w*w*(w*(w*6.0-10.0)+5.0);
    vec3 du = 6.0*w*(1.0-w); 
    float a = hash(i+ivec3(0,0,0));
    float b = hash(i+ivec3(1,0,0));
    float c = hash(i+ivec3(0,1,0));
    float d = hash(i+ivec3(1,1,0));
    float e = hash(i+ivec3(0,0,1));
	float f = hash(i+ivec3(1,0,1));
    float g = hash(i+ivec3(0,1,1));
    float h = hash(i+ivec3(1,1,1));
    float k0 =   a;
    float k1 =   b - a;
    float k2 =   c - a;
    float k3 =   e - a;
    float k4 =   a - b - c + d;
    float k5 =   a - c - e + g;
    float k6 =   a - b - e + f;
    float k7 = - a + b + c - d + e - f - g + h;
    return vec4( k0 + k1*u.x + k2*u.y + k3*u.z + k4*u.x*u.y + k5*u.y*u.z + k6*u.z*u.x + k7*u.x*u.y*u.z, 
                 du * vec3( k1 + k4*u.y + k6*u.z + k7*u.y*u.z,
                            k2 + k5*u.z + k4*u.x + k7*u.z*u.x,
                            k3 + k6*u.x + k5*u.y + k7*u.x*u.y ) );
}

vec4 noisedFBM(in vec3 x, int octaves, float gain)
{
    vec4 result = vec4(0.);
    float a = 1.0;
    float s = 0.0;
    for (int i = 0; i < octaves; i++)
    {
        result += noised(x * 0.109 ) * a;
        s += a;
        x *= 2.0;
        a *= gain;
    }
    return result / s;
}

vec2 combineMin(vec2 a, vec2 b)
{
    return (a.x < b.x)? a : b;
}

#define PI 3.14159265

// PCG2D random number generator
vec2 get_random_numbers(inout uvec2 seed) {
    seed = 1664525u * seed + 1013904223u;
    seed.x += 1664525u * seed.y;
    seed.y += 1664525u * seed.x;
    seed ^= (seed >> 16u);
    seed.x += 1664525u * seed.y;
    seed.y += 1664525u * seed.x;
    seed ^= (seed >> 16u);
    return vec2(seed) * 2.32830643654e-10;
}

vec3 sample_sphere(vec2 rn) {
    float z = 2.0 * rn[1] - 1.0;
    float phi = 2.0 * PI * rn[0];
    float xy = sqrt(1.0 - z * z);
    return vec3(cos(phi) * xy, sin(phi) * xy, z);
}

vec3 sample_hemisphere(vec2 rn, vec3 n) {
    vec3 d = sample_sphere(rn);
    if (dot(n, d) < 0.0)
        d -= 2.0 * dot(n, d) * n;  // reflect to correct hemisphere
    return d;
}

float map(vec3 p) {
    float sphere = length(p) - 1.0;
    float floor_ = p.y + 1.0;
    return min(sphere, floor_);
}

vec3 getNormal(vec3 p) {
    vec2 e = vec2(0.001, 0.0);
    return normalize(vec3(
        map(p+e.xyy)-map(p-e.xyy),
        map(p+e.yxy)-map(p-e.yxy),
        map(p+e.yyx)-map(p-e.yyx)
    ));
}

float raymarch(vec3 ro, vec3 rd) {
    float t = 0.0;
    for(int i = 0; i < 80; i++) {
        float d = map(ro + rd * t);
        t += d;
        if(d < 0.001 || t > 100.0) break;
    }
    return t;
}

vec3 trace(vec2 uv, inout uvec2 seed) {
    vec3 ro = vec3(0, 0, -3);
    vec3 rd = normalize(vec3(uv, 1.0));

    vec3 throughput = vec3(1.0);
    vec3 color = vec3(0.0);

    for(int bounce = 0; bounce < 3; bounce++) {
        float t = raymarch(ro, rd);

        if(t > 100.0) {
            // sky light
            color += throughput * mix(vec3(1.0), vec3(0.5, 0.7, 1.0), 0.5 + 0.5 * rd.y);
            break;
        }

        vec3 p = ro + rd * t;
        vec3 n = getNormal(p);

        vec3 albedo = vec3(0.8);

        throughput *= albedo;
        ro = p + n * 0.002;
        rd = sample_hemisphere(get_random_numbers(seed), n);
    }
    return color;
}

void mainImage(out vec4 O, in vec2 I) {
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;

    // PCG2D seed: pixel position + frame count for unique seed per pixel per frame
    uvec2 seed = uvec2(I) + uvec2(uint(iFrame) * 7919u, uint(iFrame) * 6271u);

    vec3 color = trace(uv, seed);

    // accumulate with previous frames
    vec3 prev = texelFetch(iChannel0, ivec2(I), 0).rgb;
    color = mix(prev, color, 1.0 / float(iFrame + 1));

    O = vec4(color, 1.0);
}

