// The minimunm distance a ray must travel before we consider an intersection.
// This is to prevent a ray from intersecting a surface it just bounced off of.
const float MIN_RAY = .01;

// after a hit, it moveD2 the ray this far along the normal away from a surface.
// Helps prevent incorrect intersections when rays bounce off of objects.
const float RO_NORMAL_NUDGE = 0.01;

// the farthest we look for ray hits
const float FAR = 10000.0;

// camera FOV
const float CAMERA_FOV = 90.0;

// number of ray bounces allowed
const int BOUNCES = 20;

// how many renders per frame - to get around the vsync limitation.
const int FRAME_RENDERS = 1;

const float PI = 3.14159265359;
const float TWO_PI = 2.0 * PI;

uint hash2(inout uint seed)
{
    seed = uint(seed ^ uint(61)) ^ uint(seed >> uint(16));
    seed *= uint(9);
    seed = seed ^ (seed >> 4);
    seed *= uint(0x27d4eb2d);
    seed = seed ^ (seed >> 15);
    return seed;
}

float hash1(inout uint state)
{
    return float(hash2(state)) / 4294967296.0;
}

vec3 hasUnit(inout uint state)
{
    float z = hash1(state) * 2.0 - 1.0;
    float a = hash1(state) * TWO_PI;
    float r = sqrt(1.0f - z * z);
    float x = r * cos(a);
    float y = r * sin(a);
    return vec3(x, y, z);
}

struct SRayHitInfo
{
    float dt;
    vec3 normal;
    vec3 albedo;
    vec3 emissive;
};

float scalarTriple(vec3 u, vec3 v, vec3 w)
{
    return dot(cross(u, v), w);
}

bool quadTrace(in vec3 ro, in vec3 rd, inout SRayHitInfo info, in vec3 a, in vec3 b, in vec3 c, in vec3 d)
{
    // calculate normal and flip vertices order if needed
    vec3 normal = normalize(cross(c-a, c-b));
    if (dot(normal, rd) > 0.0)
    {
        normal *= -1.0;

		vec3 temp = d;
        d = a;
        a = temp;

        temp = b;
        b = c;
        c = temp;
    }

    vec3 p = ro;
    vec3 q = ro + rd;
    vec3 pq = q - p;
    vec3 pa = a - p;
    vec3 pb = b - p;
    vec3 pc = c - p;

    // determine which triangle to test against by testing against diagonal first
    vec3 m = cross(pc, pq);
    float v = dot(pa, m);
    vec3 intersectPos;
    if (v >= 0.0)
    {
        // test against triangle a,b,c
        float u = -dot(pb, m);
        if (u < 0.0) return false;
        float w = scalarTriple(pq, pb, pa);
        if (w < 0.0) return false;
        float denom = 1.0 / (u+v+w);
        u*=denom;
        v*=denom;
        w*=denom;
        intersectPos = u*a+v*b+w*c;
    }
    else
    {
        vec3 pd = d - p;
        float u = dot(pd, m);
        if (u < 0.0) return false;
        float w = scalarTriple(pq, pa, pd);
        if (w < 0.0) return false;
        v = -v;
        float denom = 1.0 / (u+v+w);
        u*=denom;
        v*=denom;
        w*=denom;
        intersectPos = u*a+v*d+w*c;
    }

    float dt;
    if (abs(rd.x) > 0.1)
    {
        dt = (intersectPos.x - ro.x) / rd.x;
    }
    else if (abs(rd.y) > 0.1)
    {
        dt = (intersectPos.y - ro.y) / rd.y;
    }
    else
    {
        dt = (intersectPos.z - ro.z) / rd.z;
    }

	if (dt > MIN_RAY && dt < info.dt)
    {
        info.dt = dt;        
        info.normal = normal;        
        return true;
    }    

    return false;
}

bool sphereTrace(in vec3 ro, in vec3 rd, inout SRayHitInfo info, in vec4 sphere)
{
	//get the vector from the center of this sphere to where the ray begins.
	vec3 m = ro - sphere.xyz;

    //get the dot product of the above vector and the ray's vector
	float b = dot(m, rd);
	float c = dot(m, m) - sphere.w * sphere.w;

	//exit if r's origin outside s (c > 0) and r pointing away from s (b > 0)
	if(c > 0.0 && b > 0.0)
		return false;

	//calculate discriminant
	float discr = b * b - c;

	//a negative discriminant corresponds to ray missing sphere
	if(discr < 0.0)
		return false;

	//ray now found to intersect sphere, compute smallest t value of intersection
    bool fromInside = false;
	float dt = -b - sqrt(discr);
    if (dt < 0.0)
    {
        fromInside = true;
        dt = -b + sqrt(discr);
    }

	if (dt > MIN_RAY && dt < info.dt)
    {
        info.dt = dt;        
        info.normal = normalize((ro+rd*dt) - sphere.xyz) * (fromInside ? -1.0 : 1.0);
        return true;
    }

    return false;
}

// What did we hit
void sceneTrace(in vec3 ro, in vec3 rd, inout SRayHitInfo hitInfo)
{    
    vec3 moveD1 = vec3(0.0, 0.0, 10.0);
    vec4 moveD2 = vec4(moveD1, 0.0);

    float a1 = 12.6, a2 = 25.0, a3 = 12.45, a4 = 15.0, a5 = 12.5;

    vec3 albedo1 = vec3(0.7);
    vec3 emissive1 = vec3(0);

    // back wall
    {
        vec3 A = vec3(-a1, -a1, a2) + moveD1;
        vec3 B = vec3( a1, -a1, a2) + moveD1;
        vec3 C = vec3( a1,  a1, a2) + moveD1;
        vec3 D = vec3(-a1,  a1, a2) + moveD1;
        if (quadTrace(ro, rd, hitInfo, A, B, C, D))
        {
            hitInfo.albedo = albedo1;
            hitInfo.emissive = emissive1;
        }
    }    

    // floor
    {
        vec3 A = vec3(-a1, -a3, a2) + moveD1;
        vec3 B = vec3( a1, -a3, a2) + moveD1;
        vec3 C = vec3( a1, -a3, a4) + moveD1;
        vec3 D = vec3(-a1, -a3, a4) + moveD1;
        if (quadTrace(ro, rd, hitInfo, A, B, C, D))
        {
            hitInfo.albedo = albedo1;
            hitInfo.emissive = emissive1;
        }        
    }

    // cieling
    {
        vec3 A = vec3(-a1, a5, a2) + moveD1;
        vec3 B = vec3( a1, a5, a2) + moveD1;
        vec3 C = vec3( a1, a5, a4) + moveD1;
        vec3 D = vec3(-a1, a5, a4) + moveD1;
        if (quadTrace(ro, rd, hitInfo, A, B, C, D))
        {
            hitInfo.albedo = albedo1;
            hitInfo.emissive = emissive1;
        }        
    }    

    // left wall
    {
        vec3 A = vec3(-a5, -a1, a2) + moveD1;
        vec3 B = vec3(-a5, -a1, a4) + moveD1;
        vec3 C = vec3(-a5,  a1, a4) + moveD1;
        vec3 D = vec3(-a5,  a1, a2) + moveD1;
        if (quadTrace(ro, rd, hitInfo, A, B, C, D))
        {
            hitInfo.albedo = vec3(0.7, 0.1, 0.1);
            hitInfo.emissive = emissive1;
        }        
    }

    // right wall 
    {
        vec3 A = vec3( a5, -a1, a2) + moveD1;
        vec3 B = vec3( a5, -a1, a4) + moveD1;
        vec3 C = vec3( a5,  a1, a4) + moveD1;
        vec3 D = vec3( a5,  a1, a2) + moveD1;
        if (quadTrace(ro, rd, hitInfo, A, B, C, D))
        {
            hitInfo.albedo = vec3(0.1, 0.7, 0.1);
            hitInfo.emissive = emissive1;
        }        
    }    

    // light
    {
        vec3 A = vec3(-5.0, 12.4, 22.5) + moveD1;
        vec3 B = vec3( 5.0, 12.4, 22.5) + moveD1;
        vec3 C = vec3( 5.0, 12.4, 17.5) + moveD1;
        vec3 D = vec3(-5.0, 12.4, 17.5) + moveD1;
        if (quadTrace(ro, rd, hitInfo, A, B, C, D))
        {
            hitInfo.albedo = vec3(0);
            hitInfo.emissive = vec3(1.0, 0.9, 0.7) * 20.0;
        }        
    }

    // Balls
    if (sphereTrace(ro, rd, hitInfo, vec4(-9.0, -0.5, 20.0, 3.0) + moveD2))
    {
        hitInfo.albedo = vec3(0.9, 0.9, 0.75);
        hitInfo.emissive = emissive1;        
    } 

    if (sphereTrace(ro, rd, hitInfo, vec4(0.0, -9.5, 20.0, 3.0) + moveD2))
    {
        hitInfo.albedo = vec3(0.9, 0.75, 0.9);
        hitInfo.emissive = emissive1;        
    }    

    if (sphereTrace(ro, rd, hitInfo, vec4(9.0, -3.5, 20.0, 3.0) + moveD2))
    {
        hitInfo.albedo = vec3(0.75, 0.9, 0.9);
        hitInfo.emissive = emissive1;
    }    
}

// The bouncing loop 
vec3 colorRay(in vec3 ro, in vec3 rd, inout uint rngState)
{
    // initialize
    vec3 ret = vec3(0);
    vec3 throughput = vec3(1);

    for (int i = 0; i <= BOUNCES; ++i)
    {
        // shoot a ray out into the world
        SRayHitInfo hitInfo;
        hitInfo.dt = FAR;
        sceneTrace(ro, rd, hitInfo);

        // if the ray missed, we are done
        if (hitInfo.dt == FAR)
        {
            ret += vec3(0);
            break;
        }

		// update the ray position
        ro = (ro + rd * hitInfo.dt) + hitInfo.normal * RO_NORMAL_NUDGE;

        // calculate new ray direction, in a cosine weighted hemisphere oriented at normal
        rd = normalize(hitInfo.normal + hasUnit(rngState));        

		// add in emissive lighting
        ret += hitInfo.emissive * throughput;

        // update the colorMultiplier
        throughput *= hitInfo.albedo;      
    }

    // return pixel color
    return ret;
}

void mainImage( out vec4 O, in vec2 I )
{
    vec3 R = iResolution;
    // initialize a random number state based on frag coord and frame
    uint rngState = uint(uint(I.x) * uint(1973) + uint(I.y) * uint(9277) + uint(iFrame) * uint(26699)) | uint(1);

    // Ray oririgin
    vec3 ro = vec3(0);

    // calculate the camera distance
	float cameraDt = 1.0 / tan(CAMERA_FOV * .45 * PI / 180.0);        

    // calculate coordinates of the ray target on the imaginary pixel plane.
    // -1 to +1 on x,y axis. 1 unit away on the z axis
    vec3 uv = vec3((I/R.xy) * 2.0 - 1.0, cameraDt);

    // correct for aspect ratio
	float aspectRatio = R.x / R.y;
    uv.y /= aspectRatio;

    // calculate a normalized vector for the ray direction.
    // it's pointing from the ray position to the ray target.
    vec3 rd = normalize(uv - ro);

    // raytrace for this pixel
    vec3 color = vec3(0);
    for (int index = 0; index < FRAME_RENDERS; ++index)
    	color += colorRay(ro, rd, rngState) / float(FRAME_RENDERS);

    // average the frames together
    vec3 lastFrameColor = texture(iChannel0, I / R.xy).rgb;
    color = mix(lastFrameColor, color, 1.0 / float(iFrame+1));

    // show the result
    O = vec4(color, 1.0);
}

