const int BOUNCES = 20;

// how many renders per frame - to get around the vsync limitation.
const int FRAME_RENDERS = 1;

const float PI = 3.14159265359;
const float TWO_PI = 2.0 * PI;


uint hash2(inout uint seed)
{
    seed = uint(seed ^ uint(61)) ^ uint(seed >> uint(16));
    seed *= uint(9);
    seed = seed ^ (seed >> 4);
    seed *= uint(0x27d4eb2d);
    seed = seed ^ (seed >> 15);
    return seed;
}

float hash1(inout uint state)
{
    return float(hash2(state)) / 4294967296.0;
}

vec3 hasUnit(inout uint state)
{
    float z = hash1(state) * 2.0 - 1.0;
    float a = hash1(state) * TWO_PI;
    float r = sqrt(1.0f - z * z);
    float x = r * cos(a);
    float y = r * sin(a);
    return vec3(x, y, z);
}

struct SRayHitInfo
{
    float dt;
    vec3 normal;
    vec3 albedo;
    vec3 emissive;
};

float scalarTriple(vec3 u, vec3 v, vec3 w)
{
    return dot(cross(u, v), w);
}

bool quadTrace(in vec3 ro, in vec3 rd, inout SRayHitInfo info, in vec3 a, in vec3 b, in vec3 c, in vec3 d)
{
    // calculate normal and flip vertices order if needed
    vec3 normal = normalize(cross(c-a, c-b));
    if (dot(normal, rd) > 0.0)
    {
        normal *= -1.0;

		vec3 temp = d;
        d = a;
        a = temp;

        temp = b;
        b = c;
        c = temp;
    }

    vec3 p = ro;
    vec3 q = ro + rd;
    vec3 pq = q - p;
    vec3 pa = a - p;
    vec3 pb = b - p;
    vec3 pc = c - p;

    // determine which triangle to test against by testing against diagonal first
    vec3 m = cross(pc, pq);
    float v = dot(pa, m);
    vec3 intersectPos;
    if (v >= 0.0)
    {
        // test against triangle a,b,c
        float u = -dot(pb, m);
        if (u < 0.0) return false;
        float w = scalarTriple(pq, pb, pa);
        if (w < 0.0) return false;
        float denom = 1.0 / (u+v+w);
        u*=denom;
        v*=denom;
        w*=denom;
        intersectPos = u*a+v*b+w*c;
    }
    else
    {
        vec3 pd = d - p;
        float u = dot(pd, m);
        if (u < 0.0) return false;
        float w = scalarTriple(pq, pa, pd);
        if (w < 0.0) return false;
        v = -v;
        float denom = 1.0 / (u+v+w);
        u*=denom;
        v*=denom;
        w*=denom;
        intersectPos = u*a+v*d+w*c;
    }

    float dt;
    if (abs(rd.x) > 0.1)
    {
        dt = (intersectPos.x - ro.x) / rd.x;
    }
    else if (abs(rd.y) > 0.1)
    {
        dt = (intersectPos.y - ro.y) / rd.y;
    }
    else
    {
        dt = (intersectPos.z - ro.z) / rd.z;
    }

	if (dt > MIN_RAY && dt < info.dt)
    {
        info.dt = dt;        
        info.normal = normal;        
        return true;
    }    

    return false;
}

bool sphereTrace(in vec3 ro, in vec3 rd, inout SRayHitInfo info, in vec4 sphere)
{
	//get the vector from the center of this sphere to where the ray begins.
	vec3 m = ro - sphere.xyz;

    //get the dot product of the above vector and the ray's vector
	float b = dot(m, rd);
	float c = dot(m, m) - sphere.w * sphere.w;

	//exit if r's origin outside s (c > 0) and r pointing away from s (b > 0)
	if(c > 0.0 && b > 0.0)
		return false;

	//calculate discriminant
	float discr = b * b - c;

	//a negative discriminant corresponds to ray missing sphere
	if(discr < 0.0)
		return false;

	//ray now found to intersect sphere, compute smallest t value of intersection
    bool fromInside = false;
	float dt = -b - sqrt(discr);
    if (dt < 0.0)
    {
        fromInside = true;
        dt = -b + sqrt(discr);
    }

	if (dt > MIN_RAY && dt < info.dt)
    {
        info.dt = dt;        
        info.normal = normalize((ro+rd*dt) - sphere.xyz) * (fromInside ? -1.0 : 1.0);
        return true;
    }

    return false;
}

void TestSceneTrace(in vec3 rayPos, in vec3 rayDir, inout SRayHitInfo hitInfo)
{    
    {
        vec3 A = vec3(-15.0f, -15.0f, 22.0f);
        vec3 B = vec3( 15.0f, -15.0f, 22.0f);
        vec3 C = vec3( 15.0f,  15.0f, 22.0f);
        vec3 D = vec3(-15.0f,  15.0f, 22.0f);
        if (quadTrace(rayPos, rayDir, hitInfo, A, B, C, D))
        {
            hitInfo.albedo = vec3(0.7f, 0.7f, 0.7f);
            hitInfo.emissive = vec3(0);
        }
    }    

    if (sphereTrace(rayPos, rayDir, hitInfo, vec4(-10, 0, 20, 1)))
    {
        hitInfo.albedo = vec3(1.0f, 0.1f, 0.1f);
        hitInfo.emissive = vec3(0);        
    } 

    if (sphereTrace(rayPos, rayDir, hitInfo, vec4(0, 0, 20, 1)))
    {
        hitInfo.albedo = vec3(0.1f, 1.0f, 0.1f);
        hitInfo.emissive = vec3(0);        
    }    

    if (sphereTrace(rayPos, rayDir, hitInfo, vec4(10, 0, 20, 1)))
    {
        hitInfo.albedo = vec3(0.1f, 0.1f, 1.0f);
        hitInfo.emissive = vec3(0);
    }           


    if (sphereTrace(rayPos, rayDir, hitInfo, vec4(0, 10, 20,3)))
    {
        hitInfo.albedo = vec3(0);
        hitInfo.emissive = vec3(1.0f, 0.9f, 0.7f) * 100.0;
    }         
}

vec3 GetColorForRay(in vec3 startRayPos, in vec3 startRayDir, inout uint rngState)
{
    // initialize
    vec3 ret = vec3(0);
    vec3 throughput = vec3(1);
    vec3 rayPos = startRayPos;
    vec3 rayDir = startRayDir;

    for (int bounceIndex = 0; bounceIndex <= BOUNCES; ++bounceIndex)
    {
        // shoot a ray out into the world
        SRayHitInfo hitInfo;
        hitInfo.dt = FAR;
        TestSceneTrace(rayPos, rayDir, hitInfo);

        // if the ray missed, we are done
        if (hitInfo.dt == FAR)
            break;

        // update the ray position
        rayPos = (rayPos + rayDir * hitInfo.dt) + hitInfo.normal * RO_NORMAL_NUDGE;

        // calculate new ray direction, in a cosine weighted hemisphere oriented at normal
        rayDir = normalize(hitInfo.normal + hasUnit(rngState));        

        // add in emissive lighting
        ret += hitInfo.emissive * throughput;

        // update the colorMultiplier
        throughput *= hitInfo.albedo;      
    }

    // return pixel color
    return ret;
}

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;

    // init
    vec3 ro = vec3(0,0,7);
    vec3 rd = normalize(vec3(uv, 1.0));

    // initialize a random number state based on frag coord and frame
    uint rngState = uint(uint(I.x) * uint(1973) + uint(I.y) * uint(9277) + uint(iFrame) * uint(26699)) | uint(1);

    vec3 color = GetColorForRay(ro, rd, rngState);

    // average the frames together
    vec3 prevFrame = texture(iChannel0, I / iResolution.xy).rgb;
    color = mix(prevFrame, color, 1.0f / float(iFrame+1));

    O = vec4(color, 1.0);
}

// ============================================================
//  Monte Carlo Path Tracer — Shadertoy
//  Based on "Ray Tracing: The Rest of Your Life" by P. Shirley
//
//  Features:
//   • Lambertian diffuse with cosine-weighted hemisphere sampling
//   • Importance sampling: direct light PDF + surface scatter PDF
//     mixed 50/50  →  faster convergence, no fireflies
//   • Orthonormal basis (ONB) to transform local scatter dirs
//   • Progressive accumulation via iChannel0 feedback buffer
//   • Cornell box scene (floor, ceiling, walls, area light, 2 spheres)

// ─── CONSTANTS ──────────────────────────────────────────────
#define PI      3.14159265359
#define INF     1e20
#define EPS     1e-4

// light 
#define LIGHT_EMIT  15.0

// samples added per frame (raise for faster convergence, lower for fps)
#define SPP     2

// max bounces per path
#define MAX_DEPTH 6

// ─── PSEUDO-RANDOM (hash-based, stateless) ──────────────────
// State is carried as a uint and evolved with PCG
uint rngState;

uint pcgHash(uint s){
    s = s * 747796405u + 2891336453u;
    s = ((s >> ((s >> 28u) + 4u)) ^ s) * 277803737u;
    return (s >> 22u) ^ s;
}
float rand01(){
    rngState = pcgHash(rngState);
    return float(rngState) * (1.0/4294967296.0);
}
vec2 rand2(){ return vec2(rand01(), rand01()); }
vec3 rand3(){ return vec3(rand01(), rand01(), rand01()); }

// ─── ONB (orthonormal basis around a normal) ────────────────
struct ONB { vec3 u, v, w; };

ONB makeONB(vec3 n){
    ONB b;
    b.w = normalize(n);
    vec3 a = (abs(b.w.x) > 0.9) ? vec3(0,1,0) : vec3(1,0,0);
    b.v = normalize(cross(b.w, a));
    b.u = cross(b.w, b.v);
    return b;
}

vec3 onbTransform(ONB b, vec3 v){
    return v.x*b.u + v.y*b.v + v.z*b.w;
}

// ─── RANDOM DIRECTION GENERATORS ────────────────────────────

// Uniform on full sphere (used for initial ray direction tests)
vec3 randUnitSphere(){
    // inversion method from the book
    float r1 = rand01(), r2 = rand01();
    float phi = 2.0*PI*r1;
    float cosT = 1.0 - 2.0*r2;
    float sinT = sqrt(max(0.0, 1.0 - cosT*cosT));
    return vec3(cos(phi)*sinT, sin(phi)*sinT, cosT);
}

// Cosine-weighted hemisphere (Lambertian ideal PDF = cosθ/π)
// derived via inversion: cosθ = sqrt(1-r2), φ = 2π·r1
vec3 randCosineDirZ(){
    float r1 = rand01(), r2 = rand01();
    float phi = 2.0*PI*r1;
    float x = cos(phi)*sqrt(r2);
    float y = sin(phi)*sqrt(r2);
    float z = sqrt(1.0 - r2);
    return vec3(x, y, z);
}

// Random point on a quad light (world-space)
// Light: centre lc, two edge vectors le1, le2
vec3 randOnLight(vec3 lc, vec3 le1, vec3 le2){
    return lc + (rand01()-0.5)*le1 + (rand01()-0.5)*le2;
}

// ─── SCENE GEOMETRY ─────────────────────────────────────────
// Cornell box  (550×550×550 interior, y-up, z-forward)
// We use infinite planes + sphere SDFs via ray-AABB / ray-sphere

struct Hit {
    float t;
    vec3  p;
    vec3  n;      // outward normal
    int   matID;  // 0=white, 1=red, 2=green, 3=light, 4=glass(unused)
};

// Ray-sphere
bool hitSphere(vec3 ro, vec3 rd, vec3 sc, float sr,
               float tMin, float tMax, out Hit h){
    vec3 oc = ro - sc;
    float a = dot(rd,rd);
    float hb = dot(oc,rd);
    float c  = dot(oc,oc) - sr*sr;
    float disc = hb*hb - a*c;
    if(disc < 0.0) return false;
    float sq = sqrt(disc);
    float t = (-hb - sq)/a;
    if(t < tMin || t > tMax){ t = (-hb + sq)/a; }
    if(t < tMin || t > tMax) return false;
    h.t = t;
    h.p = ro + t*rd;
    h.n = (h.p - sc)/sr;
    return true;
}

// Ray-axis-aligned plane (one-sided)
bool hitPlane(vec3 ro, vec3 rd,
              vec3 normal, float d,      // plane: dot(p,normal)=d
              float tMin, float tMax, out Hit h){
    float denom = dot(rd, normal);
    if(abs(denom) < 1e-6) return false;
    float t = (d - dot(ro, normal)) / denom;
    if(t < tMin || t > tMax) return false;
    h.t = t;
    h.p = ro + t*rd;
    h.n = normal;
    return true;
}

// Clamp hit to a finite quad: check if p is inside bounds
bool inBounds(vec3 p, vec3 axis, float lo, float hi,
                       vec3 axis2, float lo2, float hi2){
    float a = dot(p, axis);
    float b = dot(p, axis2);
    return a >= lo && a <= hi && b >= lo2 && b <= hi2;
}

// Full scene intersection
bool sceneHit(vec3 ro, vec3 rd, float tMin, float tMax, out Hit best){
    best.t = tMax;
    bool found = false;
    Hit h;

    // Cornell box walls (550 units)
    // Floor  y=0   (white)
    if(hitPlane(ro, rd, vec3(0,1,0), 0.0, tMin, best.t, h)){
        if(inBounds(h.p, vec3(0.9,0,0),0.,550., vec3(0,0,1),0.,550.)){
            h.matID=0; best=h; found=true;
        }
    }
    // Ceiling y=550 (white)
    if(hitPlane(ro, rd, vec3(0,-1,0), -550.0, tMin, best.t, h)){
        if(inBounds(h.p, vec3(0.9,0,0),0.,550., vec3(0,0,1),0.,550.)){
            h.matID=0; h.n=vec3(0,-1,0); best=h; found=true;
        }
    }
    // Back wall z=555 (white)
    if(hitPlane(ro, rd, vec3(0,0,-1), -555.0, tMin, best.t, h)){
        if(inBounds(h.p, vec3(1,0,0),0.,555., vec3(0,1,0),0.,555.)){
            h.matID=0; h.n=vec3(0,0,-1); best=h; found=true;
        }
    }
    // Left wall x=555 (green)
    if(hitPlane(ro, rd, vec3(-1,0,0), -555.0, tMin, best.t, h)){
        if(inBounds(h.p, vec3(0,1,0),0.,555., vec3(0,0,1),0.,555.)){
            h.matID=2; h.n=vec3(-1,0,0); best=h; found=true;
        }
    }
    // Right wall x=0 (red)
    if(hitPlane(ro, rd, vec3(1,0,0), 0.0, tMin, best.t, h)){
        if(inBounds(h.p, vec3(0,1,0),0.,555., vec3(0,0,1),0.,555.)){
            h.matID=1; best=h; found=true;
        }
    }

    // Area light (on ceiling, y=554, pointing down)
    // centre (278,554,279), extents 130×105
    if(hitPlane(ro, rd, vec3(0,-1,0), -544.0, tMin, best.t, h)){
        if(inBounds(h.p, vec3(1,0,0), 213., 343., vec3(0,0,1), 227., 332.)){
            h.matID=3; h.n=vec3(0,-1,0); best=h; found=true;
        }
    }

    // Sphere 1: large diffuse sphere (white)
    if(hitSphere(ro, rd, vec3(190.,90.,190.), 90., tMin, best.t, h)){
        h.matID=0; best=h; found=true;
    }
    // Sphere 2: smaller mirror-ish sphere (slightly different white)
    if(hitSphere(ro, rd, vec3(360.,65.,295.), 65., tMin, best.t, h)){
        h.matID=0; best=h; found=true;
    }

    return found;
}

// ─── LIGHT PARAMETERS ───────────────────────────────────────
vec3 LIGHT_POS = vec3(278., 554., 279.5);
vec3 LIGHT_E1  = vec3(130., 0., 0.);
vec3 LIGHT_E2  = vec3(0., 0., 105.);
float LIGHT_AREA;   // set in mainImage

// PDF of sampling a direction toward the quad light from point p
// p(ω) = dist²/(cosθ_light · A)
float lightPDF(vec3 p, vec3 lp){
    vec3 toL  = lp - p;
    float dist2 = dot(toL, toL);
    float dist  = sqrt(dist2);
    vec3  lDir  = toL / dist;
    // Normal of light faces -y
    float cosL = abs(dot(lDir, vec3(0,1,0)));
    if(cosL < EPS) return 0.0;
    return dist2 / (cosL * LIGHT_AREA);
}

// ─── MATERIALS ──────────────────────────────────────────────
// matID 0 = white Lambertian  albedo 0.73
// matID 1 = red   Lambertian  albedo (0.65,0.05,0.05)
// matID 2 = green Lambertian  albedo (0.12,0.45,0.15)
// matID 3 = area light  emit 15,15,15

vec3 matAlbedo(int id){
    if(id==1) return vec3(0.65,0.05,0.05);
    if(id==2) return vec3(0.12,0.45,0.15);
    return vec3(0.73);
}

// ─── PATH TRACING ───────────────────────────────────────────
// One path, returns radiance estimate.
// Uses MIS: 50% cosine scatter PDF, 50% direct-light PDF.
vec3 tracePath(vec3 ro, vec3 rd){
    vec3 throughput = vec3(1.0);
    vec3 radiance   = vec3(0.0);

    for(int depth=0; depth<MAX_DEPTH; depth++){
        Hit h;
        if(!sceneHit(ro, rd, EPS, INF, h)){
            // No background radiance (black env)
            break;
        }

        // Hit a light?
        if(h.matID == 3){
            // Only count emission on first hit or when sampled via scatter PDF
            // (to avoid double-counting when we do explicit light sampling)
            if(depth == 0)
                radiance += throughput * vec3(LIGHT_EMIT);
            break;
        }

        vec3 albedo = matAlbedo(h.matID);
        // Make normal face the ray
        vec3 n = dot(h.n, rd) < 0.0 ? h.n : -h.n;

        // ── Explicit direct light sample ──────────────────
        // Sample a point on the light
        vec3 lSamplePos = randOnLight(LIGHT_POS, LIGHT_E1, LIGHT_E2);
        vec3 toL = lSamplePos - h.p;
        float distL = length(toL);
        vec3 dirL = toL / distL;
        float cosL = dot(n, dirL);

        if(cosL > 0.0){
            // Shadow test
            Hit sh;
            bool blocked = sceneHit(h.p + n*EPS, dirL, EPS, distL - EPS, sh);
            if(!blocked || sh.matID == 3){
                // Scattering PDF for this direction (Lambertian: cosθ/π)
                float scatPDF_L = max(0.0, cosL) / PI;
                // Light PDF
                float lPDF = lightPDF(h.p, lSamplePos);
                if(lPDF > 0.0){
                    // MIS weight (50/50 mixture)
                    float mixPDF = 0.5*lPDF + 0.5*scatPDF_L;
                    radiance += throughput * albedo * (vec3(LIGHT_EMIT) * scatPDF_L / mixPDF);
                }
            }
        }

        // ── Scatter new direction (cosine-weighted hemisphere) ──
        ONB onb = makeONB(n);
        vec3 localDir = randCosineDirZ();
        vec3 scatDir  = normalize(onbTransform(onb, localDir));
        float cosT = max(0.0, dot(n, scatDir));

        // Scatter PDF
        float scatPDF = cosT / PI;
        if(scatPDF < EPS){ break; }

        // Check if scatter direction hits the light
        Hit sh2;
        float lPDFscatter = 0.0;
        if(sceneHit(h.p + n*EPS, scatDir, EPS, INF, sh2)){
            if(sh2.matID == 3){
                // compute light PDF for this direction
                lPDFscatter = lightPDF(h.p, sh2.p);
            }
        }

        // MIS weight for scatter ray
        float mixPDF2 = 0.5*lPDFscatter + 0.5*scatPDF;
        if(mixPDF2 < EPS){ break; }

        // BRDF weight: albedo * scatPDF / mixPDF
        throughput *= albedo * (scatPDF / mixPDF2);

        ro = h.p + n*EPS;
        rd = scatDir;

        // Russian roulette after depth 3
        if(depth >= 3){
            float p = max(throughput.r, max(throughput.g, throughput.b));
            if(rand01() > p) break;
            throughput /= p;
        }
    }

    return radiance;
}

// ─── MAIN (Buffer A) ────────────────────────────────────────
void mainImage(out vec4 fragColor, in vec2 fragCoord){
    LIGHT_AREA = length(LIGHT_E1) * length(LIGHT_E2);

    // ── Camera ────────────────────────────────────────────
    vec3 lookFrom = vec3(278., 278., -800.);
    vec3 lookAt   = vec3(278., 278.,  0.);
    vec3 vup      = vec3(0.,1.,0.);
    float vfov    = 40.0 * (PI/180.0);

    float aspect = iResolution.x / iResolution.y;
    float h = tan(vfov*0.5);
    vec3 w = normalize(lookFrom - lookAt);
    vec3 u = normalize(cross(vup, w));
    vec3 v = cross(w, u);

    float vpH = 2.0*h;
    float vpW = aspect * vpH;
    vec3 horiz  = u * vpW;
    vec3 vert   = v * vpH;
    vec3 llc    = lookFrom - horiz*0.5 - vert*0.5 - w;

    // ── Accumulate ────────────────────────────────────────
    vec2 uv = fragCoord / iResolution.xy;

    // Seed: mix pixel coord + frame count + sample index
    rngState = pcgHash(uint(fragCoord.x) + pcgHash(uint(fragCoord.y) +
               pcgHash(uint(iTime*1000.0) + uint(iFrame)*1973u)));

    vec3 col = vec3(0.0);
    for(int s=0; s<SPP; s++){
        // Stratified jitter within pixel
        vec2 jitter = rand2() - 0.5;
        vec2 st = (fragCoord + jitter) / iResolution.xy;

        vec3 rd = normalize(llc + st.x*horiz + st.y*vert - lookFrom);
        col += tracePath(lookFrom, rd);
    }
    col /= float(SPP);

    // ── Temporal accumulation (exponential running average) ──
    vec4 prev = texture(iChannel0, uv);
    float weight = 1.0 / (prev.a + 1.0);   // a stores sample count
    vec3  acc = mix(prev.rgb, col, weight);

    // Tone-map + gamma for display (done in Image tab or here if single-pass)
    vec3 display = pow(clamp(acc, 0.0, 1.0), vec3(1.0/2.2));

    fragColor = vec4(acc, prev.a + 1.0);
}

