float shape(vec3 p0, float height, float rotate)
{
    // Rotate around the base of the capsule (at y = -1)
    vec3 p = p0;
    p.xz *= R2(rotate);
    // capsules 
    vec3 p1 = p;
    float d = sdCapsule(p1, vec3(0,-1,0), vec3(0,height,0), 0.1 );

    // ellipse 
    vec3 p2 = p + vec3(0,-0.8 - (height - 0.5),-0.3);
    float d1 = sdEllipsoid(p2 , vec3(0.5, 0.5, 0.4));

    // subtract the sphere with the ellipse
    vec3 p3 = p + vec3(0.1,-0.8 - (height - 0.5),-0.6);
    float d2 = sdSphere(p3, 0.3);

    return max(-d2, min(d,d1));
}

