            // you are at least 0.001 far from the shape so you can jump 
            dt += d;

            // if distance travel is too much then exist
            if(dt > 10.0) break;
        }

        /*
            Now we are inside the surface of the shape we HIT something!!!
        */

        if(HIT)
        {
            mat3 onb = makeONB(hitN);
            vec3 scatterDt = normalize(onb * sampleHemisphere(getRandom()));
            // scatter direction = random point on hemisphere around normal
            //vec3 scatterDt = sampleHemisphere(getRandom());
            //vec3 scatterDt = normalize(vec3(0,3,0) - hitP);

            // make sure scatter goes same side as normal
            if(dot(scatterDt, hitN) < 0.0) scatterDt = -scatterDt;

            /*
                lets lift the ray origin from the hit surface so we are a bit 
                above the surface so the agent doesn't re-hit the surface he's 
                standing on
            */

            vec3 ro2 = hitP + hitN * .01;

            bool hit2 = false; float dt2 = 0.0;

            // setup a 2nd raymarch ? explain more
            for(int k = 0; k < 40; k++)
            {
                // position with scatter distance travel 
                vec3 p2 = ro2 + scatterDt * dt2;
                float d = map(p2);
                // setup hit2 
                if(d < 0.001)
                {
                    hit2 = true; break;
                }

                // add hit distance travel sdf to dt2 
                dt2 += d;

                if(dt > 10.) break;
            }


            // if we hit the sdf then that's a shadow 

            /*
                We got out CIA agent back again ready to report he's gonna tell us 
                that after we sent a couple of scatter points we'll know if it hit
            */



            // if hit2 AND hit the light sphere → agentColor = bright white (emission)
            if(hit2){
                vec3 p2Final = ro2 + scatterDt * dt2;
                float dLight = length(p2Final - vec3(0,3,0)) - 0.5;

                if(dLight < 0.01){
                    float cosTheta = max(0.0, dot(hitN, scatterDt));
                    float pdf = 1.0 / (2.0 * PI);
                    agentColor = vec3(10.0) * cosTheta / pdf; 
                    lightHits += 10.0;
                } else
                    agentColor = vec3(0);  // hit something else
            } else {
                agentColor = vec3(0.0); // missed everything, sky is black
            }
            // if hit2 AND hit something else   → agentColor = black (shadow)  
            // if !hit2                         → agentColor = dim (sky)
            //if(!hit2) agentColor = vec3(1);// sky
            //else      agentColor = vec3(0); 
        }

        col += agentColor;
    }

    // explain more ?
    col /= float(NUM_SAMPLES); // after loop
    //col = vec3(lightHits / float(NUM_SAMPLES), 0.0, 0.0);

    vec3 prev = texture(iChannel0, I / iResolution.xy).rgb;
    col = mix(prev, col, 1. / float(iFrame + 1));
    O = vec4(col, 1.0);
}

