const float FAR = 20.0;

float map(vec3 p)
{
    float d1 = length(p + vec3(sin(iTime), sin(iTime) - .5,0)) - 1.0;
    float d2 = p.y + 1.1;

    return min(d1, d2);
}

// Ray march 
float rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.0;

    for(int i = 0; i<50; i++)
    {
        vec3 p = ro + rd * dt;
        float d = map(p);

        // if we are really close to the shape stop marching
        if(d < 0.001){
            break;
        }

        // advance ray by the safe SDF distance traveled
        dt += d;

        // Ray is too far away from the distance we exit
        if(dt > FAR) break;
    }
    return dt;
}

// iq 
// https://iquilezles.org/articles/rmshadows/
float shadow(vec3 ro, vec3 rd)
{
    float res = 1.;
    float dt = 0.2;

    for(int i = 0; i<100; i++)
    {
        // we are gonna computer the position from the raymarch 
        // and the light direction x distance travel 
        float d = map(ro + rd * dt);

        // if we are close to the shape then return 0 
        // so we can multiply and get a shadow 
        if(d < 0.001) return 0.;
        res = min(res, 8. * d / dt);
        dt += d;

        if(dt > FAR) break;
    }

    // else return 1 so we don't change the color 
    return res;
}

vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
        map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
        map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
    ));
}

void mainImage( out vec4 O, vec2 I )
{
    vec2 uv = (2. * I - iResolution.xy)/iResolution.y;

    // color
    vec3 col = vec3(uv.y + 0.4);

    // Ray origin
    vec3 ro = vec3(0,0,3);
    // Ray direction controls the field of view
    vec3 rd = normalize(vec3(uv, -1.));

    // distance travel, marching
    float dt = rayMarch(ro,rd);

    if(dt < FAR)
    {
        vec3 p = ro + rd * dt;
        vec3 norm = calcNormal(p);

        vec3 L = normalize(vec3(2,2,2));

        float diff = max(dot(L,norm), 0.0);

        col = vec3(0.6) * diff * shadow(p,L);
    }

    // Output to screen
    O = vec4(col,1.0);
}

