int flat_idx;
int seed;

const int SAMPLES = 32;
const int MAXDEPTH = 6;

const float PI = 3.14159265359;
const float TWO_PI = 2.0f * PI;

uint wang_hash(inout uint seed)
{
    seed = uint(seed ^ uint(61)) ^ uint(seed >> uint(16));
    seed *= uint(9);
    seed = seed ^ (seed >> 4);
    seed *= uint(0x27d4eb2d);
    seed = seed ^ (seed >> 15);
    return seed;
}

float RandomFloat01(inout uint state)
{
    return float(wang_hash(state)) / 4294967296.0;
}

vec3 RandomUnitVector(inout uint state)
{
    float z = RandomFloat01(state) * 2.0f - 1.0f;
    float a = RandomFloat01(state) * TWO_PI;
    float r = sqrt(1.0f - z * z);
    float x = r * cos(a);
    float y = r * sin(a);
    return vec3(x, y, z);
}

float map(vec3 p)
{
    float d1 = length(p) - 1.;
    float d2 = p.y + 1.0;

    return min(d1, d2);
}

struct Ray
{
    vec3 rd, ro, material, p, norm, emission, surfaceColor;
    bool hit;
    float dt;
};

float rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.0;
    for(int j = 0; j < 40; j++)
    {
        vec3 p = ro + rd * dt;
        float d = map(p);
        if(d < 0.01)
        { 
            break;
        }
        dt += d;
        if(dt > 10.0) break;

    }
    return dt;
}

vec3 calcNormal(vec3 p) {
    vec2 e = vec2(0.001, 0.0);
    return normalize(vec3(
        map(p + e.xyy) - map(p - e.xyy),
        map(p + e.yxy) - map(p - e.yxy),
        map(p + e.yyx) - map(p - e.yyx)
    ));
}

// Returns material color based on what was hit
vec3 getMaterial(vec3 p)
{
    float sphere = length(p) - 1.0;
    float floor  = p.y + 1.0;
    if (sphere < floor) return vec3(0.4); // sphere: dark grey
    return vec3(0.8);                     // floor: light grey
}

vec3 radiance(Ray r, inout uint rngState) {
    vec3 acc  = vec3(0.);
    vec3 mask = vec3(1.);

    for (int depth = 0; depth < MAXDEPTH; ++depth)
    {
        if (!r.hit) 
        {
            // Sky / background — simple gradient
            vec3 sky = mix(vec3(0.0), vec3(0.1), clamp(r.rd.y + 0.5, 0.0, 1.0));
            acc += mask * sky;
            break;
        }

        vec3 x = r.p;
        vec3 n = r.norm;

        // Emission (surfaces here emit nothing)
        acc += mask * r.emission;

        // Attenuate
        mask *= r.surfaceColor;

        // Cosine-weighted hemisphere bounce
        vec3 newDir = normalize(n + RandomUnitVector(rngState));

        // March the new ray
        vec3 newRo = x + n * 0.02; // offset to avoid self-intersection
        float dt = 0.0;
        bool hit = false;
        for (int j = 0; j < 64; j++) 
        {
            vec3 p = newRo + newDir * dt;
            float d = map(p);
            dt += d;
            if (d < 0.001) { hit = true; break; }
            if (dt > 20.0) break;
        }

        // Build next ray
        r.hit = hit;
        r.rd  = newDir;
        if (hit) {
            r.p           = newRo + newDir * dt;
            r.norm        = calcNormal(r.p);
            r.surfaceColor = getMaterial(r.p);
            r.emission    = vec3(0.0);
        }
    }

    return acc;
}

