    for (int k=0; k < SAMPLES; k++)
    {
        // choose random points in pixel 
        uint rngState = uint(uint(I.x) * uint(1973) + uint(I.y) * uint(9277) + uint(iFrame) * uint(26699)) | uint(1);

            // Choose random point on image plane P_image

            // D = normalize(P_image - P_lens)
