                }

                if(isect.dt > 10.0) break;

            }
        }

        // if the ray hits something then 
        if (isect.hit) 
        {
            // Build the first Ray struct
            Ray r;
            r.hit          = true;
            r.rd           = rd;
            r.ro           = ro;
