            r.p            = ro + rd * isect.dt;
            r.norm         = calcNormal(r.p);
            r.surfaceColor = getMaterial(r.p);
            r.emission     = vec3(0.0);

            // C += radiance(ray, isect, 0)
            C += radiance(r, rngState);

        //else 
        } else {
