/*

This shader is an attempt at porting smallpt to GLSL.

See what it's all about here:
http://www.kevinbeason.com/smallpt/

The code is based in particular on the slides by David Cline.

Some differences:

- For optimization purposes, the code considers there is
  only one light source (see the commented loop)
- Russian roulette and tent filter are not implemented

I spent quite some time pulling my hair over inconsistent
behavior between Chrome and Firefox, Angle and native. I
expect many GLSL related bugs to be lurking, on top of
implementation errors. Please Let me know if you find any.

Update #1:
There is a bug in the next event estimation. If the scene
is modified into a furnace test, the result will be correct
when ENABLE_NEXT_EVENT_PREDICTION is undefined, but too
much energy ends up being added when it is defined.
Thanks @bernie_freidin for reporting this bug.

Update #2:
I've finally added accumulation over time. The accumulation
is absolute, and resizing is not detected. This means
switching to full screen will leave a thumbnail burnt at
the left corner.

--
Zavie

*/

// Play with the two following values to change quality.
// You want as many samples as your GPU can bear. :)
#define SAMPLES 4
#define MAXDEPTH 6
//#define ENABLE_NEXT_EVENT_PREDICTION

// Uncomment to see how many samples never reach a light source
//#define DEBUG

// Not used for now
#define DEPTH_RUSSIAN 2

#define PI 3.14159265359
#define DIFF 0
#define SPEC 1
#define REFR 2
#define NUM_SPHERES 9

// random seed state
float seed = 0.;
float rand() { return fract(sin(seed++)*43758.5453123); }

// ray defined by origin and direction
struct Ray { vec3 o, d; };

/* 
    sphere defined by:
    radius 
    position, emission, color
    material type

*/
struct Shape {
	float r;
	vec3 p, e, c;
	int refl;
};

// light source sphere used for next event prediction
Shape lightSourceVolume = Shape(20., vec3(50., 81.6, 81.6), vec3(12.), vec3(0.), DIFF);

// scene sphere array
Shape shape[NUM_SPHERES];

void initScene() 
{
	// left wall (red)
	shape[0] = Shape(1e5, vec3(-1e5+1., 4.8, 81.6),	vec3(0.), vec3(.75, .25, .25), DIFF);
	// right wall (blue)
	shape[1] = Shape(1e5, vec3( 1e5+99., 40.8, 81.6),vec3(0.), vec3(.25, .25, .75), DIFF);
	// back wall (white)
	shape[2] = Shape(1e5, vec3(50., 40.8, -1e5),		vec3(0.), vec3(.75), DIFF);
	// front wall (black/invisible)
	shape[3] = Shape(1e5, vec3(50., 40.8,  1e5+170.),vec3(0.), vec3(0.), DIFF);
	// floor (white)
	shape[4] = Shape(1e5, vec3(50., -1e5, 81.6),		vec3(0.), vec3(.75), DIFF);
	// ceiling (white)
	shape[5] = Shape(1e5, vec3(50.,  1e5+81.6, 81.6),vec3(0.), vec3(.75), DIFF);
	// left sphere (mirror)
	shape[6] = Shape(16.5, vec3(27., 16.5, 47.), 	vec3(0.), vec3(1.), SPEC);
	// right sphere (glass)
	shape[7] = Shape(16.5, vec3(73., 16.5, 78.), 	vec3(0.), vec3(.7, 1., .9), REFR);
	// area light (emissive sphere on ceiling)
	shape[8] = Shape(600., vec3(50., 681.33, 81.6),	vec3(12.), vec3(0.), DIFF);
}

float intersect(Shape s, Ray r) 
{
	// vector from ray origin to sphere center
	vec3 op = s.p - r.o;

	// dt holds the hit distance, epsilon avoids self-intersection
    float dt, epsilon = 1e-3;

    // b is the projection of op onto the ray direction
    float b = dot(op, r.d);

    // discriminant of the quadratic intersection equation
    float det = b * b - dot(op, op) + s.r * s.r;

	// no intersection if discriminant is negative, otherwise take square root
    if (det < 0.) return 0.; else det = sqrt(det);

	// return nearest positive intersection, or 0 if behind the ray
    return (dt = b - det) > epsilon ? dt : ((dt = b + det) > epsilon ? dt : 0.);
}

int intersect(Ray r, out float t, out Shape s, int avoid) 
{
	// no hit id
	int id = -1;
	// initialize t to a large value
	t = 1e5;
	// default sphere output
	s = shape[0];

	for (int i = 0; i < NUM_SPHERES; ++i) 
    { 
		// current shape to test
		Shape S = shape[i];
		// distance to current shape
		float d = intersect(S, r);

		// keep the closest valid hit, skipping the avoided shapes
		if (i != avoid && d!=0. && d<t) { t = d; id = i; s=S; }
	}
	// return index of closest hit shape, or -1 if none
	return id;
}

vec3 jitter(vec3 d, float phi, float sina, float cosa) 
{
	// build an orthonormal basis around direction d
	vec3 w = normalize(d), u = normalize(cross(w.yzx, w)), v = cross(w, u);

	// rotate sample direction by phi around w, using sine and cosine of polar angle
	return (u*cos(phi) + v*sin(phi)) * sina + w * cosa;
}

vec3 radiance(Ray r) 
{
	// accumulated light contribution
	vec3 acc  = vec3(0.);
	// throughput mask, multiplied at each bounce
	vec3 mask = vec3(1.);
	// last hit sphere index, -1 means none
	int id = -1;

    // number of bounces
	for (int depth = 0; depth < MAXDEPTH; ++depth) 
    {
		// hit distance
		float dt;
		// hit sphere
		Shape obj;

        // if no intersection, exit the loop
        if ((id = intersect(r, dt, obj, id)) < 0) break;

        // hit position along the ray
        vec3 p = r.o + r.d * dt;

        // surface normal at the hit point
        vec3 n = normalize(p - obj.p);
        // oriented normal, flipped to face the incoming ray
        vec3 nl = n * sign(-dot(n, r.d));

        // diffuse material
		if (obj.refl == DIFF) 
        {
			// random value for cosine-weighted hemisphere sampling
			float r2 = rand();
			// new diffuse bounce direction using cosine-weighted sampling
			vec3 d = jitter(nl, 2.*PI*rand(), sqrt(r2), sqrt(1. - r2));
			// direct light contribution (unused for now)
			vec3 e = vec3(0.);

			// energy weight for direct emission (1 = always include)
			float E = 1.;//float(depth==0);
			// accumulate emission and indirect light contribution
			acc += mask * obj.e * E + mask * obj.c * e;
			// attenuate throughput by surface color
			mask *= obj.c;
			// continue path in new diffuse direction
			r = Ray(p, d);
		} 
        // specular material
        else if (obj.refl == SPEC) 
        {
			// accumulate emission from specular surface
			acc += mask * obj.e;
			// attenuate throughput by surface color
			mask *= obj.c;
			// reflect ray around the surface normal
			r = Ray(p, reflect(r.d, n));
		} 
        // refraction/glass material
        else 
        {
			// a is cosine of angle between normal and ray, ddn is its absolute value
			float a=dot(n,r.d), ddn=abs(a);

			// nc = air IOR, nt = glass IOR, nnt = ratio depending on ray direction
			float nc=1., nt=1.5, nnt=mix(nc/nt, nt/nc, float(a>0.));

			// cosine squared of the refracted angle, used to detect total internal reflection
            float cos2t=1.-nnt*nnt*(1.-ddn*ddn);

			// default to reflection
            r = Ray(p, reflect(r.d, n));

			// refraction is possible, no total internal reflection
            if (cos2t>0.) 
            {
				// compute the refracted ray direction
				vec3 tdir = normalize(r.d*nnt + sign(a)*n*(ddn*nnt+sqrt(cos2t)));

				// R0 is Fresnel reflectance at normal incidence (Schlick base), c is the view-dependent factor
                float R0=(nt-nc)*(nt-nc)/((nt+nc)*(nt+nc)),
					c = 1.-mix(ddn,dot(tdir, n),float(a>0.));

				// Re is Schlick Fresnel reflectance, P is Russian roulette probability, RP and TP are energy compensation weights
                float Re=R0+(1.-R0)*c*c*c*c*c,P=.25+.5*Re,RP=Re/P,TP=(1.-Re)/(1.-P);

				// Russian roulette: choose reflection
                if (rand()<P) { mask *= RP; }

				// choose refraction and update ray to refracted direction
                else { mask *= obj.c*TP; r = Ray(p, tdir); }
			}
		}
	}
	return acc;
}

void mainImage( out vec4 O, in vec2 I ) 
{
	// resolution shorthand
    vec3 R = iResolution;
	// initialize scene geometry
	initScene();
	// unique seed per pixel and frame to decorrelate samples
	seed = iTime + R.y * I.x / R.x + I.y / R.y;

    // camera UV coordinates in [-1, 1] range
    vec2 uv = 2. * I.xy / R.xy - 1.;
    // ray origin, controlled by mouse or default center position
	vec3 ro = vec3((2. * (iMouse.xy==vec2(0.)?.5*R.xy:iMouse.xy) / R.xy - 1.) * vec2(48., 40.) + vec2(50., 40.8), 169.);
	// camera forward vector
	vec3 cz = normalize(vec3(50., 40., 81.6) - ro);
	// camera right vector (world up assumption)
	vec3 cx = vec3(1., 0., 0.);
	// camera up vector, reorthogonalized against forward
	vec3 cy = normalize(cross(cx, cz)); cx = cross(cz, cy);

    // accumulated color for this pixel
    vec3 C = vec3(0.);

    // samples per frame
    for (int i = 0; i < SAMPLES + min(0, iFrame); ++i)
    {
        // ray direction through the current pixel with FOV scale
        vec3 rd = normalize(.53135 * (R.x / R.y*uv.x * cx + uv.y * cy) + cz);

		// trace path and accumulate radiance
		C += radiance( Ray( ro, rd));
    }

    // previous frame accumulation buffer
    vec4 accum = texture(iChannel0, I.xy / R.xy);

    // total sample count including previous frames
    float samples = accum.a + float(SAMPLES);

	// blend current result with history and store total sample count in alpha
    O = vec4((accum.rgb * accum.a + C)/samples, samples);
}

/*

This shader is an attempt at porting smallpt to GLSL.

See what it's all about here:
http://www.kevinbeason.com/smallpt/

The code is based in particular on the slides by David Cline.

Some differences:

- For optimization purposes, the code considers there is
  only one light source (see the commented loop)
- Russian roulette and tent filter are not implemented

I spent quite some time pulling my hair over inconsistent
behavior between Chrome and Firefox, Angle and native. I
expect many GLSL related bugs to be lurking, on top of
implementation errors. Please Let me know if you find any.

Update #1:
There is a bug in the next event estimation. If the scene
is modified into a furnace test, the result will be correct
when ENABLE_NEXT_EVENT_PREDICTION is undefined, but too
much energy ends up being added when it is defined.
Thanks @bernie_freidin for reporting this bug.

Update #2:
I've finally added accumulation over time. The accumulation
is absolute, and resizing is not detected. This means
switching to full screen will leave a thumbnail burnt at
the left corner.

--
Zavie

*/

// Play with the two following values to change quality.
// You want as many samples as your GPU can bear. :)
#define SAMPLES 4
#define MAXDEPTH 6
//#define ENABLE_NEXT_EVENT_PREDICTION

// Uncomment to see how many samples never reach a light source
//#define DEBUG

// Not used for now
#define DEPTH_RUSSIAN 2

#define PI 3.14159265359
#define DIFF 0
#define SPEC 1
#define REFR 2
#define GLOSSY 3 
#define NUM_SPHERES 9

// random seed state
float seed = 0.;
float rand() { return fract(sin(seed++)*43758.5453123); }

// ray defined by origin and direction
struct Ray { vec3 o, d; };

/* 
    sphere defined by:
    radius 
    position, emission, color
    material type

*/
struct Shape {
	float r;
	vec3 p, e, c;
	int refl;
};

// light source sphere used for next event prediction
Shape lightSourceVolume = Shape(20., vec3(50., 81.6, 81.6), vec3(12.), vec3(0.), DIFF);

// scene sphere array
Shape shape[NUM_SPHERES];

void initScene() 
{
	// left wall (red)
	shape[0] = Shape(1e5, vec3(-1e5+1., 4.8, 81.6),	vec3(0.), vec3(.75, .25, .25), DIFF);
	// right wall (blue)
	shape[1] = Shape(1e5, vec3( 1e5+99., 40.8, 81.6),vec3(0.), vec3(.25, .25, .75), DIFF);
	// back wall (white)
	shape[2] = Shape(1e5, vec3(50., 40.8, -1e5),		vec3(0.), vec3(.75), DIFF);
	// front wall (black/invisible)
	shape[3] = Shape(1e5, vec3(50., 40.8,  1e5+170.),vec3(0.), vec3(0.), DIFF);
	// floor (white)
	shape[4] = Shape(1e5, vec3(50., -1e5, 81.6),		vec3(0.), vec3(.75), DIFF);
	// ceiling (white)
	shape[5] = Shape(1e5, vec3(50.,  1e5+81.6, 81.6),vec3(0.), vec3(.75), DIFF);
	// left sphere (mirror)
	shape[6] = Shape(16.5, vec3(27., 16.5, 47.), 	vec3(0.), vec3(1.), DIFF);
	// right sphere (glass)
	shape[7] = Shape(16.5, vec3(73., 16.5, 78.), 	vec3(0.), vec3(0.165,0.800,0.118), GLOSSY);
	// area light (emissive sphere on ceiling)
	shape[8] = Shape(600., vec3(50., 681.33, 81.6),	vec3(12.), vec3(0.), DIFF);
}

float intersect(Shape s, Ray r) 
{
	// vector from ray origin to sphere center
	vec3 op = s.p - r.o;

	// dt holds the hit distance, epsilon avoids self-intersection
    float dt, epsilon = 1e-3;

    // b is the projection of op onto the ray direction
    float b = dot(op, r.d);

    // discriminant of the quadratic intersection equation
    float det = b * b - dot(op, op) + s.r * s.r;

	// no intersection if discriminant is negative, otherwise take square root
    if (det < 0.) return 0.; else det = sqrt(det);

	// return nearest positive intersection, or 0 if behind the ray
    return (dt = b - det) > epsilon ? dt : ((dt = b + det) > epsilon ? dt : 0.);
}

int intersect(Ray r, out float t, out Shape s, int avoid) 
{
	// no hit id
	int id = -1;
	// initialize t to a large value
	t = 1e5;
	// default sphere output
	s = shape[0];

	for (int i = 0; i < NUM_SPHERES; ++i) 
    { 
		// current shape to test
		Shape S = shape[i];
		// distance to current shape
		float d = intersect(S, r);

		// keep the closest valid hit, skipping the avoided shapes
		if (i != avoid && d!=0. && d<t) { t = d; id = i; s=S; }
	}
	// return index of closest hit shape, or -1 if none
	return id;
}

vec3 jitter(vec3 d, float phi, float sina, float cosa) 
{
	// build an orthonormal basis around direction d
	vec3 w = normalize(d), u = normalize(cross(w.yzx, w)), v = cross(w, u);

	// rotate sample direction by phi around w, using sine and cosine of polar angle
	return (u*cos(phi) + v*sin(phi)) * sina + w * cosa;
}

vec3 radiance(Ray r) 
{
	// accumulated light contribution
	vec3 acc  = vec3(0.);
	// throughput mask, multiplied at each bounce
	vec3 mask = vec3(1.);
	// last hit sphere index, -1 means none
	int id = -1;

    // number of bounces
	for (int depth = 0; depth < MAXDEPTH; ++depth) 
    {
		// hit distance
		float dt;
		// hit sphere
		Shape obj;

        // if no intersection, exit the loop
        if ((id = intersect(r, dt, obj, id)) < 0) break;

        // hit position along the ray
        vec3 p = r.o + r.d * dt;

        // surface normal at the hit point
        vec3 n = normalize(p - obj.p);
        // oriented normal, flipped to face the incoming ray
        vec3 nl = n * sign(-dot(n, r.d));

        // diffuse material
		if (obj.refl == DIFF) 
        {
			// random value for cosine-weighted hemisphere sampling
			float r2 = rand();
			// new diffuse bounce direction using cosine-weighted sampling
			vec3 d = jitter(nl, 2.*PI*rand(), sqrt(r2), sqrt(1. - r2));
			// direct light contribution (unused for now)
			vec3 e = vec3(0.);

			// energy weight for direct emission (1 = always include)
			float E = 1.;//float(depth==0);
			// accumulate emission and indirect light contribution
			acc += mask * obj.e * E + mask * obj.c * e;
			// attenuate throughput by surface color
			mask *= obj.c;
			// continue path in new diffuse direction
			r = Ray(p, d);
		} 
        // specular material
        else if (obj.refl == SPEC) 
        {
			// accumulate emission from specular surface
			acc += mask * obj.e;
			// attenuate throughput by surface color
			mask *= obj.c;
			// reflect ray around the surface normal
			r = Ray(p, reflect(r.d, n));
		} 
        else if (obj.refl == GLOSSY)
        {
            // roughness factor, 0 = mirror, higher = blurrier
            float roughness = 0.1;

            // reflect ray around normal
            vec3 reflected = reflect(r.d, nl);

            // jitter the reflected direction by roughness amount
            float r2 = rand();
            vec3 d = jitter(reflected, 2.*PI*rand(), roughness*sqrt(r2), sqrt(1. - roughness*roughness*r2));

            // accumulate emission
            acc += mask * obj.e;
            // attenuate throughput by surface color
            mask *= obj.c;
            // continue in jittered reflection direction
            r = Ray(p, normalize(d));
        }
        // refraction/glass material
        else 
        {
			// a is cosine of angle between normal and ray, ddn is its absolute value
			float a=dot(n,r.d), ddn=abs(a);

			// nc = air IOR, nt = glass IOR, nnt = ratio depending on ray direction
			float nc=1., nt=1.5, nnt=mix(nc/nt, nt/nc, float(a>0.));

			// cosine squared of the refracted angle, used to detect total internal reflection
            float cos2t=1.-nnt*nnt*(1.-ddn*ddn);

			// default to reflection
            r = Ray(p, reflect(r.d, n));

			// refraction is possible, no total internal reflection
            if (cos2t>0.) 
            {
				// compute the refracted ray direction
				vec3 tdir = normalize(r.d*nnt + sign(a)*n*(ddn*nnt+sqrt(cos2t)));

				// R0 is Fresnel reflectance at normal incidence (Schlick base), c is the view-dependent factor
                float R0=(nt-nc)*(nt-nc)/((nt+nc)*(nt+nc)),
					c = 1.-mix(ddn,dot(tdir, n),float(a>0.));

				// Re is Schlick Fresnel reflectance, P is Russian roulette probability, RP and TP are energy compensation weights
                float Re=R0+(1.-R0)*c*c*c*c*c,P=.25+.5*Re,RP=Re/P,TP=(1.-Re)/(1.-P);

				// Russian roulette: choose reflection
                if (rand()<P) { mask *= RP; }

				// choose refraction and update ray to refracted direction
                else { mask *= obj.c*TP; r = Ray(p, tdir); }
			}
		}
	}
	return acc;
}

void mainImage( out vec4 O, in vec2 I ) 
{
	// resolution shorthand
    vec3 R = iResolution;
	// initialize scene geometry
	initScene();
	// unique seed per pixel and frame to decorrelate samples
	seed = iTime + R.y * I.x / R.x + I.y / R.y;

    // camera UV coordinates in [-1, 1] range
    vec2 uv = 2. * I.xy / R.xy - 1.;
    // ray origin, controlled by mouse or default center position
	vec3 ro = vec3((2. * (iMouse.xy==vec2(0.)?.5*R.xy:iMouse.xy) / R.xy - 1.) * vec2(48., 40.) + vec2(50., 40.8), 169.);
	// camera forward vector
	vec3 cz = normalize(vec3(50., 40., 81.6) - ro);
	// camera right vector (world up assumption)
	vec3 cx = vec3(1., 0., 0.);
	// camera up vector, reorthogonalized against forward
	vec3 cy = normalize(cross(cx, cz)); cx = cross(cz, cy);

    // accumulated color for this pixel
    vec3 C = vec3(0.);

    // samples per frame
    for (int i = 0; i < SAMPLES + min(0, iFrame); ++i)
    {
        // ray direction through the current pixel with FOV scale
        vec3 rd = normalize(.53135 * (R.x / R.y*uv.x * cx + uv.y * cy) + cz);

		// trace path and accumulate radiance
		C += radiance( Ray( ro, rd));
    }

    // previous frame accumulation buffer
    vec4 accum = texture(iChannel0, I.xy / R.xy);

    // total sample count including previous frames
    float samples = accum.a + float(SAMPLES);

	// blend current result with history and store total sample count in alpha
    O = vec4((accum.rgb * accum.a + C)/samples, samples);
}

