// Play with the two following values to change quality.
// You want as many samples as your GPU can bear. :)
#define SAMPLES 4
#define MAXDEPTH 6
//#define ENABLE_NEXT_EVENT_PREDICTION

// Uncomment to see how many samples never reach a light source
//#define DEBUG

// Not used for now
#define DEPTH_RUSSIAN 2

#define PI 3.14159265359
#define DIFF 0
#define SPEC 1
#define REFR 2
#define GLOSSY 3 
#define NUM_SPHERES 9

#define MAX_STEPS 100
#define SURF_DIST 0.0001
#define MAX_DIST  40.0

#define T iTime

#define FAR 30.0

mat2 R2(float a) { return mat2(cos(a), -sin(a), sin(a), cos(a));}

float sdSphere(in vec3 p, float r) {
    return length(p) - r;
}

// random seed state
float seed = 0.;
float rand() { return fract(sin(seed++)*43758.5453123); }

// ray defined by origin and direction
struct Ray { vec3 o, d; };

/* 
    sphere defined by:
    radius 
    position, emission, color
    material type

*/
struct Shape {
	float r;
	vec3 p, e, c;
	int refl;
};

struct GhostMat {
    vec3  color;
    vec3  emission;
    int   refl;
    float roughness;
};

GhostMat ghostMaterial(float id, float mouthOcc)
{
    GhostMat m;
    m.roughness = 0.0;
    m.emission  = vec3(0.0);

    // area light
    if (id > 98.0) {
        m.color    = vec3(0);
        m.emission = vec3(12);
        m.refl     = DIFF;
        return m;
    }

    // room walls, floor, ceiling
    if (id > 1.5) {
        m.color = vec3(0.75);
        m.refl  = DIFF;
        return m;
    }

    // spike ball
    m.color     = vec3(0,0.9,0.6);
    m.refl      = GLOSSY;
    m.roughness = 0.05;
    return m;
}

float sdCircle(vec3 p)
{
    float phi = length(p) - 1.5;
    // displacement near center
    if(phi < 2.0)
    {
        vec3 new_p = p; float v;
        new_p.xz = R2(0.15) * new_p.xz;
        new_p /= length(new_p);
        new_p.x = atan(new_p.x, new_p.z); new_p.y = asin(new_p.y);
        v = ceil(4.0 * abs(new_p.y) / 1.57) / 4.0;
        v = 8.0 * sqrt(1.0 - v * v);
        new_p.x *= floor(v + 0.1);
        new_p.y *= 8.0;
        new_p = sin(new_p * 1.0);
        v = new_p.x * new_p.y;
        v *= v < 0. ? 0.0 : v;
        v += sin(new_p.y * new_p.x * 1.5) * 0.4 + 1.5;
        phi -= v * 0.231;
    }
    return phi;
}

vec3 map(vec3 p)
{
    // spike ball at center
    float d = sdCircle(p);

    // floor
    float floor    = p.y + 2.5;
    // ceiling
    float ceiling  = -p.y + 6.0;
    // back wall
    float backWall = p.z + 4.0;
    // left wall
    float leftWall = p.x + 5.0;
    // right wall
    float rightWall = -p.x + 5.0;

    // combine all room surfaces
    float room = min(min(min(min(floor, ceiling), backWall), leftWall), rightWall);
    if (room < d) return vec3(room, 2.0, 1.0);

    // area light on the ceiling, large and far enough to not be visible directly
    float lightDist = sdSphere(p - vec3(0, 5.8, 1), 2.5);
    if (lightDist < d) return vec3(lightDist, 99.0, 1.0);

    // spike ball id 1.0
    return vec3(d, 1.0, 1.0);
}

float intersect(Shape s, Ray r) 
{
	// vector from ray origin to sphere center
	vec3 op = s.p - r.o;

	// dt holds the hit distance, epsilon avoids self-intersection
    float dt, epsilon = 1e-3;

    // b is the projection of op onto the ray direction
    float b = dot(op, r.d);

    // discriminant of the quadratic intersection equation
    float det = b * b - dot(op, op) + s.r * s.r;

	// no intersection if discriminant is negative, otherwise take square root
    if (det < 0.) return 0.; else det = sqrt(det);

	// return nearest positive intersection, or 0 if behind the ray
    return (dt = b - det) > epsilon ? dt : ((dt = b + det) > epsilon ? dt : 0.);
}

// central differences normal for the SDF surface
vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)).x - map(p - vec3(e,0,0)).x,
        map(p + vec3(0,e,0)).x - map(p - vec3(0,e,0)).x,
        map(p + vec3(0,0,e)).x - map(p - vec3(0,0,e)).x
    ));
}

vec3 intersectScene(Ray r)
{
    // total marched distance
    float t = 0.0;

    for (int i = 0; i < MAX_STEPS; i++)
    {
        // current position along the ray
        vec3 res = map(r.o + r.d * t);

        // close enough to the surface, count as a hit
        if (res.x < SURF_DIST) return vec3(t, res.y, res.z);

        // step forward by the safe distance
        t += res.x;

        // exceeded maximum range, no hit
        if (t > MAX_DIST) break;
    }
    // no hit
    return vec3(-1.0);
}



vec3 jitter(vec3 d, float phi, float sina, float cosa) 
{
	// build an orthonormal basis around direction d
	vec3 w = normalize(d), u = normalize(cross(w.yzx, w)), v = cross(w, u);

	// rotate sample direction by phi around w, using sine and cosine of polar angle
	return (u*cos(phi) + v*sin(phi)) * sina + w * cosa;
}


// simple dark sky with a faint moon highlight
vec3 sky(vec3 rd)
{
    // dark purple background
    vec3 bg   = vec3(0.1);
    // moon highlight in the upper direction
    float moon = pow(max(0.0, dot(rd, normalize(vec3(0.3, 1, 0.2)))), 32.0);
    return bg + vec3(100) * moon * 2.0;
}

vec3 radiance(Ray r)
{
    // accumulated light contribution
    vec3 acc  = vec3(0.);
    // throughput mask, multiplied at each bounce
    vec3 mask = vec3(1.);

    // number of bounces
    for (int depth = 0; depth < MAXDEPTH; ++depth)
    {
        // march the ray against the ghost SDF
        vec3 hit = intersectScene(r);

        // no hit, sample sky and terminate
        if (hit.x < 0.0)
        {
            acc += mask * sky(r.d);
            break;
        }

        // hit position along the ray
        vec3 p  = r.o + r.d * hit.x;
        // surface normal at the hit point
        vec3 n  = calcNormal(p);
        // oriented normal, flipped to face the incoming ray
        vec3 nl = n * sign(-dot(n, r.d));

        // resolve material from sdfId and mouth occlusion
        GhostMat mat = ghostMaterial(hit.y, hit.z);

        // accumulate emission
        acc += mask * mat.emission;

        // diffuse material
        if (mat.refl == DIFF)
        {
            // random value for cosine-weighted hemisphere sampling
            float r2 = rand();
            // new diffuse bounce direction using cosine-weighted sampling
            vec3 d = jitter(nl, 2. * PI * rand(), sqrt(r2), sqrt(1. - r2));
            // attenuate throughput by surface color
            mask *= mat.color;
            // offset origin to avoid self-intersection
            r = Ray(p + nl * 0.5, d);
        }
        // specular material
        else if (mat.refl == SPEC)
        {
            // attenuate throughput by surface color
            mask *= mat.color;
            // reflect ray around the surface normal
            r = Ray(p + nl * 0.002, reflect(r.d, n));
        }
        // glossy material
        else if (mat.refl == GLOSSY)
        {
            // reflect ray around normal
            vec3 reflected = reflect(r.d, nl);

            // jitter the reflected direction by roughness amount
            float r2 = rand();
            vec3 d = jitter(reflected, 2. * PI * rand(), mat.roughness * sqrt(r2), sqrt(1. - mat.roughness * mat.roughness * r2));

            // attenuate throughput by surface color
            mask *= mat.color;
            // continue in jittered reflection direction
            r = Ray(p + nl * 1., normalize(d));
        }
        // refraction/glass material
        else
        {
            // a is cosine of angle between normal and ray, ddn is its absolute value
            float a = dot(n, r.d), ddn = abs(a);

            // nc = air IOR, nt = glass IOR, nnt = ratio depending on ray direction
            float nc = 1., nt = 1.5, nnt = mix(nc / nt, nt / nc, float(a > 0.));

            // cosine squared of the refracted angle, used to detect total internal reflection
            float cos2t = 1. - nnt * nnt * (1. - ddn * ddn);

            // default to reflection
            r = Ray(p, reflect(r.d, n));

            // refraction is possible, no total internal reflection
            if (cos2t > 0.)
            {
                // compute the refracted ray direction
                vec3 tdir = normalize(r.d * nnt + sign(a) * n * (ddn * nnt + sqrt(cos2t)));

                // R0 is Fresnel reflectance at normal incidence (Schlick base), c is the view-dependent factor
                float R0 = (nt - nc) * (nt - nc) / ((nt + nc) * (nt + nc)),
                      c  = 1. - mix(ddn, dot(tdir, n), float(a > 0.));

                // Re is Schlick Fresnel reflectance, P is Russian roulette probability, RP and TP are energy compensation weights
                float Re = R0 + (1. - R0) * c * c * c * c * c, P = .25 + .5 * Re, RP = Re / P, TP = (1. - Re) / (1. - P);

                // Russian roulette: choose reflection
                if (rand() < P) { mask *= RP; }

                // choose refraction and update ray to refracted direction
                else { mask *= mat.color * TP; r = Ray(p, tdir); }
            }
        }
    }
    return acc;
}

void mainImage( out vec4 O, in vec2 I ) 
{
    vec3 R = iResolution;
    // unique seed per pixel and frame to decorrelate samples
    seed = iTime + R.y * I.x / R.x + I.y / R.y;

    // camera UV coordinates
    vec2 uv = 2. * I.xy / R.xy - 1.;
    uv.x *= R.x / R.y;

    // camera target
    vec3 ta = vec3(0);
    // ray origin
    vec3 ro = vec3(0,0,5);

    // camera forward vector
    vec3 cz = normalize(ta - ro);
    // camera right vector
    vec3 cx = normalize(cross(vec3(0, 1, 0), cz));
    // camera up vector, reorthogonalized against forward
    vec3 cy = normalize(cross(cz, cx));

    // accumulated color for this pixel
    vec3 C = vec3(0.);

    // samples per frame
    for (int i = 0; i < SAMPLES + min(0, iFrame); ++i)
    {
        // ray direction through the current pixel with FOV scale
        vec3 rd = normalize(uv.x * cx + uv.y * cy + 1.6 * cz);

        // trace path and accumulate radiance
        C += radiance(Ray(ro, rd));
    }

    // previous frame accumulation buffer
    vec4 accum = texture(iChannel0, I.xy / R.xy);

    // total sample count including previous frames
    float samples = accum.a + float(SAMPLES);

    // blend current result with history and store total sample count in alpha
    O = vec4((accum.rgb * accum.a + C)/samples, samples);
}

