float dist(vec2 p, vec2 ap, vec2 ab, vec2 a)
{
    float dt = dot(ap, ab) / dot(ab, ab);
    dt = clamp(dt,0.,1.);
    vec2 closest = a + ab * dt;

    return length(p - closest);
}

float sdOne(vec2 p)
{
    p.x = abs(p.x);
    vec2 a = vec2(0,-0.5);
    vec2 b = vec2(0.5);
    vec2 c = vec2(0,0.5);

    vec2 ap = p - a, ab = b - a, bp = p - b, bc = c - b;

    float d = dist(p, ap, ab, a);
    float d1 = dist(p, bp, bc, b);

    float d3 = min(d,d1) - 0.34;

    return d3;
}

