    float dt = dot(ap, ab) / dot(ab, ab);

    // without this line it will stretched on to the end of the screen
    dt = clamp(dt,0.,1.);

    // this is the paremetric equation from the point A and B
    // at dt = 0 you are at a 
    // at dt = 1 you've walked the full vector
    // at dt = 0.5 you're half way
    vec2 closest = a + ab * dt;

    // the vector from the closest point to the pixel
    return length(p - closest);
