float sdOne(vec2 p)
{
    // mirror the x value from uv
    p.x = abs(p.x);

    // our points 
    // A is at the bottom
    vec2 a = vec2(0,-0.5);
    // B is right 
    vec2 b = vec2(0.5);
    // C is in the top middle
    vec2 c = vec2(0,0.5);

    // length of the vectors AB = B - A and so on
    vec2 ap = p - a, ab = b - a, bp = p - b, bc = c - b;

    // This takes the dot product so we get the projection 
    // the point is to have the vector AB and take the dot product
    // of the points UV on point A of AB and so on
    float d = dist(p, ap, ab, a);
    float d1 = dist(p, bp, bc, b);

    // we add the edges
    float d3 = min(d,d1);

    // take the determinant, the formula is very simple 
    // det(A,B) = A.x*B.y - A.y*B.x

    float s1 = det(ab, ap);
    float s2 = det(bc, bp);

    // check if we are inside or outside the shape 
    return -sign(min(s1,s2)) * d3;
}

