// iq 
// https://iquilezles.org/articles/distfunctions/
float sdBox(vec3 p)
{ 
    vec3 b = vec3(1.6);
    vec3 d = abs(p) - b;
    return length(max(d,0.0)) + min(max(d.x,max(d.y,d.z)),0.0);
}

// Rotation
mat2 R2(float a){ return mat2(cos(a), -sin(a), sin(a), cos(a));}

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;

    float T = iTime;

    // init
    vec3 ro = vec3(0,0, -4);
    vec3 rd = normalize(vec3(uv, 1));

    vec3 col = vec3(mix(vec3(0), vec3(0,0.1,0.1), -uv.y + 0.1));

    float dt = 0.;

    for(int i=0; i<80 && dt < 30.; i++)
    {
        // Ray position
        vec3 p = ro + rd * dt;

        // rotate
        p.xz *= R2(iTime * 0.1);

        vec3 offset = vec3(cos(T * 5.) * .5,sin(T * 7.) * .5,cos(T * 2.) * .9);
        // sdfs
        float d1 = sdBox(p);
        float d2 = length(p + offset) - 0.9;

        // glow
        col += vec3(1, 0, 0.2) / (80. + d1  * 10.);
        col += vec3(0, 0.5, 1) / (40. + d2  * 40.);

        // march by minimum so we don't skip any surface
        dt += max(min(d2, d1), 0.05);
    }

    O = vec4(col, 1.0);
    //O = vec4(tanh(col), 1.0);
}

