void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
	fragColor = vec4(pow(clamp(texture(iChannel0, fragCoord.xy / iResolution.xy).rgb, 0., 1.), vec3(1./2.2)), 1.);
}

