// Rotation
mat2 R2(float a){ return mat2(cos(a), -sin(a), sin(a), cos(a));}

float intersect(vec3 p, vec3 ro, vec3 rd, float r) 
{
	// vector from ray origin to sphere center
	vec3 op = p - ro;

	// dt holds the hit distance, epsilon avoids self-intersection
    float dt, epsilon = 1e-3;

    // b is the projection of op onto the ray direction
    float b = dot(op, rd);

    // discriminant of the quadratic intersection equation
    float det = b * b - dot(op, op) + r * r;

	// no intersection if discriminant is negative, otherwise take square root
    return det;
}

float des(vec3 p, vec3 ro, vec3 rd, float r) 
{
	// vector from ray origin to sphere center
	vec3 op = p - ro;

	// dt holds the hit distance, epsilon avoids self-intersection
    float dt, epsilon = 1e-3;

    // b is the projection of op onto the ray direction
    float b = dot(op, rd);

    // discriminant of the quadratic intersection equation
    float det = b * b - dot(op, op) + r * r;

	if (det < 0.) return 0.; else det = sqrt(det);
    return (dt = b - det) > epsilon ? dt : ((dt = b + det) > epsilon ? dt : 0.);
}


void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;

    // init
    vec3 ro = vec3(0,0, -4);
    vec3 rd = normalize(vec3(uv, 1));
    // color
    vec3 col = vec3(0);

    // sphere intersect with a radius 
    float r = 2.5;
    float d = intersect(vec3(0), ro, rd, r);

    // did we hit the shape
    // return the discriminant
    float hit = des(vec3(0), ro, rd, r);

    // normal
    vec3 n = (ro + rd * hit) / r;

    // diffuse
    vec3 diff = max(n * vec3(2,1,1),0.0);

    // exagerate the diffuse
    col += diff * 3.;

    // we can use the intersect to color the shere 
    // animate the weight
    float w = (max(d,0.0) / (r*r)) * sin(iTime * 2.) * 1.9 ;
    col+= mix(vec3(0,0.5,0.5), vec3(1,0,0), w);

    // this is to just give some background
    if(d < 0.)
        col = vec3(mix(vec3(0), vec3(0,0.1,0.1), -uv.y + .0));

    O = vec4(col, 1.0);
    //O = vec4(tanh(col), 1.0);
}

