#define NUM_SPHERES 9

struct Deter{
    float dis, tn, tf;
    bool hit;
};

// Rotation
//mat2 R2(float a){ return mat2(cos(a), -sin(a), sin(a), cos(a));}
void intersect(vec3 c, vec3 ro, vec3 rd, float r, out Deter d)
{
    float dt = 0.0;
    // the main formulas is 
    // circle: || p - c || = r*r

    // The ray is
    // || (ro + rd(dt)) - c) || ^2 = r * r
    vec3 op = c - ro;

    // || rd(dt) - op || ^2 = r * r
    // expand 
    // dt^2 - 2dt(rd * op) + ||op||^2 - r^2

    // we solve for
    // a(dt^2) + b(dt) + c = 0

    // a = 1
    // b = 2(rd * op)
    float b = dot(op, rd);
    // c = ||op||^2 - r*r

    // we are left with 
    float dis = b * b  - dot(op,op) + r * r; 

    if(dis < 0.0) 
    {
        d.hit = false;
        d.tn = 0.0;
        d.tf = 0.0;
    } else {
        d.dis = dis;
        dis = sqrt(dis);

        d.tn = b - dis;
        d.tf = b + dis;
        d.hit = true;
    }
}

