    float T = iTime * 10.5;

    vec3 ta = vec3(0.0, 0.0, 0.0); 
    vec3 ro = ta + vec3(4.0*cos(0.1*T), 2.0, 4.0*sin(0.1*T)); 

    mat3 ca = setCamera(ro, ta, 0.0);

    vec3 rd = ca * normalize(vec3(uv, 1));
    // color
    vec3 col = vec3(0);

    // sphere intersect with a radius 
    float r = 1.0;

    vec3 shape[NUM_SPHERES] = vec3[](
        vec3(0   ,1  ,0 ),
        vec3(1   ,2  ,1 ),
        vec3(2.  ,0  ,2 ),
        vec3(0   ,-1 ,3 ),
        vec3(1   ,-2 ,0 ),
        vec3(2   ,-1 ,-1),
        vec3(0   ,2  ,-2),
        vec3(-1  ,-1 ,-3),
