    for(int i=0; i<NUM_SPHERES; i++)
    {
        intersect(shape[i], ro, rd, r, d[i]);
        if(d[i].hit)
        {
               vec3 n = ((ro + rd * d[i].tn) - shape[i] ) / r;
               col += n * 0.5 + 0.5;
        }
    }

    //O = vec4(col, 1.0);
    O = vec4(tanh(col), 1.0);
}

