void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;

    // init
    float T = iTime * 4.5;

    // camera, ray origin, direction setup
    vec3 ta = vec3(0,0,0); 
    vec3 ro = ta + vec3(4.0*cos(0.1*T), 2.0, 4.0*sin(0.1*T) -1.); 
    mat3 ca = setCamera(ro, ta, 0.);
    vec3 rd = ca * normalize(vec3(uv, 1));

    // color
    vec3 col = vec3(0);

    // sphere intersect with a radius 
    float r = .6;

    // Array of sphere positions
    vec3 shape[NUM_SPHERES] = vec3[](
        // Front Plane (z = -1)
        vec3(-1.5, -1.0, -2.0), vec3(0.0, -1.0, -1.0), vec3(1.5, -1.0, -2.0),
        vec3(-1.5,  2.0, -2.0), vec3(0.0,  2.0, -1.0), vec3(1.5,  2.0, -2.0),

        // Back Plane (z = 1)
        vec3(-1.5, -1.0,  2.0), vec3(0.0, -1.0,  1.0), vec3(1.5, -1.0,  2.0),
        vec3(-1.5,  2.0,  1.0), vec3(0.0,  2.0,  1.0), vec3(1.5,  2.0,  2.0)
    );

    // Array of the constructor
    Deter d[NUM_SPHERES];

    for(int i=0; i<NUM_SPHERES; i++)
        intersect(shape[i], ro, rd, r, d[i]);


    // Array of spheres
    for(int i=0; i<NUM_SPHERES; i++)
    {
        // we hit a shape
        if(d[i].hit)
        {
           // now we can color
           vec3 p = ro + rd * d[i].tn;
           vec3 n = (p - shape[i] ) / r;

           // bounce origin 
           vec3 p2 = p + .7 * n;

           // bounce direction 
           vec3 w = normalize(n + rand3() * 2. - 1.); 
           //col += n * 0.5 + 0.5;

           vec3 albedo = vec3(0,0.5,0.9) * 20.;

           bool hit2 = false;
           // we need to loop over the spheres again so we can create a random 
           // ray direction
           // does this bounce loop hit any spheres in the scene ?
           for(int j=0; j<NUM_SPHERES; j++)
           {
               // then we call intercept again with a new origin and bounce direction
               intersect(shape[j], p2, w, r, d[j]);

               // then we check if we hit something so we can color it
               if(d[j].hit)
                   hit2 = true;
            }

            if(hit2)
                // if we hit then that's a shadow
                col += vec3(4);
            else 
               // if we didn't hit anything then we pain the spheres with the color 
               // of the sky
               col += albedo *  mix(vec3(1), vec3(0,0.5,0.7), w.y * .5 + 0.5);
               // col += albedo * bright * l;
        }
    }

    vec4 accum = texture(iChannel0, I.xy / iResolution.xy) * .99;

    // total sample count including previous frames
    float samples = accum.a + float(SAMPLES);

	// blend current result with history and store total sample count in alpha
    O = vec4((accum.rgb * accum.a + (col* 3.0))/samples, samples);
}

