// Discriminant or hit points 
struct Deter{
    float dis, tn, tf;
    bool hit;
};

// I should setup a struct for the shapes that way we can have a sphere 
// and also a square 

/*
      This computes the discriminant, its a cheaper way then raymarch 
      to find the hit point, near or far from the shape 
      this will only work with spheres.

      squares, triangles have another way to compute it maybe I'll do that later

      For complex shapes then we'll need a ray march
*/
void intersect(vec3 c, vec3 ro, vec3 rd, float r, out Deter d)
{
    float dt = 0.0;
    // the main formulas is 
    // circle: || p - c || = r*r

    // The ray is
    // || (ro + rd(dt)) - c) || ^2 = r * r
    vec3 op = c - ro;

    // || rd(dt) - op || ^2 = r * r
    // expand 
    // dt^2 - 2dt(rd * op) + ||op||^2 - r^2

    // we solve for
    // a(dt^2) + b(dt) + c = 0

    // a = 1
    // b = 2(rd * op)
    float b = dot(op, rd);
    // c = ||op||^2 - r*r

    // we are left with 
    float dis = b * b  - dot(op,op) + r * r; 

    if(dis < 0.0) 
    {
        d.hit = false;
        d.tn = 0.0;
        d.tf = 0.0;
    } else {
        d.dis = dis;
        dis = sqrt(dis);

        d.tn = (b - dis); // if tn < 0 ray origin inside the sphere
        d.tf = (b + dis); // if tf < 0 sphere entierly behind the re
        d.hit = true;
    }
}


vec3 jitter(vec3 d, float phi, float sina, float cosa) 
{
	// build an orthonormal basis around direction d
	vec3 w = normalize(d), u = normalize(cross(w.yzx, w)), v = cross(w, u);

	// rotate sample direction by phi around w, using sine and cosine of polar angle
	return (u*cos(phi) + v*sin(phi)) * sina + w * cosa;
}


// camera setup
mat3 setCamera(vec3 ro, vec3 ta, float cr )
{
    vec3 cw = normalize(ta-ro);
    vec3 cp = vec3(sin(cr), cos(cr),0.0);
    vec3 cu = normalize( cross(cw,cp) );
    vec3 cv =          ( cross(cu,cw) );
    return mat3( cu, cv, cw );
}

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    uv.y += iTime * .15;
    uv.x += .5;
    uv = vec2(mod(uv, 1.2) - .5);
    uv *= 1.5;

    rngState = uint(I.x) + uint(I.y) * uint(iResolution.x) + uint(iTime * 1000.0) * 1999u;
    // init
    float T = iTime * 5.5;

    // camera, ray origin, direction setup
    vec3 ta = vec3(0,0.5,0); 
    vec3 ro = ta + vec3(4.0*cos(0.1*T), 3, 4.0*sin(0.1*T)); 
    mat3 ca = setCamera(ro, ta, 1.);
    vec3 rd = ca * normalize(vec3(uv, 1));

    // color
    vec3 col = vec3(0);

    // sphere intersect with a radius 
    float r = 1.;

    float rough = 0.01;

    // boncing effect
    float fx1 = sin(2.5 * iTime) * 0.2 - 1.;
    float off = fx1 + .8;
    // Array of sphere positions
    vec3 shape[NUM_SPHERES] = vec3[](
        // 1
        vec3(0.0, 0.0, 0.0),
        vec3( r + off , 0.0 , r + off ),
        vec3(-r - off, 0.0,  r + off ),
        vec3(-r - off, 0.0, -r - off ),
        vec3( r + off, 0.0, -r - off ),
        vec3( 0 , r + off,  0  ),
        vec3( 0 , -r - off,  0  )
    );

    // Array of the constructor
    Deter d[NUM_SPHERES];

    // Array of spheres
    for(int i=0; i<NUM_SPHERES + min(0, iFrame); i++)
    {
        // setup the intersection of the spheres 
        intersect(shape[i], ro, rd, r, d[i]);
        // we hit a shape
        // and lets use the result from the discriminant
        if(d[i].hit)
        //if(d[i].hit)
        {

           // now we can color
           vec3 p = ro + rd * d[i].tn;

           // play ground
           //float offset = .0;
           //p = vec3(mod(p, offset) - offset * 0.5);
           vec3 n = (p - shape[i] ) / r;

           vec3 reflected = reflect(rd, n);
           vec3 d2 = jitter(reflected, 2. * PI * rand(), rough * sqrt(r), sqrt(1. - rough * rough * r));

           // bounce origin 
           vec3 p2 = p + .001 * n; //* normalize(reflected); // ??? how should I add this 

           // bounce direction 
           vec3 w = normalize(d2); 

           vec3 albedo = vec3(3,1.,2.9) * 1.;

           bool hit2 = false;
           // we need to loop over the spheres again so we can create a random 
           // ray direction
           // does this bounce loop hit any spheres in the scene ?
           for(int j=0; j<NUM_SPHERES; j++)
           {
               // don't self shadow
               if(j == i) continue; 
               // then we call intercept again with a new origin and bounce direction
               intersect(shape[j], p2, w, r, d[j]);

               // then we check if we hit something so we can color it
               if(d[j].hit)
                   hit2 = true;
            }

            if(hit2)
                // if we hit then that's a shadow
                col += vec3(0);
            else 
                // if we didn't hit anything then we pain the spheres with the color 
                // of the sky
                col += albedo *  mix(vec3(0), vec3(0,.9,0.6) *4., w.y * .5+.5);
        }
    }

    vec4 accum = texture(iChannel0, I.xy / iResolution.xy) * .8;

    // total sample count including previous frames
    float samples = accum.a + float(SAMPLES);

	// blend current result with history and store total sample count in alpha
    O = vec4((accum.rgb * accum.a + (col* 10.0))/samples, samples);
}

