// Rotation
//mat2 R2(float a){ return mat2(cos(a), -sin(a), sin(a), cos(a));}
void intersect(vec3 c, vec3 ro, vec3 rd, float r, out Deter d)
{
    float dt = 0.0;
    // the main formulas is 
    // circle: || p - c || = r*r

    // The ray is
    // || (ro + rd(dt)) - c) || ^2 = r * r
    vec3 op = c - ro;

    // || rd(dt) - op || ^2 = r * r
    // expand 
    // dt^2 - 2dt(rd * op) + ||op||^2 - r^2

    // we solve for
    // a(dt^2) + b(dt) + c = 0

    // a = 1
    // b = 2(rd * op)
    float b = dot(op, rd);
    // c = ||op||^2 - r*r

    // we are left with 
    float dis = b * b  - dot(op,op) + r * r; 

    if(dis < 0.0) 
    {
        d.hit = false;
        d.tn = 0.0;
        d.tf = 0.0;
    } else {
        d.dis = dis;
        dis = sqrt(dis);

        d.tn = b - dis;
        d.tf = b + dis;
        d.hit = true;
    }
}

mat3 setCamera(vec3 ro, vec3 ta, float cr )
{
    vec3 cw = normalize(ta-ro);
    vec3 cp = vec3(sin(cr), cos(cr),0.0);
    vec3 cu = normalize( cross(cw,cp) );
    vec3 cv =          ( cross(cu,cw) );
    return mat3( cu, cv, cw );
}

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;

    rngState = uint(I.x) + uint(I.y) * uint(iResolution.x) + uint(iTime * 1000.0) * 1999u;

    initScene();
    // init
    float T = iTime * 0.;

    vec3 ta = vec3(0,0,0); 
    vec3 ro = vec3(0,0,5);//ta + vec3(4.0*cos(0.1*T), 0, 4.0*sin(0.1*T)); 

    mat3 ca = setCamera(ro, ta, 0.0);

    vec3 rd = normalize(vec3(uv * 0.7, -1));
    // color
    vec3 col = vec3(0);

    // throughput mask, multiplied at each bounce
    vec3 mask = vec3(1.);

    Deter d[NUM_SPHERES];



    for (int depth = 0; depth < 6; ++depth) 
    {

        float tmin = 1e5;
        int imin = -1;

        for(int i=0; i<NUM_SPHERES + min(0, iFrame); i++) 
        {
            Shape s = shape[i];

            // we find the intersection of when the
            // ray is near the surface = tn
            // ray is far from the surface = tf
            intersect(s.p, ro, rd, s.r, d[i]);

            // If we hit a shape and ray is less then a big number
            // then asign tmin = the closest ray
            if(d[i].hit && d[i].tn < tmin )
            {
               tmin = d[i].tn;
               // asign the index of the sphere to what we hit?
               imin = i;
            }
        }

        // Now we only want to see the shapes that we hit
        if(imin != -1)
        {
            // we only wanna see the shapes we hit for coloring?
            Shape s = shape[imin];

            // then the distance travel is = to the closest ray
            vec3 p = ro + rd * d[imin].tn;

            // we take the norm of the sphere
            vec3 n = (p - s.p) / s.r;

            // We color with the accumulation of the mask and the energy
            col += mask * s.e;

            // our 2nd position is p + a delta * the norm 
            vec3 p2 = p + .001 * n;

            // we have our random state 
            vec3 ran = rand3() * 3. - 1.;

            // Reject the sample outside the unit norm
            if( length(ran) > 1.0)
                ran = vec3(0);

            // Bounce direction 
            vec3 w = normalize(n + ran);

            // attenuating the through by the surface albedo
            mask *= s.albedo;

            // occlusion check
            bool hit2 = false;
            for(int j=0; j<NUM_SPHERES; j++)
            {
                // avoid self intersection
                if(j == imin) continue;
                // grab the intersection of p2 
                intersect(shape[j].p, p2, w, shape[j].r, d[j]);
                // if we hit something then we should have a shadow
                if(d[j].hit) hit2 = true;
            }

            // not occluded
            if(!hit2)
                col += mix(vec3(0), vec3(0,0.8,0.7)*1., w.y*.5+.5);
            else 
            // occluted bounce 
                col += mask * mix(vec3(1), vec3(0), w.y * .5 + 0.5);

            ro = p2, rd = w;
        }
    }

    vec4 accum = texture(iChannel0, I.xy / iResolution.xy) * .8;

    // total sample count including previous frames
    float samples = accum.a + float(SAMPLES);

	// blend current result with history and store total sample count in alpha
    O = vec4((accum.rgb * accum.a + (col* 3.0))/samples, samples);
}

