mat2 R2(float a){ return mat2(cos(a), -sin(a), sin(a), cos(a));}

// Hash function: Takes a vec2, spits out a float. Useful for randomness.
float hash21(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// State is carried as a uint and evolved with PCG
// uknown where It came from 
uint rngState;

uint pcgHash(uint s){
    s = s * 747796405u + 2891336453u;
    s = ((s >> ((s >> 28u) + 4u)) ^ s) * 277803737u;
    return (s >> 22u) ^ s;
}
float rand01(){
    rngState = pcgHash(rngState);
    return float(rngState) * (1.0/4294967296.0);
}
vec2 rand2(){ return vec2(rand01(), rand01()); }
vec3 rand3(){ return vec3(rand01(), rand01(), rand01()); }


