// https://iquilezles.org/articles/distfunctions/
float sdCappedCylinder( vec3 p, float r, float h )
{
  vec2 d = abs(vec2(length(p.xz),p.y)) - vec2(r,h);
  return min(max(d.x,d.y),0.0) + length(max(d,0.0));
}

// https://iquilezles.org/articles/distfunctions/
float smin( float a, float b, float k )
{
    k *= 4.0;
    float h = max(k-abs(a-b),0.0);
    return min(a, b) - h*h*0.25/k;
}

// Similar idea from @neozhaoliang
// https://www.shadertoy.com/view/3tccWf
float map(vec3 p)
{ 
    p.xy *= mat2(0,1,-1,0);
    p.z -= iTime * 1.1;
    float offset = 3.;
    vec3 p1 = vec3(
        mod(p.x, offset) - offset * 0.5,
        mod(p.y, offset) - offset * 0.5,
        mod(p.z, 1.5) - 1.5 * 0.5
        );
    float d = 1e5;

    vec3 pts[8];
    pts[0] = vec3( 1, 1, -1);
    pts[1] = vec3(-1,-1, -1);
    pts[2] = vec3(-1, 1,-1);
    pts[3] = vec3( 1,-1,-1);

    pts[4] = vec3(-1, -1, 1);
    pts[5] = vec3(-1, 1, 1);
    pts[6] = vec3(1, 1, 1);
    pts[7] = vec3( 1,-1,1);

    for(int i = 0; i < 8; i++)
    {
         // all edges come from center
        vec3 a = vec3(0);       
        vec3 b = pts[i];

        // edge direction
        vec3 h = normalize(b - a);

        vec3 u = vec3(0,1,0);

        // perpendicular to edge 
        vec3 x = normalize(cross(h, u));

        // 3rd axis completes the frame
        vec3 y = cross(h, x);

        // rotate p into the frame
        mat3 R = mat3(x, y, h);
        vec3 q = (p1 - (a+b)*0.5) * R;
        float L = length(b - a) * .4;
        d = min(d, sdCappedCylinder(q, 0.1, L));
    }

    d = smin(d, length(p1 + vec3(0,-1.5,0)) - 0.5, 0.1);
    d = smin(d, length(p1 + vec3(0,1.5,0)) - 0.5, 0.1);
    return d;
}


vec3 calcNormal(vec3 p)
{
    float e = 0.1;
    return normalize(vec3(
        map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
        map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
        map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
    ));
}

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;

    // init
    vec3 ro = vec3(0.0, 0.0, 3.0);
    vec3 rd = normalize(vec3(uv, -1.0));

    vec3 col = vec3(0.0);

    // Raymarching 
    float dt = 0.0; 
    for(int i=0; i<80; i++)
    {
        float d = map(ro + rd * dt);
        dt += d;                         
        if(abs(d) < 0.001 || dt > 30.0) break;
    }

    // Coloring, norms, light, fog
    if(dt < 30.0)
    {
        vec3 p = ro + rd * dt;

        vec3 n = calcNormal(p);

        col = n * 0.5 + 0.5;

        //col = mix( col, vec3(0.0), 1.0-exp( -0.0005*dt.x*dt.x*dt.x) );
        col = mix(col, vec3(0), 1.0 - exp(-0.003 * dt * dt * dt));
    }


    O = vec4(col, 1.0);
}

