    p.x -= 1.2;
    p.y += iTime * 0.1;
    float offset = 1.8;
    float off2 = 0.5;

    //if(mod(iTime, 10.0) < 5.){
#if SHAPE == 1    
        off2 = 0.0;
        p.x += 0.2;
#endif 

    vec3 p1 = vec3(
        mod(p.x, offset + off2) - (offset+ off2) * 0.5,
        mod(p.y, 1.8 + off2) - (1.8 + off2)* 0.5,
        mod(p.z, 1.5 + off2) - (1.5 + off2) * 0.5
        );
    float d = 1e5;

    vec3 pts[8];
    pts[0] = vec3( 1, 1, -1);
    pts[1] = vec3(-1,-1, -1);
    pts[2] = vec3(-1, 1, -1);
    pts[3] = vec3( 1,-1, -1);

    pts[4] = vec3(-1, -1, 1);
    pts[5] = vec3(-1,  1, 1);
    pts[6] = vec3( 1,  1, 1);
    pts[7] = vec3( 1, -1, 1);

    for(int i = 0; i < 8; i++)
    {
         // all edges come from center
        vec3 a = vec3(0);       
        vec3 b = pts[i];

        // edge direction
        vec3 h = normalize(b - a);

        vec3 u = vec3(0,0,1);

        // perpendicular to edge 
        vec3 x = normalize(cross(h, u));

        // 3rd axis completes the frame
        vec3 y = cross(h, x);

        // rotate p into the frame
        mat3 R = mat3(x, y, h);
        vec3 q = (p1 - (a+b)*0.5) * R;
        float L = length(b - a) * .4;
        d = min(d, sdCappedCylinder(q, 0.08, L));
    }

    d = smin(d, length(p1 + vec3( 0.7, -0.9,0.1)) - 0.2, 0.1);
    d = smin(d, length(p1 + vec3( 0.7,  0.9,0.1)) - 0.2, 0.1);
    d = smin(d, length(p1 + vec3(-0.7, 0.9,0.1)) - 0.2, 0.1);
    d = smin(d, length(p1 + vec3(-0.7,-0.9,0.1)) - 0.2, 0.1);
    return d;
}


