vec3 render(vec3 ro, vec3 rd)
{
    vec3 col = vec3(0.0);

    // Raymarching 
    float dt = 0.0; 
    for(int i=0; i<80; i++)
    {
        float d = map(ro + rd * dt);
        dt += d;                         
        if(abs(d) < 0.01 || dt > 30.0) break;
    }

    // Coloring, norms, light, fog
    if(dt < 30.0)
    {
        vec3 p = ro + rd * dt;

        vec3 norm = calcNormal(p); 

        norm = doBumpMap(p, norm, 1.025); 

        float NoV = clamp(dot(norm, -rd), 0.0, 1.0);

        float fx = sin(iTime) * 1.5 + 7.5;

        float rim = pow(1.0 - NoV,3.0) * fx;


        vec3 albedo = palette(norm.y * .1, vec3(0.5), vec3(0.95), vec3(1.0), vec3(0.9, 0.3, 0.1));

        // Light position in world space
        vec3 lightPos = ro + vec3(0, 0.9, 5);
        vec3 L = lightPos - p;
        float distlpsp = max(length(L), 0.001);
        L /= distlpsp;

        // Light attenuation based on distance
        float atten = 1.0 / (1.0 + distlpsp * .525);

        // Lighting terms 
        float ambience = .5; 
        float diff = max(dot(norm, L), .0);

        // Specular with different colors based on objId
        vec3 specColor =  vec3(0.871);
        float spec = pow(max(dot(reflect(-L, norm), -rd), 0.0), 32.0);

        // Base texture + separate specular
        col = albedo * (diff + ambience) + specColor * spec;

        // Apply attenuation, shading, AND ambient occlusion
        col *= atten * (rim * vec3(1)); 

        float hi = abs(mod(dt/0.3665 - iTime*2.3, 7.) - 5.) *2.15;
        vec3 chargeCol = vec3(0.3) * col * .1 / (.01061 + hi * hi * .02);
        col +=  mix(chargeCol.yxz, chargeCol,col);

        col = mix(col, vec3(0), 1.0 - exp(-0.0093 * dt * dt * dt));
    }

    return col;
    //O = vec4(col, 1.0);
}


