// cube-centered lattice (cubic symmetry), 6 directions
vec2 lattice_cc(vec3 p) {
    vec3 o = p*p;    
    float s = sqrt(o.x+o.y);
    s = min(s, sqrt(o.x+o.z));
    s = min(s, sqrt(o.y+o.z));
    return vec2(s, 0.0);
}

// face-centered lattice (rhombic dodecahedral symmetry), 12 directions
vec2 lattice_fcc(vec3 p) {
    vec3 o = abs(p);
    vec3 q = o / 2.0;
    float s = length(vec3(o.xy - (q.x + q.y), o.z));
    s = min(s, length(vec3(o.xz - (q.x + q.z), o.y)));
    s = min(s, length(vec3(o.yz - (q.y + q.z), o.x)));
    return vec2(s, 2.0);
}

// body-centered lattice (octahedral symmetry), 8 directions
vec2 lattice_bcc(vec3 p) {
    vec3 o = abs(p) + vec3(0.3,0.1,0.3);    
    return vec2(length( o - (o.x+o.y+o.z) / 3.0 ), 1.0);
}


// ==================[ Lattice ]==================
float map(vec3 p)
{ 
    p.z -= iTime * .5;
    p.y +=.0;

    p.y += sin(p.x * 5.0 + iTime * .6) * 0.057;
    p.z += sin(p.x * 5.0 + iTime * .5) * 0.005;

    vec3 p2 = p;
    p2 *= .9;
    p2.z += 0.0;//iMouse.x/100.;
    p2.y += .59;//iMouse.y/100.;

    vec3 p1 = p;
    p1 *= .4;
    p1.y += .9;

    p1 = mod(p1,2.0)-1.0;
    p2 = mod(p2,2.0)-1.0;


    float bcc = lattice_bcc(p1).x;
    float bcc2 = lattice_bcc(p2).x;

    float d = bcc - 0.13;
    float d3 = bcc2 - .06;

    float b = cellTile(p*1.5 + vec3(0,0,-iTime * 0.10)); 

    //return d + b*0.1;
    float d2 =  smax(d - d3, b*.0045, 0.252);
    //return  smin(d, -b*.001, 0.006);
    return d2;
