// ==================[ Lattice ]==================
float map(vec3 p)
{ 
    p.z -= iTime * 0.1;
    p.y +=1.;

    p.y += sin(p.x * 5.0 + iTime * .9) * 0.057;
    p.z += sin(p.x * 5.0 + iTime * .5) * 0.005;

    vec3 p1 = p;
    vec3 p2 = p;
    vec3 p3 = p;

    //p1 
    //p1.z += iTime * 0.4;

    //p2
    p2.yz *= mat2(0,1,-1,0);
    //p2.z += iMouse.y / 100.0;

    // p3
    //p3.y += iMouse.y / 100.0;

    // mod
    p1 = mod(p1,2.0)-1.0;
    p2 = mod(p2,2.0)-1.0;


    float bcc = lattice_bcc(p1).x;
    float fcc = lattice_fcc(p2).x;

    float d  = bcc - 0.14;
    float d1 = fcc - 0.2;
    float d3 = smax(1.0125 - length(p3.xy - vec2(0, 1)) + .5*cos(p3.z*3.14159/32.), .875-d1, .5) - abs(1.5-d1)*.40375;

    float b = cellTile(p*1.5 + vec3(0,0,-iTime * 0.14)); 

    float d2 =  smax(smin(d3,d,0.05), b*.003, 0.09);
    return d2;
}

// ==================[ normal ]=====================
vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
        map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
        map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
    ));
}

