vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

// https://www.bernhard-hoffmann.com/gradient-fitter/
vec3 polyPalette(float t) {
    vec3 c0 = vec3(0.334, 0.321, 0.488);
    vec3 c1 = vec3(-0.101, 0.141, 0.212);
    vec3 c2 = vec3(1.233, 0.146, -0.192);
    vec3 c3 = vec3(-2.612, 0.035, 0.039);

    vec3 color = c0 + c1 * t + c2 * t * t + c3 * t * t * t;
    return clamp(color, 0.0, 1.0);
}

vec3 render(vec3 ro, vec3 rd)
{   
    vec3 col = vec3(0.0);

    // ==================[ raymarch ]===================
    float dt = 0.0; 
    for(int i=0; i<60; i++)
    {
        float d = map(ro + rd * dt);

        if(abs(d) < 0.001 || dt > 20.0) break;
        dt += d;  
    }

    // ==================[ colors, fog ]=====================
    if(dt < 20.0)
    {
        vec3 p = ro + rd * dt;

        vec3 norm = calcNormal(p);

        //col = n * 0.5 + 0.5;

        float NoV = clamp(dot(norm, -rd), 0.0, 1.0);

        float fx = sin(iTime * 1.) * 1.5 + 7.5;

        float rim = pow(1.0 - NoV,4.0) * 1.2;


        //vec3 albedo = palette(norm.y * 1., vec3(0.5), vec3(.5), vec3(1.0), vec3(0.325,0.075,0.137));
        vec3 albedo = polyPalette(norm.x);

        // Light position in world space
        vec3 lightPos = ro + vec3(0, 0, 5);
        vec3 L = lightPos - p;
        float distlpsp = max(length(L), 0.001);
        L /= distlpsp;

        // Light attenuation based on distance
        float atten = 1.0 / (1.0 + distlpsp * .525);

        // Lighting terms 
        float ambience = 1.; 
        float diff = max(dot(norm, L), .0);

        // Specular with different colors based on objId
        vec3 specColor =  vec3(0.871);
        float spec = pow(max(dot(reflect(-L, norm), -rd), 0.0), 32.0);

        // Base texture + separate specular
        col = albedo * (diff + ambience) + specColor * spec;

        // Apply attenuation, shading, AND ambient occlusion
        col *= atten + (rim * vec3(0.7));

        //col += f;
        //col += vec3(0.7);
        col = mix(col, vec3(0), 1.0 - exp(-0.034 * dt * dt * dt));
    }

    return col;
    //O = vec4(col, 1.0);
}


