// ==================[ Lattice ]==================
float map(vec3 p)
{ 
    p.z -= iTime * .3;
    p.y +=0.;

    p.y += sin(p.x * 5.0 + iTime * .9) * 0.057;
    p.z += sin(p.y * 5.0 + iTime * .5) * 0.05;

    vec3 p1 = p;
    vec3 p2 = p;

    //P2 
    p2.z += 1.;
    p1.y += 1.;

    // mod
    p1 = mod(p1,2.)-1.;
    p2 = mod(p2,2.)-1.;


    float cc = lattice_cc(p2).x;
    float bcc = lattice_bcc(p2).x;
    float bcc2 = lattice_bcc2(p1).x;

    float d  = bcc - 0.15;
    float d1  = bcc2 - 0.1;
    float d3  = cc - 0.1;

    float b = cellTile(p*1.5 + vec3(0,0,-iTime * 0.14)); 

    //return min(d, d1);
    float d2 =  smax(min(min(d,d1), d3), b*.001, 0.07);
    return d2;
}

