    p2.x += 1.;// + iMouse.x / 100.;
    p2.z -= iTime * 0.3;

    // mod
    p1 = mod(p1,2.)-1.;
    p2 = mod(p2,2.)-1.;

    float cc = lattice_cc(p1).x;
    float bcc = lattice_bcc(p2).x;
    float bcc2 = lattice_bcc2(p2).x;

    float d  = bcc - 0.1;
    float d1  = bcc2 - 0.1;
    float d3  = cc - 0.05;

    float b = cellTile(p*.75 + vec3(0,0,-iTime * 0.34)); 

    //return min(d, d1);
    float d2 =  smax(min(min(d3,d),d1), b*.0023, 0.05);
    return d2;
}

// ==================[ normal ]=====================
vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
        map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
        map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
    ));
}

// ==================[ palettes ]=====================
vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

// https://www.bernhard-hoffmann.com/gradient-fitter/

vec3 polyPalette(float t) {
    vec3 c0 = vec3(0.442, -0.864,0.613);
    vec3 c1 = vec3(1.087, .809, -1.413);
    vec3 c2 = vec3(0.553, .023, 10.134);
    vec3 c3 = vec3(.105, -0.704, -0.835);

    vec3 color = c0 + c1 * t + c2 * t * t + c3 * t * t * t;
    return clamp(color, 0.0, 1.0);
}

vec3 polyPalette1(float t) {
    vec3 c0 = vec3(-0.049, 0.542, 1.495);
    vec3 c1 = vec3(6.173, -.7578, -0.572);
    vec3 c2 = vec3(-16.596, 1.749, 0.226);
    vec3 c3 = vec3(10.570, -1.169, 0.258);

    vec3 color = c0 + c1 * t + c2 * t * t + c3 * t * t * t;
    return clamp(color, 0.0, 1.0);
}


vec3 render(vec3 ro, vec3 rd)
{   
    vec3 col = vec3(0.0);

    // ==================[ raymarch ]===================
    float dt = 0.0; 
    for(int i=0; i<60; i++)
    {
        float d = map(ro + rd * dt);

        if(abs(d) < 0.001 || dt > 20.0) break;
        dt += d;  
    }

    // ==================[ colors, fog ]=====================
    if(dt < 20.0)
    {
        vec3 p = ro + rd * dt;

        vec3 norm = calcNormal(p);

        //col = n * 0.5 + 0.5;

        float NoV = clamp(dot(norm, -rd), 0.0, 1.0);

        float fx = sin(iTime * 1.) * 1.5 + 7.5;

        float rim = pow(1.0 - NoV,4.0) * 1.5;


        #if PALETTE == 1
        vec3 albedo = palette(dt * 1., vec3(0.5), vec3(.5), vec3(1.0), vec3(0.5325,0.2075,0.137));
        #else 
        vec3 albedo = polyPalette1(norm.y);
        #endif
        // Light position in world space
        vec3 lightPos = ro + vec3(0, 0, 5);
        vec3 L = lightPos - p;
        float distlpsp = max(length(L), 0.001);
        L /= distlpsp;

        // Light attenuation based on distance
        float atten = 1.0 / (1.0 + distlpsp * .525);

        // Lighting terms 
        float ambience = 1.; 
        float diff = max(dot(norm, L), .0);

        // Specular with different colors based on objId
        vec3 specColor =  vec3(0.871);
        float spec = pow(max(dot(reflect(-L, norm), -rd), 0.0), 32.0);

        // Base texture + separate specular
        col = albedo * (diff + ambience) + specColor * spec;

        // Apply attenuation, shading, AND ambient occlusion
        col *= atten + (rim * vec3(0.7));

        //col += f;
        //col += vec3(0.7);
        col = mix(col, vec3(0), 1.0 - exp(-0.034 * dt * dt * dt));
    }

    return col;
    //O = vec4(col, 1.0);
}


