void mainImage(out vec4 O, in vec2 I)
{   
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;

    vec3 ro = vec3(0.0,0, 3.0);

    vec3 tot = vec3(0.0);

    for (int m = 0; m < AA; m++)
    for (int n = 0; n < AA; n++) {
        vec2 off = vec2(m, n) / float(AA) - 0.5;
        vec2 uv = (2.0 * (I + off) - iResolution.xy) / iResolution.y;
        uv *= 2.0;
        vec3 rd = normalize(vec3(uv * .5, -1.0));
        vec3 col = render(ro, rd); 

        col = pow(col * 1.0, vec3(1.1 / 2.2));

        col = mix(vec3(0), col, smoothstep(7.6, .1, length(uv * vec2(1.4,1.) )));
        tot += col;
    }

    tot /= float(AA * AA);

    O = vec4(tot, 1.0);
}

