float smin( float a, float b, float k )
{
    k *= 1.0/(1.0-sqrt(0.5));
    float h = max( k-abs(a-b), 0.0 )/k;
    return min(a,b) - k*0.5*(1.0+h-sqrt(1.0-h*(h-2.0)));
}

float lattice_bcc(vec2 p) 
{
    vec2 o = abs(p);
    //return length(o);
    return length( o - (o.x+o.y) / 2.0 );
}

float sdCircle(vec2 p, float r)
