vec2 hash2( vec2 p ) 
{
    p = vec2( dot(p, vec2(127.1,191.7)), dot(p, vec2(269.5,183.3)) );
    return -1.0 + 2.0 * fract(sin(p) * 43758.5453123);
}

vec2 voronoiFragment(vec2 uv, float size, float minDist)
{
    vec2 grid = floor(uv * size);
    float grid2;
    for (int x = -1; x <= 1; x++) 
    for (int y = -1; y <= 1; y++) {

        // Neighbor cell ID
        vec2 cell = grid + vec2(float(x), float(y));

        // Get pseudo-random position for the cell
        vec2 cellPos = hash2(cell);
        cellPos =  .2 + .2 * sin(iTime + 10.213 * cellPos);

        // Cell position in normalized space
        vec2 pos = cell / size + cellPos / size;

        // Compute distance to the cell's point
        float dt = length(uv - pos) - 0.1;

        // Update minimum distance if necessary
        minDist = min(minDist, dt);

        vec2 o = abs(cellPos) - 0.046;
        grid2 = min(o.x, o.y);
    }
    return vec2(minDist, grid2);
}

void mainImage( out vec4 O, in vec2 I ) 
{
    vec2 uv = I / iResolution.y;// * 2.0 - 1.0;
    float minDist = 1.0;

    float size = 8.0;
    vec2 d1 = voronoiFragment(uv, size, minDist);

    vec3 colorA = vec3(1);
    vec3 colorB = vec3(0);

    float d2 = smoothstep(-0.2, 0.11, d1.x);
    float d3 = smoothstep(-0.2, 0.11, d1.y);

    vec3 col = mix(colorA, colorB, d2);
    col -= mix(colorA, colorB, d3);

    O = vec4(col, 1.0);
}

