#define AA 2

// https://iquilezles.org/articles/distfunctions/
float smin( float a, float b, float k )
{
    k *= 4.0;
    float h = max(k-abs(a-b),0.0);
    return min(a, b) - h*h*0.25/k;
}

// @paniq
// https://www.shadertoy.com/view/llfGRj
// cube-centered lattice (cubic symmetry), 6 directions
vec2 lattice_cc(vec3 p) {
    vec3 o = p*p;    
    float s = sqrt(o.x+o.y);
    s = min(s, sqrt(o.x+o.z));
    s = min(s, sqrt(o.y+o.z));
    return vec2(s, 0.0);
}

// @eliso
// https://www.shadertoy.com/view/NclSWM
#define dot2(v) dot(v, v)
#define pi acos(-1.)
#define v1 (4. + tanh(cos(0.) * 5. + 2.) * 2.)
#define v2 (.12 + tanh(cos(1.0) * 5. - 2.) * .12)
#define v3 (4.5 + tanh(cos(3.0) * 5.) * 1.5)

float line(vec3 p, vec3 a, vec3 b) {
    vec3 pa = p - a, ba = b - a;
    return dot2(pa - ba * clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0));
}

vec3 spirograph(float t) {
    vec3 p;
    float d = .9 / v1,
          R = .9,
          r = .9 / v3;

    p.x = (R + r) * cos(t) - d * cos(t * (R + r) / r);
    p.y = (R + r) * sin(t) - d * sin(t * (R + r) / r);

    return p;
}

float sdEpicycloid(vec3 p) {
    int steps = 9; 
    float dist = 1e6,
          dt = 2. * pi / float(steps);

    vec3 prev = spirograph(0.);
    for(int i; i < steps; i++) {
        vec3 cur = spirograph(float(i + 1) * dt);
        dist = min(dist, line(p, prev, cur));
        prev = cur;
    }

    return sqrt(dist) - v2;
}



// ==================[ Lattice ]==================
float map(vec3 p)
{ 
    p.z -= iTime * .5;

    p.y += sin(p.x * 1.+ iTime * 0.3) * 0.57;
    //p.z += sin(p.x * 5.0 + iTime * .5) * 0.005;

    vec3 p1 = p;
    vec3 p2 = p;

    p2.x +=1.0;
    p2.y +=2.;
    p2.z +=1.5;
    // mod
    p1 = vec3(mod(p1.x,4.0)-1.,
        mod(p1.y,2.0)-1.,
        mod(p1.z,2.0)-1.);
    p2 = vec3(mod(p2.x,4.0)-2.,
        mod(p2.y,4.0)-2.,
        mod(p2.z,2.0)-0.5
    );
    float bcc = lattice_cc(p1).x;
    float d  = bcc - 0.1;

    float d1 = sdEpicycloid(p2);

    return smin(d1,d, 0.2);
}

// ==================[ normal ]=====================
vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
        map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
        map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
    ));
}

// https://www.bernhard-hoffmann.com/gradient-fitter/
vec3 polyPalette(float t) {
    vec3 c0 = vec3(0.624, 1.031, 0.986);
    vec3 c1 = vec3(-1.595, -3.288, -2.507);
    vec3 c2 = vec3(1.080, 4.441, 3.470);
    vec3 c3 = vec3(0.663, -1.268, -0.894);

    vec3 color = c0 + c1 * t + c2 * t * t + c3 * t * t * t;
    return clamp(color, 0.0, 1.0);
}

vec3 render(vec3 ro, vec3 rd)
{   
    vec3 col = vec3(0.0);

    // ==================[ raymarch ]===================
    float dt = 0.0; 
    for(int i=0; i<60; i++)
    {
        float d = map(ro + rd * dt);

        if(abs(d) < 0.001 || dt > 20.0) break;
        dt += d;  
    }

    // ==================[ colors, fog ]=====================
    if(dt < 20.0)
    {
        vec3 p = ro + rd * dt;

        vec3 norm = calcNormal(p);

        // Base texture + separate specular
        col = norm * 0.5 + 0.5;


        float NoV = clamp(dot(norm, -rd), 0.0, 1.0);

        float rim = pow(1.0 - NoV,4.0) * 1.;

        vec3 albedo = polyPalette(norm.y);

        // Light position in world space
        vec3 lightPos = ro + vec3(0, 0, 5);
        vec3 L = lightPos - p;
        float distlpsp = max(length(L), 0.001);
        L /= distlpsp;

        // Light attenuation based on distance
        float atten = 1.0 / (1.0 + distlpsp * .3525);

        // Lighting terms 
        float ambience = 1.; 
        float diff = max(dot(norm, L), .0);

        // Specular with different colors based on objId
        vec3 specColor =  vec3(0.871);
        float spec = pow(max(dot(reflect(-L, norm), -rd), 0.0), 32.0);

        // Base texture + separate specular
        col = albedo * (diff + ambience) + specColor * spec;

        // Apply attenuation, shading, AND ambient occlusion
        col *= atten + (rim * vec3(0.7));

        col = mix(col, vec3(0), 1. - exp(-0.0054 * dt*dt*dt));
    }

    return col;
    //O = vec4(col, 1.0);
}


