    vec3 ro = vec3(3, 2.0, 3.0);
    vec3 rd = normalize(vec3(uv * 1.5, -1.0));

    vec3 tot = vec3(0.0);

    for (int m = 0; m < AA; m++)
    for (int n = 0; n < AA; n++) {
        vec2 off = vec2(m, n) / float(AA) - 0.5;
