float size = 5.0;

vec2 hash2( vec2 p ) 
{
    p = vec2( dot(p, vec2(127.1,191.7)), dot(p, vec2(269.5,183.3)) );
    return -1.0 + 2.0 * fract(sin(p) * 43758.5453123);
}

// iq
float sdCross( in vec2 p, in vec2 b, float r ) 
{
    p = abs(p); p = (p.y>p.x) ? p.yx : p.xy;
    vec2  q = p - b;
    float k = max(q.y,q.x);
    vec2  w = (k>0.0) ? q : vec2(b.y-p.x,-k);
    return sign(k)*length(max(w,0.0)) + r;
}

float voronoi(vec2 uv)
{
    uv.y += iTime * 0.05;  
    float minDist = 1.0;
    vec2 grid = floor(uv * size);
    float grid2;
    for (int x = -1; x <= 1; x++) 
    for (int y = -1; y <= 1; y++) {

        // Neighbor cell ID
        vec2 cell = grid + vec2(float(x), float(y));

        // Get pseudo-random position for the cell
        vec2 cellPos = hash2(cell);
        cellPos =  .5 + .5 * sin( 0.1 * iTime + 10.213 * cellPos);

        // Cell position in normalized space
        vec2 pos = cell / size + cellPos / size;

        // Compute distance to the cell's point
        float dt = sdCross(uv - pos, vec2(1.,.295) * .11, 0.06) - 0.1;//length(uv - pos) - 0.08;

        // Update minimum distance if necessary
        minDist = min(minDist, dt);

        vec2 o = abs(cellPos) - 0.6;
        grid2 = min(o.x, o.y);
    }
    return minDist;
    //return vec2(minDist, grid2);
}
