// Inigo Quilez (MIT) https://www.shadertoy.com/view/ll2GD3
vec3 polyPalette(float t) {
    vec3 brightness = vec3(0.1101, 0.3285, 0.4380);
    vec3 contrast = vec3(.564183, -.20, 0.3261);
    vec3 frequency = vec3(2.000, 2.000, 2.000);
    vec3 phase = vec3(0.2244, 0.207, 0.200);

    vec3 color = brightness + contrast * cos(3.28318 * (frequency * t + phase));
    return clamp(color, 0.0, 1.0); // sRGB
}
vec3 render(vec3 ro, vec3 rd)
{   
    vec3 col = vec3(0.0);

    float maxdist=50.;
//https://www.shadertoy.com/view/XlsGWl
    // ==================[ raymarch ]===================
    float dt = 0.0; 
    for(int i=0; i<45; i++)
    {
        float d = map(ro + rd * dt);

        if(abs(d) < 0.001 || dt > 10.0) break;
        dt += d;  
    }

    // ==================[ colors, fog ]=====================
    if(dt < 10.0)
    {
        vec3 p = ro + rd * dt;

        vec3 norm = calcNormal(p);

        float NoV = clamp(dot(norm, -rd), 0.0, 1.0);

        float rim = pow(1.0 - NoV,4.0) * .5;

        vec3 albedo = polyPalette(dt);

        // Light position in world space
        vec3 lightPos = ro + vec3(0, 0, 5);
        vec3 L = lightPos - p;
        float distlpsp = max(length(L), 0.001);
        L /= distlpsp;

        // Light attenuation based on distance
        float atten = 1.0 / (1.0 + distlpsp * .2);

        // Lighting terms 
        float ambience = 1.; 
        float diff = max(dot(norm, L), .0);

        // Specular with different colors based on objId
        vec3 specColor =  vec3(0.3);
        float spec = pow(max(dot(reflect(-L, norm), -rd), 0.0), 32.0);

        // Base texture + separate specular
        col = albedo * (diff + ambience) + specColor * spec;

        // Apply attenuation, shading, AND ambient occlusion
        col *= atten + (rim * vec3(.57));

        col = mix(col, vec3(0), 1. - exp(-0.0254 * dt*dt*dt));
    }

    return col;
    //O = vec4(col, 1.0);
}


