// Color palette function. Produces some nice cycling colors.
// @Shane
#define Palette(t) (.5 + .5 * sin(6.111 * (t + vec3(0, 1, 2)*1.23)))

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// iq
float sdCross( in vec2 p, in vec2 b, float r ) 
{
    p = abs(p); p = (p.y>p.x) ? p.yx : p.xy;
    vec2  q = p - b;
    float k = max(q.y,q.x);
    vec2  w = (k>0.0) ? q : vec2(b.y-p.x,-k);
    return sign(k)*length(max(w,0.0)) + r;
}

float lattice_bcc(vec2 p) 
{
    vec2 o = abs(p);
    //return length(o);
    return length( o - (o.x+o.y) / 2.0 );
}

void mainImage( out vec4 O, vec2 I )
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    uv *= 7.5;
    uv.x += iTime * 2.;
    vec3 col = vec3(0);

    vec2 cell = mod(uv, 2.0) - 1.;
    vec2 cellid = vec2(floor((uv- 1.) / 2.0));

    float d = lattice_bcc(cell) - 0.01;

    float fx1 = hash(cellid) * 1.28;
    float fx2 = sin(iTime * 3. * fx1) * 0.1 - 0.05;
    float d1 = sdCross(cell, vec2(1.9 * fx1,.26 + fx2) * .43, 0.06);

    float d3 = min(d, d1);

    d3 = smoothstep(-0.02,.05,d3);

    //col = vec3(d3);
    // Give each sphere its own color from the palette.
    float cellHash = hash(cellid + float(2) * 51.3);
    vec3 colD1 = Palette(cellHash * 0.5 + 0.3);
    float glow = exp(-d3 *10.0) * 1.93 * cellHash;

    col = mix(colD1,vec3(0), d3) * glow;

    O = vec4(col,1.0);
}

