void mainImage( out vec4 O, in vec2 I ) 
{
    vec2 uv = I.xy / iResolution.xy;
    vec3 col = vec3(0);
    float r = 30.0;
    int samples = 10;

    for(int i = 0; i < samples; i++) {
        float a = float(i) * 6.2832 / float(samples);
        vec2 offset = vec2(cos(a), sin(a)) * r / iResolution.xy;
        col += texture(iChannel0, uv + offset).rgb;
    }
    col /= float(samples);

    // Add original on top so it stays sharp
    vec3 original = texture(iChannel0, uv).rgb;
    col = original + col * .55;

    col = pow(col, vec3(1.1 / 2.2));
    O = vec4(clamp(col, 0., 1.), 1.);
}

