void mainImage( out vec4 O, vec2 I )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = I/iResolution.xy;

    // accumulate color
    vec4 col = vec4(0,0,0,1);

    vec4 txt = texture(iChannel0, uv, (iMouse.x / iResolution.x * 8.));

    // samples taken
    float samples = 0.;

    // For each pixel take 8 samples of each offset
    for(int i=0; i<8; i++)
    {
        // Random offset with a simple hash
        vec2 jitter = sin(vec2(I + vec2(float(i*13), float(i*7))));

        // scale 
        jitter *= (iMouse.x / iResolution.x) * 50. / iResolution.y;

        txt = texture(iChannel1, uv + jitter);
        col += txt;
    }

    col /= 8.;


    O = col;
}

