    ▓              🌟  KuKo Day 357  🌟 

    ▓ BufferA -> Shape and you can play with speed and size

    ▓ image -> @Shane mipmap bloom, jitter blue noise

    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓
*/



void mainImage(out vec4 fragColor, in vec2 fragCoord){


    // Screen oordinates.
    vec2 uv = fragCoord/iResolution.xy;

    // The DOF looks nice, but I'm going for a cleaner, and cheaper, look.
    //vec4 col = DpthFld(iChannel0, uv).xyzz;

    // Retrieving the stored color.
    vec4 col = texture(iChannel0, uv);



    // Hardware bloom that I made up on the spot. It's
    // not as nice as software bloom, but it's way cheaper
    // and definitely easier to implement.
    // Load the "Blue Noise" texture into "iChannel1" with
    // the filter set to "linear". The filter for "Buffer A"
    // needs to be set to "mipmap" for the hardware blur
    // to take effect.

    float a = 1., w = 1.;
    vec4 bloomCol = vec4(0);
    for (int i = 0; i<18; i++){
        vec2 jit = (texture(iChannel1, uv + vec2(i*57, i*27)*.327 + 
                             fract(iTime)).xy - .5)/iResolution.y;
        bloomCol += texture(iChannel0, uv + jit*5., float(i%6)/2.)*w;
        a += w;
        w *= .7071;
    }
    bloomCol /= a;

    col += smoothstep(vec4(.0), vec4(1), bloomCol)*12.;


    // Subtle Reinhard-based tone-mapping.
    //col /= (2. + col)/2.25;

    // Basic high frequency sigmoid tone mapping, popularized by XOR.
    col = tanh(col);


    // Subtle vignette.
    //col *= pow(16.*uv.x*uv.y*(1. - uv.x)*(1. - uv.y) , 1./16.);

    // Rough gamma correction and screen presentation.
    fragColor = pow(max(col, 0.), vec4(1./2.2)); 

}




