/*
    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓

    ▓ Play with the Speed to move it on the x direction

    ▓ Play with the Size of the grid


    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓
*/

const float speed = 0.0;
const float size = 41.;

// Color palette function. Produces some nice cycling colors.
// @Shane
#define Palette(t) (.5 + .5 * sin(8.111 * (t + vec3(0, 1, 2)*1.23)))

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// iq
float sdCross( in vec2 p, in vec2 b, float r ) 
{
    p = abs(p); p = (p.y>p.x) ? p.yx : p.xy;
    vec2  q = p - b;
    float k = max(q.y,q.x);
    vec2  w = (k>0.0) ? q : vec2(b.y-p.x,-k);
    return sign(k)*length(max(w,0.0)) + r;
}

float lattice_bcc(vec2 p) 
{
    vec2 o = abs(p);
    //return length(o);
    return length( o - (o.x+o.y) / 2.0 );
}

void mainImage( out vec4 O, vec2 I )
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;
    uv *= size;
    uv.y += iTime * speed;
    vec3 col = vec3(0);

    vec2 cell = mod(uv, 2.0) - 1.;
    vec2 cellid = vec2(floor((uv- 1.) / 2.0));

    float d = lattice_bcc(cell) - 0.01;

    float fx1 = hash(cellid) * 1.28;
    float fx2 = sin(iTime * 3. * fx1) * 0.1 - 0.05;
    float d1 = sdCross(cell, vec2(3.49 * fx1,.3426 + fx2) * .343, 0.06);

    float d3 = min(d, d1);

    d3 = smoothstep(-0.034,.08,d3);

    //col = vec3(d3);
    // Give each sphere its own color from the palette.
    float cellHash = hash(cellid + float(7) * 52.3);
    vec3 colD1 = Palette(cellHash * .5 + .43);
    float glow = exp(-d3 *40.0) * 1.93 * cellHash;

    col = mix(colD1,vec3(0), d3) * glow;

    // Previous "smoke/light" field
    vec3 prev = texture(iChannel0, I / iResolution.xy).rgb * .29;
    if(iFrame==0) col = vec3(0);
    O = vec4(col + prev , 1.0);
}

/*
    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓

    ▓              🌟  KuKo Day 359  🌟  

    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓
*/

#define AA 2

// body-centered lattice (octahedral symmetry), 8 directions
vec2 lattice_bcc(vec3 p) {
    vec3 o = abs(p) + vec3(.0,0.,.0);    
    return vec2(length( o - (o.x+o.y+o.z) / 3.0 ), 1.0);
}

vec2 lattice_bcc2(vec3 p) {
    float d_body   = length(p);
    float d_corner = length(abs(p) - 1.0);
    return vec2(min(d_body, d_corner), max(d_body, d_corner));
}

float sdRoundBox( vec3 p, vec3 b, float r )
{
  vec3 q = abs(p) - b + r;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0) - r;
}

// ==================[ Lattice ]==================
float map(vec3 p)
{ 
    vec3 p1 = p;
    p1.y -= iTime * .5;
    // mod
    p1 = mod(p1,2.0)-1.0;

    vec2 bcc = lattice_bcc2(p1);

    float d  = (bcc.y - bcc.x) - 0.05;
    float d1 = sdRoundBox(p, vec3(3.2,3.2,3.2), 3.6);
    return max(d, d1);
}

// ==================[ normal ]=====================
vec3 calcNormal(vec3 p)
{
    float e = 0.1;
    return normalize(vec3(
        map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
        map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
        map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
    ));
}

// ==================[ palettes ]=====================
vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}


// https://www.bernhard-hoffmann.com/gradient-fitter/
vec3 polyPalette(float t) {
    vec3 c0 = vec3(0.334, 0.321, 0.488);
    vec3 c1 = vec3(-0.101, 0.141, 0.212);
    vec3 c2 = vec3(1.233, 0.146, -0.192);
    vec3 c3 = vec3(-1.612, 0.035, 0.039);

    vec3 color = c0 + c1 * t + c2 * t * t + c3 * t * t * t;
    return clamp(color, 0.0, 1.0);
}


mat3 setCamera( in vec3 ro, in vec3 ta, float cr )
{
	vec3 cw = normalize(ta-ro);
	vec3 cp = vec3(sin(cr), cos(cr),0.0);
	vec3 cu = normalize( cross(cw,cp) );
	vec3 cv =          ( cross(cu,cw) );
    return mat3( cu, cv, cw );
}

vec3 render(vec3 ro, vec3 rd)
{   
    vec3 col = vec3(0.0);

    // ==================[ raymarch ]===================
    float dt = 0.0; 
    for(int i=0; i<60; i++)
    {
        float d = map(ro + rd * dt);

        if((d) < 0.001 || dt > 10.0) break;
        dt += d * 0.5;  
    }

    // ==================[ colors, fog ]=====================
    if(dt < 20.0)
    {
        vec3 p = ro + rd * dt;

        vec3 norm = calcNormal(p);

        //col = n * 0.5 + 0.5;

        float NoV = clamp(dot(norm, -rd), 0.0, 1.0);

        float fx = sin(iTime * 1.) * 1.5 + 7.5;

        float rim = pow(1.0 - NoV,4.0) * 2.2;


        vec3 albedo = palette(norm.y * .1, vec3(0.5), vec3(.95), vec3(1.0), vec3(0.694,0.314,0.949));
        //vec3 albedo = polyPalette(norm.y);

        // Light position in world space
        vec3 lightPos = ro + vec3(0, 0, 5);
        vec3 L = lightPos - p;
        float distlpsp = max(length(L), 0.001);
        L /= distlpsp;

        // Light attenuation based on distance
        float atten = 1.0 / (1.0 + distlpsp * .525);

        // Lighting terms 
        float ambience = 1.; 
        float diff = max(dot(norm, L), .0);

        // Specular with different colors based on objId
        vec3 specColor =  vec3(0.871);
        float spec = pow(max(dot(reflect(-L, norm), -rd), 0.0), 32.0);

        // Base texture + separate specular
        col = albedo * (diff + ambience) + specColor * spec * 3.;

        // Apply attenuation, shading, AND ambient occlusion
        col *= atten + (rim * vec3(0.7));

        //col += f;
        //col += vec3(0.7);
        col = mix(col, vec3(0), 1.0 - exp(-0.034 * dt * dt * dt));
    }

    return col;
    //O = vec4(col, 1.0);
}


/*
    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓

