#define AA 2
// @Shane
// https://www.shadertoy.com/view/XsKXRh
float drawObject(in vec3 p){

    // Anything that wraps the domain will work. The following looks pretty intereting.
    p = cos(p*6.2831853) + 1.;
    return dot(p, p);

}

// Fast, three tap version, but I feel four should be the minimum... Even so, this should give 
// a pretty convincing pattern, under the right circumstances.
float cellTile(in vec3 p){

    vec3 d;

    // Draw three overlapping objects (spherical, in this case) at various positions throughout the tile.
    d.x = drawObject(p - vec3(.81, .62, .53));
    p.xy = vec2(p.y-p.x, p.y + p.x)*.7071;
    d.y = drawObject(p - vec3(.92, .82, .64));
    p.yz = vec2(p.z-p.y, p.z + p.y)*.7071;
    d.z = drawObject(p - vec3(.41, .06, .70));

    return 1.- min(min(d.x, d.y), d.z)*1.6266; // Normalize... roughly.
}
vec2 lattice_bcc2(vec3 p) {
    float d_body   = length(p);
    float d_corner = length(abs(p) - 1.0);
    return vec2(min(d_body, d_corner), max(d_body, d_corner));
}

float sdSphere( vec3 p, float r )
{
    return length(p) - r;
}
float sdRoundBox( vec3 p, vec3 b, float r )
{
  vec3 q = abs(p) - b + r;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0) - r;
}

float smin( float a, float b, float k )
{
    k *= 4.0;
    float h = max(k-abs(a-b),0.0);
    return min(a, b) - h*h*0.25/k;
}
// by iq. https://iquilezles.org/articles/smin
float smax(float a, float b, float k) {
	float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
	return mix(a, b, h) + k * h * (1.0 - h);
}


// ==================[ Lattice ]==================
float map(vec3 p)
{ 
    vec3 p1 = p;
    p1.y -= iTime * .1;
    // mod
    p1 = mod(p1,2.0)-1.0;

    vec2 bcc = lattice_bcc2(p1);

    float d  = (bcc.y - bcc.x) - 0.1;
    //float d1 = sdSphere(p, 3.);
    float d1 = sdRoundBox(p, vec3(2.8), 1.5);

    float b = cellTile(p*1.5 + vec3(0,0,-iTime * 0.14)); 

    float d3 =  smax(d,d1,0.51);
    float d2 =  smax( b*.0713, d3, .537);

    return d2;
    return smax(-d,d1,0.01);
    return max(d, d1);
}

// ==================[ normal ]=====================
vec3 calcNormal(vec3 p)
{
    float e = 0.1;
    return normalize(vec3(
        map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
        map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
        map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
    ));
}

// ==================[ palettes ]=====================
vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

// https://www.bernhard-hoffmann.com/gradient-fitter/
vec3 polyPalette(float t) {
    vec3 c0 = vec3(0.624, 1.031, 0.986);
    vec3 c1 = vec3(-1.595, -3.288, -2.507);
    vec3 c2 = vec3(1.080, 4.441, 3.470);
    vec3 c3 = vec3(0.663, -1.268, -0.894);

    vec3 color = c0 + c1 * t + c2 * t * t + c3 * t * t * t;
    return clamp(color, 0.0, 1.0);
}

// https://www.bernhard-hoffmann.com/gradient-fitter/
vec3 polyPalette2(float t) {
    vec3 c0 = vec3(1.184, 1.037, -0.160);
    vec3 c1 = vec3(-8.647, -2.393, 7.682);
    vec3 c2 = vec3(84.399, 26.826, -76.056);
    vec3 c3 = vec3(-283.993, -94.122, 257.637);
    vec3 c4 = vec3(363.300, 115.537, -329.394);
    vec3 c5 = vec3(-155.627, -46.994, 140.827);

    vec3 color = c0 + c1 * t + c2 * t * t + c3 * t * t * t + c4 * pow(t,4.0) + c5 * pow(t, 5.0);
    return clamp(color, 0.0, 1.0);
}

