// @Shane
// https://www.shadertoy.com/view/XsKXRh
float drawObject(in vec3 p){

    // Anything that wraps the domain will work. The following looks pretty intereting.
    p = cos(p*6.2831853) + 1.;
    return dot(p, p);

}

// Fast, three tap version, but I feel four should be the minimum... Even so, this should give 
// a pretty convincing pattern, under the right circumstances.
float cellTile(in vec3 p)
{    
    vec3 d;   
    // Draw three overlapping objects (spherical, in this case) at various positions throughout the tile.
    d.x = drawObject(p - vec3(.81, .62, .53));
    p.xy = vec2(p.y-p.x, p.y + p.x)*.7071;
    d.y = drawObject(p - vec3(.92, .82, .64));
    p.yz = vec2(p.z-p.y, p.z + p.y)*.7071;
    d.z = drawObject(p - vec3(.41, .06, .70));

    return 1.- min(min(d.x, d.y), d.z)* 1.462; // Normalize... roughly.
}

vec2 lattice_bcc2(vec3 p) 
{
    float o   = length(p);
    float v = length(abs(p) - 1.0);
    return vec2(min(o, v), max(o, v));
}

float sdSphere( vec3 p, float r )
{
    return length(p) - r;
}

float sdRoundBox( vec3 p, vec3 b, float r )
{
  vec3 q = abs(p) - b + r;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0) - r;
}

float smin( float a, float b, float k )
{
    k *= 4.0;
    float h = max(k-abs(a-b),0.0);
    return min(a, b) - h*h*0.25/k;
}

// by iq. https://iquilezles.org/articles/smin
float smax(float a, float b, float k) {
	return -smin(-a, b, k);
}


// ==================[ Lattice ]==================
float map(vec3 p)
{ 
    vec3 p1 = p;
    p1.y -= iTime * .21;
    // mod
    p1 = mod(p1,2.0)-1.0;

    vec2 bcc = lattice_bcc2(p1);

    float d  = (bcc.y - bcc.x) - 0.1;
    //float d1 = sdSphere(p, 3.);
    float d1 = sdRoundBox(p, vec3(3.), 1.);

    float b = cellTile(p*.69 + vec3(0,-iTime * .2,0)); 

    float d3 =  smax(d,d1,0.51);
    float d2 =  smax( b*.0713, d3, .537);

    //return d2;
    return smax(d,-d2, .051);
    return max(d, d1);
}

// ==================[ normal ]=====================
vec3 calcNormal(vec3 p)
{
    float e = 0.01;
    return normalize(vec3(
        map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
        map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
        map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
    ));
}

