vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

// https://www.bernhard-hoffmann.com/gradient-fitter/
vec3 polyPalette(float t) 
{
    vec3 c0 = vec3(0.298, 0.182, 0.473);
    vec3 c1 = vec3(3.181, 3.715, 3.105);
    vec3 c2 = vec3(-9.386, -10.685, -9.421);
    vec3 c3 = vec3(6.452, 7.196, 6.515);

    vec3 color = c0 + c1 * t + c2 * t * t + c3 * t * t * t;
    return clamp(color, 0.0, 1.0);
}

// https://www.bernhard-hoffmann.com/gradient-fitter/
vec3 polyPalette2(float t) {
    vec3 c0 = vec3(1.184, 1.037, -0.160);
    vec3 c1 = vec3(-8.647, -2.393, 7.682);
    vec3 c2 = vec3(84.399, 26.826, -76.056);
    vec3 c3 = vec3(-283.993, -94.122, 257.637);
    vec3 c4 = vec3(363.300, 115.537, -329.394);
    vec3 c5 = vec3(-155.627, -46.994, 140.827);

    vec3 color = c0 + c1 * t + c2 * t * t + c3 * t * t * t + c4 * pow(t,4.0) + c5 * pow(t, 5.0);
    return clamp(color, 0.0, 1.0);
}

mat3 setCamera( in vec3 ro, in vec3 ta, float cr )
{
	vec3 cw = normalize(ta-ro);
	vec3 cp = vec3(sin(cr), cos(cr),0.0);
	vec3 cu = normalize( cross(cw,cp) );
	vec3 cv =          ( cross(cu,cw) );
    return mat3( cu, cv, cw );
}

vec3 render(vec3 ro, vec3 rd)
{   
    vec3 col = vec3(0.0);

    // ==================[ raymarch ]===================
    float dt = 0.0; 
    for(int i=0; i<80; i++)
    {
        float d = map(ro + rd * dt);

        if(abs(d) < 0.001 || dt > 10.0) break;
        dt += d * 0.5;  
    }

    // ==================[ colors, fog ]=====================
    if(dt < 10.0)
    {
        vec3 p = ro + rd * dt;

        vec3 norm = calcNormal(p);

        float NoV = clamp(dot(norm, -rd), 0.0, 1.0);

        float rim = pow(1.0 - NoV,4.0) * 5.2;

        //vec3 albedo = palette(norm.y * .5, vec3(0.5), vec3(.65), vec3(1.0), vec3(0.024,0.439,0.576));
        //vec3 albedo = palette(norm.z * 1.1, vec3(0.5), vec3(.65), vec3(1.0), vec3(0.537,0.114,0.082));
        vec3 albedo = polyPalette(norm.y);

        // Light position in world space
        vec3 lightPos = ro + vec3(-2, 2, 2);
        vec3 L = lightPos - p;
        float distlpsp = max(length(L), 0.001);
        L /= distlpsp;

        // Light attenuation based on distance
        float atten = 1.0 / (1.0 + distlpsp * .25);

        // Lighting terms 
        float ambience = 1.; 
        float diff = max(dot(norm, L), .0);

        // Specular with different colors based on objId
        vec3 specColor =  vec3(0.871);
        float spec = pow(max(dot(reflect(-L, norm), -rd), 0.0),24.0);

        // Base texture + separate specular
        col = albedo * (diff + ambience) + specColor * spec * 3.;

        // Apply attenuation, shading, AND ambient occlusion
        col *= atten + (rim * vec3(0.7));

        col = mix(col, vec3(0), 1.0 - exp(-0.034 * dt * dt * dt));
    }

    return col;
}


