    float v = length(abs(p) - 1.0);
    return vec2(min(o, v), max(o, v));
}

float sdSphere( vec3 p, float r )
{
    return length(p) - r;
}

float sdBox( vec3 p, vec3 b )
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

// by iq. https://iquilezles.org/articles/smin
float smax(float a, float b, float k) {
	float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
	return mix(a, b, h) + k * h * (1.0 - h);
}

float proj(vec3 p)
{
    // hole size (animate this later with sin(iTime))
    float hs = sin(iTime * 2.) * 0.05 + 0.45;

    // for each axis face: depth component, and the 2D square SDF on the other two
    float h0 = max(max(abs(p.y), abs(p.z)) - hs + 0.1,  abs(p.x) - 2.4);  // ±X faces
    float h1 = max(max(abs(p.x), abs(p.z)) - hs + 0.1,  abs(p.y) - 2.4);  // ±Y faces  
    float h2 = max(max(abs(p.x), abs(p.y)) - hs + 0.1,  abs(p.z) - 2.4);  // ±Z faces

    float h3 = abs(p.y) + abs(p.z) - hs;
    float h4 = abs(p.x) + abs(p.y) - hs;
    float h5 = abs(p.x) + abs(p.z) - hs;

    float h6 = length(p.yz) - 0.9 + hs;

    return min(h6, min(h4, h2));

    return min(h0, min(h1, h2));
}

