    p1 = mod(p1,2.0)-1.0;

    vec2 bcc = lattice_bcc2(p1);

    float d  = (bcc.y - bcc.x) - 0.15;
    float d1 = sdSphere(p, 5.);
    //float d1 = sdBox(p, vec3(5.5, 8., 5.5));
    float d3 =  smax(d,d1,.25);

    float d5 = proj(p1);


