    vec3 frequency = vec3(1.174, 0.713, 1.144);
    vec3 phase = vec3(0.795, -0.080, 0.305);

    vec3 color = brightness + contrast * cos(6.28318 * (frequency * t + phase));
    return clamp(color, 0.0, 1.0); // sRGB
}

