mat3 setCamera( in vec3 ro, in vec3 ta, float cr )
{
	vec3 cw = normalize(ta-ro);
	vec3 cp = vec3(sin(cr), cos(cr),0.0);
	vec3 cu = normalize( cross(cw,cp) );
	vec3 cv =          ( cross(cu,cw) );
    return mat3( cu, cv, cw );
}

vec3 render(vec3 ro, vec3 rd)
{   
    vec3 col = vec3(0.0);

    // running glow accumulator, starts dark, gets warmer as we march
    // this is what we'll add on top of the surface color at the end
    vec3 glow = vec3(0);
    float w = 0.;

    // ==================[ raymarch ]===================
    float dt = 0.0; 
    for(int i=0; i<80; i++)
    {
        float d = map(ro + rd * dt);

        if(abs(d) < 0.001 || dt > 20.0) break;

        // glow accumulation
        w = 1./ (0.01 + d*d) * exp(-.015 * dt);

        glow += vec3(1.000,0.957,0.741) * w * .00622;

        dt += d * .5;  
    }

    // ==================[ colors, fog ]=====================
    if(dt < 10.0)
    {
        vec3 p = ro + rd * dt;

        vec3 norm = calcNormal(p);

        float NoV = clamp(dot(norm, -rd), 0.0, 1.0);

        float rim = pow(1.0 - NoV,4.0) * 3.2;

        // 1. Normalize p to get a pure direction from the origin
        vec3 np = normalize(norm);

        // 2. Define all 14 face normals (6 axis-aligned, 8 diagonal)
        vec3 faceNorm[14];
        // square faces
        faceNorm[0] = vec3( 1, 0, 0);
        faceNorm[1] = vec3(-1, 0, 0);
        faceNorm[2] = vec3( 0, 1, 0);
        faceNorm[3] = vec3( 0,-1, 0);
        faceNorm[4] = vec3( 0, 0,-1);
        faceNorm[5] = vec3( 0, 0, 1);

        // hex faces
        faceNorm[6] =  vec3( 1, 1, 1);
        faceNorm[7] =  vec3(-1, 1, 1);
        faceNorm[8] =  vec3( 1,-1, 1);
        faceNorm[9] =  vec3(-1,-1, 1);
        faceNorm[10] = vec3( 1, 1,-1);
        faceNorm[11] = vec3(-1, 1,-1);
        faceNorm[12] = vec3( 1,-1,-1);
        faceNorm[13] = vec3(-1,-1,-1);

        // 3. Loop over all 14 — compute dot product of np with each normal
        int faceID = 0;
        float bestDot = -1.0;
        for(int i=0; i<14; i++)
        {
            float d = dot(np, faceNorm[i]);
            // 4. Track which index gave the highest dot product
            if(d < bestDot)
            {
                bestDot = d;
                faceID = i;
            }
        }


        // create the Tangent and Bitengant vector
        vec3 T = cross(faceNorm[faceID], norm);
        vec3 texCol = vec3(1);
        // 5. That index is your face ID — use it to pick a color
        // assign a color per face ID
        vec3 albedo = vec3(1,0,0); // fallback
        if(faceID == 0)  albedo = vec3(0.188,0.353,0.624);
        if(faceID == 1)  albedo = vec3(1);
        if(faceID == 2)  albedo = vec3(1);
        if(faceID == 3)  albedo = vec3(0.165,0.337,0.314);
        if(faceID == 4)  albedo = vec3(0.165,0.337,0.314);
        if(faceID == 5)  albedo = vec3(0.165,0.337,0.314);
        if(faceID == 6)  albedo = vec3(0.165,0.337,0.314);
        if(faceID == 7)  
        {
            albedo = vec3(0.725,0.651,0.624);
        }
        if(faceID == 8)  
        {
            albedo = vec3(0.62,0.412,0.463);

            texCol = texture(iChannel3, T.yz/.061).xyz; 
            texCol *= texCol; // Rough sRGB to linear conversion... That's a whole other conversation. :)
            // A bit of color processing.
            texCol = smoothstep(.15, 0.45, pow(texCol, vec3(0.975, .968, .85)));
        }
        if(faceID == 9)  
        {
            albedo = vec3(0.816,0.643,0.439);


            texCol = texture(iChannel1, T.yz/.061).xyz; 
            texCol *= texCol; // Rough sRGB to linear conversion... That's a whole other conversation. :)
            // A bit of color processing.
            texCol = smoothstep(.15, 0.45, pow(texCol, vec3(0.975, .968, .85)));
        }
        if(faceID == 10)
        {
            albedo = vec3(0.569,0.647,0.463);

        }
        if(faceID == 11) albedo = vec3(0.71,0.749,0.675);
        if(faceID == 12) 
        {
            albedo = vec3(0.282,0.549,0.533);


            texCol = texture(iChannel2, T.yz/.061).xyz; 
            texCol *= texCol; // Rough sRGB to linear conversion... That's a whole other conversation. :)
            // A bit of color processing.
            texCol = smoothstep(.15, 0.45, pow(texCol, vec3(0.975, .968, .85)));
        }
        if(faceID == 13){
            albedo = vec3(0.706,0.392,0.122);


            texCol = texture(iChannel1, T.yz/.061).xyz; 
            texCol *= texCol; // Rough sRGB to linear conversion... That's a whole other conversation. :)
            // A bit of color processing.
            texCol = smoothstep(.15, 0.45, pow(texCol, vec3(0.975, .968, .85)));
        }



        // Light position in world space
        vec3 lp = ro + vec3(3, 3, 3);
        vec3 L =  lp - p;
        float distlpsp = max(length(L), 0.001);
        L /= distlpsp;

        // Light attenuation based on distance
        float atten = 1.0 / (1.0 + distlpsp * .2525);

        // Lighting terms 
        float ambience = 1.; 
        float diff = max(dot(norm, L), .0);

        // Specular with different colors based on objId
        vec3 specColor =  vec3(0.871);
        float spec = pow(max(dot(reflect(-L, norm), -rd), 0.0),24.0);

        // Base texture + separate specular

        col = (albedo * (diff + ambience) + specColor * spec * 3.);

        // Apply attenuation, shading, AND ambient occlusion
        col *= atten + (rim * vec3(0.7));
        col = mix(col, vec3(0), 1.0 - exp(-0.006224 * dt * dt * dt));

    }
    col += glow * .002;

    return col;
}


