// @paniq
// https://www.shadertoy.com/view/llfGRj
// face-centered lattice (rhombic dodecahedral symmetry), 12 directions
float lattice_fcc(vec3 p) {
    vec3 o = abs(p);
    vec3 q = o / 2.0;
    //float s = length(vec3(o.xy - (q.x + q.y), o.z));
    float s = length(vec3(o.xz - (q.x + q.z), o.y));
    //s = min(s, length(vec3(o.xz - (q.x + q.z), o.y)));
    s = min(s, length(vec3(o.yz - (q.y + q.z), o.x)));
    return s;
}

vec3 path(vec3 p)
{
    p.y += sin(p.z * 1.0) * .5;
    p.x += sin(p.z * 1.0) * .2;
    return p;
}

float map(vec3 p)
{
    p.xy *= mat2(cos(p.z*1.5 + vec4(0,11,33,0) ));
    p.x += sin(p.z * 1.0) * .4;
    p.y += sin(p.z * 1.0) * .1;

    vec3 p1 = p;
    p1.y += .0;
    //p1 = path(p1);
    p1 = vec3(mod(p1, 2.) - 1.);
    return lattice_fcc(p1) - 0.05;
}

// Inigo Quilez (MIT) https://www.shadertoy.com/view/ll2GD3
vec3 cosPalette(float t) {
    vec3 brightness = vec3(0.855, 0.281, 0.487);
    vec3 contrast = vec3(0.227, 0.298, 0.025);
    vec3 frequency = vec3(1.000, 1.000, 3.000);
    vec3 phase = vec3(-0.379, -0.180, -0.007);

    vec3 color = brightness + contrast * cos(6.28318 * (frequency * t + phase));
    return clamp(color, 0.0, 1.0); // sRGB
}

vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
        map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
        map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
    ));
}


void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2. * I - iResolution.xy) / iResolution.y;

    vec3 ro = vec3(0, 0,-iTime*.3);  
    ro = path(ro);
    vec3 rd = normalize(vec3(uv * 5., -1));
    float dt = 0.; 
    float voxel = 35.;
    O=vec4(0.);

    // ray march
    for(int i=0; i< 70; i++)
    {
        // ray position
        vec3 p = ro + rd * dt;
        // voxel from 
        // @OldEclipse
        // https://www.shadertoy.com/view/7fSXDw
        p = round(p * voxel) / voxel;

        //normal I think this helps the colors be more stable on the voxels
        vec3 n = calcNormal(p);

        // sdf
        float d = map(p); 

        // distance travel
        dt += d*.13; 

        // Color accumulation based on density, position and distance travelled
        O+=(exp(cos(float(i)*.1))  
            / (abs(d * .78)) * 0.153 + .1 )
            * vec4(cosPalette( n.x * n.y * (n.z+ iTime *4.)  ),0);
   } 
    // Tone mapping
    O = tanh(O/5e3);
}

