#define AA 2

// iq 
// https://iquilezles.org/articles/distfunctions2d/
float sdStar(vec2 p, float r, int n, float m)
{
    // next 4 lines can be precomputed for a given shape
    float an = 3.141593/float(n);
    float en = 3.141593/m;  // m is between 2 and n
    vec2  acs = vec2(cos(an),sin(an));
    vec2  ecs = vec2(cos(en),sin(en)); // ecs=vec2(0,1) for regular polygon

    float bn = mod(atan(p.x,p.y),2.0*an) - an;
    p = length(p)*vec2(cos(bn),abs(sin(bn)));
    p -= r*acs;
    p += ecs*clamp( -dot(p,ecs), 0.0, r*acs.y/ecs.y);
    return length(p)*sign(p.x);
}

vec2 lattice_bcc2(vec3 p) {
    float o   = length(p);
    float v = length(abs(p) - 1.0);
    return vec2(min(o, v), max(o, v));
}

float sdSphere( vec3 p, float r )
{
    return length(p) - r;
}

float sdBox( vec3 p, vec3 b )
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

// by iq. https://iquilezles.org/articles/smin
float smax(float a, float b, float k) {
	float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
	return mix(a, b, h) + k * h * (1.0 - h);
}


// ==================[ SDF ]==================
float map(vec3 p)
{ 
    vec3 p1 = p;
    p1.y += iTime * .21;
    // mod
    p1 = mod(p1,2.0)-1.0;

    vec2 bcc = lattice_bcc2(p1);

    float d  = (bcc.y - bcc.x) - 0.15;
    float d1 = sdSphere(p, 3.4);
    //float d1 = sdBox(p, vec3(5., 2.6, 5.));
    float d3 =  smax(-d,d1,.25);
    float d4 = sdStar(p1.xy, 0.65,  4, 0.35); 
    return d3 - d4 * 0.65;
}

// ==================[ normal ]=====================
vec3 calcNormal(vec3 p)
{
    float e = 0.01;
    return normalize(vec3(
        map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
        map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
        map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
    ));
}

// ==================[ palettes ]=====================
vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

// Inigo Quilez (MIT) https://www.shadertoy.com/view/ll2GD3
vec3 cosPalette(float t) {
    vec3 brightness = vec3(0.556, 0.424, 0.240);
    vec3 contrast = vec3(0.562, 0.457, 0.299);
    vec3 frequency = vec3(1.174, 0.713, 1.144);
    vec3 phase = vec3(0.795, -0.080, 0.305);

    vec3 color = brightness + contrast * cos(6.28318 * (frequency * t + phase));
    return clamp(color, 0.0, 1.0); // sRGB
}

// camera 
mat3 setCamera( in vec3 ro, in vec3 ta, float cr )
{
	vec3 cw = normalize(ta-ro);
	vec3 cp = vec3(sin(cr), cos(cr),0.0);
	vec3 cu = normalize( cross(cw,cp) );
	vec3 cv =          ( cross(cu,cw) );
    return mat3( cu, cv, cw );
}

vec3 render(vec3 ro, vec3 rd)
{   
    vec3 col = vec3(0.0);

    // running glow accumulator, starts dark, gets warmer as we march
    // this is what we'll add on top of the surface color at the end
    vec3 glow = vec3(0);
    float w = 0.;

    // ==================[ raymarch ]===================
    float dt = 0.0; 
    for(int i=0; i<80; i++)
    {
        float d = map(ro + rd * dt);

        if(abs(d) < 0.001 || dt > 20.0) break;

        // glow accumulation
        w = 1./ (0.01 + d*d) * exp(-.015 * dt);

        glow += vec3(0.361,0.925,1.000) * w * .022;

        dt += d * .5;  
    }

    // ==================[ colors, fog ]=====================
    if(dt < 10.0)
    {
        vec3 p = ro + rd * dt;

        vec3 norm = calcNormal(p);

        float NoV = clamp(dot(norm, -rd), 0.0, 1.0);

        float rim = pow(1.0 - NoV,4.0) * 3.2;

        // 1. Normalize p to get a pure direction from the origin
        vec3 np = normalize(norm);

        // 2. Define all 14 face normals (6 axis-aligned, 8 diagonal)
        vec3 faceNorm[14];
        // square faces
        faceNorm[0] = vec3( 1, 0, 0);
        faceNorm[1] = vec3(-1, 0, 0);
        faceNorm[2] = vec3( 0, 1, 0);
        faceNorm[3] = vec3( 0,-1, 0);
        faceNorm[4] = vec3( 0, 0,-1);
        faceNorm[5] = vec3( 0, 0, 1);

        // hex faces
        faceNorm[6] =  vec3( 1, 1, 1);
        faceNorm[7] =  vec3(-1, 1, 1);
        faceNorm[8] =  vec3( 1,-1, 1);
        faceNorm[9] =  vec3(-1,-1, 1);
        faceNorm[10] = vec3( 1, 1,-1);
        faceNorm[11] = vec3(-1, 1,-1);
        faceNorm[12] = vec3( 1,-1,-1);
        faceNorm[13] = vec3(-1,-1,-1);

        // 3. Loop over all 14 — compute dot product of np with each normal
        int faceID = 0;
        float bestDot = -1.0;
        for(int i=0; i<14; i++)
        {
            float d = dot(np, faceNorm[i]);
            // 4. Track which index gave the highest dot product
            if(d < bestDot)
            {
                bestDot = d;
                faceID = i;
            }
        }


        // 5. That index is your face ID — use it to pick a color
        // assign a color per face ID
        vec3 albedo = vec3(1,0,0); // fallback
        if(faceID == 0)  albedo = vec3(1, 0, 0);
        if(faceID == 1)  albedo = vec3(0, 1, 0);
        if(faceID == 2)  albedo = vec3(0, 0, 1);
        if(faceID == 3)  albedo = vec3(0.180,0.294,0.761);
        if(faceID == 4)  albedo = vec3(0, 1, 1);
        if(faceID == 5)  albedo = vec3(1, 0, 1);
        if(faceID == 6)  albedo = vec3(0.110,0.294,0.729);
        if(faceID == 7)  albedo = vec3(0.169,0.196,0.969);
        if(faceID == 8)  albedo = vec3(0.125,0.243,0.835);
        if(faceID == 9)  albedo = vec3(0.263,0.353,0.796);
        if(faceID == 10) albedo = vec3(0.165,0.475,0.875);
        if(faceID == 11) albedo = vec3(0.157,0.176,0.741);
        if(faceID == 12) albedo = vec3(0.094,0.271,0.627);
        if(faceID == 13) albedo = vec3(0.145,0.192,0.557);


        // Light position in world space
        vec3 lp = ro + vec3(3, 3, 3);
        vec3 L =  lp - p;
        float distlpsp = max(length(L), 0.001);
        L /= distlpsp;

        // Light attenuation based on distance
        float atten = 1.0 / (1.0 + distlpsp * .2525);

        // Lighting terms 
        float ambience = 1.; 
        float diff = max(dot(norm, L), .0);

        // Specular with different colors based on objId
        vec3 specColor =  vec3(0.871);
        float spec = pow(max(dot(reflect(-L, norm), -rd), 0.0),24.0);

        // Base texture + separate specular

        col = albedo * (diff + ambience) + specColor * spec * 3.;

        // Apply attenuation, shading, AND ambient occlusion
        col *= atten + (rim * vec3(0.7));
        col = mix(col, vec3(0), 1.0 - exp(-0.00224 * dt * dt * dt));

    }
    col += glow * .002;

    return col;
}


