void mainImage(out vec4 O, in vec2 I)
{   
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;

    vec2 mo = iMouse.xy/iResolution.xy;
	float time = 32.0 + iTime*.5;

    // camera	
    vec3 ta = vec3(0);
    vec3 ro = ta + vec3( 4.5*cos(0.1*time + 7.0*mo.x),3.3, 4.5*sin(0.1*time + 7.0*mo.x) );
    // camera-to-world transformation
    mat3 ca = setCamera( ro, ta, 0.0 );

    vec3 tot = vec3(0.0);

    for (int m = 0; m < AA; m++)
    for (int n = 0; n < AA; n++) {
        vec2 off = vec2(m, n) / float(AA) - 0.5;
        vec2 uv = (2.0 * (I + off) - iResolution.xy) / iResolution.y;
        uv *= 2.0;
        vec3 rd = ca *  normalize(vec3(uv, 2.5));
        vec3 col = render(ro, rd); 

        col = pow(col * 1.0, vec3(1.1 / 2.2));

        tot += col;
    }

    tot /= float(AA * AA);

    O = vec4(tot, 1.0);
}

