#define SCALE (20.0/R.y)
#define STEPS 30.0
//2D voxel bitmap
bool map(vec2 p)
{
    return dot(sin(p+vec2(0,iTime * 0.5)), cos(p.yx*.56)) > 0.9;
}

void mainImage(out vec4 O, in vec2 I)
{
    vec2 R = iResolution.xy;
    vec2 uv = I * SCALE;

    // rotate 
    vec2 wonder = (cos(iTime/vec2(1,.7)* 0.2 + 0.5) * R); 
    // screen center
    vec2 p1 = (R *.5) * SCALE;
    // animated target
    vec2 p2 = wonder * SCALE;
    // Ray Direction
    vec2 rd = normalize(p1 - p2);
    // prevent division by 0
    rd += vec2(rd.x==0., rd.y==0.) * 1e-5;

    // sign direction for each target
    vec2 sig = sign(rd);
    // voxel step size for each axis
    vec2 stp = sig / rd;

    // vox, dep, for loop, axis, hit 
    // voxel position
    vec2 vox = floor(p1);
    // initial step size to the next voxel 
    vec2 dep = ((vox - p1 + 0.5) * sig + 0.5) * stp;
    dep += vec2(0,1) * 1e-4;

    // voxel interesction point
    vec2 hit;
    // axis selector(ei. vec2(1,0) or vec2(0,1))
    vec2 axis;
    //output color, starting with map
    vec3 col = vec3(map(floor(uv))) * vec3(.0,.3,.5);
    // grid glow intensity
    vec2 edge = vec2(0.7);

    // loop through the voxels
    for(float i=0.; i<STEPS; i++)
    {   
        // stop if we hit a voxel
        if(map(vox)) break;

        // select the next closest voxel 
        axis = step(dep, dep.yx);
        // compute intersect point
        hit = p1 + dot(dep, axis) * rd;
        // step one voxel along the axis
        vox += sig * axis;
        // set the length of the next voxel 
        dep += stp * axis;

        // draw glowing points
        col += vec3(axis, 0) 
        * clamp(.5 * (.1 - length(hit - uv)) / SCALE + 0.5, 0., 1.)
        + .2 * float(vox==floor(uv));
    }

    // grid lines 
    vec2 grid = max(edge - 0.5 * abs(fract(uv+0.5)-0.5) / SCALE, 0.0);
    col.rg += grid;

    // Highlight raycast line from p1 to hit point
    vec2 pa = uv - p1;
    vec2 ba = hit - p1;

    float line = length(pa-ba * clamp(dot(pa,ba) / dot(ba,ba),0.,1.));

    col += vec3(.3, .6, 1) * clamp(.5 *(.05 - line) / SCALE + .5, .0, 1.);
    col += clamp(0.5*(0.15-length(pa)) / SCALE+0.5,0.0,1.0);
    O = vec4(col, 1);
}

