    vec3 L = vec3(xA, yA, iTime*SPEED + 15.);

    // accumulation, attenuation, vox direction and steps
    float accum = 0.0, att, voxDt, steps;

    // trans.. step light, henyey-greenstein 
    float transmittance = 1., stepL,henyey, newXyCros, dx,dy,dz, edge;

    vec3 lightAcc, colEdge;



    for(float i = 1.0; i<MAX; i++)
    {
        // Check if the current cell is solid. If yes, stop. 
        // The ray found something.
        if(map(vox)) break;

        // @Shane 
        // https://www.shadertoy.com/view/Xd3SDs
        // Unit ray jitter is another way to hide artifacts. It can also trick the viewer into believing
        // something hard core, like global illumination, is happening. :)
       //xyCrossing *= 1.0 + hash33(xyCrossing)*.005;
        xyCrossing += hash33(vox + ro) * stepDir * 0.005;


        // light distance to the nearest voxel 
        voxDt = length((vox+.5) - L)  * .2;

        // attenuation
        att = 1./ (16. + voxDt * voxDt );

        //accumulate the attenuation
        accum += att;

        //Increment steps
        steps++;

        // Compare the two depth values. Whichever is smaller tells you 
        // which boundary you reach first. That gives you an axis selector — 
        // either X or Y won this step.
        axis =  xyCrossing.x<xyCrossing.z? 
             ( xyCrossing.x<xyCrossing.y? vec3(1,0,0) : vec3(0,1,0) ):
             ( xyCrossing.z<xyCrossing.y? vec3(0,0,1) : vec3(0,1,0) );

        // Compute the exact world position where the ray crosses that 
        // boundary. You travel along the ray by exactly the winning depth distance. 
        // That landing point is hit.
        p = ro + dot(xyCrossing, axis) * rd;

        // Each step, compute the cosine of the angle between your ray direction and the 
        // direction from the current sample point toward the light
        float angleL = dot(rd, normalize(p-L));

        //Feed that cosine into Henyey-Greenstein with asymmetry parameter 
        float g = 0.45;
        henyey = (1. - g) / (4.*3.1416 * pow((1. + g*g - 2.*g*cos(angleL)),2.5)); 

        // create a copy of the voxel so we save it before steping 
        vox2 = vox;

        // Step into the next cell. Move one unit in the ray's direction,
        // but only along the winning axis. The other axis coordinate of voxel 
        // stays the same.
        vox += axis * axisDir;

        // make a copy of the xy corssing before steping
        newXyCros = dot(xyCrossing, axis);

        // Advance the depth on the winning axis only. Add one step size to it,
        // setting up the distance to the following boundary on that axis. The other 
        // depth value is untouched because you didn't cross that boundary.
        xyCrossing += axis * stepDir;

        // step light 
        stepL = dot(xyCrossing, axis) - newXyCros * 0.7;

        // glow of the step light 
        transmittance *= exp(-0.000712 * stepL);

        // light accumulation
        lightAcc += max(map2(p), 0.0) * henyey * transmittance * stepL * att;

        // find the edges with the xy crossings
        dx = xyCrossing.x - L.x * 0.2,
        dy = xyCrossing.y - 0.,
        dz = xyCrossing.z - 1.;

        float d1 = min(dx, min(dy, dz));
        float d2 = min(max(dy,dx), max(dy,dz));
        //d2 = min(d2, max(dx, dz));

        if(map2(p+ vec3(0,0,0)) > 0.)
        edge = (1. - smoothstep(-.5, .4, d2 - d1));


    }

    vec3 nor = axisDir * axis;
    vec3 hit = p + rd*dot(xyCrossing-stepDir, axis);
    float NoV = clamp(dot(nor, -hit), 0.0, 1.0);
    float rim = pow(1. - NoV, 3.0) * 10.0;

    // setup the grid so we see each unit of the grid
    vec3 grid = max(vec3(.7) - 2. * abs(fract(p+.5)-0.) * SCALE, 0.0);
    vec3 newGrid = mix(vec3(0.061),vec3(0),grid.x + grid.y + grid.z);

    // Hash to return a random uv number from 0 to 6 
    float rand = hash(floor(vox)) * 1. + sin(iTime * .0 + .530) * .0 + .4;

    // Color the cell which we can find if the floor of uv is = to the voxel which 
    // is each cell
    col =  colArr[int(rand)] * 2.+ vec3(0.494,0.086,0.208) * edge * 1.0 * rim;// os( (vox.y * 1.151) - u_time) *

    //Apply shading 
    vec3 shade = mix(vec3(0.243,0.243,0.259), vec3(1.1), dot(axis, vec3(0,1,.5)));

    // appply color
    col = (lightAcc * col);
    //col = col ;

    //col = mix(col, vec3(0,0.2,0.9), edge);
    // look at the henyey formula
    //col = vec3(henyey);
    //col = vec3(transmittance);
    //col = colEdge;
    // grid lines
    col -= newGrid;

    // fog
    float fog = steps/MAX ;
    col = mix(col, vec3(0.2,.24,.3), fog);

    // gamma correction
    //col = pow(col, vec3(1.1/2.2)); 

    O = vec4(col, 1.0);
}

