*/

float sdBox( vec3 p, vec3 b )
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

mat2 r2(float r)
{
    return mat2(cos(r), sin(r), -sin(r), cos(r));
}

float map(vec3 p)
{ 
    p.xz *= r2(iTime * 0.5);
    p.yz *= r2(iTime * 0.25);

    return sdBox(p, vec3(1));
    //return length(p) - 1.0; 
}

vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
        map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
        map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
    ));
}

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;

    // init
    vec3 ro = vec3(0.0, 0.0, 3.0);
    vec3 rd = normalize(vec3(uv, -1.0));

    float dt = 0.0;

    vec3 col = vec3(0.4);

    // Raymarching 
    float md = 1e9;
    bool stp = false;

    float prevStp = 1e9;
    float edgeSize =  .2;
    vec3 p;
    for(int i=0; i<80; i++)
    {
        p = ro + rd * dt; 

        float d = map(p) - edgeSize;                      

        dt += d;                             

        md = min(md, d);

        if(d < 0.001 || dt > 30.) break;

        if(md < edgeSize && d > prevStp && i > 0)
           stp = true;

       prevStp = d;
    }

    // we hit something
    float nl;

    if(dt < 30.)
    {
        vec3 n = calcNormal(p);
        vec3 l = normalize(vec3(0,1,3));

        nl = max(dot(n, l), 0.0);

        col = vec3(0.9,0.6,0) * nl;

    }

    if(!stp)
        md = 1.0;

    float edge =  smoothstep(edgeSize - .025, edgeSize  + 0.01, md);

    col *= edge;

    O = vec4(col, 1.0);
}

