const float maxT = 30.0;
const float edgeSize =  0.2;

float rayMarch(vec3 ro, vec3 rd, out bool edg)
{

    float infl = edgeSize;
    float dt = 0.0;

    for( int i=0; i<250 && dt<maxT; i++ )
    {
        // position 
        vec3 p = ro + rd * dt; 
        // sdf shape - the size of the edge 
        float d = map(p) - infl;

        // if we reached the shape 
        if( d<0.001 )
        {
            // this will toggle if we hit the boundery of the shape or not
            edg = !edg;
            // if the edge is strue then add the edge size to it
            // since we added already make the edge 0 
            if( edg ) { d += infl; infl=0.; }
            else { break; }
        }
        // accumulate the sdf to the distance travel
        dt += d;
    }
    return dt;
}

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;

