    vec3 ro = vec3(0,0, 3);
    vec3 rd = normalize(vec3(uv, -1));

    // simple none 0 color
    vec3 col = vec3(0.4);

    // edge detection
    bool edg = false;

    // ray march returns distance travel
    float dt = rayMarch(ro, rd, edg);

    // colors to the sdf shape
    if( dt<maxT )
    {
        // position, normal, light and light direction
        vec3 p = ro+rd*dt;
        vec3 n = calcNormal(p);
        vec3 l = normalize(vec3(0,1,3));
        float nl = max(dot(n, l), 0.0);
        col = vec3(0.9,0.5,0) * nl;
    }

    // if the edge is true make it black 
    if(edg) col *= 0.0;

    O = vec4(col, 1.0);
}

