    return normalize(vec3(
        map(p + vec3(e,0,0)).x - map(p - vec3(e,0,0)).x,
        map(p + vec3(0,e,0)).x - map(p - vec3(0,e,0)).x,
        map(p + vec3(0,0,e)).x - map(p - vec3(0,0,e)).x
    ));
}


const float maxT = 30.0;
const float edgeSize =  0.2;

float rayMarch(vec3 ro, vec3 rd, out bool edg)
{

    float infl = edgeSize;
    float dt = 0.0;
    float id = -1.0;
    for( int i=0; i<250 && dt<maxT; i++ )
    {
        // position 
        vec3 p = ro + rd * dt; 
        // sdf shape - the size of the edge 
        vec2 sdf = map(p);
        float d = sdf.x  - infl;

        // if we reached the shape 
        if( (d)<0.001 )
        {
            if(!edg)
            {
                // at the first hit save the id
                id = sdf.y;
                d += infl;
                infl = .0;
                edg = true;
            }

            // if the edge is strue then add the edge size to it
            // since we added already make the edge 0 
            else
            {
                if(id == sdf.y)
                    edg = false;
                break;
            }
        }
        // accumulate the sdf to the distance travel
        dt += d;
    }
    return dt;
}

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;

    // init ray origin and ray direction
    vec3 ro = vec3(0,0, 3. - iTime);

    vec3 rd = normalize(vec3(uv, -1));

    // simple none 0 color
    vec3 col = vec3(0.2);

    // edge detection
    bool edg = false;

    // ray march returns distance travel
    float dt = rayMarch(ro, rd, edg);

    // colors to the sdf shape
    if( dt<maxT )
    {
        // position, normal, light and light direction
        vec3 p = ro+rd*dt;
        vec3 n = calcNormal(p);
        vec3 l = normalize(vec3(0,1,3));
        float nl = max(dot(n, l), 0.0);
        col = vec3(0.9,0.5,0) * nl;


    }

    col = mix(col, vec3(0.1), 1. - exp(-0.00015 * dt*dt*dt));


    // if the edge is true make it black 
    if(edg) col *= 0.;

    O = vec4(col, 1.0);
}

