bool map(vec3 p)
{
    return dot(sin(p * .13), cos(p.yzx*.4384))+p.y*0.0561 > .9;
}

float map2(vec3 p)
{
    return dot(sin(p * .13), cos(p.yzx*.4384))+p.y*.061;
}

float hash(vec3 p) {
    return fract(sin(dot(p, vec3(127.1, 311.7, 411.7))) * 43758.5453);
}

// Cheap vec3 to vec3 hash. Works well enough, but there are other ways.
vec3 hash33(vec3 p){ 

    float n = sin(dot(p, vec3(7, 157, 113)));    
    return fract(vec3(2097152, 262144, 32768)*n); 
}


void mainImage(out vec4 O, in vec2 I)
