    // X boundary crossings, and between consecutive Y boundary crossings. 
    // These are your two step sizes, one per axis. The faster you move in a 
    // direction, the shorter the distance between crossings on that axis.
    vec3 axisDir = sign(rd);
    vec3 stepDir = (1. / abs(rd)) * 1.;

