    // and the very first Y crossing. These two values together are your depth. 
    // They're not equal — your origin is somewhere inside a cell, so one boundary 
    // is closer than the other. This is the initial state of dep before the loop 
    // touches anything.
    vec3 xyCrossing = ((vox-ro + .0) // so we are in the middle of the cell
    * axisDir + 0.6) // this will anchor the ray on the grid
    * stepDir; // this will move us over to the next cell

    vec3 axis, p, vox2;

