        // setting up the distance to the following boundary on that axis. The other 
        // depth value is untouched because you didn't cross that boundary.
        xyCrossing += axis * stepDir;

        // step light 
        stepL = dot(xyCrossing, axis) - newXyCros * .07;

        // glow of the step light 
        transmittance *= exp(-0.000712 * stepL);

        // light accumulation
        lightAcc += max(map2(p), .0) * henyey * transmittance * stepL * att;

        // find the edges with the xy crossings
        dx = xyCrossing.x - 0.,
        dy = xyCrossing.y + 0.5,
        dz = xyCrossing.z - .2;

        float d1 = min(dx, min(dy,dz));
        float d2 = min(dy,max(dz,dy));//max(dy,dx), max(dy,dz));
        //d2 = min(d2, max(dx, dz));

        //if(map2(p+ vec3(0,0,0)) > 0.)
        edge = (1. - smoothstep(-5.0, .4, d2-dz));


    }

    vec3 nor = axisDir * axis;
    vec3 hit = p + rd*dot(xyCrossing-stepDir, axis);
    float NoV = clamp(dot(nor, -hit), 0.0, 1.0);
    float rim = pow(1. - NoV, 3.0) * 10.0;

    // setup the grid so we see each unit of the grid
    vec3 grid = max(vec3(.7) - 2. * abs(fract(p+.5)-0.) * SCALE, 0.0);
    vec3 newGrid = mix(vec3(0.061),vec3(0),grid.x + grid.y + grid.z);

    // Hash to return a random uv number from 0 to 6 
    float rand = hash(floor(vox)) * 2. + sin(iTime * 2.0 + .530) * .0 + .4;

