// sphere intersection using quadratics
// x^2 + y^2 + z^2 = r^2 thats the same as 
// p^2 - r^2 = 0 
vec2 intersect(vec3 ro, vec3 rd, float r, out bool hit)
{
    vec3 op = -ro;

    float b = dot(op, rd);

    float dis = b * b  - dot(op,op) + r * r; 

    float tf, tn;
    if(dis > 0.)
    {
        float root = sqrt(dis);

        tn = b - root;
        tf = b + root;

        hit = true;
    } else {
        hit = false;
    }

    return vec2(tn, tf);
}

