vec3 refract_snell(vec3 l, vec3 n, float n0, float n1)
{
    // Snell's law
    // http://en.wikipedia.org/wiki/Snell's_law
    float c = dot(l, -n);
    float r = n0/n1;
    float c1 = sqrt(1.0 - r*r*(1.0-c*c));
    return r*l + (r*c-c1)*n;
}

