#define FAR 30.
float objId = 0.0;

float hash(vec3 p) {
    return fract(sin(dot(p, vec3(127.1, 311.7, 511.7))) * 43758.5453);
}


float opUnion(float sdf, float thickness )
{
    return abs(sdf)-thickness;
}

float smin( float a, float b, float k )
{
    k *= 4.0;
    float h = max(k-abs(a-b),0.0);
    return min(a, b) - h*h*0.25/k;
}

mat2 r2(float a)
{
    return mat2(cos(a), sin(a), -sin(a), cos(a));
}

vec2 map(vec3 p)
{ 
    float offset = 6.3;

    vec3 cellId = vec3(
        floor((p.x) / offset),
        floor((p.y) / 5.),
        floor((p.z) / offset)
    );

    float xOff = hash(cellId + vec3(321,40,30)) * 1.2;
    float yOff = hash(cellId + vec3(21,41,30)) * .2;
    float zOff = hash(cellId + vec3(51,21,40)) * 1.2;

    vec3 np2 = p;

    ///*
    p = vec3(
        mod(p.x + xOff, offset) - offset *.5,
        mod(p.y + yOff, 5.) - 5. *.5,
        mod(p.z + zOff, offset) - offset *.5
    );
    //*/

    float speed = 1.;
    float size = .7;
    vec3 np = p;

    np.xz *= r2(iTime * .05);

    np.y += sin(np.x * 3. + iTime * speed) * 0.21;
    np.z += cos(np.y * 3. + iTime * speed) * 0.21;

    float d2 = length(np ) - 2.3 * size;//+ vec3(cos(iTime*speed * 1.2) * .6,sin(iTime*speed) * .6,0)) - 2.; 
    float d1 = length(np) - 2.5 * size; 
    float d3 = length(np) - .7 * size;

    d1 = opUnion(d1, .01);
    d2 = opUnion(d2, .001);
    d3 = opUnion(d3, .081);

    objId = step(d1, d2);

    float minD = smin(d1, d2, 0.01);
    minD = smin(minD, d3, 0.01);

    float ids = d1 < d2 ? 0. : d2 < d3 ? 10.0: 30.; 
    return vec2(minD, ids);
}


// ==================[ normal ]=====================
vec3 calcNormal(vec3 p)
{
    float e = 0.1;
    return normalize(vec3(
        map(p + vec3(e,0,0)).x - map(p - vec3(e,0,0)).x,
        map(p + vec3(0,e,0)).x - map(p - vec3(0,e,0)).x,
        map(p + vec3(0,0,e)).x - map(p - vec3(0,0,e)).x
    ));
}


// Cheap vec3 to vec3 hash. Works well enough, but there are other ways.
vec3 hash33(vec3 p){ 

    float n = sin(dot(p, vec3(7, 157, 113)));    
    return fract(vec3(2097152, 262144, 32768)*n); 
}


vec3 polyPalette1(float t) {
    vec3 c0 = vec3(-0.049, 0.542, 1.495);
    vec3 c1 = vec3(6.173, -.7578, -0.572);
    vec3 c2 = vec3(-16.596, 1.749, 0.226);
    vec3 c3 = vec3(10.570, -1.169, 0.258);

    vec3 color = c0 + c1 * t + c2 * t * t + c3 * t * t * t;
    return clamp(color, 0.0, 1.0);
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}


