#define FAR 30.
float objId = 0.0;

float opUnion(float sdf, float thickness )
{
    return abs(sdf)-thickness;
}

float smin( float a, float b, float k )
{
    k *= 4.0;
    float h = max(k-abs(a-b),0.0);
    return min(a, b) - h*h*0.25/k;
}

mat2 r2(float a)
{
    return mat2(cos(a), sin(a), -sin(a), cos(a));
}

// iq
// https://www.shadertoy.com/view/4sfGzS
float noise( in vec3 x )
{
    #if 1

    vec3 i = floor(x);
    vec3 f = fract(x);
	f = f*f*(3.0-2.0*f);
	vec2 uv = (i.xy+vec2(37.0,17.0)*i.z) + f.xy;
	vec2 rg = textureLod( iChannel0, (uv+0.5)/256.0, 0.0).yx;
	return mix( rg.x, rg.y, f.z );

    #else

    ivec3 i = ivec3(floor(x));
    vec3 f = fract(x);
	f = f*f*(3.0-2.0*f);
	ivec2 uv = i.xy + ivec2(37,17)*i.z;
	vec2 rgA = texelFetch( iChannel0, (uv+ivec2(0,0))&255, 0 ).yx;
    vec2 rgB = texelFetch( iChannel0, (uv+ivec2(1,0))&255, 0 ).yx;
    vec2 rgC = texelFetch( iChannel0, (uv+ivec2(0,1))&255, 0 ).yx;
    vec2 rgD = texelFetch( iChannel0, (uv+ivec2(1,1))&255, 0 ).yx;
    vec2 rg = mix( mix( rgA, rgB, f.x ),
                   mix( rgC, rgD, f.x ), f.y );
    return mix( rg.x, rg.y, f.z );

    #endif
}

const mat3 m = mat3( 0.00,  0.80,  0.60,
                    -0.80,  0.36, -0.48,
                    -0.60, -0.48,  0.64 );


vec2 map(vec3 p)
{ 

    p = vec3(
        mod(p.x, 6.) - 3.,
        mod(p.y, 6.) - 3.,
        mod(p.z, 8.) - 4.
    );


    float speed = 1.;
    vec3 np = p;
    np.xz *= r2(iTime * .05);
    np.y += sin(np.x * 3.5 + iTime * speed) * 0.1;
    np.x += sin(np.z * 3.5 + iTime * speed) * 0.2;


    float d2 = length(np) - 1.; 

    float d1 = length(np) - 2.5; 
    d1 = opUnion(d1, .15);
    d2 = opUnion(d2, .2);

    objId = step(d1, d2);

    float minD = smin(d1, d2, 0.2);//min(d1, d2);
    float ids = d1 < d2 ? 0. : 10.0; 

    return vec2(minD, ids);
}


// ==================[ normal ]=====================
vec3 calcNormal(vec3 p)
{
    float e = 0.1;
    return normalize(vec3(
        map(p + vec3(e,0,0)).x - map(p - vec3(e,0,0)).x,
        map(p + vec3(0,e,0)).x - map(p - vec3(0,e,0)).x,
        map(p + vec3(0,0,e)).x - map(p - vec3(0,0,e)).x
    ));
}


// Cheap vec3 to vec3 hash. Works well enough, but there are other ways.
vec3 hash33(vec3 p){ 

    float n = sin(dot(p, vec3(7, 157, 113)));    
    return fract(vec3(2097152, 262144, 32768)*n); 
}


void mainImage(out vec4 O, vec2 I) 
{
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;

    // init 
    vec3 ro = vec3(0,0. + iTime * -.2,4. - iTime * -1.3);
    // @Shane camera trick 
    // Unit direction ray. The last term is one of many ways to fish-lens the camera.
    // For a regular view, set "rd.z" to something like "0.5."
    vec3 rd = normalize(vec3(uv, (1. - dot(uv, uv)*1.)*.45));

    //vec3 rd = normalize(vec3(uv, -1));

    vec3 col = vec3(uv.y + 1.) * 0.0, sp;

    float as = 1.33;


    // @Shane 
    // Ray distance, bail out layer number, surface distance and normalized accumulated distance.
	float t=0., layers=0.,f = 0., d, aD, sOne, sTwo;

    // Unit ray jitter is another way to hide artifacts. It can also trick the viewer into believing
    // something hard core, like global illumination, is happening. :)
    rd *= 0.985 + hash33(rd)*.0203;

    // Surface distance threshold. Smaller numbers give a sharper object. I deliberately
    // wanted some blur, so bumped it up slightly.
    float thD = 0.025; // + smoothstep(-0.2, 0.2, sin(iTime*1.75 - 3.14159*0.4))*0.025;

    // add a refraction ray direction 
    vec3 refRd = vec3(0), q;

    // ids and sdf
    vec2 shape = vec2(0);

    // Only a few iterations seemed to be enough. Obviously, more looks better, but is slower.
	for(int i=0; i<80; i++)	
    {    
        // Break conditions. Anything that can help you bail early usually increases frame rate.
        if(layers>50. || col.x<0.0 || t>20.) break;

        // Current ray postion. Slightly redundant here, but sometimes you may wish to reuse
        // it during the accumulation stage.

        sp = ro + rd*t;
        //vec3 n = calcNormal(sp);
        // lets get the cosine of theta so we can use it for some reflection
        //float cosT = dot(-rd, n);
        q = 8.0*sp;
        f = noise( 20.*sp );
        //sp = ro + refRd*t;
        shape = map(sp + f * 0.3); // Distance to nearest point in the cube field.

        d = shape.x;
        // If we get within a certain distance of the surface, accumulate some surface values.
        // Values further away have less influence on the total.
        //
        // aD - Accumulated distance. I interpolated aD on a whim (see below), because it seemed 
        // to look nicer.
        //
        // 1/.(1. + t*t*.25) - Basic distance attenuation. Feel free to substitute your own.
        // Normalized distance from the surface threshold value to our current isosurface value.
        // this is an abs value function going down from 1 on the y ^ axis at 0 on the x 
        // axis between .02
        aD = (thD-abs(d)*5./15.)/thD;

        // If we're within the surface threshold, accumulate some color.
        // Two "if" statements in a shader loop makes me nervous. I don't suspect there'll be any
        // problems, but if there are, let us know.
        if(aD>0. && shape.y > 0.) { 
            // Smoothly interpolate the accumulated surface distance value, then apply some
            // basic falloff (fog, if you prefer) using the camera to surface distance, "t."
            col +=  aD*aD*(3. - 2.*aD) / (1. + t*t*f)*.911; 
            sOne += (1. - shape.y);
            layers++;

            vec3 L = normalize(vec3(3,3,4));
            vec3 n = calcNormal(sp);
            vec3 rd2 = refract(rd, n, 1.933);

            float diff = max(dot(n, L), 0.) * 0.2;

            col *= vec3(0.6 * f,0.05,0.15) + diff + vec3(0.6);

        } else if(aD > 0. && shape.y < 1.)
        { 
            col +=  aD*aD*(3. - 2.*aD) / exp(f * t) *.0541; 
            sTwo +=  1. - shape.y;

            vec3 n = calcNormal(sp);
            vec3 rd2 = refract(rd, n, 1.933);

            float NoV = clamp(dot(n, -rd2), 0.0, 1.0);
            float rim = pow(1.0 - NoV,4.0) * .15;

            vec3 L = normalize(vec3(3,3,4));

            float diff = max(dot(n, L), 0.) * .5;
            //col += n * 0.5 + 0.5;
            //col *= vec3(0,0.04,0.04) * (diff + 2.) + vec3(.85) + (rim * vec3(0.7));
            col *= vec3(0,0.074 * f * float(i) * 0.02,0.074 * float(i) * 0.01) * (diff + 2.) + vec3(.85) + (rim * vec3(0.7));
            //col *= vec3(0,f * 0.094,f * 0.094) * (diff + 2.) + vec3(0.8) + (rim * vec3(0.7));

            layers++;
        }
        // Kind of weird the way this works. I think not allowing the ray to hone in properly is
        // the very thing that gives an even spread of values. The figures are based on a bit of 
        // knowledge versus trial and error. If you have a faster computer, feel free to tweak
        // them a bit.
        t += max(abs(d)*.5, thD* 0.3); 
	}

    // I'm virtually positive "col" doesn't drop below zero, but just to be safe...
    col = max(col, 0.);

    // tone mapping 
    col = 1. - exp( -col );

    col = mix(vec3(0.001), col, smoothstep(1.3, .4, length(uv * vec2(0.5,0.5) )));

    O = vec4(col, 1.0);
}

