#define AA 2

// create the vector arrow
float arrow(vec3 p, vec3 a, vec3 b, float off, int id)
{
    float d1 = sdCapsule(p, a, b, 0.1);

    vec3 np = p;


    if(id == 2)
    {
        np += vec3(-b.x + off,-b.y - off,0);
        np.xy *= r2(0.9);
    }
    else if(id == 3)
    {
        np += vec3(-b.x - off,-b.y - off,0);
        np.xy *= r2(-0.9);
    } 
    else 
    {
        np += vec3(-b.x ,-b.y - off *2.,0);
    }
    float d2 = sdCone(np,vec2(0.1,0.2),.4);

    return min(d1,d2);
}

// the plane
float plane(vec3 p)
{
    p.y += 0.2;
    vec3 a1 = vec3(3.,0.05,3);
    vec3 a2 = vec3(a1.x-0.2,a1.y+0.2,a1.z-0.2);
    float d1 = sdRoundBox(p, a1, 0.02);
    float d2 = sdRoundBox(p, a2, 0.02);

    return d1; //max(d1,-d2);
}


