    float off = 0.2;

    // translate d2 to the tip of d2
    vec3 a3 = vec3(b2.x,b2.y + off,b2.z);
    vec3 b3 = vec3(b2.x + b1.x + off, b2.y + b1.y+ off, b2.z + b1.z);

    // translate d3 to the tip of d2
    vec3 a4 = vec3(b1.x,b1.y +off,b1.z);
    vec3 b4 = vec3(b2.x + b1.x- off, b2.y + b1.y + off,  b2.z + b1.z);

