    vec3 b5 = b1 + b2;

    // arrow vector shape
    float d2 = arrow(p, a1, b1, off, 2);
    float d3 = arrow(p, a2, b2, off, 3);

    // translate d2 to the tip of d3
    float d4 = arrow(p, a3, b3, off, 2);

    // translate d3 to the tip of d2
    float d5 = arrow(p, a4, b4, off, 3);

    // final sum of a + b
    float d6 = arrow(p, a5, b5, off, 4);

    // final shape
    float shape = d1;
    float id = 1.0;

    if(d2 < shape) { shape = d2; id = 2.;}
    if(d3 < shape) { shape = d3; id = 3.;}

    if(d4 < shape) { shape = d4; id = 2.;}
    if(d5 < shape) { shape = d5; id = 3.;}

    if(d6 < shape) { shape = d6; id = 4.;}

    return vec2(shape, id);
}

vec2 rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.;
    float id = 0.;
    for(int i=0; i<80; i++)
    {
        // position along the ray 
        vec3 p = ro + rd * dt; 

        // current distance to the scene
        vec2 sdf = map(p);                      

        float d = sdf.x;

        id = sdf.y;
        // march the ray
        dt += d;                             

        if(abs(d) < 0.001 || dt > 30.) break;
    }

    return vec2(dt, id);
}

vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)).x - map(p - vec3(e,0,0)).x,
        map(p + vec3(0,e,0)).x - map(p - vec3(0,e,0)).x,
        map(p + vec3(0,0,e)).x - map(p - vec3(0,0,e)).x
    ));
}


mat3 setCamera( in vec3 ro, in vec3 ta, float cr )
{
	vec3 cw = normalize(ta-ro);
	vec3 cp = vec3(sin(cr), cos(cr),0.0);
	vec3 cu = normalize( cross(cw,cp) );
	vec3 cv =          ( cross(cu,cw) );
    return mat3( cu, cv, cw );
}


vec3 render(vec3 ro, vec3 rd)
{   
    vec3 col = vec3(0.05);

    vec2 dt = rayMarch(ro,rd);

    if(dt.x < 30.)
    {
        vec3 n = calcNormal(ro + rd * dt.x);
        vec3 l = normalize(vec3(0,1.,1));
        vec3 bgcol = vec3(0);

        float diff = max(dot(n, l), 0.0);
        float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 32.0);

        if (dt.y > 3.)
            bgcol = vec3(0,0.2,0.9);
        else if (dt.y > 2.)
            bgcol = vec3(0.8,0.04,0.1);
        else if(dt.y > 1.)
            bgcol = vec3(0.1,0.7,0.1);
        else if (dt.y > 0.)
            bgcol = vec3(0,0.4,0.6);


        col = bgcol * (diff + .15) + vec3(0.5) * spec * .6;

    }

    return col;
    //O = vec4(col,1.0);
}


