vec2 map(vec3 p)
{ 
    vec3 np1 = p;

    float speed = 1.;
    //np1.xz *= r2(iTime * .05);
    np1.y += sin(np1.x * 3.5 + iTime * speed) * 0.1;
    np1.x += sin(np1.z * 3.5 + iTime * speed) * 0.2;

     np1 = vec3(
        mod(np1.x, 7.) - 3.5,
        mod(np1.y, 7.) - 3.5,
        mod(np1.z, 10.) - 5.
    );

    float f = noise( 20.*p );

    np1 += f * .3;

    p = vec3(
        mod(p.x, 7.) - 3.5,
        mod(p.y, 7.) - 3.5,
        mod(p.z, 10.) - 5.
    );

    vec3 np = p;
    np.xz *= r2(iTime * .05);
    np.y += sin(np.x * 3.5 + iTime * speed) * 0.1;
    np.x += sin(np.z * 3.5 + iTime * speed) * 0.2;

    float d3 = length(np1) - 3.; 

    float d2 = length(np) - 1.; 

    float d1 = length(np) - 2.5; 
    d1 = opUnion(d1, .05);
    d2 = opUnion(d2, .08);
    d3 = opUnion(d3, .05);

    objId = step(d1, d2);

    //float minD = smin(d1, d2, 0.2);//min(d1, d2);
    float ids = d1 < d2 ? 0. : 10.0; 

    float minD = smin(d1, d2, 0.2);

    if(d3 < minD) { minD = smin(minD, d3, 0.2); ids = 20.; }

    return vec2(minD, ids);
}


