#define AA 2

// create the vector arrow
float arrow(vec3 p, vec3 a, vec3 b, float off, int id)
{
    float d1 = sdCapsule(p, a, b, 0.1);

    vec3 np = p;


    if(id == 2)
    {
        np += vec3(-b.x + off,-b.y - off,0);
        np.xy *= r2(0.9);
    }
    else if(id == 3)
    {
        np += vec3(-b.x - off *1.,-b.y - off * .5,0);
        np.xy *= r2(-1.1);
    } 
    else if(id == 4) 
    {
        np += vec3(-b.x + off * 0.6,-b.y - off * 1.6,0);
        np.xy *= r2(.4);
    } else 
    {
        np += vec3(-b.x - off * .5,-b.y - off * 1.1,0);
        np.xy *= r2(-0.4);
    }
    float d2 = sdCone(np,vec2(0.1,0.2),.4);

    return min(d1,d2);
}

// the plane
float plane(vec3 p)
{
    p.y += 0.2;
    vec3 a1 = vec3(3.,0.05,3);
    return sdRoundBox(p, a1, 0.02);
}


vec2 map(vec3 p)
{
    p.yz *= r2(-0.05);
    vec2 mu = iMouse.xy/iResolution.xy;

    // offset 
    float off = 0.2;

    // plane
    float d1 = plane(p);

    vec3 a1 = vec3(0,0,0);
    vec3 b1 = vec3(2.5,1.3,0);

    vec3 a2 = b1;
    vec3 b2 = vec3(-.9,3.,0);

    vec3 a3 = a1;
    vec3 b3 = b2;

    // final sum of all 3 vectors 
    vec3 a4 = a1;
    vec3 b4 = (b1 + b2) * 0.5;

    // arrow vector shape
    float d2 = arrow(p, a1, b1, off, 3);
    float d3 = arrow(p, a2 + vec3(0,off,0), b2 + vec3(0,off,0), off, 2);

    // translate d2 to the tip of d3
    float d4 = arrow(p, a3 , b3 + vec3(0,-off,0), off, 4);

    // translate d3 to the tip of d2
    float d5 = arrow(p, a4, b4 + vec3(0,-off,0), off, 5);

    // final sum of a + b
   // float d6 = arrow(p, a5, b5, off, 4);

    // final shape
    float shape = d1;
    float id = 1.0;

    if(d2 < shape) { shape = d2; id = 3.;}
    if(d3 < shape) { shape = d3; id = 2.;}

    if(d4 < shape) { shape = d4; id = 4.;}
    if(d5 < shape) { shape = d5; id = 5.;}

    //if(d6 < shape) { shape = d6; id = 4.;}

    return vec2(shape, id);
}

vec2 rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.;
    float id = 0.;
    for(int i=0; i<80; i++)
    {
        // position along the ray 
        vec3 p = ro + rd * dt; 

        // current distance to the scene
        vec2 sdf = map(p);                      

        float d = sdf.x;

        id = sdf.y;
        // march the ray
        dt += d;                             

        if(abs(d) < 0.001 || dt > 30.) break;
    }

    return vec2(dt, id);
}

vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)).x - map(p - vec3(e,0,0)).x,
        map(p + vec3(0,e,0)).x - map(p - vec3(0,e,0)).x,
        map(p + vec3(0,0,e)).x - map(p - vec3(0,0,e)).x
    ));
}


mat3 setCamera( in vec3 ro, in vec3 ta, float cr )
{
	vec3 cw = normalize(ta-ro);
	vec3 cp = vec3(sin(cr), cos(cr),0.0);
	vec3 cu = normalize( cross(cw,cp) );
	vec3 cv =          ( cross(cu,cw) );
    return mat3( cu, cv, cw );
}


vec3 render(vec3 ro, vec3 rd)
{   
    vec3 col = vec3(0.0123);

    vec2 dt = rayMarch(ro,rd);

    if(dt.x < 30.)
    {
        vec3 n = calcNormal(ro + rd * dt.x);
        vec3 l = normalize(vec3(0,1.,1));
        vec3 bgcol = vec3(0);

        float diff = max(dot(n, l), 0.0);
        float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 32.0);

        if (dt.y > 4.)
            bgcol = vec3(0.2);
        else if (dt.y > 3.)
            bgcol = vec3(0,0.2,0.9);
        else if (dt.y > 2.)
            bgcol = vec3(0.8,0.04,0.1);
        else if(dt.y > 1.)
            bgcol = vec3(0.1,0.7,0.1);
        else if (dt.y > 0.)
            bgcol = vec3(0,0.4,0.6);


        col = bgcol * (diff + .15) + vec3(0.5) * spec * .6;

    }

    return col;
    //O = vec4(col,1.0);
}


