    vec3 np = p;
    np.xz *= r2(iTime * .05);
    np.y += sin(np.x * 3. + iTime * speed) * 0.31;
    np.z += cos(np.y * 3. + iTime * speed) * 0.31;
    float d2 = length(np + vec3(cos(iTime*speed * 1.2) * .6,sin(iTime*speed) * .6,0)) - 1.; 

