mat3 rotate_from_to(vec3 u, vec3 v) // create the rotation matrix that rotates from u direction to v direction
{
    u = normalize(u);
    v = normalize(v);
    vec3 X  = normalize(cross(u, v));
    vec3 Z1 = normalize(cross(X, u));
    vec3 Z2 = normalize(cross(X, v));
    mat3 R = outerProduct(X,X) + outerProduct(v,u) + outerProduct(Z2, Z1);
    return R;
}

float arrow(vec3 a, vec3 b, vec3 p)
{
    p -= a; // Translate to start at A

    // Rotate to align with direction: B-A
    vec3 ab = b-a;
    mat3 R = rotate_from_to(vec3(0,1,0), ab);
    p *= R;

    // Draw capsule and cone
    float len = length(ab);
    //float sdf = seg(vec3(0), vec3(0,len,0), p)-.05;
    float sdf = sdCapsule(p, vec3(0), vec3(0,len,0), 0.1);
    sdf = min(sdf, sdCone(p-vec3(0,len+.2,0), vec2(.1,.2), .2) );
    return sdf;
}

vec2 map(vec3 p)
{
    p.yz *= r2(-0.05);
    vec2 mu = iMouse.xy/iResolution.xy;

    // offset 
    float off = 0.2;

    // plane
    float d1 = plane(p);

    float fx = sin(iTime * 0.3) * 2.;

    vec3 a1 = vec3(0,0,0);
    vec3 b1 = vec3(0);


    // arrow vector shape
    float d2 = 0.;


    // final shape
    float shape = d1;
    float id = 1.0;

    /*
