        p.yz *= r2(0.52);
        //p.xz *= r2(0.2);
        if(d2 < shape) { shape = d2; id = 3.;}
    }
    */

    vec3 a = vec3(0,1,0); // common starting point for all arrows

    for(float i = -2.; i < 3.; i++)
    for(float j = -1.; j < 2.; j++)
    {
        vec3 b = vec3(-2, j*1., i*1.) + a; // calculate endpoint
        d2 = arrow(a, b, p); // add vector arrow to scene
        if(d2 < shape) { shape = d2; id = 3.;}
    }

    return vec2(shape, id);
}

