// Hash function: Takes a vec2, spits out a float. Useful for randomness.
float hash21(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

void mainImage( out vec4 O, in vec2 I )
{
    vec2 uv = (2. * I - iResolution.xy) / iResolution.y;

    // size of the grid
    float size = 8.;
    uv *= size;

    vec3 col = vec3(0.);

    float cIndex = floor(uv.x / .4) - 0.0;
    vec2 off = uv, id, grid;

    if (mod(cIndex, 4.0) == 0.0) { 
        float ran = hash21(vec2(0, cIndex));
        float delta = 1.5 + (ran * .5);
        off = vec2(uv.x, uv.y + iTime * delta);

        id = vec2( floor(off.x + uv.x / 1.) - 0.5,
                   floor(off.y + uv.y / 0.4) - 0.2);


        // grid repetition
        grid = vec2(mod(off.x + uv.x, 1.) - 0.5,
                    mod(off.y + uv.y, 0.4) - 0.2);

        float c1 = hash21(id) * 1.;
        col += vec3(0,c1 * 0.3,c1 * 0.5);

    } 
    else  if (mod(cIndex, 2.0) == 0.0) 
    { 
        float ran = hash21(vec2(cIndex, 0));
        float delta = 3.5 + (ran * .05);
        off = vec2(uv.x, uv.y + iTime * delta);

        id = vec2(floor(off.x + uv.x / 1.) - 0.5,
                  floor(off.y + uv.y / 0.4) - 0.2);

        // grid repetition
        grid = vec2(mod(off.x + uv.x, 1.) - 0.5,
                    mod(off.y + uv.y, 0.4) - 0.2);

        float c2 = hash21(id) * 1.5;
        col -= vec3(0,c2 * 0.9,c2 * 0.9);
    } else {
        col -= vec3(1);
    }

    float px = 4. / iResolution.y;

    // I wanna draw a 64 bit kind of thing so I need some squares
    float a1 = 0.0, d1=1.0, d2=1.0;

    for(int i=-2; i<3; i++)
    {
        a1 = sdBox(grid + vec2(float(i) * 0.2,0) , vec2(0.04,0.1));
        d1 = step(px, a1);

        if(d2 != d1)
        {
            col += vec3(d2 * d1);
            float c2 = hash21(id) * 1.;
            col += vec3(0.1,c2,c2);
            d2 = d1;
        }
    }

    // Output to screen
    O = vec4(col,1.0);
}

