#define AA 2

// create the vector arrow
float arrow(vec3 p, vec3 a, vec3 b, float off, int id)
{
    float d1 = sdCapsule(p, a, b, 0.1);
    return d1;//min(d1,d2);
}


// Got the matrix folding idea from this shader
// https://www.shadertoy.com/view/s3XXDj
float shape(vec3 p, vec3 a, vec3 b)
{
    // fold the space
    float angle = .72;
    for(int i=0; i<4; i++)
    {
        p = abs(p) - 0.9;
        p.xz *= mat2(angle,angle,-angle,angle);
        p.yz *= mat2(angle,angle,-angle,angle);
    }

    p.zx *= r2(iTime * .25);

    float d4 = arrow(p, a , b, 0.3, 4);

    return d4;
}

vec3 path(vec3 p)
{
//	float t = -0. + iTime*1.;
    return vec3(-iTime * 3.,0,0); //+ vec3( 5.5*cos(0.1*t), .2, 5.5*sin(0.1*t));;
}

vec2 map(vec3 p)
{
    p.yz *= r2(iTime * 0.1);

    // offset 
    float off = 0.2;

    // box
    float d1 = sdBox(p - path(p),vec3(.95));

    float fx = sin(iTime * 1.) * 1.5 - 4.;

    // red
    vec3 a1 = vec3(0,0,0);
    vec3 b1 = vec3(4.,0,0);

    // green
    vec3 a2 = a1;
    vec3 b2 = vec3(0,0,4.);


    // take the cross product of b1,b2
    vec3 a3 = a1;
    vec3 b3 = b2;
    vec3 np1 = p;

    float cell = 9.;
    np1 = vec3(
        mod(np1.x, cell) - cell * 0.5,
        mod(np1.y, cell) - cell * 0.5,
        mod(np1.z, cell) - cell * 0.5
    );
    float d4 = shape(np1, a3, b3 + fx);

    vec3 b4 = cross(b1 + 2.,b3 + .5);
    float d6 = shape(np1, a1, b4 + fx);

    vec3 b5 = cross(-b1,b2);
    float d5 = arrow(p, a1, b5 * 0.5, off, 5);

    float depth = 1.0;
    vec3 np2 = p;
    //np2.y += iTime * 2.;
    // The edge of the tunnel. Set at a radius of one, plus the depth.
    float tun =  0.4 / length(np2.zy);//vec2(, 1. / length(p.xy));//(1. + depth) - length(p.yz); 

    //flr = max(flr, tun - depth - .1);

    // final shape
    float shape = 1.;
    float id = 1.0;

    //if(d2 < shape) { shape = d2; id = 3.;}
    //if(d3 < shape) { shape = d3; id = 2.;}

    if(d4 < shape) { shape = max(d4,-d1); id = 4.;}

    if(d6 < shape) { shape = d6; id = 4.;}

   // if(d5 < shape) { shape = max(d5, -tun); id = 5.;}

    if(tun < shape) { shape = tun - depth  + 1.; id = 2.;}

    return vec2(shape, id);
}

float acc;
vec2 rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.;
    float id = 0.;
    for(int i=0; i<50; i++)
    {
        // position along the ray 
        vec3 p = ro + rd * dt; 

        // current distance to the scene
        vec2 sdf = map(p);                      

        float d = sdf.x;

        id = sdf.y;                             

        acc += exp(-abs(d) * 10.0) * 0.003;

        // march the ray
        dt += d * 0.5;//abs(d * .5);

        if(abs(d) < 0.001 || dt > 10.) break;

    }

    return vec2(dt, id);
}

vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)).x - map(p - vec3(e,0,0)).x,
        map(p + vec3(0,e,0)).x - map(p - vec3(0,e,0)).x,
        map(p + vec3(0,0,e)).x - map(p - vec3(0,0,e)).x
    ));
}

mat3 setCamera( in vec3 ro, in vec3 ta, float cr )
{
	vec3 cw = normalize(ta-ro);
	vec3 cp = vec3(sin(cr), cos(cr),0.0);
	vec3 cu = normalize( cross(cw,cp) );
	vec3 cv =          ( cross(cu,cw) );
    return mat3( cu, cv, cw );
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

vec3 render(vec3 ro, vec3 rd)
{   
    vec3 col = vec3(0.0123);

    vec2 dt = rayMarch(ro,rd);

    if(dt.x < 10.)
    {
        //vec3 n = calcNormal(ro + rd * dt.x);
        //vec3 l = normalize(vec3(1,3,0));
        vec3 bgcol = vec3(0);

        //float diff = max(dot(n, l), 0.0);
        //float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 24.0);

        bgcol = palette(dt.x * 0.235 + iTime * 0.59, vec3(0.5), vec3(.85), vec3(1.0), vec3(0.694,0.29314,0.949));

        col = bgcol; //* (diff + .2) + vec3(0.8) * spec * .6;

        col *= (acc * 1.5);
        col = mix(col,vec3(0.0123), 1. - exp(-0.005 * dt.x*dt.x*dt.x));   
    }

    return col;
    //O = vec4(col,1.0);
}


