void mainImage(out vec4 O, in vec2 I)
{   
    vec2 uv = (2.0 * I - iResolution.xy) / iResolution.y;

    vec2 mo = iMouse.xy/iResolution.xy;
	float t = 0. + iTime*0.;
    // camera	
    vec3 ta = vec3(-iTime * 3.,0.,0.);
    vec3 ro = ta + vec3( .1*cos(0.1*t), .0, .1*sin(0.1*t));
    //vec3 ro = path(vec3(0));
    // camera-to-world transformation
    mat3 ca = setCamera( ro, ta, 0.0 );

    vec3 tot = vec3(0.0);

    for (int m = 0; m < AA; m++)
    for (int n = 0; n < AA; n++) {
        vec2 off = vec2(m, n) / float(AA) - 0.5;
        vec2 uv = (2.0 * (I + off) - iResolution.xy) / iResolution.y;
        vec3 rd = ca *  normalize(vec3(uv, 1.5));
        vec3 col = render(ro, rd); 

        col = pow(col * 1.0, vec3(1.1 / 2.2));

        tot += col;
    }

    tot /= float(AA * AA);

    O = vec4(tot, 1.0);
}

// helpers

mat2 r2(float a){ return mat2(cos(a), sin(a), -sin(a), cos(a)); }

float sdCapsule( vec3 p, vec3 a, vec3 b, float r )
{
  vec3 pa = p - a, ba = b - a;
  float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
  return length( pa - ba*h ) - r;
}

float sdBox( vec3 p, vec3 b )
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

/*
    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓

