*/
vec2 map(vec3 p)
{
    p.yz *= r2(0.1);
    // offset 
    float off = 0.2;
    // plane
    float d1 = plane(p);
    // animation effect
    float fx = sin(iTime * 0.) * 0.5 - .0;
    // origin
    vec3 a1 = vec3(-0,0,-0);
    // value to add to the matrix
    float c = cos(iTime);
    float s = sin(iTime);
    // initial lenght of the vectors
    float l = 3.;
    // Play with addine stuff to matrices
    mat3 mb = mat3(
                l,0.1,0.1,
                0.2,l,0.2,
                0.1,0.1,l);
    mat3 mbT = inverse(mb);
    // matrix rotations in 3x3 matrix
    mat3 mbx = mat3(2,0, 0,
                    0,c,-s,
                    0,s,c );

    mat3 mby = mat3(c,0,-s,
                    0,2, 0,
                    s,0, c);

    mat3 mbz = mat3(c,-s, 0,
                    s, c, 0,
                    0, 0, 2);
    // initial vectors
    float d2a = arrow(p, a1, mb[0], off, 3);
    float d2b = arrow(p, a1, mb[1], off, 3);
    float d2c = arrow(p, a1, mb[2], off, 3);
    // green
    // which index
    int i = 0;//int(mod(iTime / 10., 3.));
    float zi = (mod(iTime / 5., 3.));

    vec3 noff = vec3(0,zi,0);

    // d4 lets try multiplying the matrices 
    mat3 mb2 = mb * mby;
    vec3 b4 = mb2[i];
    float d4 = arrow(p, a1 + noff, b4 + noff, 0., 3);


    // d5 lets try dividing the matrices 
    mat3 mb3 = mb * mbz;
    vec3 b5 = mb3[i];
    float d5 = arrow(p, a1, b5, off, 3);
    // d3 add the matrices 
    mat3 mb1 = mb * mbx;
    vec3 b1 = mb1[i];
    vec3 np2 = p;

    vec3 b6 = b4 + noff + 0.01;
    vec3 b7 = b4 + noff + vec3(0,-1,0);
    float d3 = arrow(np2, b6, b7, off, 3);

    // final shape
    float shape = d1;
    float id = 1.0;
    if(d2a < shape) { shape = d2a; id = 5.;}
    if(d2b < shape) { shape = d2b; id = 5.;}
    if(d2c < shape) { shape = d2c; id = 5.;}
    // green
    if(d3 < shape) { shape = d3; id = 2.;}
    if(d4 < shape) { shape = d4; id = 3.;}
   // if(d5 < shape) { shape = d5; id = 4.;}

    return vec2(shape, id);
}

vec2 rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.;
    float id = 0.;
    for(int i=0; i<50; i++)
    {
        // position along the ray 
        vec3 p = ro + rd * dt; 

