vec2 map(vec3 p)
{
    //p.yz *= r2(0.1);
    // offset 
    float off = 0.2;
    // plane
    float d1 = plane(p + vec3(0,1,0));
    // animation effect
    float fx = sin(iTime * .5) * 0.5 - .5;
    // origin
    vec3 a1 = vec3(0,0,0);
    // initial lenght of the vectors
    float l = 1.;
    // Play with addine stuff to matrices
    mat3 mb = mat3(
                l,fx,0,
                fx,l,fx,
                0,fx,l);
    mat3 mbT = inverse(mb);

    // initial vectors
    float d2a = arrow(p, a1, mb[0], off, 3);
    float d2b = arrow(p, a1, mb[1], off, 3);
    float d2c = arrow(p, a1, mb[2], off, 3);

    float det = determinant(mb);
    float newid = 0.;
    if(det == 1.)
        newid = 3.;
    else 
        newid = 2.;

    float d3 = arrow(p, a1, vec3(det,det,0), off, 3);
    // final shape
    float shape = d1;
    float id = 1.0;
    if(d2a < shape) { shape = d2a; id = 5.;}
    if(d2b < shape) { shape = d2b; id = 5.;}
    if(d2c < shape) { shape = d2c; id = 5.;}
    // green
    if(d3 < shape) { shape = d3; id = newid;}
   // if(d4 < shape) { shape = d4; id = 3.;}
   // if(d5 < shape) { shape = d5; id = 4.;}

    return vec2(shape, id);
}

vec2 rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.;
    float id = 0.;
    for(int i=0; i<50; i++)
    {
        // position along the ray 
        vec3 p = ro + rd * dt; 

        // current distance to the scene
        vec2 sdf = map(p);                      

        float d = sdf.x;

        id = sdf.y;
        // march the ray
        dt += d;                             

        if(abs(d) < 0.001 || dt > 30.) break;
    }

    return vec2(dt, id);
}

vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)).x - map(p - vec3(e,0,0)).x,
        map(p + vec3(0,e,0)).x - map(p - vec3(0,e,0)).x,
        map(p + vec3(0,0,e)).x - map(p - vec3(0,0,e)).x
    ));
}


mat3 setCamera( in vec3 ro, in vec3 ta, float cr )
{
	vec3 cw = normalize(ta-ro);
	vec3 cp = vec3(sin(cr), cos(cr),0.0);
	vec3 cu = normalize( cross(cw,cp) );
	vec3 cv =          ( cross(cu,cw) );
    return mat3( cu, cv, cw );
}


vec3 render(vec3 ro, vec3 rd)
{   
    vec3 col = vec3(0.0123);

    vec2 dt = rayMarch(ro,rd);

    if(dt.x < 30.)
    {
        vec3 n = calcNormal(ro + rd * dt.x);
        vec3 l = normalize(vec3(0,3,0));
        vec3 bgcol = vec3(0);

        float diff = max(dot(n, l), 0.0);
        float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 24.0);

        if (dt.y > 4.)
            bgcol = vec3(0.2);
        else if (dt.y > 3.)
            bgcol = vec3(0,0.2,0.9);
        else if (dt.y > 2.)
            bgcol = vec3(0.8,0.04,0.1);
        else if(dt.y > 1.)
            bgcol = vec3(0.1,0.7,0.1);
        else if (dt.y > 0.)
            bgcol = vec3(0,0.4,0.6);


        col = bgcol * (diff + .15) + vec3(0.8) * spec * .6;

    }

    return col;
    //O = vec4(col,1.0);
}


