vec2 map(vec3 p)
{
    p.yz *= r2(iTime * .1);

    // offset 
    float off = 0.2;
    // plane
    float d1 = sdBox(p,vec3(.65));
    // animation effect
    float fx = sin(iTime * .0) * .1 + 0.3;
    float fx2 = sin(iTime * .0) * .2 - 0.4;
    // origin
    vec3 a1 = vec3(0,0,0);
    // initial lenght of the vectors
    float l = 1.;
    // Play with addine stuff to matrices
    mat3 mb = mat3(
                l,fx,0,
                fx,l,fx,
                0,fx,l);


    // initial vectors
    float d2a = arrow(p, a1, mb[0], off, 3);
    float d2b = arrow(p, a1, mb[1], off, 3);
    float d2c = arrow(p, a1, mb[2], off, 3);


    float k = 0.;
    float angle = .7;
    for(int i=0; i<7; i++)
    {
        p = abs(p) - 0.1 + fx2;

        p.xy *= mat2(angle,angle,-angle,angle);
        p.yz *= mat2(angle,angle,-angle,angle);

        p.zy *= r2(iTime * 0.04);
    }

    mat3 mbA = mat3(
                p.x,p.y,p.z,
                fx,l,fx,
                0,fx,l);

    mat3 mbB = mat3(
                l,fx,0,
                p.x,p.y,p.z,
                0,fx,l);

    mat3 mbC = mat3(
                l,fx,0,
                fx,l,fx,
                p.x,p.y,p.z);

    float det = determinant(mb);
    float detA = determinant(mbA);
    float detB = determinant(mbB);
    float detC = determinant(mbC);

    float dA = determinant(mbA) / det;
    float dB = determinant(mbB) / det;
    float dC = determinant(mbC) / det;

    float newp = -sign(det) * max( min(detA, min(detB, min(detC, 
                 det - detA - detB - detC ))),1.);

    // α a + β b + γ c
    mat3 np = dA * mbA + dB * mbB + dC * mbC;

    float newid = 0.;
    if(newp < 0.){
        newid = 3.;
        newp = 1.;
    }else 
        newid = 2.;

    vec3 p1 = np[2];

  //  int i = int(mod(iTime / 3., 3.));
  //  p1 = np[i];

    float d3 = arrow(p1, a1, vec3(det,det,det), off, 3);

    // final shape
    float shape = max(d3,-d1);
    //float shape = d1;
    float id = newid;
   // if(d2a < shape) { shape = d2a; id = 5.;}
    //if(d2b < shape) { shape = d2b; id = 5.;}
    //if(d2c < shape) { shape = d2c; id = 5.;}
    // green
    //if(d3 < shape) { shape = d3; id = newid;}
    //if(newp < shape) { shape = newp; id = 4.;}
   // if(d5 < shape) { shape = d5; id = 4.;}

    return vec2(shape, id);
}

vec2 rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.;
    float id = 0.;
    for(int i=0; i<50; i++)
    {
        // position along the ray 
        vec3 p = ro + rd * dt; 

        // current distance to the scene
        vec2 sdf = map(p);                      

        float d = sdf.x;

        id = sdf.y;
        // march the ray
        dt += d;                             

        if(abs(d) < 0.001 || dt > 30.) break;
    }

    return vec2(dt, id);
}

