        bgcol = palette(n.x * n.x * .3 + .5 + iTime * 0.1, vec3(0.5), vec3(.85), vec3(1.0), vec3(0.925,0.678,0.6));

        col = bgcol * (diff + .0) + vec3(0.8) * spec * .6;

    }
    col = mix(clamp(col, 0., 1.), vec3(0), smoothstep(0., FAR-1., t));
    return col;
    //O = vec4(col,1.0);
}


