    // origin
    vec3 a1 = vec3(0,0,0);
    // initial lenght of the vectors
    float l = 1.;
    // Play with addine stuff to matrices
    mat3 mb = mat3(
                l,fx,0,
                fx,l,fx,
                0,fx,l);

    vec3 np1 = p;

    float cell = 17.;
    np1 = vec3(
        mod(np1.x, cell) - cell * 0.5,
        mod(np1.y, cell) - cell * 0.5,
        mod(np1.z, cell) - cell * 0.5
    );

    float k = 0.;
    float angle = .61;
    float fx2 = sin(iTime * 0.05) * 0.5 + 0.5;

    for(int i=0; i<6; i++)
    {
        np1 = abs(np1) - .5;

        np1.xy *= mat2(angle,angle,-angle,angle);
        np1.yz *= mat2(angle,angle,-angle,angle);

        np1.zx *= r2(3. + fx2 + iMouse.x/100.); // r2(3.29);
    }

    mat3 mbA = mat3(
                np1.x,np1.y,np1.z,
                fx,l,fx,
                0,fx,l);

    mat3 mbB = mat3(
                l,fx,0,
                np1.x,np1.y,np1.z,
                0,fx,l);

    mat3 mbC = mat3(
                l,fx,0,
                fx,l,fx,
                np1.x,np1.y,np1.z);

    float det = determinant(mb);
    float detA = determinant(mbA);
    float detB = determinant(mbB);
    float detC = determinant(mbC);

    float dA = determinant(mbA) / det;
    float dB = determinant(mbB) / det;
    float dC = determinant(mbC) / det;

    float newp = -sign(det) * max( min(detA, min(detB, min(detC, 
                 det - detA - detB - detC ))),1.);

    // α a + β b + γ c
    mat3 np = dA * mbA + dB * mbB + dC * mbC;

    float newid = 0.;
    if(newp < 0.){
        newid = 3.;
        newp = 1.;
    }else 
        newid = 2.;

    vec3 p1 = np[0];

    float d3 = arrow(p1, a1, vec3(det,det,0), off, 3);

    // light source at 0,0,0
    float d4 = length(p2) - .5;
