// Got the matrix folding idea from this shader
// https://www.shadertoy.com/view/s3XXDj
float shape(vec3 p, vec3 a, vec3 b)
{

    // fold the space
    float angle = .7;
    for(int i=0; i<4; i++)
    {
        p = abs(p) - 0.91;
        p.xy *= mat2(angle,angle,-angle,angle);
        p.yz *= mat2(angle,angle,-angle,angle);
    }

    p.xz *= r2(iTime * 0.5);
    float d4 = sdLink(p, b.z , b.y, 0.03);

    return d4;
}

vec2 map(vec3 p)
{
    p.yz *= r2(4.);

    // offset 
    float off = 0.2;

    // plane
    float d1 = 1.0;

    float fx = sin(iTime * 1.) * 0.005 - 0.03;

    // red
    vec3 a1 = vec3(0,0,0);
    vec3 b1 = vec3(4.,0,0);

    // green
    vec3 a2 = a1;
    vec3 b2 = vec3(0,0,4.);

    // take the cross product of b1,b2
    vec3 a3 = a1;
    vec3 b3 = b2;
    vec3 np1 = p;

    float d4 = shape(p, a3, b3);

    vec3 b4 = cross(b1,b3);
    float d6 = shape(p, a1, b4 * fx);

    vec3 b5 = cross(-b1,b2);
    float d5 = arrow(p, a1, b5 * 0.5, off, 5);

    // final shape
    float shape = 1.;
    float id = 1.0;

    if(d6 < shape) { shape = smin(d6,d4,0.1); id = 3.;}

    return vec2(shape, id);
}

vec2 rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.;
    float id = 0.;
    for(int i=0; i<60; i++)
    {
        // position along the ray 
        vec3 p = ro + rd * dt; 

        // current distance to the scene
        vec2 sdf = map(p);                      

        float d = sdf.x;

        id = sdf.y;
        // march the ray
        dt += d;                             

        if(abs(d) < 0.001 || dt > 30.) break;
    }

    return vec2(dt, id);
}

