    vec3 np = p; 
    np.xy += .2;//iMouse.x/200.;;
    //np.y += iMouse.y/200.;
    np.z += iTime * 0.02;//iMouse.z/200.;

    float cell = .6;
    np = vec3(mod(np, cell) - cell * 0.5);
    float d5 = length(np) - 0.6 * triNoise3D( p * .5 , .201, 2., 3.3);

    float d6 = -smin(-d2,-d4, 0.3);
    float id =2.;

    if(d6 > d5){ d6 = -smin(-d2,-d5, 0.25); id = 4.;} 
    return vec2(d6, id);
}

vec2 map(vec3 p)
{
