    vec3 b2 = vec3(0,0,1.);

    vec2 d1 = shape(p, a1, b2);
    float d2 = length(p) - 4.4;

    // final shape
    float  shape = d1.x;
    float id = d1.y;

    //if(shape > d1.x) { shape = -smin(-d2,-d1.x, 0.34); id= 0.;}

    return vec2(shape, id);
}

vec2 rayMarch(vec3 ro, vec3 rd)
{
    float dt = 0.;
    float id = 0.;
    for(int i=1; i<50; i++)
    {
        // position along the ray 
        vec3 p = ro + rd * dt; 

        // current distance to the scene
        vec2 sdf = map(p);                      

        float d = sdf.x;

        id = sdf.y;
        // march the ray
        dt += d;                             

        if(abs(d) < 0.001 || dt > 30.) break;
    }

    return vec2(dt, id);
}

vec3 calcNormal(vec3 p)
{
    float e = 0.001;
    return normalize(vec3(
        map(p + vec3(e,0,0)).x - map(p - vec3(e,0,0)).x,
        map(p + vec3(0,e,0)).x - map(p - vec3(0,e,0)).x,
        map(p + vec3(0,0,e)).x - map(p - vec3(0,0,e)).x
    ));
}


mat3 setCamera( in vec3 ro, in vec3 ta, float cr )
{
	vec3 cw = normalize(ta-ro);
	vec3 cp = vec3(sin(cr), cos(cr),0.0);
	vec3 cu = normalize( cross(cw,cp) );
	vec3 cv =          ( cross(cu,cw) );
    return mat3( cu, cv, cw );
}


vec3 render(vec3 ro, vec3 rd)
{   
    vec3 col = vec3(0);

    vec2 dt = rayMarch(ro,rd);

    vec3 l,p;
    if(dt.x < 30.)
    {
        p = ro + rd * dt.x;
        vec3 n = calcNormal(p);
        l = normalize(vec3(0,3,0)-p);

        float NoV  = clamp(dot(n, -rd), 0.0, 1.0);    
        float rim  = pow(1.0 - NoV, 2.5) * 3.;

        vec3 bgcol = vec3(0);

        float diff = max(dot(n, l), 0.0);
        float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 12.0);

        vec3 rimCol = vec3(0);

        if (dt.y > 3.) 
        {
            // blobs
            bgcol = vec3(0.678,0.016,0.863);
            rimCol = vec3(0.259,0.055,0.565) * rim;
        }
        else 
        {
            // spikes 
            bgcol = vec3(0.910,0.067,0.435);
            rimCol = vec3(0.922,0.039,0.039) * rim;
        }

        col = bgcol * (diff + 0.02) + vec3(.8) * spec * .5;
        col += rimCol;

    }


    // Blend the scene and the background
    col = mix(col, vec3(0.0123), min(pow(dt.x,2.9)*.3/FAR, 1.));

    return col;
    //O = vec4(col,1.0);
}


