float tri(in float x){return abs(fract(x)-.5);}
vec3 tri3(in vec3 p){return vec3( tri(p.z+tri(p.z*1.)), tri(p.z+tri(p.x*1.)), tri(p.y+tri(p.x*1.)));}


// Taken from https://www.shadertoy.com/view/4ts3z2
float triNoise3D(vec3 p,float spd, float idx, float n2)
{
    float z=4.9;
	float rz = 0.;
    vec3 bp = p;
	for (float i=0.; i<=idx; i++ )
	{
        vec3 dg = tri3(bp*n2);
        p += (dg+spd);

        bp *= 2.;
		z *= 1.7;
		p *= 1.497;
        //p.xz*= m2;

        rz+= (tri(p.z+tri(p.x+tri(p.y))))/z;
        bp += iTime * .01;
	}
	return rz;
}

