vec2 shape(vec3 p, vec3 a, vec3 b)
{
    vec3 np1 = p;
    // fold the space
    for(int i=0; i<5; i++)
    {
        p = abs(p) - 0.25;
        p.xy *= mat2(-0.3443, 0.8854, -0.8854,-0.3443);
        p.yz *= mat2( 0.3443, 0.8854, -0.8854, 0.3443);
        //p.xz *= r2(iTime * 0.1);//
