    //p.yz *= r2(iMouse.x/100.);//r2(2.85); //
    p.yz *= r2(iTime * 0.01); //r2(iMouse.y/100.);

    float d2 = length(np1) - 5.;

    vec3 np = p; 
    np.xy += .2;//iMouse.x/200.;;
    //np.y += iMouse.y/200.;
    np.z += iTime * 0.12;//iMouse.z/200.;

    float cell = .9;
    np = vec3(mod(np, cell) - cell * 0.5);
    float d5 = length(np) - 3. * triNoise3D( p * .15 , .501, 3., 5.);

    float d6 = max(d2,d5);
    float id =2.;


    return vec2(d6, id);
}

