// SPACE to reseed.
#define readKey(key) (texelFetch(iChannel1, ivec2(key, 0), 0).x > 0.5)

float hash1(float n) { return fract(sin(n)*138.5453123); }

const float liveval = 6.;      // energy value of a freshly born cell
const float density = 8.0;     // initial random fill, in %
const float cstep   = 1.0/256.0;

// Rule bitmasks: bit (k-1) set = rule applies for k live neighbours
const int stayset = 1175456;
const int bornset = 1910512;

// Colour parameters 
const float rp = 0.1, gp = 0.136, bp = 0.215;   // gain per channel while alive
const float rm = 20.0, gm = 31.0, bm = 41.0;   // fade per channel while dead
const int   ra = 1,    ga = 2,    ba = 4;      // bitmask picking which channels light up

const int KEY_SPACE = 32;

int cell(ivec2 p) {
    ivec2 r = ivec2(textureSize(iChannel0, 0));
    p = (p + r) % r;   // wrap edges
    return (texelFetch(iChannel0, p, 0).w == liveval) ? 1 : 0;
}

float randpix(vec2 I) {
    float rn = hash1(iTime + I.x*13.0 + hash1(I.y*71.1));
    return step(1.01 - density/100.0, rn) * liveval;
}

void mainImage(out vec4 O, in vec2 I)
{
    ivec2 px  = ivec2(I);
    vec4 curr = texelFetch(iChannel0, px, 0);

    if (iFrame == 0 || readKey(KEY_SPACE)) {
        O = vec4(0, 0, 0, randpix(I));
        return;
    }

    int k = 0;
    for (int j = -2; j <= 2; j++)
        for (int i = -2; i <= 2; i++)
            if (i != 0 || j != 0)
                k += cell(px + ivec2(i, j));

    // Life rule
    float ev = curr.w;
    float ff = 0.0;
    if (ev > 0.) {
        ff = ev - 1.0;                                     // decay ("decimate")
        if ((stayset & (1 << (k-1))) > 0) ff = float(k);   // survives
    } else {
        ff = ((bornset & (1 << (k-1))) > 0) ? liveval : 0.0; // born
    }

    // Colour accumulation
    if (ff >= 1.) {
        int st = int(ff);
        if ((st & ra) > 0) curr.x += cstep * ff * rp;
        if ((st & ga) > 0) curr.y += cstep * ff * gp;
        if ((st & ba) > 0) curr.z += cstep * ff * bp;
    } else {
        curr.x -= cstep * rm;
        curr.y -= cstep * gm;
        curr.z -= cstep * bm;
    }

    O = vec4(clamp(curr.xyz, 0.0, 1.0), ff);
}

