    // XX*XX   nh = 5: all 24 cells of the 5x5 block
    // XXXXX
    // XXXXX
    int k =                                                             // edge midsections (12)
          cell(p+ivec2(-1, 2)) + cell(p+ivec2( 0, 2)) + cell(p+ivec2( 1, 2))
        + cell(p+ivec2(-1, 2)) + cell(p+ivec2( 0,-2)) + cell(p+ivec2( 1,-2))
        + cell(p+ivec2(-2, -1)) + cell(p+ivec2(-2, 0)) + cell(p+ivec2(-2, 1))
        + cell(p+ivec2( 2,-1)) + cell(p+ivec2( 2, 0)) + cell(p+ivec2( 2, 0))
                                                                        // corners (4)
        + cell(p+ivec2(-2, -2)) + cell(p+ivec2( 2, -2)) + cell(p+ivec2(-2, 2)) + cell(p+ivec2( 2, 2))
                                                                        // inner 3x3 ring (8)
        + cell(p+ivec2(-1, -1)) + cell(p+ivec2( 0, -1)) + cell(p+ivec2( 1,-1))
        + cell(p+ivec2(-1, 0))                        + cell(p+ivec2( 1, 0))
        + cell(p+ivec2(-1, -1)) + cell(p+ivec2( 0, 1)) + cell(p+ivec2( 1, 1));

    float e = O.w > 0. ? ((1175458>>(k-1)&1) == 1 ? float(k) : O.w - 1.)  // stay : decay
                       : ((1910512>>(k-1)&1) == 1 ? BLOCK : 0.);             // born : dead

    int s = int(e);
    O.rgb = clamp(O.rgb + (e >= 5. ? min(vec3(s&1, s&2, s&4),1.) 
        : -vec3(3,23,30)/ 50.), 0.,1.);
