    vec4 curr = texelFetch(iChannel0, px, 0);

    bool on = curr.w >= 5.;
    bool live =  ((k == 2));

    float ev = curr.w; 
    float ff = 0.;

    if (ev > 0.) {
        ff = ev - 1.0;                                     // decay ("decimate")
        if (live) ff = BLOCK;   // survives
    } else {
        ff = live ? BLOCK : 0.0; // born
    }

