    }else {
        // grab the current value and subtracted so we get the old value          
       col.rgb -= 1./40. * vec3(2,20,15);
    }    

    O = vec4(clamp(col.xyz, 0.0, 1.0), ff);
}

#define ZOOM 2
const int steps = 4;

// steps, left, right, etc...
const ivec2 STEP[steps] = ivec2[steps]( 
    ivec2(1,0), ivec2(-1,0), ivec2(0,1), ivec2(0,-1) 
);

float S(ivec2 p){
    ivec2 R = ivec2(iResolution.xy) / ZOOM;
    return texelFetch(iChannel0, ((p + R) % R) * ZOOM, 0).x;
}

float rnd(ivec2 p, int salt){
    uint n = uint(p.x)*1973u + uint(p.y)*9277u + uint(salt)*26699u;
    n = (n ^ (n >> 15)) * 2246822519u;
    n = (n ^ (n >> 13)) * 3266489917u;
    return float(n ^ (n >> 16)) / 4294967296.0;
}

void mainImage(out vec4 O, in vec2 U)
{
    ivec2 p = ivec2(U) / ZOOM;
    ivec2 c = ivec2(iResolution.xy) / 2;

    int delta = 16 * 2;
    // a grid ofheads
    if (iFrame == 0) 
    {                                    
        bool seed = (p.x*14 * p.y*9) % (delta*delta) == 0;

        O = vec4(seed ? float(2 + (p.x/delta + p.y/(delta)) % steps) : 0.);
        return;
    }

    float me = S(p), next = me;
    // a head 
    if (me >= 2.)
        next = 1.;

    // inject a random head every 120 frames 
    if (iFrame % 120 == 0 && next == 0. && rnd(p, iFrame) < 0.002)
        next = float(2 + int(rnd(p, iFrame + 1) * 4.));

    // loop through the steps
    for(int i = 0; i < steps; i++)
    {
        // Peek one cell backward, against the direction we're testing. 
        // If there's a head parked there aiming straight at us, 
        // we're next in line to light up.
        if(S(p - STEP[i]) == float(2 + i))
        {
            // save the position 
            int d = int(S(p - STEP[i])) - 2;

            // look at 3 cells ahead if occupied skip
            ivec2 f = STEP[i], t = ivec2(f.y, f.x);
            if(S(p+f) + S(p+f+t) + S(p+f-t) > 0.) continue;

            // random direction 
            if(rnd(p,4) > .67)
                d = (i < 2 ? 2 : 0) + int(rnd(p,9) * 2.);
            // keep going the same direction the incoming head was pointing
            //if( (p.x + p.y) % 11 == 0) 
                // Head pointing this way the direction of d (0,1,2,3)
              //  d = (i < 2 ? 2 : 0) + (p.x/5 + p.y/15 &1);
            next = float(2+d);
        } 


    }
    O = vec4(next);
}

