    else if(dv.x == 2.)
         col += vec3(0.059,0.718,1.000) + (dv.x * 1.) ;
    else if(dv.x == 3.)
        col += vec3(0.039,1.000,0.984)+(dv.x * 1.);
    else if(dv.x == 4.)
        col += vec3(0.039,1.000,0.106)+(dv.x * 1.);
    else if(dv.x == 5.)
        col += vec3(1.000,0.922,0.039)+(dv.x * 1.);
   // else 
   //    col += vec3(0.043,0.635,0.627)+(dv * 1.);

    col = pow(col, vec3(2.))*1.1;
    col *= smoothstep(0.,1.,col);

	O = vec4(col,1.0);
}

