    ▓              🌟  Grid setup  🌟 

    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓
*/

#define ZOOM 2
const int steps = 4;

// steps, left, right, etc...
const ivec2 STEP[steps] = ivec2[steps]( 
    ivec2(1,0), ivec2(-1,0), ivec2(0,1), ivec2(0,-1) 
);

float S(ivec2 p){
    ivec2 R = ivec2(iResolution.xy) / ZOOM;
    return texelFetch(iChannel0, ((p + R) % R) * ZOOM, 0).w;
}

// paint
vec3 P(ivec2 p){
    ivec2 R = ivec2(iResolution.xy) / ZOOM;
    return texelFetch(iChannel0, ((p + R) % R) * ZOOM, 0).rgb;
}

float rnd(ivec2 p, int salt){
    uint n = uint(p.x)*1973u + uint(p.y)*9277u + uint(salt)*26699u;
    n = (n ^ (n >> 15)) * 2246822519u;
    n = (n ^ (n >> 13)) * 3266489917u;
    return float(n ^ (n >> 16)) / 4294967296.0;
}


// iq's cosine palette. t is a position on a colour wheel.
vec3 palette(float t){
    return 0.5 + 0.5*cos(6.28318*(t + vec3(0., 0.4, 0.5)));
}

const vec3 trail = vec3(0.071,0.667,0.710);
// save the colors of the heads
const vec3 colState[4] = vec3[4](
    vec3(0.000,1.000,0.984),  // right
    vec3(0.498,0.518,0.565),  // left
    vec3(0.106,0.671,0.816),  // down
    vec3(0.976,0.224,0.949)  // up
);

// return the state of the color 
vec3 state(int s)
{
    // save incoming value from buffer A as int
    int a = s;
    // return the trail or the background 
    if(s == 1) return trail;
    if(s == 0) return vec3(1);
    return colState[a];
}


void mainImage(out vec4 O, in vec2 U)
{
    ivec2 p = ivec2(U) / ZOOM;

    // At frame 0 create a grid of points in can be random or maybe a pattern
    if(iFrame == 0)
    {
        bool seed = rnd(p,15)<0.00005;//(p.x % 200 == 0) && (p.y % 100 == 0);
        O = vec4(0,0,0,seed ?
            float(2 + (p.x/14 + p.y/26) % 3):0.);//float(2 + int(rnd(p,4)) ): 0.);//
        return;
    }

    if(iFrame >= 200)
        p.y -= iFrame/(iFrame);

    //  init my position
    float me = S(p), next = me;

    if (iFrame % 1000 == 0 && next == 0. && rnd(p, iFrame) < 0.0002)
        next = float(2 + int(rnd(p, iFrame + 1) * 4.));

    // a head 
    if(me >= 2.) next = 1.;

    // counter to claim neighbour
    int inc=0, dn = -1, pd = -1;
    // Check my 4 neighbours each side has exactly one state
    for(int i = 0; i<4; i++)
    {
        // subtract the head offset
        int dq = int(S(p - STEP[i])) - 2;
        if(dq<0 || dq>3) continue;

        // aimed straight at me remember it it wants to keep going right
        if(dq == i) {inc++; dn = i; pd = dq;}

        // going sideways next to me, maybe fork if dq is going up and
        // i isn't going horizontal then we can spawn a branch 4% of the time 
        else if((dq >> 1) != (i >>1) && rnd(p,i*31) < 0.04)
        {
            inc++; dn = i; pd = dq;
        }
    }

    // only light up if exactly one head claims me
    if(inc == 1)
    {
        int d = dn;
        // look at 3 cells ahead if occupied skip
        ivec2 f = STEP[d], t = ivec2(f.y, f.x);
        if(S(p+f) + S(p+f+t) + S(p+f-t) == 0.)
        {
            // random direction
            if(rnd(p,7) > .9)
                d = (d < 2 ? 2 : 0) + int(rnd(p,9) *2.);
            // become a head direction + the head object.
            next = float(2+d);
        }
    }

    // paint th
    vec3 paint = P(p) * 1.;
    int d = int(next) - 2;
    if(d >= 0)
        paint = max(paint, colState[d]);

    O = vec4(paint,next);
}

