void mainImage( out vec4 O, in vec2 I )
{
    vec2 uv = (  I - 0.5*iResolution.xy) / iResolution.y;
    vec3 dv = texture(iChannel0, uv).rgb;
    vec3 col = dv.rgb; 
    col = pow(col, vec3(1.1))*1.1;
    col *= smoothstep(0.,1.,col);
    col = mix(vec3(0),col, smoothstep(0.77, .1, length(uv * vec2(0.2,1) )));
	O = vec4(col,1.0);
}

