/*
    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓

    ▓              🌟  Layers, 3D look   🌟 

    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓
*/

#define ZL   6
#define SPAN .7
void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (I - 0.5*iResolution.xy)/iResolution.y;
    float T = iTime*0.2;
    vec3 g = vec3(0);
    float wsum = 0.0;
    // layers from @nimitz
    // https://www.shadertoy.com/view/MtKSWW
    for(int i=0;i<ZL;i++)
    {
        float t = mod(T + float(i)*(SPAN/float(ZL)), SPAN);
        float scale = SPAN - t;
        // The layers is a sine wave fading and coming 
        float w = sin(3.14159*t/SPAN);
        vec2 q = uv*scale + vec2(float(i)*3.31, float(i)*3.17);
        // accumulate the paint
        g    += texture(iChannel0, q).rgb * w;  
        wsum += w;
    }
    O = vec4(g/max(wsum,1e-3), 1.0);
}

/*
    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓

    ▓              🌟  KuKo Day 467  🌟 

    ▓ Buffer A: Grid + Color 
    ▓ Buffer B: Layers (3D look)

    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓
*/
void mainImage(out vec4 O, in vec2 U)
{
    vec2 p = U/iResolution.xy;
    // toward centre
    vec2 tc = vec2(.5) - p;                 
    // * scrollVelocity later for speed streaks
    float strength = .0225;                  
    vec3 col = vec3(0); float tw = 0.0;
    // @nimitz blur 
    // https://www.shadertoy.com/view/MtKSWW
    for(int i=0;i<12;i++)
    {
        float sr = float(i)/30.0;
        col += texture(iChannel0, p + tc*sr*strength).rgb * sr;
        tw  += sr;
    }

    col /= tw; 

    // Hardware bloom that I made up on the spot. It's
    // not as nice as software bloom, but it's way cheaper
    // and definitely easier to implement.
    // Load the "Blue Noise" texture into "iChannel1" with
    // the filter set to "linear". The filter for "Buffer A"
    // needs to be set to "mipmap" for the hardware blur
    // to take effect.

    // @shane's jittered mip bloom
    float a = 1., w = 1.;
    vec3 bloomCol = vec3(0);
    for(int i=0;i<18;i++){
        vec2 jit = (texture(iChannel1, p + vec2(i*57, i*27)*.327 +
                            fract(iTime)).xy - .5)/iResolution.y;
        bloomCol += texture(iChannel0, p + jit*5., float(i%6)/2.).rgb*w;
        a += w;
        w *= 1.;
    }
    bloomCol /= a;

    col += smoothstep(vec3(0.07), vec3(1), bloomCol)*5.;
    col *= pow(14.0*p.x*p.y*(1.0-p.x)*(1.0-p.y),.5); 
    col = tanh(col);

    O = vec4(col, 1.0);
}

