#define ZL   5
#define SPAN .7

void mainImage(out vec4 O, in vec2 I)
{
    vec2 uv = (I - 0.5*iResolution.xy)/iResolution.y;
    float T = iTime*0.1;
    vec3 g = vec3(0);
    float wsum = 0.0;
    // layers from @nimitz
    // https://www.shadertoy.com/view/MtKSWW
    for(int i=0;i<ZL;i++)
    {
        float t = mod(T + float(i)*(SPAN/float(ZL)), SPAN);
        float scale = SPAN - t;
        // The layers is a sine wave fading and coming 
        float w = sin(3.14159*t/SPAN);
        vec2 q = uv*scale + vec2(float(i)*3.31, float(i)*3.17);
        // accumulate the paint
        g    += texture(iChannel0, q).rgb * w;
        wsum += w;
    }


    O = vec4(g/max(wsum,1e-3),1.0);
}

void mainImage(out vec4 O, vec2 I)
{
    O = texel(ch0,I);

    // get the 4 quadrants
    vec2 q = step(R*.5, I);
    float id = q.x + 2.*q.y;

    vec3 c;

    if(id < 0.5) c = vec3(O.x/R.x,0,0);
    else if(id < 1.5) c = vec3(0,O.y/R.y,0);
    else if(id < 2.5) c = (.5+.5*sin(O.z))*vec3(0,0.65,0.6);
    else c = O.w * vec3(0.5,.6,0.9);
    O = vec4(c,1);
    //O = vec4(fract(a.x) * vec3(0,1,1),1);
}

