float vnoise(vec2 I)
{
    // Hash the 4 lattice points then blend smoothly 
    // cell id
    vec2 id = floor(I);
    // position inside it 
    vec2 cell = fract(I);

    // smoothstyle easing
    cell = cell*cell*(1.-2.*cell);

    // four corner hashes then 2 lerps horizontal and vertical 
    float a = hash12(id + vec2(0,0)), b = hash12(id + vec2(1,0));
    float c = hash12(id + vec2(0,1)), d = hash12(id + vec2(1,1));
    return mix(mix(a,b,cell.x), mix(c,d,cell.x),cell.y);
}

