    // counter
    for(float i=0.; i< 5.; i++)
    {
         if(i >= k) break;
         v += amp * vnoise(uv*scale + i + vec2(T*.5,0)*scale);
         // half the feature size
         scale *= 3.;
         // half the contribution
         amp *= 0.5;
    }

    O = vec4(v*vec3(0.1,0.5,1) + v*v*v*0.02,1);

