    vec2 ran = (hash22(id)-0.5) * size * k; 

    // We add the circle position - the grid + the disorder 
    float d = length(I - (grid + ran));
    d = smoothstep(5.0, 2.5, d);//step(d,5.);

    // faint the lattice so u can order the disorder
    vec2 g = abs(fract(I/size) - 0.5);
    float site = step(max(g.x,g.y),.4) * .52;

    // output the grid
    O = vec4(d * vec3(0,.6,0.8) + site*vec3(0.3,0,0.8), 1);
    */

    // Ex 3
    /*
    // Now threshold the has and each cell chooses on of two states
