    float cs = 22.;
    // where am i inside
    I.x += T*50.;
    vec2 id = floor(I/cs);
    vec2 cell = fract(I/cs) - 0.5;

    // random hash
    float ran = hash22(id).x;

    // The DECISION 
    float alive = step(k, ran);

    // Add some shapes and output them at random 
    float d = step(length(cell), .4);
    float d2 = step(abs(cell.x) + abs(cell.y), .4);

    // we mix them
    float shape = mix(d,d2,alive);

    vec3 col = mix(vec3(1,0,0),vec3(0,0,1),alive);

    O = vec4(shape * col, 1);
    */


    // Ex 2
    /*
