    // and u get objects

    // which cell am I in. which makes them agree on a shared random value
    vec2 cell = floor(I / k);

    // one has per cell not position
    vec2 jitter = hash22(cell);
    vec2 dotP = (cell + jitter) * k;

    // circle and random radius
    float d = length(I - dotP);
    float ran = 2.+4.*hash22(cell + 7.3).y;

    O = vec4(step(d,ran) * vec3(0,0.5,0.6), 1);
