    vec2 g = vec2( F(I+vec2(h,0)) - F(I-vec2(h,0)),
                   F(I+vec2(0,h)) - F(I-vec2(0,h))) / (2.*h);

    float k = T*1.;
    vec2 st = vec2( cos(k), sin(k));

    // with the dot product now we know which way is steep if uphill
    // flat if walking along the slope and downhill 
    float dg = dot(st,g);


    // we need to setup a circle that reads our gradient
    vec3 col = vec3(0);

    col += max( dg, .0)*30. * vec3(1,0,1);
    col += max(-dg, .0)*50. * vec3(0,1,1);

    col /= (0.2+col);
    O = vec4(col + col*col*0.6,1);
