void mainImage( out vec4 O, in vec2 I )
{
    // Each 10 pixel wide we are looking for a particle
    float size = 6.;
    float id = floor(I.x/size);
    O = texel(cha, vec2(3.+size*id,3.));


    if(id < 230.)
    {
        // Sample the gradient at the particle not at myself
        float h = 2.0;
        vec2 g = vec2( F(O.xy+vec2(h,0)) - F(O.xy-vec2(h,0)),
                       F(O.xy+vec2(0,h)) - F(O.xy-vec2(0,h)));

        float k = 45. + iMouse.x/10.;

        float nt = mod(T,6.) < 5. ? 1.:-1.;

        // up hill
        if(nt == 1.)
            O.xy += g*k*220.;
        // down hill 
        else 
            O.xy -= g*k*220.;

        O.xy = clamp(O.xy, vec2(2), R-2.);

        O.w += 1.;

        if(O.w > 300.)
        {
            O.xy = R * hash22(vec2(id, floor(float(iFrame/300)) )); 
            O.w = 0.;
        }
    }

    if(iFrame < 1)
    {
        // scatter random points
        O.xy = R * hash22(vec2(id, 0));
        O.w = hash22(vec2(id,4)).x*300.;
    }
}

