void mainImage( out vec4 O, vec2 I )
{
    float s = 3., h = .03,
         id = floor(I.x/s);
    vec2  g = vec2(1.5+s*id, 1.5);

    // check if we have something accross the columns
    O = T(iChannel0, g);
    if(id < 4e2)
    {   I = O.xy;
        // gradient formula 
        O.xy +=  vec2(-F(I+vec2(0,h)) + F(I-vec2(0,h))
                     , F(I+vec2(h,0)) - F(I-vec2(h,0))
                     ) 
               * 22. *(450. + iMouse.x);
        if (O.w++ > 340.)
            O.xy = R * H(vec2(id, iFrame/340)),
            O.w = 0.;
    }

    // initial grid of points
    if(iFrame<1)
        O.xy = R * H(g),
        O.w = H(vec2(id,1)).x* 4e2; 
}






