    ▓              🌟  KuKo Day 477  🌟 

    ▓ Laplacian of Gaussian:
    ▓ https://homepages.inf.ed.ac.uk/rbf/HIPR2/log.htm

    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓
*/

float map(vec2 p)
{
    vec2 uv = (p/R.y);
    float fx = sin(T*0.2) * 0.5+ 0.5;

    float d = smoothstep(0.02,-.04, length(uv - vec2(0.5 + fx,0.6)) - .33);
    d += 0.10*(H(floor(p* 0.045)) - 0.5)*2.;

    return d;
}

float LoG(vec2 I, float s)
{
    float acc=0.0, wsum=0.0;

    // loop through 13x13 neighbours
    int i = 6;
    for(int x=-i; x<=i; x++)
        for(int y=-i; y<=i; y++)
        {
            vec2 o = vec2(x,y) * (s*0.5);
            float o2 = dot(o,o);
            // Laplacian of Gaussian
            float w = G(o2,s);

            // sample the sdf, weight by the hat
            acc += map(I+o) * w; 
            // normalize
            wsum += abs(w);
        }
    return acc / max(wsum, 0.1);
}


void mainImage( out vec4 O, in vec2 I )
{
    vec3 col = vec3(0);

    float s = 4. + iMouse.x/10.,
    d = LoG(I,s) * 26.;

    if(I.y > R.y * 0.2)
    {
        // draw the shape, blue positive, white negative 
        col += max(d,0.0) * vec3(0.078,0.694,0.800);
        col += max(-d,0.) * vec3(0.851,0.808,0.851)* 0.7;

    } 
    else 
    {
        float r = (I.x - R.x * 0.5) * 0.3;
        float y = (I.y - R.y * 0.1) / (R.y * 0.2);

        // laplacian of gauss 
        float w = G(r*r,s);

        // draw the hat function at the bottom 
        float d2 = plot(y,w*s*s,0.05);
        col += d2;
    }
    // color 
    //col /= (0.9+col);
    O = vec4(col+col*col*1.,1);
}

